		sales_order.Quantity,
		App.tbTaxCode.TaxCode,
		App.tbTaxCode.TaxRate,
		sales_order.UnitCharge,
		sales_order.TotalCharge,
		Usr.tbUser.MobileNumber,
		Usr.tbUser.Signature
	FROM
	  Usr.tbUser
	INNER JOIN
	  Object.tbObject
	INNER JOIN
	  Project.tbProject AS sales_order
	ON
	  Object.tbObject.ObjectCode = sales_order.ObjectCode
	INNER JOIN
	  Subject.tbSubject
	ON
	  sales_order.SubjectCode = Subject.tbSubject.SubjectCode
	LEFT OUTER JOIN
	  Subject.tbAddress AS invoice_address
	ON
	  Subject.tbSubject.AddressCode = invoice_address.AddressCode
	ON
	  Usr.tbUser.UserId = sales_order.ActionById
	LEFT OUTER JOIN
	  Subject.tbAddress AS delivery_address
	ON
	  sales_order.AddressCodeTo = delivery_address.AddressCode
	LEFT OUTER JOIN
	  App.tbTaxCode
	ON
	  sales_order.TaxCode = App.tbTaxCode.TaxCode
	LEFT OUTER JOIN
	  Subject.vwReal
	ON
	  sales_order.SubjectCode   = Subject.vwReal.SubjectCode
	AND sales_order.ContactName = Subject.vwReal.ContactName
	WHERE EXISTS
