PRINT N'Creating Function [Subject].[fnCurrentAgedInvoiceItems]...';


GO
CREATE FUNCTION Subject.fnCurrentAgedInvoiceItems
(
    @AgedOn date
)
RETURNS TABLE
AS
RETURN
(
    SELECT
        invoice.SubjectCode,
        subject.SubjectName,
        CAST(@AgedOn AS date) AS AgedOn,
        invoice.InvoiceNumber,
        invoice.InvoiceTypeCode,
        invoice_type.InvoiceType,
        CAST(invoice.InvoicedOn AS date) AS InvoicedOn,
        CAST(invoice.DueOn AS date) AS DueOn,
        DATEDIFF(DAY, CAST(invoice.DueOn AS date), @AgedOn) AS DaysOverdue,
        CAST
        (
            CASE
                WHEN CAST(invoice.DueOn AS date) >= @AgedOn THEN 0
                WHEN DATEDIFF(DAY, CAST(invoice.DueOn AS date), @AgedOn) <= 30 THEN 1
                WHEN DATEDIFF(DAY, CAST(invoice.DueOn AS date), @AgedOn) <= 60 THEN 2
                WHEN DATEDIFF(DAY, CAST(invoice.DueOn AS date), @AgedOn) <= 90 THEN 3
                ELSE 4
            END
            AS smallint
        ) AS AgeBandCode,
        CAST
        (
            CASE invoice_type.CashPolarityCode
                WHEN 1 THEN
                    (invoice.InvoiceValue + invoice.TaxValue)
                    - (invoice.PaidValue + invoice.PaidTaxValue)
                WHEN 0 THEN
                    (
                        (invoice.InvoiceValue + invoice.TaxValue)
                        - (invoice.PaidValue + invoice.PaidTaxValue)
                    ) * -1
            END
            AS decimal(18, 5)
        ) AS BusinessAmount
    FROM Invoice.tbInvoice AS invoice
        JOIN Invoice.tbType AS invoice_type
            ON invoice.InvoiceTypeCode = invoice_type.InvoiceTypeCode
        JOIN Subject.tbSubject AS subject
            ON invoice.SubjectCode = subject.SubjectCode
        JOIN Subject.tbType AS subject_type
            ON subject.SubjectTypeCode = subject_type.SubjectTypeCode
    WHERE subject_type.SubjectClassCode <> 2
      AND invoice.InvoiceStatusCode < 3
      AND
      (
          (invoice.InvoiceValue + invoice.TaxValue)
          - (invoice.PaidValue + invoice.PaidTaxValue)
      ) <> 0
);
GO
PRINT N'Creating Function [Subject].[fnCurrentInvoiceReconciliation]...';


GO
CREATE FUNCTION Subject.fnCurrentInvoiceReconciliation()
RETURNS TABLE
AS
RETURN
(
    WITH eligible_subjects AS
    (
        SELECT
            subject.SubjectCode,
            subject.SubjectName,
            subject.OpeningBalance
        FROM Subject.tbSubject AS subject
            JOIN Subject.tbType AS subject_type
                ON subject.SubjectTypeCode = subject_type.SubjectTypeCode
        WHERE subject_type.SubjectClassCode <> 2
    ),
    statement_movements AS
    (
        SELECT
            subject.SubjectCode,
            CAST(subject.OpeningBalance AS decimal(38, 5)) AS Charge
        FROM eligible_subjects AS subject

        UNION ALL

        SELECT
            invoice.SubjectCode,
            CAST
            (
                CASE invoice_type.CashPolarityCode
                    WHEN 0 THEN invoice.InvoiceValue + invoice.TaxValue
                    WHEN 1 THEN (invoice.InvoiceValue + invoice.TaxValue) * -1
                END
                AS decimal(38, 5)
            ) AS Charge
        FROM Invoice.tbInvoice AS invoice
            JOIN Invoice.tbType AS invoice_type
                ON invoice.InvoiceTypeCode = invoice_type.InvoiceTypeCode
            JOIN eligible_subjects AS subject
                ON invoice.SubjectCode = subject.SubjectCode

        UNION ALL

        SELECT
            payment.SubjectCode,
            CAST
            (
                CASE
                    WHEN payment.PaidInValue > 0 THEN payment.PaidInValue
                    ELSE payment.PaidOutValue * -1
                END
                AS decimal(38, 5)
            ) AS Charge
        FROM Cash.tbPayment AS payment
            JOIN Subject.tbAccount AS account
                ON payment.AccountCode = account.AccountCode
            JOIN eligible_subjects AS subject
                ON payment.SubjectCode = subject.SubjectCode
        WHERE account.AccountTypeCode < 2
          AND payment.PaymentStatusCode = 1
    ),
    statement_balances AS
    (
        SELECT
            subject.SubjectCode,
            subject.SubjectName,
            CAST(COALESCE(SUM(movement.Charge), 0) AS decimal(18, 5)) AS NativeStatementBalance
        FROM eligible_subjects AS subject
            LEFT JOIN statement_movements AS movement
                ON subject.SubjectCode = movement.SubjectCode
        GROUP BY
            subject.SubjectCode,
            subject.SubjectName
    ),
    open_invoices AS
    (
        SELECT
            item.SubjectCode,
            CAST(SUM(item.BusinessAmount) AS decimal(18, 5)) AS OpenInvoiceBusinessBalance
        FROM Subject.fnCurrentAgedInvoiceItems(CAST(GETDATE() AS date)) AS item
        GROUP BY item.SubjectCode
    )
    SELECT
        statement.SubjectCode,
        statement.SubjectName,
        statement.NativeStatementBalance,
        CAST(statement.NativeStatementBalance * -1 AS decimal(18, 5)) AS StatementBusinessBalance,
        CAST(COALESCE(invoice.OpenInvoiceBusinessBalance, 0) AS decimal(18, 5)) AS OpenInvoiceBusinessBalance,
        CAST
        (
            (statement.NativeStatementBalance * -1)
            - COALESCE(invoice.OpenInvoiceBusinessBalance, 0)
            AS decimal(18, 5)
        ) AS ReconciliationResidual
    FROM statement_balances AS statement
        LEFT JOIN open_invoices AS invoice
            ON statement.SubjectCode = invoice.SubjectCode
    WHERE statement.NativeStatementBalance <> 0
       OR COALESCE(invoice.OpenInvoiceBusinessBalance, 0) <> 0
);
GO
PRINT N'Creating Function [Subject].[fnDatedBalances]...';


GO
CREATE FUNCTION Subject.fnDatedBalances
(
    @AsOfDate date
)
RETURNS TABLE
AS
RETURN
(
    WITH eligible_subjects AS
    (
        SELECT
            subject.SubjectCode,
            subject.SubjectName,
            subject.InsertedOn,
            subject.OpeningBalance
        FROM Subject.tbSubject AS subject
            JOIN Subject.tbType AS subject_type
                ON subject.SubjectTypeCode = subject_type.SubjectTypeCode
        WHERE subject_type.SubjectClassCode <> 2
    ),
    first_transactions AS
    (
        SELECT
            transaction_date.SubjectCode,
            MIN(transaction_date.TransactedOn) AS FirstTransactedOn
        FROM
        (
            SELECT invoice.SubjectCode, invoice.InvoicedOn AS TransactedOn
            FROM Invoice.tbInvoice AS invoice

            UNION ALL

            SELECT payment.SubjectCode, payment.PaidOn AS TransactedOn
            FROM Cash.tbPayment AS payment
                JOIN Subject.tbAccount AS account
                    ON payment.AccountCode = account.AccountCode
            WHERE account.AccountTypeCode < 2
              AND payment.PaymentStatusCode = 1
        ) AS transaction_date
        GROUP BY transaction_date.SubjectCode
    ),
    statement_movements AS
    (
        SELECT
            subject.SubjectCode,
            CAST(subject.OpeningBalance AS decimal(38, 5)) AS Charge
        FROM eligible_subjects AS subject
            LEFT JOIN first_transactions AS first_transaction
                ON subject.SubjectCode = first_transaction.SubjectCode
        WHERE CAST
        (
            COALESCE
            (
                DATEADD(DAY, -1, first_transaction.FirstTransactedOn),
                subject.InsertedOn
            )
            AS date
        ) <= @AsOfDate

        UNION ALL

        SELECT
            invoice.SubjectCode,
            CAST
            (
                CASE invoice_type.CashPolarityCode
                    WHEN 0 THEN invoice.InvoiceValue + invoice.TaxValue
                    WHEN 1 THEN (invoice.InvoiceValue + invoice.TaxValue) * -1
                END
                AS decimal(38, 5)
            ) AS Charge
        FROM Invoice.tbInvoice AS invoice
            JOIN Invoice.tbType AS invoice_type
                ON invoice.InvoiceTypeCode = invoice_type.InvoiceTypeCode
            JOIN eligible_subjects AS subject
                ON invoice.SubjectCode = subject.SubjectCode
        WHERE invoice.InvoicedOn < DATEADD(DAY, 1, @AsOfDate)

        UNION ALL

        SELECT
            payment.SubjectCode,
            CAST
            (
                CASE
                    WHEN payment.PaidInValue > 0 THEN payment.PaidInValue
                    ELSE payment.PaidOutValue * -1
                END
                AS decimal(38, 5)
            ) AS Charge
        FROM Cash.tbPayment AS payment
            JOIN Subject.tbAccount AS account
                ON payment.AccountCode = account.AccountCode
            JOIN eligible_subjects AS subject
                ON payment.SubjectCode = subject.SubjectCode
        WHERE account.AccountTypeCode < 2
          AND payment.PaymentStatusCode = 1
          AND payment.PaidOn < DATEADD(DAY, 1, @AsOfDate)
    ),
    balances AS
    (
        SELECT
            subject.SubjectCode,
            subject.SubjectName,
            CAST(COALESCE(SUM(movement.Charge), 0) AS decimal(18, 5)) AS NativeStatementBalance
        FROM eligible_subjects AS subject
            LEFT JOIN statement_movements AS movement
                ON subject.SubjectCode = movement.SubjectCode
        GROUP BY
            subject.SubjectCode,
            subject.SubjectName
        HAVING COALESCE(SUM(movement.Charge), 0) <> 0
    )
    SELECT
        balance.SubjectCode,
        balance.SubjectName,
        CAST(@AsOfDate AS date) AS AsOfDate,
        balance.NativeStatementBalance,
        CAST(balance.NativeStatementBalance * -1 AS decimal(18, 5)) AS BusinessBalance,
        CAST(CASE WHEN balance.NativeStatementBalance < 0 THEN 0 ELSE 1 END AS smallint) AS PositionCode,
        CAST(ABS(balance.NativeStatementBalance) AS decimal(18, 5)) AS HumanBalance
    FROM balances AS balance
);
GO
PRINT N'Creating Function [Subject].[fnCurrentAgedInvoices]...';


GO
CREATE FUNCTION Subject.fnCurrentAgedInvoices
(
    @AgedOn date
)
RETURNS TABLE
AS
RETURN
(
    WITH item_totals AS
    (
        SELECT
            item.SubjectCode,
            MAX(item.SubjectName) AS SubjectName,
            item.AgedOn,
            CAST(SUM(item.BusinessAmount) AS decimal(18, 5)) AS BusinessBalance,
            CAST(SUM(CASE item.AgeBandCode WHEN 0 THEN item.BusinessAmount ELSE 0 END) AS decimal(18, 5)) AS CurrentAmount,
            CAST(SUM(CASE item.AgeBandCode WHEN 1 THEN item.BusinessAmount ELSE 0 END) AS decimal(18, 5)) AS Days1To30Amount,
            CAST(SUM(CASE item.AgeBandCode WHEN 2 THEN item.BusinessAmount ELSE 0 END) AS decimal(18, 5)) AS Days31To60Amount,
            CAST(SUM(CASE item.AgeBandCode WHEN 3 THEN item.BusinessAmount ELSE 0 END) AS decimal(18, 5)) AS Days61To90Amount,
            CAST(SUM(CASE item.AgeBandCode WHEN 4 THEN item.BusinessAmount ELSE 0 END) AS decimal(18, 5)) AS Over90Amount
        FROM Subject.fnCurrentAgedInvoiceItems(@AgedOn) AS item
        GROUP BY
            item.SubjectCode,
            item.AgedOn
        HAVING SUM(item.BusinessAmount) <> 0
    )
    SELECT
        item.SubjectCode,
        item.SubjectName,
        item.AgedOn,
        item.BusinessBalance,
        CAST(CASE WHEN item.BusinessBalance > 0 THEN 0 ELSE 1 END AS smallint) AS PositionCode,
        CAST(item.CurrentAmount * SIGN(item.BusinessBalance) AS decimal(18, 5)) AS CurrentAmount,
        CAST(item.Days1To30Amount * SIGN(item.BusinessBalance) AS decimal(18, 5)) AS Days1To30Amount,
        CAST(item.Days31To60Amount * SIGN(item.BusinessBalance) AS decimal(18, 5)) AS Days31To60Amount,
        CAST(item.Days61To90Amount * SIGN(item.BusinessBalance) AS decimal(18, 5)) AS Days61To90Amount,
        CAST(item.Over90Amount * SIGN(item.BusinessBalance) AS decimal(18, 5)) AS Over90Amount,
        reconciliation.StatementBusinessBalance,
        reconciliation.ReconciliationResidual
    FROM item_totals AS item
        JOIN Subject.fnCurrentInvoiceReconciliation() AS reconciliation
            ON item.SubjectCode = reconciliation.SubjectCode
);
GO
