PRINT N'Altering Procedure [Cash].[proc_TaxObligations]...';


GO
ALTER   PROCEDURE [Cash].[proc_TaxObligations]
    @AsOfDate date = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET @AsOfDate = COALESCE(@AsOfDate, CONVERT(date, CURRENT_TIMESTAMP));

    SELECT TOP (1) CAST(Balance AS decimal(18,5))
    FROM Cash.vwTaxVatStatement
    WHERE StartOn >= @AsOfDate
    ORDER BY StartOn;

    SELECT TOP (1) CAST(Balance AS decimal(18,5))
    FROM Cash.vwTaxBizStatement
    WHERE StartOn >= @AsOfDate
    ORDER BY StartOn;
END;
GO
PRINT N'Altering Procedure [App].[proc_EventLog]...';


GO
ALTER PROCEDURE App.proc_EventLog (@EventMessage NVARCHAR(MAX), @EventTypeCode SMALLINT = 0, @LogCode NVARCHAR(20) = NULL OUTPUT)
AS
	SET XACT_ABORT, NOCOUNT ON;

	BEGIN TRY
		IF NULLIF(LTRIM(RTRIM(@EventMessage)), N'') IS NULL
		BEGIN
			SET @EventTypeCode = 1;
			SET @EventMessage = CONCAT
			(
				N'Event message was not supplied. Application=', APP_NAME(),
				N'; Host=', HOST_NAME(),
				N'; Login=', ORIGINAL_LOGIN(),
				N'; Session=', @@SPID
			);
		END;

		DECLARE 
			@UserId nvarchar(10)
			, @LogNumber INT
			, @RegisterName nvarchar(50) = (SELECT RegisterName FROM App.tbOptions);
	
		SET @UserId = (SELECT TOP 1 Usr.tbUser.UserId FROM Usr.vwCredentials c INNER JOIN
								Usr.tbUser ON c.UserId = Usr.tbUser.UserId);

		IF @RegisterName IS NULL OR @UserId IS NULL
		BEGIN
			SET @LogCode = LEFT(REPLACE(CONVERT(nvarchar(36), NEWID()), '-', ''), 20);

			INSERT INTO App.tbEventLog (LogCode, EventTypeCode, EventMessage, InsertedBy)
			VALUES (@LogCode, @EventTypeCode, @EventMessage, Usr.fnUserName());

			RETURN;
		END;

		BEGIN TRANSACTION;
		
		WHILE (1 = 1)
			BEGIN
			SET @LogNumber = FORMAT((SELECT TOP 1 r.NextNumber
						FROM App.tbRegister r
						WHERE r.RegisterName = @RegisterName), '00000');
				
			UPDATE App.tbRegister
			SET NextNumber += 1
			WHERE RegisterName = @RegisterName;

			SET @LogCode = CONCAT(@UserId, @LogNumber);

			IF NOT EXISTS (SELECT * FROM App.tbEventLog WHERE LogCode = @LogCode)
				BREAK;
			END

		INSERT INTO App.tbEventLog (LogCode, EventTypeCode, EventMessage, InsertedBy)
		VALUES (@LogCode, @EventTypeCode, @EventMessage, LEFT(COALESCE(@UserId, Usr.fnUserName()), 50));

		COMMIT TRANSACTION;

		RETURN;
					
	END TRY
	BEGIN CATCH
		IF @@TRANCOUNT > 0 
			ROLLBACK TRANSACTION;
		THROW;
	END CATCH
GO
PRINT N'Altering Procedure [Cash].[proc_ReportingProfileSettingSave]...';


GO
ALTER PROCEDURE [Cash].[proc_ReportingProfileSettingSave]
(
    @SubjectCode NVARCHAR(50),
    @ReportingProfileCode NVARCHAR(20),
    @SettingCode NVARCHAR(30),
    @EffectiveFrom DATE,
    @EffectiveTo DATE = NULL,
    @TextValue NVARCHAR(4000) = NULL,
    @IntegerValue BIGINT = NULL,
    @DecimalValue DECIMAL(28,9) = NULL,
    @DateValue DATE = NULL,
    @BooleanValue BIT = NULL,
    @StatusCode SMALLINT = 0,
    @ValueSourceCode NVARCHAR(10) = N'USER',
    @IsReviewed BIT = 0
)
AS
    SET NOCOUNT, XACT_ABORT ON;

    BEGIN TRY
        IF EXISTS
        (
            SELECT 1
            FROM Cash.tbReportingProfileSetting
            WHERE SubjectCode = @SubjectCode
              AND ReportingProfileCode = @ReportingProfileCode
              AND SettingCode = @SettingCode
              AND EffectiveFrom = @EffectiveFrom
        )
            UPDATE Cash.tbReportingProfileSetting
            SET EffectiveTo = @EffectiveTo,
                TextValue = @TextValue,
                IntegerValue = @IntegerValue,
                DecimalValue = @DecimalValue,
                DateValue = @DateValue,
                BooleanValue = @BooleanValue,
                StatusCode = @StatusCode,
                ValueSourceCode = @ValueSourceCode,
                IsReviewed = @IsReviewed,
                UpdatedBy = Usr.fnUserName(),
                UpdatedOn = current_timestamp
            WHERE SubjectCode = @SubjectCode
              AND ReportingProfileCode = @ReportingProfileCode
              AND SettingCode = @SettingCode
              AND EffectiveFrom = @EffectiveFrom;
        ELSE
            INSERT Cash.tbReportingProfileSetting
            (
                SubjectCode, ReportingProfileCode, SettingCode, EffectiveFrom, EffectiveTo,
                TextValue, IntegerValue, DecimalValue, DateValue, BooleanValue,
                StatusCode, ValueSourceCode, IsReviewed
            )
            VALUES
            (
                @SubjectCode, @ReportingProfileCode, @SettingCode, @EffectiveFrom, @EffectiveTo,
                @TextValue, @IntegerValue, @DecimalValue, @DateValue, @BooleanValue,
                @StatusCode, @ValueSourceCode, @IsReviewed
            );
    END TRY
    BEGIN CATCH
        EXEC App.proc_ErrorLog;
    END CATCH;
GO
PRINT N'Altering Procedure [Cash].[proc_FlowCategoryCodeFromName]...';


GO

ALTER   PROCEDURE Cash.proc_FlowCategoryCodeFromName
	(
		@Category nvarchar(100),
		@CategoryCode nvarchar(50) output
	)
AS
	SET NOCOUNT, XACT_ABORT ON;

	BEGIN TRY
		IF EXISTS (SELECT 1 FROM Cash.tbCategory WHERE CategoryCode = @Category)
			SET @CategoryCode = @Category;
		ELSE IF EXISTS (SELECT 1 FROM Cash.tbCode WHERE CashCode = @Category)
			SET @CategoryCode = @Category;
		ELSE IF (SELECT COUNT(*) FROM Cash.tbCategory WHERE Category = @Category) = 1
			SELECT @CategoryCode = CategoryCode FROM Cash.tbCategory WHERE Category = @Category;
		ELSE IF NOT EXISTS (SELECT 1 FROM Cash.tbCategory WHERE Category = @Category)
			AND (SELECT COUNT(*) FROM Cash.tbCode WHERE CashDescription = @Category) = 1
			SELECT @CategoryCode = CashCode FROM Cash.tbCode WHERE CashDescription = @Category;
		ELSE
			SET @CategoryCode = N'';
    END TRY
	BEGIN CATCH
		EXEC App.proc_ErrorLog;
	END CATCH
GO
PRINT N'Altering Procedure [Subject].[proc_RegistrationSave]...';


GO
ALTER PROCEDURE [Subject].[proc_RegistrationSave]
(
    @SubjectCode NVARCHAR(50),
    @RegistrationSchemeCode NVARCHAR(20),
    @RegistrationValue NVARCHAR(255),
    @ValidFrom DATE,
    @ValidTo DATE = NULL,
    @StatusCode SMALLINT = 0,
    @ValueSourceCode NVARCHAR(10) = N'USER',
    @IsReviewed BIT = 0,
    @RegistrationCode NVARCHAR(20) = NULL OUTPUT
)
AS
    SET NOCOUNT, XACT_ABORT ON;

    BEGIN TRY
        IF NULLIF(LTRIM(RTRIM(@RegistrationValue)), N'') IS NULL
        BEGIN
            IF @RegistrationCode IS NULL OR NOT EXISTS
            (
                SELECT 1
                FROM Subject.tbRegistration
                WHERE SubjectCode = @SubjectCode
                  AND RegistrationCode = @RegistrationCode
            )
                THROW 51030, 'Registration value is required.', 1;

            UPDATE Subject.tbRegistration
            SET ValidTo = @ValidTo,
                StatusCode = @StatusCode,
                ValueSourceCode = @ValueSourceCode,
                IsReviewed = @IsReviewed,
                UpdatedBy = Usr.fnUserName(),
                UpdatedOn = current_timestamp
            WHERE SubjectCode = @SubjectCode
              AND RegistrationCode = @RegistrationCode;

            RETURN;
        END;

        IF @RegistrationCode IS NULL
            EXEC Subject.proc_DefaultRegistrationCode
                @SubjectCode = @SubjectCode,
                @RegistrationSchemeCode = @RegistrationSchemeCode,
                @RegistrationCode = @RegistrationCode OUTPUT;

        IF EXISTS
        (
            SELECT 1
            FROM Subject.tbRegistration
            WHERE SubjectCode = @SubjectCode
              AND RegistrationCode = @RegistrationCode
        )
            UPDATE Subject.tbRegistration
            SET RegistrationSchemeCode = @RegistrationSchemeCode,
                RegistrationValue = @RegistrationValue,
                ValidFrom = @ValidFrom,
                ValidTo = @ValidTo,
                StatusCode = @StatusCode,
                ValueSourceCode = @ValueSourceCode,
                IsReviewed = @IsReviewed,
                UpdatedBy = Usr.fnUserName(),
                UpdatedOn = current_timestamp
            WHERE SubjectCode = @SubjectCode
              AND RegistrationCode = @RegistrationCode;
        ELSE
            INSERT Subject.tbRegistration
            (
                SubjectCode, RegistrationCode, RegistrationSchemeCode, RegistrationValue,
                ValidFrom, ValidTo, StatusCode, ValueSourceCode, IsReviewed
            )
            VALUES
            (
                @SubjectCode, @RegistrationCode, @RegistrationSchemeCode, @RegistrationValue,
                @ValidFrom, @ValidTo, @StatusCode, @ValueSourceCode, @IsReviewed
            );
    END TRY
    BEGIN CATCH
        EXEC App.proc_ErrorLog;
    END CATCH;
GO
PRINT N'Altering Procedure [Cash].[proc_PaymentMove]...';


GO
ALTER   PROCEDURE Cash.proc_PaymentMove
	(
	@PaymentCode nvarchar(20),
	@AccountCode nvarchar(10)
	)
  AS
    SET NOCOUNT, XACT_ABORT ON;

	BEGIN TRY
		DECLARE @OldAccountCode nvarchar(10)

		SELECT @OldAccountCode = AccountCode
		FROM         Cash.tbPayment
		WHERE     (PaymentCode = @PaymentCode)
	
		BEGIN TRANSACTION
	
		UPDATE Cash.tbPayment 
		SET AccountCode = @AccountCode,
			UpdatedOn = CURRENT_TIMESTAMP,
			UpdatedBy = (Usr.fnUserName())
		WHERE PaymentCode = @PaymentCode	

		EXEC Cash.proc_AccountRebuild @AccountCode
		EXEC Cash.proc_AccountRebuild @OldAccountCode
	
		COMMIT TRANSACTION
	 
  	END TRY
	BEGIN CATCH
		EXEC App.proc_ErrorLog;
	END CATCH
GO
