GO
ALTER   TRIGGER [Object].Object_tbMirror_Trigger_Update
ON Object.tbMirror
FOR UPDATE
AS
	SET NOCOUNT ON;

	BEGIN TRY
		IF NOT UPDATE(TransmitStatusCode)
		BEGIN
			UPDATE mirror
			SET 
				TransmitStatusCode = CASE WHEN Subject.TransmitStatusCode = 1 THEN 2 ELSE 0 END,
				UpdatedBy = Usr.fnUserName(),
				UpdatedOn = CURRENT_TIMESTAMP
			FROM Object.tbMirror mirror 
				JOIN inserted ON mirror.SubjectCode = inserted.SubjectCode AND mirror.ObjectCode = inserted.ObjectCode
				JOIN Subject.tbSubject Subject ON inserted.SubjectCode = Subject.SubjectCode
			WHERE inserted.TransmitStatusCode <> 1;
		END
	END TRY
	BEGIN CATCH
		EXEC App.proc_ErrorLog;
	END CATCH
GO
PRINT N'Altering Trigger [Object].[Object_tbObject_TriggerUpdate]...';


GO
/*  TRIGGERS ****/
ALTER   TRIGGER Object.Object_tbObject_TriggerUpdate
   ON  Object.tbObject
   AFTER UPDATE, INSERT
AS 
BEGIN
	SET NOCOUNT ON;
	BEGIN TRY	
		IF EXISTS
		(
			SELECT 1
			FROM inserted i
			JOIN Cash.tbCode cash_code ON cash_code.CashCode = i.CashCode
			LEFT JOIN deleted d ON d.ObjectCode = i.ObjectCode
			WHERE cash_code.IsEnabled = 0
			  AND (d.ObjectCode IS NULL OR ISNULL(d.CashCode, N'') <> ISNULL(i.CashCode, N''))
		)
			THROW 51012, 'An Object cannot be assigned a disabled CashCode.', 1;

		IF EXISTS (SELECT * FROM inserted i WHERE App.fnParsePrimaryKey(ObjectCode) = 0)
			BEGIN
			DECLARE @Msg NVARCHAR(MAX);
			SELECT @Msg = Message FROM App.tbText WHERE TextId = 2004;
			RAISERROR (@Msg, 10, 1)
			ROLLBACK
			END
		ELSE
			BEGIN
			UPDATE Object.tbObject
			SET UpdatedBy = Usr.fnUserName(), UpdatedOn = CURRENT_TIMESTAMP
			FROM Object.tbObject INNER JOIN inserted AS i ON tbObject.ObjectCode = i.ObjectCode;
			END
	END TRY
	BEGIN CATCH
		EXEC App.proc_ErrorLog;
	END CATCH
END
