PRINT N'Altering Procedure [App].[proc_DatasetCreateService]...';


GO
ALTER PROCEDURE App.proc_DatasetCreateService
(
	@ServiceName NVARCHAR(50) = N'Book',
	@UnitCharge DECIMAL(18, 7) = 0.0000000,
	@ObjectCode NVARCHAR(50) OUTPUT
)
AS
	SET NOCOUNT, XACT_ABORT ON;

	BEGIN TRY
		IF NOT EXISTS (SELECT 1 FROM Usr.vwCredentials WHERE IsAdministrator <> 0)
		BEGIN
			DECLARE @Msg NVARCHAR(100) = CONCAT('Access Denied: User ', Usr.fnUserName(), ' is not an administrsator');
			RAISERROR ('%s', 13, 1, @Msg);
		END

		DECLARE
			@ServiceNameNorm NVARCHAR(50) = LTRIM(RTRIM(COALESCE(@ServiceName, N''))),
			@SoObjectCode NVARCHAR(50),
			@PoObjectCode NVARCHAR(50),
			@PoTransportCode NVARCHAR(50) = N'PO Transport',
			@Uom NVARCHAR(15) = N'copies';

		IF @ServiceNameNorm = N''
			THROW 51030, 'proc_DatasetCreateService: @ServiceName is required.', 1;

		SET @SoObjectCode = CONCAT(N'SO ', @ServiceNameNorm);
		SET @PoObjectCode = CONCAT(N'PO ', @ServiceNameNorm);

		IF NOT EXISTS (SELECT 1 FROM App.tbUom WHERE UnitOfMeasure = @Uom)
			INSERT INTO App.tbUom (UnitOfMeasure) VALUES (@Uom);

		-- Output is always the root sales order
		SET @ObjectCode = @SoObjectCode;

		DECLARE
			@SoCashCode NVARCHAR(50) = N'CC-SALES',
			@PoCashCode NVARCHAR(50) =
			(
				SELECT TOP (1) CashCode
				FROM Cash.tbCode
				WHERE CashCode IN (N'CC-DIRCT', N'CC-COGS')
				  AND IsEnabled = 1
				ORDER BY CASE CashCode WHEN N'CC-DIRCT' THEN 0 ELSE 1 END
			),
			@SoUnitCharge DECIMAL(18, 7) = ISNULL(@UnitCharge, 0.0000000),
			@PoUnitCharge DECIMAL(18, 7) = CAST(ROUND(ISNULL(@UnitCharge, 0.0000000) * 0.7, 2) AS DECIMAL(18, 7));

		IF @PoCashCode IS NULL
			THROW 51031, 'Dataset: no enabled direct-cost CashCode is available (CC-DIRCT or CC-COGS).', 1;

		---------------------------------------------------------------------
		-- Objects
		---------------------------------------------------------------------
		IF NOT EXISTS (SELECT 1 FROM Object.tbObject WHERE ObjectCode = @SoObjectCode)
		BEGIN
			INSERT INTO Object.tbObject (ObjectCode, ProjectStatusCode, ObjectDescription, UnitOfMeasure, CashCode, UnitCharge, Printed, RegisterName)
			VALUES (@SoObjectCode, 1, N'', @Uom, @SoCashCode, @SoUnitCharge, 1, N'Sales Order');
		END

		IF NOT EXISTS (SELECT 1 FROM Object.tbObject WHERE ObjectCode = @PoObjectCode)
		BEGIN
			INSERT INTO Object.tbObject (ObjectCode, ProjectStatusCode, ObjectDescription, UnitOfMeasure, CashCode, UnitCharge, Printed, RegisterName)
			VALUES (@PoObjectCode, 1, N'', @Uom, @PoCashCode, @PoUnitCharge, 1, N'Purchase Order');
		END

		IF NOT EXISTS (SELECT 1 FROM Object.tbObject WHERE ObjectCode = @PoTransportCode)
		BEGIN
			INSERT INTO Object.tbObject (ObjectCode, ProjectStatusCode, ObjectDescription, UnitOfMeasure, CashCode, UnitCharge, Printed, RegisterName)
			VALUES (@PoTransportCode, 1, N'', N'each', @PoCashCode, CAST(100.0000000 AS decimal(18,7)), 1, N'Purchase Order');
		END

		---------------------------------------------------------------------
		-- Attributes (idempotent, per attribute)
		---------------------------------------------------------------------
		DECLARE @Attr TABLE
		(
			ObjectCode NVARCHAR(50) NOT NULL,
			Attribute NVARCHAR(50) NOT NULL,
			PrintOrder SMALLINT NOT NULL,
			AttributeTypeCode SMALLINT NOT NULL,
			DefaultText NVARCHAR(400) NULL
		);

		-- Template: SO Brochure or Catalogue -> SO <ServiceName>
		INSERT INTO @Attr (ObjectCode, Attribute, PrintOrder, AttributeTypeCode, DefaultText)
		VALUES
			(@SoObjectCode, N'Delivery #1', 160, 0, N''),
			(@SoObjectCode, N'Finishing', 90, 0, N''),
			(@SoObjectCode, N'Note', 150, 0, N''),
			(@SoObjectCode, N'Origination', 40, 0, N''),
			(@SoObjectCode, N'Packing', 100, 0, N''),
			(@SoObjectCode, N'Pagination', 20, 0, N''),
			(@SoObjectCode, N'Paper', 80, 0, N''),
			(@SoObjectCode, N'Printing', 60, 0, N''),
			(@SoObjectCode, N'Proofing', 50, 0, N''),
			(@SoObjectCode, N'Trim Size', 30, 0, N''),
			(@SoObjectCode, N'UV Varnish', 70, 0, N'');

		-- Template: PO Brochure or Catalogue -> PO <ServiceName>
		INSERT INTO @Attr (ObjectCode, Attribute, PrintOrder, AttributeTypeCode, DefaultText)
		VALUES
			(@PoObjectCode, N'Delivery #1', 155, 0, N''),
			(@PoObjectCode, N'File Copies', 160, 0, N''),
			(@PoObjectCode, N'Finishing', 90, 0, N''),
			(@PoObjectCode, N'Note', 150, 0, N''),
			(@PoObjectCode, N'Origination', 40, 0, N''),
			(@PoObjectCode, N'Packing', 100, 0, N''),
			(@PoObjectCode, N'Pagination', 20, 0, N''),
			(@PoObjectCode, N'Paper', 80, 0, N''),
			(@PoObjectCode, N'Printing', 60, 0, N''),
			(@PoObjectCode, N'Proofing', 50, 0, N''),
			(@PoObjectCode, N'Trim Size', 30, 0, N''),
			(@PoObjectCode, N'UV Varnish', 70, 0, N'');

		-- Template: PO Transport -> PO Transport
		INSERT INTO @Attr (ObjectCode, Attribute, PrintOrder, AttributeTypeCode, DefaultText)
		VALUES
			(@PoTransportCode, N'Collection', 20, 0, N''),
			(@PoTransportCode, N'Description', 10, 0, N''),
			(@PoTransportCode, N'Note', 30, 1, N'');

		MERGE Object.tbAttribute AS t
		USING @Attr AS s
			ON t.ObjectCode = s.ObjectCode
			AND t.Attribute = s.Attribute
		WHEN NOT MATCHED THEN
			INSERT (ObjectCode, Attribute, PrintOrder, AttributeTypeCode, DefaultText)
			VALUES (s.ObjectCode, s.Attribute, s.PrintOrder, s.AttributeTypeCode, s.DefaultText)
		WHEN MATCHED THEN
			UPDATE SET
				PrintOrder = s.PrintOrder,
				AttributeTypeCode = s.AttributeTypeCode,
				DefaultText = s.DefaultText;

		---------------------------------------------------------------------
		-- Operations (idempotent, per operation number)
		---------------------------------------------------------------------
		DECLARE @Ops TABLE
		(
			ObjectCode NVARCHAR(50) NOT NULL,
			OperationNumber SMALLINT NOT NULL,
			SyncTypeCode SMALLINT NOT NULL,
			Operation NVARCHAR(50) NOT NULL,
			Duration DECIMAL(18, 4) NULL,
			OffsetDays SMALLINT NOT NULL
		);

		-- Template: SO <ServiceName>
		INSERT INTO @Ops (ObjectCode, OperationNumber, SyncTypeCode, Operation, Duration, OffsetDays)
		VALUES
			(@SoObjectCode, 10, 0, N'Artwork', 0, 0),
			(@SoObjectCode, 20, 0, N'Proofs', 0, 2),
			(@SoObjectCode, 30, 0, N'Approval', 0, 3),
			(@SoObjectCode, 40, 2, N'Delivery', 0, 5);

		-- Template: PO <ServiceName>
		INSERT INTO @Ops (ObjectCode, OperationNumber, SyncTypeCode, Operation, Duration, OffsetDays)
		VALUES
			(@PoObjectCode, 10, 0, N'Artwork', 0, 0),
			(@PoObjectCode, 20, 0, N'Proofs', 0, 0),
			(@PoObjectCode, 30, 0, N'Approval', 0, 0),
			(@PoObjectCode, 50, 2, N'Delivery', 0, 0);

		-- Template: PO Transport
		INSERT INTO @Ops (ObjectCode, OperationNumber, SyncTypeCode, Operation, Duration, OffsetDays)
		VALUES
			(@PoTransportCode, 10, 0, N'Despatch', 0, 0),
			(@PoTransportCode, 20, 2, N'Delivery', 0, 0);

		MERGE Object.tbOp AS t
		USING @Ops AS s
			ON t.ObjectCode = s.ObjectCode
			AND t.OperationNumber = s.OperationNumber
		WHEN NOT MATCHED THEN
			INSERT (ObjectCode, OperationNumber, SyncTypeCode, Operation, Duration, OffsetDays)
			VALUES (s.ObjectCode, s.OperationNumber, s.SyncTypeCode, s.Operation, s.Duration, s.OffsetDays)
		WHEN MATCHED THEN
			UPDATE SET
				SyncTypeCode = s.SyncTypeCode,
				Operation = s.Operation,
				Duration = s.Duration,
				OffsetDays = s.OffsetDays;

		---------------------------------------------------------------------
		-- Flow (idempotent, per step)
		---------------------------------------------------------------------
		MERGE Object.tbFlow AS t
		USING
		(
			SELECT @SoObjectCode AS ParentCode, CAST(10 AS SMALLINT) AS StepNumber, @PoObjectCode AS ChildCode, CAST(0 AS SMALLINT) AS SyncTypeCode, CAST(0 AS SMALLINT) AS OffsetDays, CAST(1.000000 AS DECIMAL(18, 6)) AS UsedOnQuantity
			UNION ALL
			SELECT @SoObjectCode AS ParentCode, CAST(20 AS SMALLINT) AS StepNumber, @PoTransportCode AS ChildCode, CAST(0 AS SMALLINT) AS SyncTypeCode, CAST(0 AS SMALLINT) AS OffsetDays, CAST(0.000000 AS DECIMAL(18, 6)) AS UsedOnQuantity
		) AS s
			ON t.ParentCode = s.ParentCode
			AND t.StepNumber = s.StepNumber
		WHEN NOT MATCHED THEN
			INSERT (ParentCode, StepNumber, ChildCode, SyncTypeCode, OffsetDays, UsedOnQuantity)
			VALUES (s.ParentCode, s.StepNumber, s.ChildCode, s.SyncTypeCode, s.OffsetDays, s.UsedOnQuantity)
		WHEN MATCHED THEN
			UPDATE SET
				ChildCode = s.ChildCode,
				SyncTypeCode = s.SyncTypeCode,
				OffsetDays = s.OffsetDays,
				UsedOnQuantity = s.UsedOnQuantity;

	END TRY
	BEGIN CATCH
		EXEC App.proc_ErrorLog;
	END CATCH
GO
PRINT N'Altering Procedure [App].[proc_DatasetCreateProduct]...';


GO
ALTER PROCEDURE App.proc_DatasetCreateProduct
(
	@MaterialType NVARCHAR(20) = N'CLEAR',
	@ObjectCode NVARCHAR(50) OUTPUT
)
AS
	SET NOCOUNT, XACT_ABORT ON;

	BEGIN TRY

		IF NOT EXISTS (SELECT 1 FROM Usr.vwCredentials WHERE IsAdministrator <> 0)
		BEGIN
			DECLARE @Msg NVARCHAR(100) = CONCAT('Access Denied: User ', Usr.fnUserName(), ' is not an administrsator');
			RAISERROR ('%s', 13, 1, @Msg);
		END

		DECLARE @ExchangeRate float =
			CASE (SELECT UnitOfCharge FROM App.tbOptions)
				WHEN 'BTC' THEN 0.135
				ELSE 1
			END;

		DECLARE @DirectCostCashCode nvarchar(50) =
		(
			SELECT TOP (1) CashCode
			FROM Cash.tbCode
			WHERE CashCode IN (N'CC-DIRCT', N'CC-COGS')
			  AND IsEnabled = 1
			ORDER BY CASE CashCode WHEN N'CC-DIRCT' THEN 0 ELSE 1 END
		);

		IF @DirectCostCashCode IS NULL
			THROW 51011, 'Dataset: no enabled direct-cost CashCode is available (CC-DIRCT or CC-COGS).', 1;

		DECLARE
			@MaterialTypeNorm NVARCHAR(20) = UPPER(LTRIM(RTRIM(ISNULL(@MaterialType, N'')))),
			@ObjectPropertyCode NVARCHAR(2);

		IF @MaterialTypeNorm = N''
			SET @MaterialTypeNorm = N'CLEAR';

		IF @MaterialTypeNorm NOT IN (N'CLEAR', N'RED', N'BLUE', N'GREEN', N'BLACK', N'WHITE')
			THROW 51010, 'Dataset: invalid @MaterialType. Allowed: CLEAR, RED, BLUE, GREEN, BLACK, WHITE.', 1;

		SET @ObjectPropertyCode =
			CASE @MaterialTypeNorm
				WHEN N'RED' THEN N'00'
				WHEN N'BLUE' THEN N'01'
				WHEN N'GREEN' THEN N'02'
				WHEN N'BLACK' THEN N'03'
				WHEN N'WHITE' THEN N'04'
				WHEN N'CLEAR' THEN N'05'
			END;

		DECLARE
			@FgCode NVARCHAR(50) = CONCAT(N'DS/PRD/FG/W/', @ObjectPropertyCode),
			@SubShelfCode NVARCHAR(50) = CONCAT(N'DS/PRD/CMP/W/100/', @ObjectPropertyCode),
			@BackDividerCode NVARCHAR(50) = CONCAT(N'DS/PRD/CMP/W/101/', @ObjectPropertyCode),
			@WideFootCode NVARCHAR(50) = CONCAT(N'DS/PRD/CMP/W/097/', @ObjectPropertyCode),
			@NarrowFootCode NVARCHAR(50) = CONCAT(N'DS/PRD/CMP/W/099/', @ObjectPropertyCode),

			@PalletCode NVARCHAR(50) = CONCAT(N'DS/PRD/CMP/BOX/PALLET/', @ObjectPropertyCode),
			@Box41Code NVARCHAR(50) = CONCAT(N'DS/PRD/CMP/BOX/41/', @ObjectPropertyCode),
			@Box99Code NVARCHAR(50) = CONCAT(N'DS/PRD/CMP/BOX/99/', @ObjectPropertyCode),
			@Insert09Code NVARCHAR(50) = CONCAT(N'DS/PRD/CMP/INS/09/', @ObjectPropertyCode),

			@MaterialPcCode NVARCHAR(50) = CONCAT(N'DS/PRD/MTR/PC/', @ObjectPropertyCode),
			@DeliveryCode NVARCHAR(50) = CONCAT(N'DS/SRV/SHP/DELIVERY/', @ObjectPropertyCode);

		SET @ObjectCode = @FgCode;

		IF NOT EXISTS (SELECT 1 FROM App.tbRegister WHERE RegisterName = 'Works Order')
		BEGIN
			INSERT INTO App.tbRegister (RegisterName, NextNumber)
			SELECT 'Works Order', (SELECT MAX(NextNumber) + 10000 FROM App.tbRegister) AS NextNumber;
		END

		---------------------------------------------------------------------
		-- Objects (mirror proc_DemoBom "shape": UOM, unit charges, printed, registers)
		---------------------------------------------------------------------
		IF NOT EXISTS (SELECT 1 FROM Object.tbObject WHERE ObjectCode = @FgCode)
		BEGIN
			INSERT INTO Object.tbObject (ObjectCode, ProjectStatusCode, ObjectDescription, UnitOfMeasure, CashCode, UnitCharge, Printed, RegisterName)
			VALUES (@FgCode, 1, CONCAT(N'DATASET WIDGET ASSEMBLY ', @MaterialTypeNorm), N'each', N'CC-SALES', CAST(1.67 * @ExchangeRate AS decimal(18,7)), 1, N'Sales Order');
		END

		IF NOT EXISTS (SELECT 1 FROM Object.tbObject WHERE ObjectCode = @SubShelfCode)
			INSERT INTO Object.tbObject (ObjectCode, ProjectStatusCode, ObjectDescription, UnitOfMeasure, CashCode, UnitCharge, Printed, RegisterName)
			VALUES (@SubShelfCode, 1, CONCAT(N'DATASET SUB SHELF ', @MaterialTypeNorm), N'each', NULL, 0, 0, N'Works Order');

		IF NOT EXISTS (SELECT 1 FROM Object.tbObject WHERE ObjectCode = @BackDividerCode)
			INSERT INTO Object.tbObject (ObjectCode, ProjectStatusCode, ObjectDescription, UnitOfMeasure, CashCode, UnitCharge, Printed, RegisterName)
			VALUES (@BackDividerCode, 1, N'DATASET BACK DIVIDER', N'each', NULL, 0, 0, N'Works Order');

		IF NOT EXISTS (SELECT 1 FROM Object.tbObject WHERE ObjectCode = @WideFootCode)
			INSERT INTO Object.tbObject (ObjectCode, ProjectStatusCode, ObjectDescription, UnitOfMeasure, CashCode, UnitCharge, Printed, RegisterName)
			VALUES (@WideFootCode, 1, N'DATASET DIVIDER (WIDE FOOT)', N'each', NULL, 0, 0, N'Works Order');

		IF NOT EXISTS (SELECT 1 FROM Object.tbObject WHERE ObjectCode = @NarrowFootCode)
			INSERT INTO Object.tbObject (ObjectCode, ProjectStatusCode, ObjectDescription, UnitOfMeasure, CashCode, UnitCharge, Printed, RegisterName)
			VALUES (@NarrowFootCode, 1, N'DATASET DIVIDER (NARROW FOOT)', N'each', NULL, 0, 0, N'Works Order');

		IF NOT EXISTS (SELECT 1 FROM Object.tbObject WHERE ObjectCode = @PalletCode)
			INSERT INTO Object.tbObject (ObjectCode, ProjectStatusCode, ObjectDescription, UnitOfMeasure, CashCode, UnitCharge, Printed, RegisterName)
			VALUES (@PalletCode, 1, N'DATASET EURO PALLET', N'each', @DirectCostCashCode, CAST(2.4 * @ExchangeRate AS decimal(18,7)), 1, N'Purchase Order');

		IF NOT EXISTS (SELECT 1 FROM Object.tbObject WHERE ObjectCode = @Box41Code)
			INSERT INTO Object.tbObject (ObjectCode, ProjectStatusCode, ObjectDescription, UnitOfMeasure, CashCode, UnitCharge, Printed, RegisterName)
			VALUES (@Box41Code, 1, N'DATASET OUTER BOX', N'each', @DirectCostCashCode, CAST(0.05 * @ExchangeRate AS decimal(18,7)), 1, N'Purchase Order');

		IF NOT EXISTS (SELECT 1 FROM Object.tbObject WHERE ObjectCode = @Box99Code)
			INSERT INTO Object.tbObject (ObjectCode, ProjectStatusCode, ObjectDescription, UnitOfMeasure, CashCode, UnitCharge, Printed, RegisterName)
			VALUES (@Box99Code, 1, N'DATASET INTERNAL BOX', N'each', NULL, 0, 0, N'Works Order');

		IF NOT EXISTS (SELECT 1 FROM Object.tbObject WHERE ObjectCode = @MaterialPcCode)
			INSERT INTO Object.tbObject (ObjectCode, ProjectStatusCode, ObjectDescription, UnitOfMeasure, CashCode, UnitCharge, Printed, RegisterName)
			VALUES (@MaterialPcCode, 1, CONCAT(N'DATASET PLASTIC ', @MaterialTypeNorm), N'kilo', @DirectCostCashCode, CAST(0.22 * @ExchangeRate AS decimal(18,7)), 1, N'Purchase Order');

		IF NOT EXISTS (SELECT 1 FROM Object.tbObject WHERE ObjectCode = @Insert09Code)
			INSERT INTO Object.tbObject (ObjectCode, ProjectStatusCode, ObjectDescription, UnitOfMeasure, CashCode, UnitCharge, Printed, RegisterName)
			VALUES (@Insert09Code, 1, N'DATASET INSERTS', N'each', @DirectCostCashCode, CAST(0.005 * @ExchangeRate AS decimal(18,7)), 1, N'Purchase Order');

		IF NOT EXISTS (SELECT 1 FROM Object.tbObject WHERE ObjectCode = @DeliveryCode)
			INSERT INTO Object.tbObject (ObjectCode, ProjectStatusCode, ObjectDescription, UnitOfMeasure, CashCode, UnitCharge, Printed, RegisterName)
			VALUES (@DeliveryCode, 1, N'DATASET DELIVERY', N'each', @DirectCostCashCode, CAST(100.0000000 * @ExchangeRate AS decimal(18,7)), 1, N'Purchase Order');

		---------------------------------------------------------------------
		-- Attributes (mirror proc_DemoBom set; inject @MaterialTypeNorm for Colour)
		---------------------------------------------------------------------
		DECLARE @Attr AS TABLE
		(
			ObjectCode NVARCHAR(50) NOT NULL,
			Attribute NVARCHAR(50) NOT NULL,
			PrintOrder SMALLINT NOT NULL,
			AttributeTypeCode SMALLINT NOT NULL,
			DefaultText NVARCHAR(400) NULL
		);

		-- Finished good (equivalent to M/00/70/00)
		INSERT INTO @Attr (ObjectCode, Attribute, PrintOrder, AttributeTypeCode, DefaultText)
		VALUES
			(@FgCode, N'Colour', 20, 0, @MaterialTypeNorm),
			(@FgCode, N'Colour Number', 10, 0, N'-'),
			(@FgCode, N'Count Type', 50, 0, N'Weigh Count'),
			(@FgCode, N'Drawing Issue', 40, 0, N'1'),
			(@FgCode, N'Drawing Number', 30, 0, N'321554'),
			(@FgCode, N'Label Type', 70, 0, N'Assembly Card'),
			(@FgCode, N'Mould Tool Specification', 110, 1, NULL),
			(@FgCode, N'Pack Type', 60, 0, N'Despatched'),
			(@FgCode, N'Quantity/Box', 80, 0, N'100');

		-- Sub shelf (equivalent to M/100/70/00)
		INSERT INTO @Attr (ObjectCode, Attribute, PrintOrder, AttributeTypeCode, DefaultText)
		VALUES
			(@SubShelfCode, N'Cavities', 170, 0, N'1'),
			(@SubShelfCode, N'Colour', 20, 0, @MaterialTypeNorm),
			(@SubShelfCode, N'Colour Number', 10, 0, N'-'),
			(@SubShelfCode, N'Count Type', 50, 0, N'Weigh Count'),
			(@SubShelfCode, N'Drawing Issue', 40, 0, N'1'),
			(@SubShelfCode, N'Drawing Number', 30, 0, N'321554-01'),
			(@SubShelfCode, N'Impressions', 180, 0, N'1'),
			(@SubShelfCode, N'Label Type', 70, 0, N'Route Card'),
			(@SubShelfCode, N'Location', 150, 0, N'STORES'),
			(@SubShelfCode, N'Pack Type', 60, 0, N'Assembled'),
			(@SubShelfCode, N'Part Weight', 160, 0, N'175g'),
			(@SubShelfCode, N'Quantity/Box', 80, 0, N'100'),
			(@SubShelfCode, N'Tool Number', 190, 0, N'1437');

		-- Back divider (equivalent to M/101/70/00)
		INSERT INTO @Attr (ObjectCode, Attribute, PrintOrder, AttributeTypeCode, DefaultText)
		VALUES
			(@BackDividerCode, N'Cavities', 170, 0, N'2'),
			(@BackDividerCode, N'Colour', 20, 0, @MaterialTypeNorm),
			(@BackDividerCode, N'Colour Number', 10, 0, N'-'),
			(@BackDividerCode, N'Count Type', 50, 0, N'Weigh Count'),
			(@BackDividerCode, N'Drawing Issue', 40, 0, N'1'),
			(@BackDividerCode, N'Drawing Number', 30, 0, N'321554-02'),
			(@BackDividerCode, N'Impressions', 180, 0, N'2'),
			(@BackDividerCode, N'Label Type', 70, 0, N'Route Card'),
			(@BackDividerCode, N'Location', 150, 0, N'STORES'),
			(@BackDividerCode, N'Pack Type', 60, 0, N'Assembled'),
			(@BackDividerCode, N'Part Weight', 160, 0, N'61g'),
			(@BackDividerCode, N'Quantity/Box', 80, 0, N'100'),
			(@BackDividerCode, N'Tool Number', 190, 0, N'1439');

		-- Wide foot (equivalent to M/97/70/00)
		INSERT INTO @Attr (ObjectCode, Attribute, PrintOrder, AttributeTypeCode, DefaultText)
		VALUES
			(@WideFootCode, N'Cavities', 170, 0, N'4'),
			(@WideFootCode, N'Colour', 20, 0, @MaterialTypeNorm),
			(@WideFootCode, N'Colour Number', 10, 0, N'-'),
			(@WideFootCode, N'Count Type', 50, 0, N'Weigh Count'),
			(@WideFootCode, N'Drawing Issue', 40, 0, N'1'),
			(@WideFootCode, N'Drawing Number', 30, 0, N'321554A'),
			(@WideFootCode, N'Impressions', 180, 0, N'4'),
			(@WideFootCode, N'Label Type', 70, 0, N'Route Card'),
			(@WideFootCode, N'Location', 150, 0, N'STORES'),
			(@WideFootCode, N'Pack Type', 60, 0, N'Assembled'),
			(@WideFootCode, N'Part Weight', 160, 0, N'171g'),
			(@WideFootCode, N'Quantity/Box', 80, 0, N'100'),
			(@WideFootCode, N'Tool Number', 190, 0, N'1440');

		-- Narrow foot (equivalent to M/99/70/00)
		INSERT INTO @Attr (ObjectCode, Attribute, PrintOrder, AttributeTypeCode, DefaultText)
		VALUES
			(@NarrowFootCode, N'Cavities', 170, 0, N'1'),
			(@NarrowFootCode, N'Colour', 20, 0, @MaterialTypeNorm),
			(@NarrowFootCode, N'Colour Number', 10, 0, N'-'),
			(@NarrowFootCode, N'Count Type', 50, 0, N'Weigh Count'),
			(@NarrowFootCode, N'Drawing Issue', 40, 0, N'1'),
			(@NarrowFootCode, N'Drawing Number', 30, 0, N'321554A'),
			(@NarrowFootCode, N'Impressions', 180, 0, N'1'),
			(@NarrowFootCode, N'Label Type', 70, 0, N'Route Card'),
			(@NarrowFootCode, N'Location', 150, 0, N'STORES'),
			(@NarrowFootCode, N'Pack Type', 60, 0, N'Assembled'),
			(@NarrowFootCode, N'Part Weight', 160, 0, N'171g'),
			(@NarrowFootCode, N'Quantity/Box', 80, 0, N'100'),
			(@NarrowFootCode, N'Tool Number', 190, 0, N'1441');

		-- Plastic material (equivalent to PC/999)
		INSERT INTO @Attr (ObjectCode, Attribute, PrintOrder, AttributeTypeCode, DefaultText)
		VALUES
			(@MaterialPcCode, N'Colour', 50, 0, @MaterialTypeNorm),
			(@MaterialPcCode, N'Grade', 20, 0, N'303EP'),
			(@MaterialPcCode, N'Location', 60, 0, N'R2123-9'),
			(@MaterialPcCode, N'Material Type', 10, 0, N'PC'),
			(@MaterialPcCode, N'Name', 30, 0, N'Calibre'),
			(@MaterialPcCode, N'SG', 40, 0, N'1.21');

		MERGE Object.tbAttribute AS t
		USING @Attr AS s
			ON t.ObjectCode = s.ObjectCode
			AND t.Attribute = s.Attribute
		WHEN NOT MATCHED THEN
			INSERT (ObjectCode, Attribute, PrintOrder, AttributeTypeCode, DefaultText)
			VALUES (s.ObjectCode, s.Attribute, s.PrintOrder, s.AttributeTypeCode, s.DefaultText)
		WHEN MATCHED THEN
			UPDATE SET
				PrintOrder = s.PrintOrder,
				AttributeTypeCode = s.AttributeTypeCode,
				DefaultText = s.DefaultText;

		---------------------------------------------------------------------
		-- Ops (match proc_DemoBom timings/offsets/durations)
		---------------------------------------------------------------------
		IF NOT EXISTS (SELECT 1 FROM Object.tbOp WHERE ObjectCode = @FgCode)
		BEGIN
			INSERT INTO Object.tbOp (ObjectCode, OperationNumber, SyncTypeCode, Operation, Duration, OffsetDays)
			VALUES (@FgCode, 10, 0, 'ASSEMBLE', 0.5, 3),
				   (@FgCode, 20, 0, 'QUALITY CHECK', 0, 0),
				   (@FgCode, 30, 0, 'PACK', 0, 1),
				   (@FgCode, 40, 2, 'DELIVER', 0, 1);
		END

		IF NOT EXISTS (SELECT 1 FROM Object.tbOp WHERE ObjectCode = @SubShelfCode)
		BEGIN
			INSERT INTO Object.tbOp (ObjectCode, OperationNumber, SyncTypeCode, Operation, Duration, OffsetDays)
			VALUES (@SubShelfCode, 10, 0, 'MOULD', 10, 2),
				   (@SubShelfCode, 20, 1, 'INSERTS', 0, 0),
				   (@SubShelfCode, 30, 0, 'QUALITY CHECK', 0, 0);
		END

		IF NOT EXISTS (SELECT 1 FROM Object.tbOp WHERE ObjectCode = @BackDividerCode)
		BEGIN
			INSERT INTO Object.tbOp (ObjectCode, OperationNumber, SyncTypeCode, Operation, Duration, OffsetDays)
			VALUES (@BackDividerCode, 10, 0, 'MOULD', 10, 0),
				   (@BackDividerCode, 20, 0, 'QUALITY CHECK', 0, 0);
		END

		IF NOT EXISTS (SELECT 1 FROM Object.tbOp WHERE ObjectCode = @WideFootCode)
		BEGIN
			INSERT INTO Object.tbOp (ObjectCode, OperationNumber, SyncTypeCode, Operation, Duration, OffsetDays)
			VALUES (@WideFootCode, 10, 0, 'MOULD', 10, 2),
				   (@WideFootCode, 20, 0, 'QUALITY CHECK', 0, 0);
		END

		IF NOT EXISTS (SELECT 1 FROM Object.tbOp WHERE ObjectCode = @NarrowFootCode)
		BEGIN
			INSERT INTO Object.tbOp (ObjectCode, OperationNumber, SyncTypeCode, Operation, Duration, OffsetDays)
			VALUES (@NarrowFootCode, 10, 0, 'MOULD', 0, 2),
				   (@NarrowFootCode, 20, 0, 'QUALITY CHECK', 0, 0);
		END

		---------------------------------------------------------------------
		-- BOM Flow (same structure/quantities/sync types/offsets as proc_DemoBom)
		---------------------------------------------------------------------
		IF NOT EXISTS (SELECT 1 FROM Object.tbFlow WHERE ParentCode = @FgCode AND StepNumber = 10)
			INSERT INTO Object.tbFlow (ParentCode, StepNumber, ChildCode, SyncTypeCode, OffsetDays, UsedOnQuantity)
			VALUES (@FgCode, 10, @SubShelfCode, 1, 0, 8);

		IF NOT EXISTS (SELECT 1 FROM Object.tbFlow WHERE ParentCode = @FgCode AND StepNumber = 20)
			INSERT INTO Object.tbFlow (ParentCode, StepNumber, ChildCode, SyncTypeCode, OffsetDays, UsedOnQuantity)
			VALUES (@FgCode, 20, @BackDividerCode, 1, 0, 4);

		IF NOT EXISTS (SELECT 1 FROM Object.tbFlow WHERE ParentCode = @FgCode AND StepNumber = 30)
			INSERT INTO Object.tbFlow (ParentCode, StepNumber, ChildCode, SyncTypeCode, OffsetDays, UsedOnQuantity)
			VALUES (@FgCode, 30, @WideFootCode, 1, 0, 3);

		IF NOT EXISTS (SELECT 1 FROM Object.tbFlow WHERE ParentCode = @FgCode AND StepNumber = 40)
			INSERT INTO Object.tbFlow (ParentCode, StepNumber, ChildCode, SyncTypeCode, OffsetDays, UsedOnQuantity)
			VALUES (@FgCode, 40, @NarrowFootCode, 0, 0, 2);

		IF NOT EXISTS (SELECT 1 FROM Object.tbFlow WHERE ParentCode = @FgCode AND StepNumber = 50)
			INSERT INTO Object.tbFlow (ParentCode, StepNumber, ChildCode, SyncTypeCode, OffsetDays, UsedOnQuantity)
			VALUES (@FgCode, 50, @Box41Code, 1, 0, 1);

		IF NOT EXISTS (SELECT 1 FROM Object.tbFlow WHERE ParentCode = @FgCode AND StepNumber = 60)
			INSERT INTO Object.tbFlow (ParentCode, StepNumber, ChildCode, SyncTypeCode, OffsetDays, UsedOnQuantity)
			VALUES (@FgCode, 60, @PalletCode, 1, 0, 0.01);

		IF NOT EXISTS (SELECT 1 FROM Object.tbFlow WHERE ParentCode = @FgCode AND StepNumber = 70)
			INSERT INTO Object.tbFlow (ParentCode, StepNumber, ChildCode, SyncTypeCode, OffsetDays, UsedOnQuantity)
			VALUES (@FgCode, 70, @DeliveryCode, 2, 1, 0);

		IF NOT EXISTS (SELECT 1 FROM Object.tbFlow WHERE ParentCode = @SubShelfCode AND StepNumber = 10)
			INSERT INTO Object.tbFlow (ParentCode, StepNumber, ChildCode, SyncTypeCode, OffsetDays, UsedOnQuantity)
			VALUES (@SubShelfCode, 10, @Box99Code, 1, 0, 0.01);

		IF NOT EXISTS (SELECT 1 FROM Object.tbFlow WHERE ParentCode = @SubShelfCode AND StepNumber = 20)
			INSERT INTO Object.tbFlow (ParentCode, StepNumber, ChildCode, SyncTypeCode, OffsetDays, UsedOnQuantity)
			VALUES (@SubShelfCode, 20, @MaterialPcCode, 1, 0, 0.175);

		IF NOT EXISTS (SELECT 1 FROM Object.tbFlow WHERE ParentCode = @SubShelfCode AND StepNumber = 30)
			INSERT INTO Object.tbFlow (ParentCode, StepNumber, ChildCode, SyncTypeCode, OffsetDays, UsedOnQuantity)
			VALUES (@SubShelfCode, 30, @Insert09Code, 1, 0, 2);

		IF NOT EXISTS (SELECT 1 FROM Object.tbFlow WHERE ParentCode = @BackDividerCode AND StepNumber = 10)
			INSERT INTO Object.tbFlow (ParentCode, StepNumber, ChildCode, SyncTypeCode, OffsetDays, UsedOnQuantity)
			VALUES (@BackDividerCode, 10, @Box99Code, 1, 0, 0.01);

		IF NOT EXISTS (SELECT 1 FROM Object.tbFlow WHERE ParentCode = @BackDividerCode AND StepNumber = 20)
			INSERT INTO Object.tbFlow (ParentCode, StepNumber, ChildCode, SyncTypeCode, OffsetDays, UsedOnQuantity)
			VALUES (@BackDividerCode, 20, @MaterialPcCode, 1, 0, 0.061);

		IF NOT EXISTS (SELECT 1 FROM Object.tbFlow WHERE ParentCode = @WideFootCode AND StepNumber = 10)
			INSERT INTO Object.tbFlow (ParentCode, StepNumber, ChildCode, SyncTypeCode, OffsetDays, UsedOnQuantity)
			VALUES (@WideFootCode, 10, @Box99Code, 1, 0, 0.01);

		IF NOT EXISTS (SELECT 1 FROM Object.tbFlow WHERE ParentCode = @WideFootCode AND StepNumber = 20)
			INSERT INTO Object.tbFlow (ParentCode, StepNumber, ChildCode, SyncTypeCode, OffsetDays, UsedOnQuantity)
			VALUES (@WideFootCode, 20, @MaterialPcCode, 1, 0, 0.172);

		IF NOT EXISTS (SELECT 1 FROM Object.tbFlow WHERE ParentCode = @NarrowFootCode AND StepNumber = 10)
			INSERT INTO Object.tbFlow (ParentCode, StepNumber, ChildCode, SyncTypeCode, OffsetDays, UsedOnQuantity)
			VALUES (@NarrowFootCode, 10, @Box99Code, 1, 0, 0.01);

		IF NOT EXISTS (SELECT 1 FROM Object.tbFlow WHERE ParentCode = @NarrowFootCode AND StepNumber = 20)
			INSERT INTO Object.tbFlow (ParentCode, StepNumber, ChildCode, SyncTypeCode, OffsetDays, UsedOnQuantity)
			VALUES (@NarrowFootCode, 20, @MaterialPcCode, 1, 0, 0.171);

	END TRY
	BEGIN CATCH
		EXEC App.proc_ErrorLog;
	END CATCH
GO
PRINT N'Altering Procedure [Cash].[proc_ReportingProfileSave]...';


GO
ALTER PROCEDURE [Cash].[proc_ReportingProfileSave]
(
    @SubjectCode NVARCHAR(50),
    @ReportingTypeCode SMALLINT,
    @TaxSourceCode NVARCHAR(20),
    @AuthorityReference NVARCHAR(100) = NULL,
    @ValidFrom DATE,
    @ValidTo DATE = NULL,
    @StatusCode SMALLINT = 0,
    @ValueSourceCode NVARCHAR(10) = N'USER',
    @IsReviewed BIT = 0,
    @ReportingProfileCode NVARCHAR(20) = NULL OUTPUT
)
AS
    SET NOCOUNT, XACT_ABORT ON;

    BEGIN TRY
        DECLARE @AuthorityCode NVARCHAR(20) =
        (
            SELECT AuthorityCode
            FROM App.tbReportingType
            WHERE ReportingTypeCode = @ReportingTypeCode
              AND IsEnabled = 1
        );

        IF @AuthorityCode IS NULL
            THROW 51031, 'An enabled reporting type is required.', 1;

        IF @StatusCode = 1 AND @IsReviewed = 0
            THROW 51032, 'An active reporting profile must be reviewed.', 1;

        IF @ReportingTypeCode = 0
        BEGIN
            DECLARE @SubjectVatNumber NVARCHAR(50) =
            (
                SELECT TOP (1) NULLIF(LTRIM(RTRIM(VatNumber)), N'')
                FROM Cash.vwTaxVatIdentity
                WHERE SubjectCode = @SubjectCode
            );

            IF @SubjectVatNumber IS NOT NULL
               AND (LEN(@SubjectVatNumber) <> 9 OR @SubjectVatNumber LIKE N'%[^0-9]%')
                THROW 51033, 'The reporting subject VAT registration number must contain nine digits.', 1;

            SET @AuthorityReference = @SubjectVatNumber;
        END;

        IF @ReportingProfileCode IS NULL
            EXEC Cash.proc_DefaultReportingProfileCode
                @SubjectCode = @SubjectCode,
                @ReportingTypeCode = @ReportingTypeCode,
                @ReportingProfileCode = @ReportingProfileCode OUTPUT;

        IF EXISTS
        (
            SELECT 1
            FROM Cash.tbReportingProfile
            WHERE SubjectCode = @SubjectCode
              AND ReportingProfileCode = @ReportingProfileCode
        )
            UPDATE Cash.tbReportingProfile
            SET TaxSourceCode = @TaxSourceCode,
                AuthorityCode = @AuthorityCode,
                ReportingTypeCode = @ReportingTypeCode,
                AuthorityReference = NULLIF(LTRIM(RTRIM(@AuthorityReference)), N''),
                ValidFrom = @ValidFrom,
                ValidTo = @ValidTo,
                StatusCode = @StatusCode,
                ValueSourceCode = @ValueSourceCode,
                IsReviewed = @IsReviewed,
                UpdatedBy = Usr.fnUserName(),
                UpdatedOn = current_timestamp
            WHERE SubjectCode = @SubjectCode
              AND ReportingProfileCode = @ReportingProfileCode;
        ELSE
            INSERT Cash.tbReportingProfile
            (
                SubjectCode, ReportingProfileCode, TaxSourceCode, AuthorityCode,
                ReportingTypeCode, AuthorityReference, ValidFrom, ValidTo,
                StatusCode, ValueSourceCode, IsReviewed
            )
            VALUES
            (
                @SubjectCode, @ReportingProfileCode, @TaxSourceCode, @AuthorityCode,
                @ReportingTypeCode, NULLIF(LTRIM(RTRIM(@AuthorityReference)), N''), @ValidFrom, @ValidTo,
                @StatusCode, @ValueSourceCode, @IsReviewed
            );
    END TRY
    BEGIN CATCH
        EXEC App.proc_ErrorLog;
    END CATCH;
GO
PRINT N'Altering Procedure [App].[proc_BasicSetup]...';


GO
ALTER   PROCEDURE App.proc_BasicSetup
(
	@TemplateCode NVARCHAR(10),
	@FinancialMonth SMALLINT = 4,
	@CoinTypeCode SMALLINT,
	@GovAccountName NVARCHAR(255),
	@BankName NVARCHAR(255) = null,
	@BankAddress NVARCHAR(MAX) = null,
	@DummyAccount NVARCHAR(50) = null, 
	@CurrentAccount NVARCHAR(50) = null,
	@CA_SortCode NVARCHAR(10) = null,
	@CA_AccountNumber NVARCHAR(20) = null,
	@ReserveAccount NVARCHAR(50) = null, 
	@RA_SortCode NVARCHAR(10) = null,
	@RA_AccountNumber NVARCHAR(20) = null,
	@IsVatRegistered BIT = 0,
	@ExpectedAnnualProfit DECIMAL(18, 2) = NULL,
	@AsOfDate DATE = NULL
)
AS
	SET @AsOfDate = COALESCE(@AsOfDate, CONVERT(DATE, CURRENT_TIMESTAMP));

	DECLARE 
		@FinancialYear SMALLINT = DATEPART(YEAR, @AsOfDate),
		@IsCompany bit;

	SELECT @IsCompany = IsCompany
	FROM App.tbTemplate
	WHERE TemplateCode = @TemplateCode;

	IF @IsCompany IS NULL
		THROW 51001, 'BasicSetup: template was not found in App.tbTemplate.', 1;

	IF @IsCompany = 0 AND (@ExpectedAnnualProfit IS NULL OR @ExpectedAnnualProfit <= 0)
		THROW 51002, 'BasicSetup: expected annual profit must be greater than zero for a sole trader.', 1;

	IF EXISTS (SELECT 1 FROM App.tbOptions WHERE UnitOfCharge <> 'BTC')
		AND NULLIF(LTRIM(RTRIM(@BankName)), '') IS NULL
		THROW 51003, 'BasicSetup: bank name is required for a fiat-currency node.', 1;

	IF EXISTS (SELECT 1 FROM App.tbOptions WHERE UnitOfCharge <> 'BTC')
		AND NULLIF(LTRIM(RTRIM(@CurrentAccount)), '') IS NULL
		THROW 51004, 'BasicSetup: current account name is required for a fiat-currency node.', 1;

		IF EXISTS (SELECT * FROM App.tbOptions WHERE UnitOfCharge <> 'BTC') AND (@CoinTypeCode <> 2)
			SET @CoinTypeCode = 2;

		IF DATEPART(MONTH, @AsOfDate) < @FinancialMonth
			 SET @FinancialYear -= 1;
		
	DECLARE 
		@Year SMALLINT = @FinancialYear - 1;

	SET NOCOUNT, XACT_ABORT ON;

	BEGIN TRY
		BEGIN TRAN
		
		UPDATE App.tbOptions
		SET CoinTypeCode = @CoinTypeCode;

		DECLARE @ProcName nvarchar(100) =
			(SELECT StoredProcedure FROM App.tbTemplate WHERE TemplateCode = @TemplateCode);

		EXEC @ProcName
				@FinancialMonth = @FinancialMonth,
				@GovAccountName = @GovAccountName, 
				@BankName = @BankName, 
				@BankAddress = @BankAddress, 
				@DummyAccount = @DummyAccount, 
				@CurrentAccount = @CurrentAccount, 
				@CA_SortCode = @CA_SortCode, 
				@CA_AccountNumber = @CA_AccountNumber, 
				@ReserveAccount = @ReserveAccount, 
				@RA_SortCode = @RA_SortCode, 
				@RA_AccountNumber = @RA_AccountNumber,
				@IsVATRegistered = @IsVatRegistered;

		--TIME PERIODS
		WHILE (@Year < DATEPART(YEAR, @AsOfDate) + 2)
		BEGIN
		
			INSERT INTO App.tbYear (YearNumber, StartMonth, CashStatusCode, Description)
			VALUES (@Year, @FinancialMonth, 0, 
						CASE WHEN @FinancialMonth > 1 THEN CONCAT(@Year, '-', @Year - ROUND(@Year, -2) + 1) ELSE CONCAT(@Year, '.') END
					);
			SET @Year += 1;
		END

		EXEC Cash.proc_GeneratePeriods;

		UPDATE App.tbYearPeriod
		SET BusinessTaxRate = CASE
			WHEN @IsCompany <> 0 THEN CAST(0.19 AS decimal(9, 6))
			ELSE CAST(Cash.fnPersonalEffectiveRateCalculator(@ExpectedAnnualProfit) AS decimal(9, 6))
		END;

		UPDATE App.tbYearPeriod
		SET CashStatusCode = 2
		WHERE StartOn < DATEADD(MONTH, -1, @AsOfDate)

		IF EXISTS(SELECT * FROM App.tbYearPeriod WHERE CashStatusCode = 3)
			WITH current_month AS
			(
				SELECT MAX(StartOn) AS StartOn
				FROM App.tbYearPeriod
				WHERE CashStatusCode = 2
			)
			UPDATE App.tbYearPeriod
			SET CashStatusCode = 1
			FROM App.tbYearPeriod JOIN current_month ON App.tbYearPeriod.StartOn = current_month.StartOn;	
		ELSE
			WITH current_month AS
			(
				SELECT MIN(StartOn) AS StartOn
				FROM App.tbYearPeriod
				WHERE CashStatusCode = 0
			)
			UPDATE App.tbYearPeriod
			SET CashStatusCode = 1
			FROM App.tbYearPeriod JOIN current_month ON App.tbYearPeriod.StartOn = current_month.StartOn;
	
	
		WITH current_month AS
		(
			SELECT YearNumber
			FROM App.tbYearPeriod
			WHERE CashStatusCode = 1
		)
		UPDATE App.tbYear
		SET CashStatusCode = 1
		FROM App.tbYear JOIN current_month ON App.tbYear.YearNumber = current_month.YearNumber;

		UPDATE App.tbYear
		SET CashStatusCode = 2
		WHERE YearNumber < 	(SELECT YearNumber FROM App.tbYear	WHERE CashStatusCode = 1);

		COMMIT TRAN
	END TRY
	BEGIN CATCH
		EXEC App.proc_ErrorLog
	END CATCH
GO
