        ('UK-CO-ACCTS-2026', 'Profile', 'Accounts profile', 2, 0, 'Contextual FRS 105 micro-entity and audit-exemption choices.', 4),
        ('UK-CO-ACCTS-2026', 'Currency', 'Reporting currency', 2, 0, 'Contextual reporting currency.', 5),
