GO
ALTER PROCEDURE App.proc_DatasetSyntheticMIS_StatutoryProfile
(
    @AsOfDate DATE = NULL
)
AS
SET NOCOUNT, XACT_ABORT ON;

DECLARE
    @SubjectCode NVARCHAR(50) = (SELECT TOP (1) SubjectCode FROM App.tbOptions ORDER BY Identifier),
    @JurisdictionCode NVARCHAR(10) = (SELECT TOP (1) JurisdictionCode FROM App.tbOptions ORDER BY Identifier),
    @BusinessTaxType SMALLINT = Cash.fnGetBizTaxType(),
    @StatusCode SMALLINT = (SELECT TOP (1) StatusCode FROM App.tbStatutoryStatus WHERE IsActive = 1 ORDER BY StatusCode),
    @SyntheticUtr NVARCHAR(10),
    @RegistrationCode NVARCHAR(20),
    @ProfileCode NVARCHAR(20);

IF @SubjectCode IS NULL
    THROW 51071, 'Synthetic statutory profile: the home subject is required.', 1;

IF @JurisdictionCode <> N'UK'
    RETURN;

IF @StatusCode IS NULL
    THROW 51072, 'Synthetic statutory profile: an active statutory status is required.', 1;

SET @AsOfDate = COALESCE
(
    @AsOfDate,
    (SELECT MIN(CONVERT(DATE, StartOn)) FROM App.tbYearPeriod),
    CONVERT(DATE, CURRENT_TIMESTAMP)
);

SET @SyntheticUtr = CASE @BusinessTaxType WHEN 0 THEN N'1000000001' ELSE N'2000000001' END;

IF @BusinessTaxType = 0
BEGIN
    DECLARE @RegisteredAddressCode NVARCHAR(15) =
    (
        SELECT TOP (1) AddressCode
        FROM Subject.tbAddress
        WHERE SubjectCode = @SubjectCode AND AddressTypeCode = 2
        ORDER BY AddressCode
    );

    IF @RegisteredAddressCode IS NULL
    BEGIN
        EXEC Subject.proc_NextAddressCode
            @SubjectCode = @SubjectCode,
            @AddressCode = @RegisteredAddressCode OUTPUT;

        INSERT INTO Subject.tbAddress (AddressCode, SubjectCode, AddressTypeCode, Address)
        VALUES
        (
            @RegisteredAddressCode, @SubjectCode, 2,
            N'1 Synthetic Registered Office Way' + CHAR(13) + CHAR(10)
                + N'Testborough' + CHAR(13) + CHAR(10) + N'TE1 1ST'
        );
    END
    ELSE
        UPDATE Subject.tbAddress
        SET Address = N'1 Synthetic Registered Office Way' + CHAR(13) + CHAR(10)
            + N'Testborough' + CHAR(13) + CHAR(10) + N'TE1 1ST'
        WHERE SubjectCode = @SubjectCode AND AddressCode = @RegisteredAddressCode;
END;

UPDATE Subject.tbVirtual
SET VatNumber = CASE
        WHEN EXISTS (SELECT 1 FROM Cash.tbTaxType WHERE TaxTypeCode = 1 AND IsEnabled = 1)
            THEN CASE
                WHEN LEN(LTRIM(RTRIM(VatNumber))) = 9
                    AND LTRIM(RTRIM(VatNumber)) NOT LIKE N'%[^0-9]%'
                    THEN LTRIM(RTRIM(VatNumber))
                ELSE N'999000001'
            END
        ELSE VatNumber
    END,
    BusinessDescription = COALESCE(NULLIF(LTRIM(RTRIM(BusinessDescription)), N''), N'Synthetic test business')
WHERE SubjectCode = @SubjectCode;

SELECT @RegistrationCode = RegistrationCode
FROM Subject.tbRegistration
WHERE SubjectCode = @SubjectCode AND RegistrationSchemeCode = N'GB-UTR';

EXEC Subject.proc_RegistrationSave
    @SubjectCode = @SubjectCode,
    @RegistrationSchemeCode = N'GB-UTR',
    @RegistrationValue = @SyntheticUtr,
    @ValidFrom = @AsOfDate,
    @StatusCode = @StatusCode,
    @ValueSourceCode = N'SYNTHETIC',
    @IsReviewed = 1,
    @RegistrationCode = @RegistrationCode OUTPUT;

IF @BusinessTaxType = 4
BEGIN
    SET @RegistrationCode = NULL;
    SELECT @RegistrationCode = RegistrationCode
    FROM Subject.tbRegistration
    WHERE SubjectCode = @SubjectCode AND RegistrationSchemeCode = N'GB-NI';

    EXEC Subject.proc_RegistrationSave
        @SubjectCode = @SubjectCode,
        @RegistrationSchemeCode = N'GB-NI',
        @RegistrationValue = N'QQ123456C',
        @ValidFrom = @AsOfDate,
        @StatusCode = @StatusCode,
        @ValueSourceCode = N'SYNTHETIC',
        @IsReviewed = 1,
        @RegistrationCode = @RegistrationCode OUTPUT;

    SELECT @ProfileCode = ReportingProfileCode
    FROM Cash.tbReportingProfile
    WHERE SubjectCode = @SubjectCode AND ReportingTypeCode = 1;

    EXEC Cash.proc_ReportingProfileSave
        @SubjectCode = @SubjectCode,
        @ReportingTypeCode = 1,
        @TaxSourceCode = N'UK-ITSA-SE-CUM',
        @AuthorityReference = N'XQIS00000000001',
        @ValidFrom = @AsOfDate,
        @StatusCode = @StatusCode,
        @ValueSourceCode = N'SYNTHETIC',
        @IsReviewed = 1,
        @ReportingProfileCode = @ProfileCode OUTPUT;

    EXEC Cash.proc_ReportingProfileSettingSave @SubjectCode, @ProfileCode, N'ACCOUNTING-BASIS', @AsOfDate,
        @TextValue = N'CASH', @StatusCode = @StatusCode, @ValueSourceCode = N'SYNTHETIC', @IsReviewed = 1;
    EXEC Cash.proc_ReportingProfileSettingSave @SubjectCode, @ProfileCode, N'QUARTERLY-PERIOD-TYPE', @AsOfDate,
        @TextValue = N'STANDARD', @StatusCode = @StatusCode, @ValueSourceCode = N'SYNTHETIC', @IsReviewed = 1;
END;

IF @BusinessTaxType = 0
BEGIN
    SELECT @ProfileCode = ReportingProfileCode
    FROM Cash.tbReportingProfile
    WHERE SubjectCode = @SubjectCode AND ReportingTypeCode = 2;

    EXEC Cash.proc_ReportingProfileSave
        @SubjectCode = @SubjectCode, @ReportingTypeCode = 2,
        @TaxSourceCode = N'UK-CO-CT-2026', @ValidFrom = @AsOfDate,
        @StatusCode = @StatusCode, @ValueSourceCode = N'SYNTHETIC', @IsReviewed = 1,
        @ReportingProfileCode = @ProfileCode OUTPUT;

    SET @ProfileCode = NULL;
    SELECT @ProfileCode = ReportingProfileCode
    FROM Cash.tbReportingProfile
    WHERE SubjectCode = @SubjectCode AND ReportingTypeCode = 3;

    EXEC Cash.proc_ReportingProfileSave
        @SubjectCode = @SubjectCode, @ReportingTypeCode = 3,
        @TaxSourceCode = N'UK-CO-ACCTS-2026', @ValidFrom = @AsOfDate,
        @StatusCode = @StatusCode, @ValueSourceCode = N'SYNTHETIC', @IsReviewed = 1,
        @ReportingProfileCode = @ProfileCode OUTPUT;

    EXEC Cash.proc_ReportingProfileSettingSave @SubjectCode, @ProfileCode, N'ACCOUNTING-STANDARD', @AsOfDate,
        @TextValue = N'FRS-105', @StatusCode = @StatusCode, @ValueSourceCode = N'SYNTHETIC', @IsReviewed = 1;
    EXEC Cash.proc_ReportingProfileSettingSave @SubjectCode, @ProfileCode, N'ACCOUNTS-TYPE', @AsOfDate,
        @TextValue = N'MICRO-ENTITY', @StatusCode = @StatusCode, @ValueSourceCode = N'SYNTHETIC', @IsReviewed = 1;
    EXEC Cash.proc_ReportingProfileSettingSave @SubjectCode, @ProfileCode, N'BALANCE-SHEET-FORMAT', @AsOfDate,
        @TextValue = N'FORMAT-1', @StatusCode = @StatusCode, @ValueSourceCode = N'SYNTHETIC', @IsReviewed = 1;
    EXEC Cash.proc_ReportingProfileSettingSave @SubjectCode, @ProfileCode, N'ACCOUNTING-POLICIES', @AsOfDate,
        @TextValue = N'These synthetic accounts use the historical-cost basis and FRS 105.',
        @StatusCode = @StatusCode, @ValueSourceCode = N'SYNTHETIC', @IsReviewed = 1;
END;

IF EXISTS (SELECT 1 FROM Cash.tbTaxType WHERE TaxTypeCode = 1 AND IsEnabled = 1)
BEGIN
    SET @ProfileCode = NULL;
    SELECT @ProfileCode = ReportingProfileCode
    FROM Cash.tbReportingProfile
    WHERE SubjectCode = @SubjectCode AND ReportingTypeCode = 0;

    EXEC Cash.proc_ReportingProfileSave
        @SubjectCode = @SubjectCode, @ReportingTypeCode = 0,
        @TaxSourceCode = NULL, @ValidFrom = @AsOfDate,
        @StatusCode = @StatusCode, @ValueSourceCode = N'SYNTHETIC', @IsReviewed = 1,
        @ReportingProfileCode = @ProfileCode OUTPUT;
END;
GO
PRINT N'Altering Procedure [App].[proc_DatasetSyntheticMIS_VatSandboxAlign]...';


GO
ALTER   PROCEDURE App.proc_DatasetSyntheticMIS_VatSandboxAlign
(
    @SandboxVrn nvarchar(9),
    @ObligationPeriodKey nvarchar(16),
    @ObligationStart date,
    @ObligationEnd date
)
AS
    SET NOCOUNT, XACT_ABORT ON;

    IF @SandboxVrn IS NULL OR LEN(@SandboxVrn) <> 9 OR @SandboxVrn LIKE N'%[^0-9]%'
        THROW 51081, 'VAT sandbox alignment: a nine-digit generated organisation VRN is required.', 1;

    IF @SandboxVrn = N'999000001'
        THROW 51082, 'VAT sandbox alignment: the synthetic placeholder VRN cannot be used.', 1;

    IF NULLIF(LTRIM(RTRIM(@ObligationPeriodKey)), N'') IS NULL
        THROW 51083, 'VAT sandbox alignment: the authority period key is required.', 1;

    IF @ObligationStart IS NULL OR @ObligationEnd IS NULL OR @ObligationEnd < @ObligationStart
        THROW 51084, 'VAT sandbox alignment: the authority period dates are invalid.', 1;

    DECLARE
        @SubjectCode nvarchar(50) = (SELECT TOP (1) SubjectCode FROM App.tbOptions ORDER BY Identifier),
        @ProfileCode nvarchar(20),
        @StatusCode smallint,
        @ValidFrom date,
        @TaxSourceCode nvarchar(20);

    SELECT
        @ProfileCode = ReportingProfileCode,
        @StatusCode = StatusCode,
        @ValidFrom = ValidFrom,
        @TaxSourceCode = TaxSourceCode
    FROM Cash.tbReportingProfile
    WHERE SubjectCode = @SubjectCode
      AND ReportingTypeCode = 0
      AND ValueSourceCode = N'SYNTHETIC';

    IF @ProfileCode IS NULL
        THROW 51085, 'VAT sandbox alignment is restricted to a disposable synthetic node.', 1;

    IF NOT EXISTS
    (
        SELECT 1
        FROM Cash.vwTaxVatSubmission submission
        JOIN Cash.fnTaxTypeDueDates(1, 0) due ON submission.StartOn = due.PayTo
        WHERE CONVERT(date, due.PayFrom) = @ObligationStart
          AND CONVERT(date, DATEADD(day, -1, due.PayTo)) = @ObligationEnd
    )
        THROW 51086, 'VAT sandbox alignment: no exact calculated local VAT submission period exists.', 1;

    -- HMRC's sandbox obligations can pre-date the synthetic dataset's commissioning date.
    -- Extend only the disposable synthetic VAT profile to cover the exact matched obligation.
    SET @ValidFrom = CASE WHEN @ValidFrom > @ObligationStart THEN @ObligationStart ELSE @ValidFrom END;

    UPDATE Subject.tbVirtual
    SET VatNumber = @SandboxVrn
    WHERE SubjectCode = @SubjectCode;

    EXEC Cash.proc_ReportingProfileSave
        @SubjectCode = @SubjectCode,
        @ReportingTypeCode = 0,
        @TaxSourceCode = @TaxSourceCode,
        @AuthorityReference = @SandboxVrn,
        @ValidFrom = @ValidFrom,
        @StatusCode = @StatusCode,
        @ValueSourceCode = N'SYNTHETIC',
        @IsReviewed = 1,
        @ReportingProfileCode = @ProfileCode OUTPUT;

    SELECT
        @ProfileCode AS ReportingProfileCode,
        @SandboxVrn AS SandboxVrn,
        @ObligationPeriodKey AS ObligationPeriodKey,
        @ObligationStart AS ObligationStart,
        @ObligationEnd AS ObligationEnd,
        N'Cash.vwTaxVatSubmission' AS SourceView;
GO
PRINT N'Altering Procedure [App].[proc_NodeBusinessInit]...';


GO
ALTER PROCEDURE [App].[proc_NodeBusinessInit]
(
	@SubjectCode NVARCHAR(50),
	@BusinessName NVARCHAR(255),
	@FullName NVARCHAR(100),
	@BusinessAddress NVARCHAR(MAX),
	@BusinessEmailAddress NVARCHAR(255) = null,
	@UserEmailAddress NVARCHAR(255) = null,
	@PhoneNumber NVARCHAR(50) = null,
	@CompanyNumber NVARCHAR(20) = null,
	@VatNumber NVARCHAR(20) = null,
	@CalendarCode NVARCHAR(10),
	@JurisdictionCode NVARCHAR(10),
	@UnitOfCharge NVARCHAR(5) = NULL
)
AS
SET NOCOUNT, XACT_ABORT ON;

BEGIN TRY
	IF NOT EXISTS (SELECT 1 FROM App.tbJurisdiction WHERE JurisdictionCode = @JurisdictionCode)
		THROW 51005, 'NodeBusinessInit: jurisdiction not found.', 1;

	IF @UnitOfCharge IS NULL
		SELECT @UnitOfCharge = UocCode
		FROM App.tbJurisdiction
		WHERE JurisdictionCode = @JurisdictionCode;

	BEGIN TRAN;

	INSERT INTO Subject.tbSubject
	(
		SubjectCode,
		SubjectName,
		SubjectTypeCode,
		SubjectStatusCode,
		PhoneNumber,
		EmailAddress
	)
	VALUES
	(
		@SubjectCode,
		@BusinessName,
		4,
		1,
		@PhoneNumber,
		@BusinessEmailAddress
	);

	INSERT INTO Subject.tbVirtual
	(
		SubjectCode,
		CompanyNumber,
		VatNumber
	)
	VALUES
	(
		@SubjectCode,
		@CompanyNumber,
		@VatNumber
	);

	EXEC Subject.proc_AddContact @SubjectCode = @SubjectCode, @ContactName = @FullName;
	EXEC Subject.proc_AddAddress @SubjectCode = @SubjectCode, @Address = @BusinessAddress;

	INSERT INTO App.tbCalendar (CalendarCode, Monday, Tuesday, Wednesday, Thursday, Friday, Saturday, Sunday)
	VALUES (@CalendarCode, 1, 1, 1, 1, 1, 0, 0);
		
	INSERT INTO Usr.tbUser (UserId, UserName, LogonName, IsAdministrator, IsEnabled, CalendarCode, EmailAddress, PhoneNumber, ThemeCode)
	VALUES (CONCAT(LEFT(@FullName, 1), SUBSTRING(@FullName, CHARINDEX(' ', @FullName) + 1, 1)), @FullName, 
		SUSER_SNAME() , 1, 1, @CalendarCode, @UserEmailAddress, @PhoneNumber, 'ORANGE');

	IF NOT EXISTS (SELECT 1 FROM Web.tbTemplate WHERE TemplateFileName = 'support_request.html')
		INSERT INTO Web.tbTemplate (TemplateFileName) VALUES ('support_request.html');

	IF NOT EXISTS (SELECT 1 FROM Web.tbTemplate WHERE TemplateFileName = 'user_registration.html')
		INSERT INTO Web.tbTemplate (TemplateFileName) VALUES ('user_registration.html');

	IF NOT EXISTS (SELECT 1 FROM Web.tbTemplate WHERE TemplateFileName = 'user_registration_confirm.html')
		INSERT INTO Web.tbTemplate (TemplateFileName) VALUES ('user_registration_confirm.html');

	IF NOT EXISTS (SELECT 1 FROM Web.tbTemplate WHERE TemplateFileName = 'user_registration_admin_notify.html')
		INSERT INTO Web.tbTemplate (TemplateFileName) VALUES ('user_registration_admin_notify.html');

	DECLARE @SupportRequestTemplateId INT =
		(SELECT TemplateId FROM Web.tbTemplate WHERE TemplateFileName = 'support_request.html');

	DECLARE @UserRegistrationTemplateId INT =
		(SELECT TemplateId FROM Web.tbTemplate WHERE TemplateFileName = 'user_registration.html');

    DECLARE @RegistrationConfirmTemplateId INT =
		(SELECT TemplateId FROM Web.tbTemplate WHERE TemplateFileName = 'user_registration_confirm.html');

	DECLARE @RegstrationNotifyTemplateId INT =
		(SELECT TemplateId FROM Web.tbTemplate WHERE TemplateFileName = 'user_registration_admin_notify.html');

	INSERT INTO App.tbOptions
	(
		Identifier,
		IsInitialised,
		SubjectCode,
		RegisterName,
		DefaultPrintMode,
		BucketIntervalCode,
		BucketTypeCode,
		TaxHorizon,
		IsAutoOffsetDays,
		JurisdictionCode,
		UnitOfCharge,
		SupportRequestTemplateId,
		UserRegistrationTemplateId,
        UserRegistrationConfirmTemplateId,
        UserRegistrationAdminNotifyTemplateId
	)
	VALUES
	(
		'TC',
		0,
		@SubjectCode,
		'Event Log',
		2,
		1,
		1,
		730,
		0,
		@JurisdictionCode,
		@UnitOfCharge,
		@SupportRequestTemplateId,
		@UserRegistrationTemplateId,
        @RegistrationConfirmTemplateId,
        @RegstrationNotifyTemplateId
	);

	COMMIT TRAN;

	EXEC App.proc_RotateSymmetricKeys;

END TRY
BEGIN CATCH
	EXEC App.proc_ErrorLog;
END CATCH
GO
PRINT N'Altering Procedure [App].[proc_Template_BASE_MIN_2026]...';


GO
ALTER PROCEDURE App.proc_Template_BASE_MIN_2026
(
    @FinancialMonth SMALLINT = 4,
    @GovAccountName NVARCHAR(255),
    @BankName NVARCHAR(255) = NULL,
    @BankAddress NVARCHAR(MAX) = NULL,
    @DummyAccount NVARCHAR(50),
    @CurrentAccount NVARCHAR(50) = NULL,
    @CA_SortCode NVARCHAR(10) = NULL,
    @CA_AccountNumber NVARCHAR(20) = NULL,
    @ReserveAccount NVARCHAR(50) = NULL,
    @RA_SortCode NVARCHAR(10) = NULL,
    @RA_AccountNumber NVARCHAR(20) = NULL
)
AS
    SET NOCOUNT, XACT_ABORT ON;

    BEGIN TRY

        DECLARE
            @CoinTypeCode SMALLINT = (SELECT TOP (1) CoinTypeCode FROM App.tbOptions),
            @SubjectCode  NVARCHAR(50),
            @AccountCode  NVARCHAR(10),
            @Decimals     SMALLINT;

        ----------------------------------------------------------------
        -- BUCKETS
        ----------------------------------------------------------------
        INSERT INTO [App].[tbBucket] ([Period], [BucketId], [BucketDescription], [AllowForecasts])
        VALUES (0,  'Overdue',    'Overdue Orders', 0),
               (1,  'Current',    'Current Week',   0),
               (2,  'Week 2',     'Week Two',       0),
               (3,  'Week 3',     'Week Three',     0),
               (4,  'Week 4',     'Week Four',      0),
               (8,  'Next Month', 'Next Month',     0),
               (16, '2 Months',   '2 Months',       1),
               (52, 'Forward',    'Forward Orders', 1);

        ----------------------------------------------------------------
        -- UNITS OF MEASURE
        ----------------------------------------------------------------
        INSERT INTO [App].[tbUom] ([UnitOfMeasure])
        VALUES ('each'),
               ('days'),
               ('hrs'),
               ('kilo'),
               ('miles'),
               ('mins'),
               ('units');

		----------------------------------------------------------------
        -- TAX CODES (minimalist, CoinType-aware)
        ----------------------------------------------------------------
        SET @Decimals = CASE @CoinTypeCode WHEN 2 THEN 2 ELSE 3 END;

        INSERT INTO [App].[tbTaxCode]
            ([TaxCode], [TaxRate], [TaxDescription], [TaxTypeCode], [RoundingCode], [Decimals])
        VALUES ('INT', 0,      'Interest Tax',       3, 0, @Decimals),
               ('N/A', 0,      'Untaxed',            3, 0, @Decimals),
               ('T0',  0,      'Zero Rated VAT',     1, 0, @Decimals),
               ('T1',  0.2000, 'Standard VAT Rate',  1, 0, @Decimals);

        ----------------------------------------------------------------
        -- CATEGORIES (purged of MTD tags; semantic prefixes)
        --   CT-* = Total (CategoryTypeCode=1)
        --   CA-* = Nominal (CategoryTypeCode=0)
        --   CE-* = Expression (CategoryTypeCode=2)
        ----------------------------------------------------------------
        INSERT INTO Cash.tbCategory
            (CategoryCode, Category, CategoryTypeCode, CashPolarityCode, CashTypeCode, DisplayOrder, IsEnabled)
        VALUES
            -- Totals / reporting groups
            ('CT-TURNOV', 'Turnover',                 1, 2, 0,  10, 1),
            ('CT-OTHRIN', 'Other Income',             1, 2, 0,  20, 1),
            ('CT-CSTSAL', 'Cost of Sales',            1, 2, 0,  30, 1),
            ('CT-STAFFC', 'Staff Costs',              1, 2, 0,  40, 1),

            ('CT-OVERHD', 'Overheads',                1, 2, 0,  60, 1),

            -- Gross profit total (required by expressions; users expect it)
            ('CT-GROSSP', 'Gross Profit',             1, 2, 0,  70, 1),

            -- Profit root (system net profit root)
            ('CT-PANDL',  'Profit and Loss',          1, 2, 0,  80, 1),

            -- Internal nominal categories
            ('CA-SALES',  'Sales',                       0, 1, 0, 100, 1),
            ('CA-INCOME', 'Other Income (Internal)',     0, 1, 0, 110, 1),
            ('CA-DIRECT', 'Direct Costs',                0, 0, 0, 120, 1),
            ('CA-WAGES',  'Wages',                       0, 0, 0, 130, 1),
            ('CA-ADMIN',  'Admin Expenses',              0, 0, 0, 140, 1),

            -- Minimal asset movement bucket (moved to P&L)
            ('CA-ASSET',  'Asset Movements',             0, 2, 2, 150, 1),

            -- Tax categories
            ('CA-TAXGD',  'Tax on Goods (VAT / General)',0, 0, 1, 170, 1),
            ('CA-TAXCO',  'Tax on Company (Biz)',        0, 0, 1, 180, 1),

            -- VAT root
            ('CT-VAT',    'VAT Control Root',            1, 2, 1, 900, 1),

            -- Internal Balance Sheet-ish groupings
            ('CA-BANK',   'Bank Accounts',               0, 2, 2, 910, 1),
            ('CA-INVEST', 'Investments / Capital',       0, 2, 2, 920, 1),
            ('CA-LIAB',   'Liabilities',                 0, 0, 2, 930, 1),

			-- Interbank Transfers
			('CA-IP',	   'Intercompany Payment',	      0, 0, 2, 200, 1),
			('CA-IR',      'Intercompany Receipt',	      0, 1, 2, 210, 1),

			-- Dividend Payment
			('CA-DIVID',   'Dividends',                   0, 0, 0, 300, 1);

        ----------------------------------------------------------------
        -- CATEGORY TOTALS (roll-up structure)
        ----------------------------------------------------------------
        INSERT INTO Cash.tbCategoryTotal (ParentCode, ChildCode)
        VALUES
            -- Profit and Loss (CT-PANDL)
            ('CT-PANDL', 'CT-GROSSP'),
            ('CT-PANDL', 'CT-STAFFC'),
            ('CT-PANDL', 'CT-OVERHD'),
            ('CT-PANDL', 'CA-ASSET'),

            -- Gross Profit
            ('CT-GROSSP', 'CT-TURNOV'),
            ('CT-GROSSP', 'CT-OTHRIN'),
            ('CT-GROSSP', 'CT-CSTSAL'),

            -- Turnover
            ('CT-TURNOV', 'CA-SALES'),

            -- Other income
            ('CT-OTHRIN', 'CA-INCOME'),

            -- Cost of sales
            ('CT-CSTSAL', 'CA-DIRECT'),

            -- Staff costs
            ('CT-STAFFC', 'CA-WAGES'),

            -- Overheads
            ('CT-OVERHD', 'CA-ADMIN'),

            -- VAT root
            ('CT-VAT', 'CA-SALES'),
            ('CT-VAT', 'CA-INCOME'),
            ('CT-VAT', 'CA-DIRECT'),
            ('CT-VAT', 'CT-OVERHD');

        ----------------------------------------------------------------
        -- CASH CODES 
        ----------------------------------------------------------------
        INSERT INTO Cash.tbCode
            (CashCode, CashDescription, CategoryCode, TaxCode, IsEnabled)
        VALUES
            -- Income
            ('CC-SALES', 'Sales',             'CA-SALES',  'T1',  1),
            ('CC-INCME', 'Other Income',      'CA-INCOME', 'T1',  1),

            -- Direct Costs
            ('CC-DIRCT', 'Direct Costs',      'CA-DIRECT', 'T1',  1),

            -- Wages
            ('CC-WAGES', 'Wages',             'CA-WAGES',  'N/A', 1),
			('CC-PENSN', 'Pensions',          'CA-WAGES',  'N/A', 1),

            -- Admin
            ('CC-ADMIN', 'Admin Expenses',    'CA-ADMIN',  'T1',  1),

            -- Depreciation (internal)
            ('CC-DEPRC', 'Depreciation',            'CA-ASSET', 'N/A', 1),
            ('CC-DEPRJ', 'Depreciation Adjustment', 'CA-ASSET', 'N/A', 1),

            -- Tax (aligned to TaxTypeCode 0–3)
            ('CC-VAT',   'VAT Control',       'CA-TAXGD',  'N/A', 1),
            ('CC-BIZTX', 'Business Tax',      'CA-TAXCO',  'N/A', 1),
            ('CC-GENTX', 'General Taxes',     'CA-TAXGD',  'N/A', 1),

			('CC-EMPNI', 'Employers NI',      'CA-WAGES',  'N/A', 1),

            -- Operational accounts
            ('CC-BANK',  'Bank',              'CA-BANK',   'N/A', 1),
            ('CC-SHCAP', 'Share Capital',     'CA-INVEST', 'N/A', 1),
            ('CC-LOAN',  'Loan / Liability',  'CA-LIAB',   'N/A', 1),

			-- Bank Transfers
			('CC-TRNPY', 'Transfer Payment',  'CA-IP',     'N/A', 1),
            ('CC-TRNRC', 'Transfer Receipt',  'CA-IR',     'N/A', 1),
			
			-- Dividends
			('CC-DIVID', 'Dividends',         'CA-DIVID',  'N/A', 1);

        ----------------------------------------------------------------
        -- EXPRESSION CATEGORIES (CategoryTypeCode = 2)
        ----------------------------------------------------------------
        INSERT INTO Cash.tbCategory
            (CategoryCode, Category, CategoryTypeCode, CashPolarityCode, CashTypeCode, DisplayOrder, IsEnabled)
        VALUES
            ('CE-GP', 'Gross Margin %',              2, 2, 0,  1, 1),
            ('CE-NP', 'Net Profit %',                2, 2, 0,  2, 1),
            ('CE-WP', 'Wages Ratio',                 2, 2, 0,  3, 1),
            ('CE-AP', 'Admin Cost Ratio',            2, 2, 0,  4, 1),
            ('CE-DP', 'Direct Cost Ratio',           2, 2, 0,  5, 1),
            ('CE-DE', 'Depreciation Ratio',          2, 2, 0,  6, 1),
            ('CE-OC', 'Overhead Coverage Ratio',     2, 2, 0,  8, 1),
            ('CE-RS', 'Revenue-to-Wages Ratio',      2, 2, 0,  9, 1);

        ----------------------------------------------------------------
        -- EXPRESSION DEFINITIONS
        ----------------------------------------------------------------
        INSERT INTO Cash.tbCategoryExp
            (CategoryCode, Expression, Format, SyntaxTypeCode, IsError, ErrorMessage)
        VALUES
            -- Gross Margin %
            ('CE-GP', 'IF([CA-SALES]=0,0,([CT-GROSSP]/[CA-SALES]))', 'Pct0', 0, 0, NULL),

            -- Net Profit % (use CT-PANDL description)
            ('CE-NP', 'IF([CA-SALES]=0,0,([CT-PANDL]/[CA-SALES]))', 'Pct0', 0, 0, NULL),

            -- Wages %
            ('CE-WP', 'IF([CA-SALES]=0,0,(ABS([CA-WAGES])/[CA-SALES]))', 'Num2', 0, 0, NULL),

            -- Admin Cost %
            ('CE-AP', 'IF([CA-SALES]=0,0,(ABS([CA-ADMIN])/[CA-SALES]))', 'Num2', 0, 0, NULL),

            -- Direct Cost %
            ('CE-DP', 'IF([CA-SALES]=0,0,(ABS([CA-DIRECT])/[CA-SALES]))', 'Num2', 0, 0, NULL),

            -- Depreciation % (Asset Movements)
            ('CE-DE', 'IF([CA-SALES]=0,0,(ABS([CA-ASSET])/[CA-SALES]))', 'Num2', 0, 0, NULL),

            -- Overhead Coverage Ratio
            ('CE-OC', 'IF([CA-ADMIN]=0,0,([CT-GROSSP]/ABS([CA-ADMIN])))', 'Num2', 0, 0, NULL),

            -- Revenue per £ Staff Cost
            ('CE-RS', 'IF([CA-WAGES]=0,0,([CA-SALES]/ABS([CA-WAGES])))', 'Num2', 0, 0, NULL);

        ----------------------------------------------------------------
        -- CRYPTO-ONLY MINER FEE CASH CODE
        ----------------------------------------------------------------
        IF @CoinTypeCode < 2
        BEGIN
            INSERT INTO [Cash].[tbCode] ([CashCode], [CashDescription], [CategoryCode], [TaxCode], [IsEnabled])
            VALUES ('CC-MINER', 'Miner Fees', 'CA-DIRECT', 'N/A', 1);

            UPDATE App.tbOptions
            SET MinerFeeCode = 'CC-MINER';
        END

        ----------------------------------------------------------------
        -- NET PROFIT & VAT CATEGORY
        ----------------------------------------------------------------
        UPDATE App.tbOptions
        SET NetProfitCode   = 'CT-PANDL',
            VatCategoryCode = 'CT-VAT';

        ----------------------------------------------------------------
        -- HOME SUBJECT TAX CODE (STANDARD VAT)
        ----------------------------------------------------------------
        UPDATE Subject.tbSubject
        SET TaxCode = 'T1'
        WHERE SubjectCode = (SELECT SubjectCode FROM App.tbOptions);

        ----------------------------------------------------------------
        -- GOV / HMRC SUBJECT
        ----------------------------------------------------------------
        EXEC Subject.proc_DefaultSubjectCode
             @SubjectName = @GovAccountName,
             @SubjectCode = @SubjectCode OUTPUT;

        INSERT INTO Subject.tbSubject
            (SubjectCode, SubjectName, SubjectStatusCode, SubjectTypeCode, TaxCode)
        VALUES
            (@SubjectCode, @GovAccountName, 1, 7, 'N/A');

        INSERT INTO Subject.tbVirtual
            (SubjectCode)
        VALUES
            (@SubjectCode);

        ----------------------------------------------------------------
        -- ASSIGN CASH CODES AND GOV TO TAX TYPES
        ----------------------------------------------------------------
        UPDATE Cash.tbTaxType
        SET SubjectCode = @SubjectCode,
            CashCode    = 'CC-BIZTX',
            MonthNumber = @FinancialMonth
        WHERE TaxTypeCode IN (0, 4, 5);  -- Business Tax

        UPDATE Cash.tbTaxType
        SET SubjectCode = @SubjectCode,
            CashCode    = 'CC-VAT',
            MonthNumber = @FinancialMonth
        WHERE TaxTypeCode = 1;  -- VAT

        UPDATE Cash.tbTaxType
        SET SubjectCode = @SubjectCode,
            CashCode    = 'CC-EMPNI',
            MonthNumber = @FinancialMonth
        WHERE TaxTypeCode = 2;  -- N.I.

        UPDATE Cash.tbTaxType
        SET SubjectCode = @SubjectCode,
            CashCode    = 'CC-GENTX',
            MonthNumber = @FinancialMonth
        WHERE TaxTypeCode = 3;  -- General

        ----------------------------------------------------------------
        -- BANK / CRYPTO SUBJECT
        ----------------------------------------------------------------
        IF @CoinTypeCode = 2
        BEGIN
            -- FIAT BANK
            EXEC Subject.proc_DefaultSubjectCode
                 @SubjectName = @BankName,
                 @SubjectCode = @SubjectCode OUTPUT;

            INSERT INTO Subject.tbSubject
                (SubjectCode, SubjectName, SubjectStatusCode, SubjectTypeCode, TaxCode)
            VALUES
                (@SubjectCode, @BankName, 1, 5, 'T0');

            INSERT INTO Subject.tbVirtual
                (SubjectCode)
            VALUES
                (@SubjectCode);

            EXEC Subject.proc_AddAddress
                 @SubjectCode = @SubjectCode,
                 @Address     = @BankAddress;
        END
        ELSE
        BEGIN
            -- CRYPTO MINER SUBJECT
            EXEC Subject.proc_DefaultSubjectCode
                 @SubjectName = 'BITCOIN MINER',
                 @SubjectCode = @SubjectCode OUTPUT;

            INSERT INTO Subject.tbSubject
                (SubjectCode, SubjectName, SubjectStatusCode, SubjectTypeCode, TaxCode)
            VALUES
                (@SubjectCode, 'BITCOIN MINER', 1, 7, 'N/A');

            INSERT INTO Subject.tbVirtual
                (SubjectCode)
            VALUES
                (@SubjectCode);

            UPDATE App.tbOptions
            SET MinerAccountCode = @SubjectCode;

            -- Reset @SubjectCode to HOME subject
            SELECT @SubjectCode = SubjectCode
            FROM App.tbOptions;
        END

        ----------------------------------------------------------------
        -- CURRENT ACCOUNT
        ----------------------------------------------------------------
        EXEC Subject.proc_DefaultSubjectCode
             @SubjectName = @CurrentAccount,
             @SubjectCode = @AccountCode OUTPUT;

        INSERT INTO Subject.tbAccount
            (AccountCode, SubjectCode, AccountName, OpeningBalance, SortCode, AccountNumber, CashCode)
        VALUES
            (@AccountCode, @SubjectCode, @CurrentAccount, 0, @CA_SortCode, @CA_AccountNumber, 'CC-BANK');

        ----------------------------------------------------------------
        -- RESERVE ACCOUNT (OPTIONAL)
        ----------------------------------------------------------------
        IF (LEN(COALESCE(@ReserveAccount, '')) > 0)
        BEGIN
            EXEC Subject.proc_DefaultSubjectCode
                 @SubjectName = @ReserveAccount,
                 @SubjectCode = @AccountCode OUTPUT;

            INSERT INTO Subject.tbAccount
                (AccountCode, SubjectCode, AccountName, OpeningBalance, SortCode, AccountNumber)
            VALUES
                (@AccountCode, @SubjectCode, @ReserveAccount, 0, @RA_SortCode, @RA_AccountNumber);
        END

        ----------------------------------------------------------------
        -- RESET SUBJECT TO HOME SUBJECT
        ----------------------------------------------------------------
        SELECT @SubjectCode = (SELECT SubjectCode FROM App.tbOptions);

        ----------------------------------------------------------------
        -- DUMMY ACCOUNT (OPTIONAL)
        ----------------------------------------------------------------
        IF (LEN(COALESCE(@DummyAccount, '')) > 0)
        BEGIN
            EXEC Subject.proc_DefaultSubjectCode
                 @SubjectName = @DummyAccount,
                 @SubjectCode = @AccountCode OUTPUT;

            INSERT INTO Subject.tbAccount
                (AccountCode, SubjectCode, AccountName, AccountTypeCode, CashCode)
            VALUES
                (@AccountCode, @SubjectCode, @DummyAccount, 1, NULL);
        END

        ----------------------------------------------------------------
        -- CAPITAL (MINIMALIST: EQUIPMENT + ADJUSTMENTS)
        ----------------------------------------------------------------
        DECLARE @CapitalAccount NVARCHAR(50);

        -- LONGTERM LIABILITIES
        SET @CapitalAccount = 'LONGTERM LIABILITIES';
        EXEC Subject.proc_DefaultAccountCode
             @AccountName = @CapitalAccount,
             @AccountCode = @AccountCode OUTPUT;

        INSERT INTO Subject.tbAccount
            (AccountCode, SubjectCode, AccountName, AccountTypeCode, BalanceConstraintCode, LiquidityLevel, CashCode, AccountClosed)
        VALUES
            (@AccountCode, @SubjectCode, @CapitalAccount, 2, 2, 50, 'CC-LOAN', 0);

        -- CALLED UP SHARE CAPITAL
        SET @CapitalAccount = 'CALLED UP SHARE CAPITAL';
        EXEC Subject.proc_DefaultAccountCode
             @AccountName = @CapitalAccount,
             @AccountCode = @AccountCode OUTPUT;

        INSERT INTO Subject.tbAccount
            (AccountCode, SubjectCode, AccountName, AccountTypeCode, BalanceConstraintCode, LiquidityLevel, CashCode, AccountClosed)
        VALUES
            (@AccountCode, @SubjectCode, @CapitalAccount, 2, 2, 60, 'CC-SHCAP', 0);

        -- EQUIPMENT (replaces P&M, Vehicles, Stock)
        SET @CapitalAccount = 'EQUIPMENT';
        EXEC Subject.proc_DefaultAccountCode
             @AccountName = @CapitalAccount,
             @AccountCode = @AccountCode OUTPUT;

        INSERT INTO Subject.tbAccount
            (AccountCode, SubjectCode, AccountName, AccountTypeCode, BalanceConstraintCode, LiquidityLevel, CashCode, AccountClosed)
        VALUES
            (@AccountCode, @SubjectCode, @CapitalAccount, 2, 1, 30, 'CC-DEPRC', 1);

        -- EQUIPMENT ADJUSTMENTS (replaces Depreciation Adjustments)
        SET @CapitalAccount = 'EQUIPMENT ADJUSTMENTS';
        EXEC Subject.proc_DefaultAccountCode
             @AccountName = @CapitalAccount,
             @AccountCode = @AccountCode OUTPUT;

        INSERT INTO Subject.tbAccount
            (AccountCode, SubjectCode, AccountName, AccountTypeCode, BalanceConstraintCode, LiquidityLevel, CashCode, AccountClosed)
        VALUES
            (@AccountCode, @SubjectCode, @CapitalAccount, 2, 0, 40, 'CC-DEPRJ', 1);


    END TRY
    BEGIN CATCH
        EXEC App.proc_ErrorLog;
    END CATCH;
GO
PRINT N'Altering Trigger [Project].[Project_tbProject_TriggerUpdate]...';


GO
ALTER TRIGGER Project.Project_tbProject_TriggerUpdate
ON Project.tbProject
FOR UPDATE
AS
    SET NOCOUNT ON;

    BEGIN TRY

		IF UPDATE(CashCode) AND EXISTS
		(
			SELECT 1
			FROM inserted i
			JOIN Cash.tbCode cash_code ON cash_code.CashCode = i.CashCode
			WHERE cash_code.IsEnabled = 0
		)
			THROW 51013, 'A Project cannot be assigned a disabled CashCode.', 1;

        IF UPDATE(SubjectCode)
        BEGIN
            UPDATE Project
            SET ParentSubjectCode = NULL
            FROM Project.tbProject Project
                JOIN inserted i ON Project.ProjectCode = i.ProjectCode
                JOIN deleted d ON i.ProjectCode = d.ProjectCode
            WHERE ISNULL(i.SubjectCode, N'') <> ISNULL(d.SubjectCode, N'');
        END

        IF UPDATE(SubjectCode) OR UPDATE(ParentSubjectCode)
        BEGIN
            ;WITH namespace_candidates AS
            (
                SELECT
                    Project.ProjectCode,
                    Project.SubjectCode,
                    Project.ParentSubjectCode,
                    ParentCount = (
                        SELECT COUNT(*)
                        FROM Subject.tbNamespace tbNamespace
                        WHERE tbNamespace.ChildSubjectCode = Project.SubjectCode
                    ),
                    SingleParentSubjectCode = (
                        SELECT MIN(tbNamespace.ParentSubjectCode)
                        FROM Subject.tbNamespace tbNamespace
                        WHERE tbNamespace.ChildSubjectCode = Project.SubjectCode
                    )
                FROM Project.tbProject Project
                    JOIN inserted i ON Project.ProjectCode = i.ProjectCode
            )
            UPDATE Project
            SET ParentSubjectCode = namespace_candidates.SingleParentSubjectCode
            FROM Project.tbProject Project
                JOIN namespace_candidates ON Project.ProjectCode = namespace_candidates.ProjectCode
            WHERE namespace_candidates.ParentSubjectCode IS NULL
              AND namespace_candidates.ParentCount = 1;

            IF EXISTS
            (
                SELECT 1
                FROM Project.tbProject Project
                    JOIN inserted i ON Project.ProjectCode = i.ProjectCode
                WHERE Project.ParentSubjectCode IS NULL
                  AND (
                        SELECT COUNT(*)
                        FROM Subject.tbNamespace tbNamespace
                        WHERE tbNamespace.ChildSubjectCode = Project.SubjectCode
                      ) > 1
            )
            BEGIN
                RAISERROR('ParentSubjectCode must be selected when Subject has multiple namespace parents.', 16, 1);
                ROLLBACK TRANSACTION;
                RETURN;
            END

            IF EXISTS
            (
                SELECT 1
                FROM Project.tbProject Project
                    JOIN inserted i ON Project.ProjectCode = i.ProjectCode
                WHERE Project.ParentSubjectCode IS NOT NULL
                  AND NOT EXISTS
                  (
                      SELECT 1
                      FROM Subject.tbNamespace tbNamespace
                      WHERE tbNamespace.ChildSubjectCode = Project.SubjectCode
                        AND tbNamespace.ParentSubjectCode = Project.ParentSubjectCode
                  )
            )
            BEGIN
                RAISERROR('ParentSubjectCode must reference a valid namespace parent for the Subject.', 16, 1);
                ROLLBACK TRANSACTION;
                RETURN;
            END
        END

        UPDATE Project
        SET Project.ActionOn = CAST(Project.ActionOn AS DATE)
        FROM Project.tbProject Project
            JOIN inserted i ON Project.ProjectCode = i.ProjectCode
        WHERE DATEDIFF(SECOND, CAST(i.ActionOn AS DATE), i.ActionOn) <> 0;

        IF UPDATE(ProjectStatusCode)
        BEGIN
            UPDATE ops
            SET OpStatusCode = 2
            FROM inserted
                JOIN Project.tbOp ops ON inserted.ProjectCode = ops.ProjectCode
            WHERE ProjectStatusCode > 1
              AND OpStatusCode < 2;

            WITH first_ops AS
            (
                SELECT ops.ProjectCode, MIN(ops.OperationNumber) AS OperationNumber
                FROM inserted i
                    JOIN Project.tbOp ops ON i.ProjectCode = ops.ProjectCode
                WHERE i.ProjectStatusCode = 1
                GROUP BY ops.ProjectCode
            ),
            next_ops AS
            (
                SELECT ops.ProjectCode,
                       ops.OperationNumber,
                       ops.SyncTypeCode,
                       LEAD(ops.OperationNumber) OVER (PARTITION BY ops.ProjectCode ORDER BY ops.OperationNumber) AS NextOpNo
                FROM inserted i
                    JOIN Project.tbOp ops ON i.ProjectCode = ops.ProjectCode
            ),
            async_ops AS
            (
                SELECT first_ops.ProjectCode, first_ops.OperationNumber, next_ops.NextOpNo
                FROM first_ops
                    JOIN next_ops ON first_ops.ProjectCode = next_ops.ProjectCode
                                 AND first_ops.OperationNumber = next_ops.OperationNumber

                UNION ALL

                SELECT next_ops.ProjectCode, next_ops.OperationNumber, next_ops.NextOpNo
                FROM next_ops
                    JOIN async_ops ON next_ops.ProjectCode = async_ops.ProjectCode
                                  AND next_ops.OperationNumber = async_ops.NextOpNo
                WHERE next_ops.SyncTypeCode = 1
            )
            UPDATE ops
            SET OpStatusCode = 1
            FROM async_ops
                JOIN Project.tbOp ops ON async_ops.ProjectCode = ops.ProjectCode
                                     AND async_ops.OperationNumber = ops.OperationNumber;

            WITH cascade_status AS
            (
                SELECT inserted.ProjectCode, inserted.ProjectStatusCode
                FROM inserted
                    JOIN deleted ON inserted.ProjectCode = deleted.ProjectCode
                WHERE inserted.CashCode IS NOT NULL
                  AND inserted.ProjectStatusCode <> deleted.ProjectStatusCode
            ),
            Project_flow AS
            (
                SELECT cascade_status.ProjectStatusCode ParentStatusCode,
                       child.ParentProjectCode,
                       child.ChildProjectCode,
                       child_Project.ProjectStatusCode
                FROM Project.tbFlow child
                    JOIN cascade_status ON child.ParentProjectCode = cascade_status.ProjectCode
                    JOIN Project.tbProject child_Project ON child.ChildProjectCode = child_Project.ProjectCode

                UNION ALL

                SELECT parent.ParentStatusCode,
                       child.ParentProjectCode,
                       child.ChildProjectCode,
                       child_Project.ProjectStatusCode
                FROM Project.tbFlow child
                    JOIN Project_flow parent ON child.ParentProjectCode = parent.ChildProjectCode
                    JOIN Project.tbProject child_Project ON child.ChildProjectCode = child_Project.ProjectCode
            )
            UPDATE Project
            SET ProjectStatusCode = CASE Project_flow.ParentStatusCode WHEN 3 THEN 2 ELSE Project_flow.ParentStatusCode END
            FROM Project.tbProject Project
                JOIN Project_flow ON Project_flow.ChildProjectCode = Project.ProjectCode
            WHERE Project.ProjectStatusCode < 2
              AND Project.ProjectStatusCode <> CASE Project_flow.ParentStatusCode WHEN 3 THEN 2 ELSE Project_flow.ParentStatusCode END;

            WITH cascade_status AS
            (
                SELECT inserted.ProjectCode, inserted.ProjectStatusCode
                FROM inserted
                    JOIN deleted ON inserted.ProjectCode = deleted.ProjectCode
                WHERE inserted.CashCode IS NOT NULL
                  AND inserted.ProjectStatusCode > 1
                  AND inserted.ProjectStatusCode <> deleted.ProjectStatusCode
            ),
            Project_flow AS
            (
                SELECT cascade_status.ProjectStatusCode ParentStatusCode,
                       child.ParentProjectCode,
                       child.ChildProjectCode,
                       child_Project.ProjectStatusCode
                FROM Project.tbFlow child
                    JOIN cascade_status ON child.ParentProjectCode = cascade_status.ProjectCode
                    JOIN Project.tbProject child_Project ON child.ChildProjectCode = child_Project.ProjectCode
                WHERE CashCode IS NULL

                UNION ALL

                SELECT parent.ParentStatusCode,
                       child.ParentProjectCode,
                       child.ChildProjectCode,
                       child_Project.ProjectStatusCode
                FROM Project.tbFlow child
                    JOIN Project_flow parent ON child.ParentProjectCode = parent.ChildProjectCode
                    JOIN Project.tbProject child_Project ON child.ChildProjectCode = child_Project.ProjectCode
                WHERE CashCode IS NULL
            )
            UPDATE ops
            SET OpStatusCode = 2
            FROM Project.tbOp ops
                JOIN Project_flow ON Project_flow.ChildProjectCode = ops.ProjectCode
            WHERE ops.OpStatusCode < 2;

            DELETE cost_set
            FROM inserted
                JOIN Project.tbCostSet cost_set ON inserted.ProjectCode = cost_set.ProjectCode
            WHERE inserted.ProjectStatusCode > 0;
        END

        IF UPDATE(Quantity)
        BEGIN
            UPDATE flow
            SET UsedOnQuantity = inserted.Quantity / parent_Project.Quantity
            FROM Project.tbFlow AS flow
                JOIN inserted ON flow.ChildProjectCode = inserted.ProjectCode
                JOIN Project.tbProject AS parent_Project ON flow.ParentProjectCode = parent_Project.ProjectCode
                JOIN Cash.tbCode ON parent_Project.CashCode = Cash.tbCode.CashCode
            WHERE (flow.UsedOnQuantity <> 0)
              AND (inserted.Quantity <> 0)
              AND (inserted.Quantity / parent_Project.Quantity <> flow.UsedOnQuantity);
        END

        IF UPDATE(Quantity) OR UPDATE(UnitCharge)
        BEGIN
            UPDATE Project
            SET Project.TotalCharge = i.Quantity * i.UnitCharge
            FROM Project.tbProject Project
                JOIN inserted i ON Project.ProjectCode = i.ProjectCode;
        END

        IF UPDATE(TotalCharge)
        BEGIN
            UPDATE Project
            SET Project.UnitCharge = CASE i.TotalCharge + i.Quantity WHEN 0 THEN 0 ELSE i.TotalCharge / i.Quantity END
            FROM Project.tbProject Project
                JOIN inserted i ON Project.ProjectCode = i.ProjectCode;
        END

        IF UPDATE(ActionOn)
        BEGIN
            WITH parent_Project AS
            (
                SELECT ParentProjectCode
                FROM Project.tbFlow flow
                    JOIN Project.tbProject Project ON flow.ParentProjectCode = Project.ProjectCode
                    JOIN Cash.tbCode cash ON Project.CashCode = cash.CashCode
                    JOIN inserted ON flow.ChildProjectCode = inserted.ProjectCode
                WHERE (SELECT SUM(UsedOnQuantity) FROM inserted JOIN Project.tbFlow ON inserted.ProjectCode = Project.tbFlow.ChildProjectCode) = 0
            ),
            Project_flow AS
            (
                SELECT flow.ParentProjectCode,
                       flow.StepNumber,
                       Project.ActionOn,
                       LAG(Project.ActionOn, 1, Project.ActionOn) OVER (PARTITION BY flow.ParentProjectCode ORDER BY StepNumber) AS PrevActionOn
                FROM Project.tbFlow flow
                    JOIN Project.tbProject Project ON flow.ChildProjectCode = Project.ProjectCode
                    JOIN parent_Project ON flow.ParentProjectCode = parent_Project.ParentProjectCode
            ),
            step_disordered AS
            (
                SELECT ParentProjectCode
                FROM Project_flow
                WHERE ActionOn < PrevActionOn
                GROUP BY ParentProjectCode
            ),
            step_ordered AS
            (
                SELECT flow.ParentProjectCode,
                       flow.ChildProjectCode,
                       ROW_NUMBER() OVER (PARTITION BY flow.ParentProjectCode ORDER BY Project.ActionOn, flow.StepNumber) * 10 AS StepNumber
                FROM step_disordered
                    JOIN Project.tbFlow flow ON step_disordered.ParentProjectCode = flow.ParentProjectCode
                    JOIN Project.tbProject Project ON flow.ChildProjectCode = Project.ProjectCode
            )
            UPDATE flow
            SET StepNumber = step_ordered.StepNumber
            FROM Project.tbFlow flow
                JOIN step_ordered ON flow.ParentProjectCode = step_ordered.ParentProjectCode
                                 AND flow.ChildProjectCode = step_ordered.ChildProjectCode;

            IF EXISTS(SELECT * FROM App.tbOptions WHERE IsAutoOffsetDays <> 0)
            BEGIN
                UPDATE flow
                SET OffsetDays = App.fnOffsetDays(inserted.ActionOn, parent_Project.ActionOn)
                                 - ISNULL((SELECT SUM(OffsetDays) FROM Project.tbFlow sub_flow WHERE sub_flow.ParentProjectCode = flow.ParentProjectCode AND sub_flow.StepNumber > flow.StepNumber), 0)
                FROM Project.tbFlow AS flow
                    JOIN inserted ON flow.ChildProjectCode = inserted.ProjectCode
                    JOIN Project.tbProject AS parent_Project ON flow.ParentProjectCode = parent_Project.ProjectCode
                    JOIN Cash.tbCode ON parent_Project.CashCode = Cash.tbCode.CashCode
                WHERE (SELECT SUM(UsedOnQuantity) FROM inserted JOIN Project.tbFlow ON inserted.ProjectCode = Project.tbFlow.ChildProjectCode) = 0;
            END

            UPDATE Project
            SET PaymentOn = App.fnAdjustToCalendar(
                    CASE
                        WHEN Subject.PayDaysFromMonthEnd <> 0 THEN
                            DATEADD(d, -1, DATEADD(m, 1, CONCAT(FORMAT(DATEADD(d, Subject.PaymentDays + Subject.ExpectedDays, i.ActionOn), 'yyyyMM'), '01')))
                        ELSE
                            DATEADD(d, Subject.PaymentDays + Subject.ExpectedDays, i.ActionOn)
                    END, 0)
            FROM Project.tbProject Project
                JOIN inserted i ON Project.ProjectCode = i.ProjectCode
                JOIN Subject.tbSubject Subject ON i.SubjectCode = Subject.SubjectCode
            WHERE NOT Project.CashCode IS NULL;
        END

        IF UPDATE(ProjectTitle)
        BEGIN
            WITH cascade_title_change AS
            (
                SELECT inserted.ProjectCode,
                       inserted.ProjectTitle AS NewTitle,
                       deleted.ProjectTitle AS PreviousTitle
                FROM inserted
                    JOIN deleted ON inserted.ProjectCode = deleted.ProjectCode
            ),
            Project_flow AS
            (
                SELECT cascade_title_change.NewTitle,
                       cascade_title_change.PreviousTitle,
                       child.ParentProjectCode,
                       child.ChildProjectCode,
                       child_Project.ProjectTitle
                FROM Project.tbFlow child
                    JOIN cascade_title_change ON child.ParentProjectCode = cascade_title_change.ProjectCode
                    JOIN Project.tbProject child_Project ON child.ChildProjectCode = child_Project.ProjectCode

                UNION ALL

                SELECT parent.NewTitle,
                       parent.PreviousTitle,
                       child.ParentProjectCode,
                       child.ChildProjectCode,
                       child_Project.ProjectTitle
                FROM Project.tbFlow child
                    JOIN Project_flow parent ON child.ParentProjectCode = parent.ChildProjectCode
                    JOIN Project.tbProject child_Project ON child.ChildProjectCode = child_Project.ProjectCode
            )
            UPDATE Project
            SET ProjectTitle = NewTitle
            FROM Project.tbProject Project
                JOIN Project_flow ON Project.ProjectCode = Project_flow.ChildProjectCode
            WHERE Project_flow.PreviousTitle = Project_flow.ProjectTitle;
        END

        IF UPDATE(Spooled)
        BEGIN
            INSERT INTO App.tbDocSpool (DocTypeCode, DocumentNumber)
            SELECT CASE
                       WHEN CashPolarityCode = 0 THEN CASE WHEN ProjectStatusCode = 0 THEN 2 ELSE 3 END
                       WHEN CashPolarityCode = 1 THEN CASE WHEN ProjectStatusCode = 0 THEN 0 ELSE 1 END
                   END AS DocTypeCode,
                   Project.ProjectCode
            FROM inserted Project
                INNER JOIN Cash.tbCode ON Project.CashCode = Cash.tbCode.CashCode
                INNER JOIN Cash.tbCategory ON Cash.tbCode.CategoryCode = Cash.tbCategory.CategoryCode
            WHERE (Project.Spooled <> 0);

            DELETE App.tbDocSpool
            FROM inserted i
                INNER JOIN App.tbDocSpool ON i.ProjectCode = App.tbDocSpool.DocumentNumber
            WHERE (i.Spooled = 0) AND (App.tbDocSpool.DocTypeCode <= 3);
        END

        IF UPDATE(ContactName)
        BEGIN
            DECLARE @Xml NVARCHAR(MAX);

            SELECT @Xml =
            (
                SELECT
                    i.SubjectCode,
                    i.ContactName
                FROM inserted AS i
                WHERE NULLIF(LTRIM(RTRIM(i.ContactName)), N'') IS NOT NULL
                FOR XML PATH('Contact'), ROOT('Contacts'), TYPE
            ).value('.', 'nvarchar(max)');

            IF NULLIF(@Xml, N'') IS NOT NULL
                EXEC Subject.proc_AddContacts @Xml = @Xml;
        END

        UPDATE Project.tbProject
        SET UpdatedBy = Usr.fnUserName(), UpdatedOn = CURRENT_TIMESTAMP
        FROM Project.tbProject
            INNER JOIN inserted AS i ON tbProject.ProjectCode = i.ProjectCode;

        IF UPDATE(ProjectStatusCode) OR UPDATE(Quantity) OR UPDATE(ActionOn) OR UPDATE(UnitCharge) OR UPDATE(ObjectCode) OR UPDATE(CashCode) OR UPDATE(TaxCode)
        BEGIN
            WITH candidates AS
            (
                SELECT ProjectCode, SubjectCode, ObjectCode, ProjectStatusCode, ActionOn, Quantity, CashCode, TaxCode, UnitCharge
                FROM inserted
                WHERE EXISTS (SELECT * FROM Project.tbChangeLog WHERE ProjectCode = inserted.ProjectCode)
            ),
            logs AS
            (
                SELECT clog.LogId,
                       clog.ProjectCode,
                       clog.SubjectCode,
                       clog.ObjectCode,
                       clog.ProjectStatusCode,
                       clog.TransmitStatusCode,
                       clog.ActionOn,
                       clog.Quantity,
                       clog.CashCode,
                       clog.TaxCode,
                       clog.UnitCharge
                FROM Project.tbChangeLog clog
                    JOIN candidates ON clog.ProjectCode = candidates.ProjectCode
                                   AND LogId = (SELECT MAX(LogId) FROM Project.tbChangeLog WHERE ProjectCode = candidates.ProjectCode)
            )
            INSERT INTO Project.tbChangeLog
                                    (ProjectCode, TransmitStatusCode, SubjectCode, ObjectCode, ProjectStatusCode, ActionOn, Quantity, CashCode, TaxCode, UnitCharge)
            SELECT candidates.ProjectCode,
                   CASE Subjects.TransmitStatusCode WHEN 1 THEN 2 ELSE 0 END TransmitStatusCode,
                   candidates.SubjectCode,
                   candidates.ObjectCode,
                   candidates.ProjectStatusCode,
                   candidates.ActionOn,
                   candidates.Quantity,
                   candidates.CashCode,
                   candidates.TaxCode,
                   candidates.UnitCharge
            FROM candidates
                JOIN Subject.tbSubject Subjects ON candidates.SubjectCode = Subjects.SubjectCode
                JOIN logs ON candidates.ProjectCode = logs.ProjectCode
            WHERE (logs.ProjectStatusCode <> candidates.ProjectStatusCode)
               OR (logs.TransmitStatusCode < 2)
               OR (logs.ActionOn <> candidates.ActionOn)
               OR (logs.Quantity <> candidates.Quantity)
               OR (logs.UnitCharge <> candidates.UnitCharge)
               OR (logs.TaxCode <> candidates.TaxCode);
        END;

        IF UPDATE(SubjectCode)
        BEGIN
            WITH candidates AS
            (
                SELECT inserted.*
                FROM inserted
                    JOIN deleted ON inserted.ProjectCode = deleted.ProjectCode
                WHERE inserted.SubjectCode <> deleted.SubjectCode
            )
            INSERT INTO Project.tbChangeLog
                                    (ProjectCode, TransmitStatusCode, SubjectCode, ObjectCode, ProjectStatusCode, ActionOn, Quantity, CashCode, TaxCode, UnitCharge)
            SELECT candidates.ProjectCode,
                   Subject.tbSubject.TransmitStatusCode,
                   candidates.SubjectCode,
                   candidates.ObjectCode,
                   candidates.ProjectStatusCode,
                   candidates.ActionOn,
                   candidates.Quantity,
                   candidates.CashCode,
                   candidates.TaxCode,
                   candidates.UnitCharge
            FROM candidates
                JOIN Subject.tbSubject ON candidates.SubjectCode = Subject.tbSubject.SubjectCode
                JOIN Cash.tbCode ON candidates.CashCode = Cash.tbCode.CashCode;
        END

    END TRY
    BEGIN CATCH
        EXEC App.proc_ErrorLog;
    END CATCH
GO
PRINT N'Altering Procedure [App].[proc_DatasetSyntheticMIS_TaxVat]...';


GO
ALTER   PROCEDURE App.proc_DatasetSyntheticMIS_TaxVat
(
	@IsCompany bit,
	@IsVatRegistered bit
)
AS
	SET NOCOUNT, XACT_ABORT ON;

	IF @IsVatRegistered = 0
		RETURN;

	DECLARE @SettlementAccountCode nvarchar(10) = (SELECT ca.AccountCode FROM Cash.vwCurrentAccount ca);

	DECLARE @CurrentPeriodStartOn date =
	(
		SELECT MIN(CAST(StartOn AS date))
		FROM App.tbYearPeriod
		WHERE CashStatusCode = 1
	);

	IF @CurrentPeriodStartOn IS NULL
		THROW 51292, 'DatasetSyntheticMIS_TaxVat: unable to resolve @CurrentPeriodStartOn from App.tbYearPeriod.', 1;

    ---------------------------------------------------------------------
	-- VAT adjustments (Admin Manager behavior):
	-- stored on App.tbYearPeriod.VatAdjustment in the last month of the quarter (PayTo)
	-- Apply only for quarters that are due (PayOn <= current period start).
	---------------------------------------------------------------------
	;WITH vat_dates AS
	(
		SELECT CAST(PayOn AS date) AS PayOn, CAST(PayTo AS date) AS PayTo
		FROM Cash.fnTaxTypeDueDates(1, 0)
	),
	due_quarters AS
	(
		SELECT vd.PayTo
		FROM vat_dates vd
		WHERE vd.PayOn <= @CurrentPeriodStartOn
	),
	target_periods AS
	(
		SELECT yp.StartOn
		FROM App.tbYearPeriod yp
		JOIN due_quarters dq
			ON CAST(yp.StartOn AS date) = dq.PayTo
	)
	UPDATE yp
	SET
		VatAdjustment = adjustment.Amount,
		VatAdjustmentNote = CASE
			WHEN adjustment.Amount <> 0
				THEN N'Synthetic dataset: illustrative VAT rounding difference.'
			ELSE NULL
		END
	FROM App.tbYearPeriod yp
	JOIN target_periods t
		ON t.StartOn = yp.StartOn
	CROSS APPLY
	(
		SELECT CAST
		(
			CASE (ABS(CHECKSUM(CONCAT(N'DS:VATADJ:', CONVERT(nvarchar(10), CAST(yp.StartOn AS date), 23)))) % 3)
				WHEN 0 THEN 0.01
				WHEN 1 THEN -0.02
				ELSE 0.00
			END
			AS decimal(18, 5)
		) AS Amount
	) adjustment
	WHERE ISNULL(yp.VatAdjustment, 0) = 0
	  AND (ABS(CHECKSUM(CONCAT(N'DS:VATADJ:ENABLE:', CONVERT(nvarchar(10), CAST(yp.StartOn AS date), 23)))) % 4) <> 0;

    ---------------------------------------------------------------------
    -- Pay vat balance from Cash.vwTaxVatStatement
    ---------------------------------------------------------------------
	DECLARE
		@HmrcSubjectCode nvarchar(50),
		@VatCashCode nvarchar(50);

	SELECT
		@HmrcSubjectCode = SubjectCode,
		@VatCashCode = CashCode
	FROM Cash.tbTaxType
	WHERE TaxTypeCode = 1;

	IF @HmrcSubjectCode IS NULL OR @VatCashCode IS NULL
		THROW 51293, 'DatasetSyntheticMIS_TaxVat: Cash.tbTaxType missing SubjectCode/CashCode for TaxTypeCode=1.', 1;

	DECLARE @UserId nvarchar(10) = (SELECT TOP (1) UserId FROM Usr.vwCredentials);

	DECLARE
		@PayOn date = (SELECT MIN(CAST(StartOn AS date)) FROM App.tbYearPeriod),
		@Balance decimal(18,5),
		@PaymentCode nvarchar(20),
		@PaidOut decimal(18,5),
		@PaidIn decimal(18,5),
		@LoopGuard int = 0;

	WHILE 1 = 1
	BEGIN
		SET @LoopGuard += 1;
		IF @LoopGuard > 200
			THROW 51294, 'DatasetSyntheticMIS_TaxVat: loop guard triggered (too many VAT payment iterations).', 1;

		SET @PayOn = DATEADD(month, 1, @PayOn);

		SELECT TOP (1)
			@PayOn = CAST(StartOn AS date),
			@Balance = Balance
		FROM Cash.vwTaxVatStatement
		WHERE CAST(StartOn AS date) BETWEEN @PayOn AND @CurrentPeriodStartOn
		  AND Balance <> 0
		ORDER BY RowNumber;

		IF @Balance IS NULL
			BREAK;

		SET @PaidOut = CASE WHEN @Balance > 0 THEN @Balance ELSE CAST(0 AS decimal(18,5)) END;
		SET @PaidIn  = CASE WHEN @Balance < 0 THEN ABS(@Balance) ELSE CAST(0 AS decimal(18,5)) END;

		SET @PaymentCode = NULL;
		EXEC Cash.proc_NextPaymentCode @PaymentCode = @PaymentCode OUTPUT;

		INSERT INTO Cash.tbPayment
		(
			PaymentCode,
			UserId,
			PaymentStatusCode,
			SubjectCode,
			AccountCode,
			CashCode,
			TaxCode,
			PaidOn,
			PaidInValue,
			PaidOutValue,
			PaymentReference
		)
		VALUES
		(
			@PaymentCode,
			@UserId,
			0,
			@HmrcSubjectCode,
			@SettlementAccountCode,
			@VatCashCode,
			N'N/A',
			@PayOn,
			@PaidIn,
			@PaidOut,
			N'DS VAT PAYMENT'
		);

		EXEC Cash.proc_PaymentPost;

		SET @Balance = NULL;
	END

	---------------------------------------------------------------------
	-- Every VAT liability due by the current synthetic period must be
	-- settled on its due date. This guards against scope changes leaving
	-- stale synthetic payments in the fixture.
	---------------------------------------------------------------------
	IF EXISTS
	(
		SELECT 1
		FROM
		(
			SELECT DISTINCT CAST(StartOn AS date) AS StartOn
			FROM Cash.vwTaxVatStatement
			WHERE VatDue <> 0
			  AND CAST(StartOn AS date) <= @CurrentPeriodStartOn
		) due_statement_dates
		OUTER APPLY
		(
			SELECT TOP (1) statement.Balance
			FROM Cash.vwTaxVatStatement statement
			WHERE CAST(statement.StartOn AS date) = due_statement_dates.StartOn
			ORDER BY statement.RowNumber DESC
		) closing
		WHERE closing.Balance IS NULL OR ABS(closing.Balance) > 0.05
	)
		THROW 51295, 'DatasetSyntheticMIS_TaxVat: historical VAT liability is not settled within tolerance.', 1;
GO
PRINT N'Altering Procedure [App].[proc_DatasetSyntheticMIS_Bootstrap]...';


GO
ALTER   PROCEDURE App.proc_DatasetSyntheticMIS_Bootstrap
(
	@TemplateCode nvarchar(10) = N'COMIN26',
	@IsVatRegistered bit = NULL,
    @EnableOpeningBalance bit = 1,
	@ExpectedAnnualProfit decimal(18, 2) = 50000,
	@CompletedYearCount smallint = 2,
	@FinancialMonth smallint = NULL,
	@AsOfDate date = NULL
)
AS
	SET NOCOUNT, XACT_ABORT ON;

	IF @CompletedYearCount NOT BETWEEN 1 AND 10
		THROW 51006, 'DatasetSyntheticMIS: @CompletedYearCount must be between 1 and 10.', 1;

	IF @FinancialMonth IS NOT NULL AND @FinancialMonth NOT BETWEEN 1 AND 12
		THROW 51007, 'DatasetSyntheticMIS: @FinancialMonth must be between 1 and 12.', 1;

	DECLARE
		@GovAccountName nvarchar(255) = NULL,
		@BankName nvarchar(255) = NULL,
		@BankAddress nvarchar(max) = NULL,
		@DummyAccount nvarchar(50) = NULL,
		@CurrentAccount nvarchar(50) = NULL,
		@CA_SortCode nvarchar(10) = NULL,
		@CA_AccountNumber nvarchar(20) = NULL,
		@ReserveAccount nvarchar(50) = NULL,
		@RA_SortCode nvarchar(10) = NULL,
		@RA_AccountNumber nvarchar(20) = NULL;

	IF @TemplateCode IS NULL OR NOT EXISTS (SELECT 1 FROM App.tbTemplate WHERE TemplateCode = @TemplateCode)
		THROW 51001, 'DatasetSyntheticMIS: @TemplateCode not found in App.tbTemplate.', 1;

	IF @IsVatRegistered IS NULL
	BEGIN
		SELECT @IsVatRegistered = IsVatRegistered
		FROM App.tbTemplate
		WHERE TemplateCode = @TemplateCode;
	END

	DECLARE
		@SubjectCode nvarchar(50) = NULL,
		@BusinessName nvarchar(255) = NULL,
		@FullName nvarchar(100) = NULL,
		@BusinessAddress nvarchar(max) = NULL,
		@BusinessEmailAddress nvarchar(255) = NULL,
		@UserEmailAddress nvarchar(255) = NULL,
		@PhoneNumber nvarchar(50) = NULL,
		@CompanyNumber nvarchar(20) = NULL,
		@VatNumber nvarchar(20) = NULL,
		@CalendarCode nvarchar(10) = NULL,
		@JurisdictionCode nvarchar(10) = NULL,
		@UnitOfCharge nvarchar(5) = NULL;

	DECLARE
		@NodeSubjectCode nvarchar(50) = (SELECT TOP (1) SubjectCode FROM App.tbOptions),
		@CoinTypeCode smallint = (SELECT TOP (1) CoinTypeCode FROM App.tbOptions);

	IF NOT EXISTS (SELECT 1 FROM App.tbOptions)
		THROW 51000, 'DatasetSyntheticMIS: App.tbOptions is empty. Configure a node once via the UI, then rerun.', 1;

	SELECT TOP (1)
		@SubjectCode = opt.SubjectCode,
		@JurisdictionCode = opt.JurisdictionCode,
		@UnitOfCharge = opt.UnitOfCharge
	FROM App.tbOptions opt;

	IF EXISTS (SELECT 1 FROM Usr.vwDoc)
	BEGIN
		SELECT TOP (1)
			@BusinessName = CompanyName,
			@BusinessAddress = CompanyAddress,
			@BusinessEmailAddress = CompanyEmailAddress,
			@PhoneNumber = CompanyPhoneNumber,
			@CompanyNumber = CompanyNumber,
			@VatNumber = VatNumber,
			@BankName = BankName,
			@BankAddress = BankAddress,
			@CurrentAccount = CurrentAccountName,
			@CA_AccountNumber = BankAccountNumber,
			@CA_SortCode = BankSortCode
		FROM Usr.vwDoc;
	END

	-- The copied node identity may pre-date the nine-digit VAT constraint. The
	-- synthetic rebuild must carry a valid test identity into BasicSetup, which
	-- creates the indirect-tax reporting profile before the statutory-profile
	-- normalisation step runs.
	IF @IsVatRegistered <> 0
		AND
		(
			LEN(LTRIM(RTRIM(COALESCE(@VatNumber, N'')))) <> 9
			OR LTRIM(RTRIM(COALESCE(@VatNumber, N''))) LIKE N'%[^0-9]%'
		)
		SET @VatNumber = N'999000001';

	IF NOT EXISTS (SELECT 1 FROM Usr.vwCredentials)
		THROW 51001, 'DatasetSyntheticMIS: current user is not registered. Web initialization required.', 1;

	SELECT
		@FullName = u.UserName,
		@UserEmailAddress = u.EmailAddress
	FROM Usr.vwCredentials uc
		JOIN Usr.tbUser u
			ON u.UserId = uc.UserId;

	SELECT TOP (1)
		@CalendarCode = CalendarCode
	FROM Usr.tbUser
	ORDER BY UserId;

	IF @FinancialMonth IS NULL
		SET @FinancialMonth = (SELECT TOP (1) StartMonth FROM App.tbYear ORDER BY YearNumber DESC);

	IF @FinancialMonth IS NULL
		SET @FinancialMonth = 4;

	IF @GovAccountName IS NULL
		SELECT TOP (1) @GovAccountName = s.SubjectName
		FROM Cash.tbTaxType t
			JOIN Subject.tbSubject s ON t.SubjectCode = s.SubjectCode
		ORDER BY t.SubjectCode;

	IF EXISTS (SELECT 1 FROM Subject.tbAccount WHERE AccountTypeCode = 1)
		SELECT TOP (1) @DummyAccount = AccountCode
		FROM Subject.tbAccount
		WHERE AccountTypeCode = 1
		ORDER BY AccountCode;

	IF EXISTS (SELECT 1 FROM Cash.vwReserveAccount)
		SELECT
			@ReserveAccount = ra.AccountCode,
			@RA_SortCode = ra.SortCode,
			@RA_AccountNumber = ra.AccountNumber
		FROM Cash.vwReserveAccount ra;

	IF @SubjectCode IS NULL OR @BusinessName IS NULL OR @BusinessAddress IS NULL OR @FullName IS NULL OR @CalendarCode IS NULL OR @JurisdictionCode IS NULL OR @UnitOfCharge IS NULL
		THROW 51002, 'DatasetSyntheticMIS: unable to reverse engineer required node configuration.', 1;

	DECLARE @IdentityUserId nvarchar(450);

	SELECT TOP (1) @IdentityUserId = au.Id
	FROM dbo.AspNetUsers au
	WHERE au.UserName = @UserEmailAddress
		OR au.Email = @UserEmailAddress
	ORDER BY au.Id;

	IF @IdentityUserId IS NULL
		THROW 51004, 'DatasetSyntheticMIS: current Identity user not found in dbo.AspNetUsers.', 1;

	DECLARE
		@KeepDomainUserCount int = (SELECT COUNT(*) FROM Usr.tbUser),
		@KeepIdentityUserCount int = (SELECT COUNT(*) FROM dbo.AspNetUsers),
		@KeepIdentityRoleCount int = (SELECT COUNT(*) FROM dbo.AspNetUserRoles),
		@KeepIdentityClaimCount int = (SELECT COUNT(*) FROM dbo.AspNetUserClaims),
		@KeepIdentityLoginCount int = (SELECT COUNT(*) FROM dbo.AspNetUserLogins),
		@KeepIdentityTokenCount int = (SELECT COUNT(*) FROM dbo.AspNetUserTokens),
		@KeepRoleCatalogueCount int = (SELECT COUNT(*) FROM dbo.AspNetRoles),
		@KeepRoleClaimCount int = (SELECT COUNT(*) FROM dbo.AspNetRoleClaims);

	-- Recommissioning replaces the accounting dataset, not the tenant's user
	-- directory. Preserve every approved business profile and every ASP.NET
	-- Identity record so additional registrations remain usable afterwards.
	SELECT
		UserId,
		UserName,
		LogonName,
		CalendarCode,
		PhoneNumber,
		MobileNumber,
		EmailAddress,
		Address,
		Avatar,
		Signature,
		IsAdministrator,
		IsEnabled,
		NextProjectNumber,
		ThemeCode,
		InsertedBy,
		InsertedOn,
		UpdatedBy,
		UpdatedOn
	INTO #Keep_UsrUsers
	FROM Usr.tbUser;

	SELECT * INTO #Keep_AspNetUsers FROM dbo.AspNetUsers;
	SELECT * INTO #Keep_AspNetUserRoles FROM dbo.AspNetUserRoles;
	SELECT * INTO #Keep_AspNetUserClaims FROM dbo.AspNetUserClaims;
	SELECT * INTO #Keep_AspNetUserLogins FROM dbo.AspNetUserLogins;
	SELECT * INTO #Keep_AspNetUserTokens FROM dbo.AspNetUserTokens;

	EXEC App.proc_NodeDataInit;

	EXEC App.proc_NodeBusinessInit
		@SubjectCode = @SubjectCode,
		@BusinessName = @BusinessName,
		@FullName = @FullName,
		@BusinessAddress = @BusinessAddress,
		@BusinessEmailAddress = @BusinessEmailAddress,
		@UserEmailAddress = @UserEmailAddress,
		@PhoneNumber = @PhoneNumber,
		@CompanyNumber = @CompanyNumber,
		@VatNumber = @VatNumber,
		@CalendarCode = @CalendarCode,
		@JurisdictionCode = @JurisdictionCode,
		@UnitOfCharge = @UnitOfCharge;

	-- NodeBusinessInit creates the administrator needed by a new node. Replace
	-- that bootstrap row with the complete pre-existing business directory.
	DELETE FROM Usr.tbUser;

	INSERT INTO Usr.tbUser
	(
		UserId,
		UserName,
		LogonName,
		CalendarCode,
		PhoneNumber,
		MobileNumber,
		EmailAddress,
		Address,
		Avatar,
		Signature,
		IsAdministrator,
		IsEnabled,
		NextProjectNumber,
		ThemeCode,
		InsertedBy,
		InsertedOn,
		UpdatedBy,
		UpdatedOn
	)
	SELECT
		UserId,
		UserName,
		LogonName,
		CalendarCode,
		PhoneNumber,
		MobileNumber,
		EmailAddress,
		Address,
		Avatar,
		Signature,
		IsAdministrator,
		IsEnabled,
		NextProjectNumber,
		ThemeCode,
		InsertedBy,
		InsertedOn,
		UpdatedBy,
		UpdatedOn
	FROM #Keep_UsrUsers;

	-- Restore Identity only after Usr.tbUser. AspNetUsers_TriggerInsert uses the
	-- business profiles to decide administrator membership; restoring earlier
	-- would incorrectly promote every identity in an empty node.
	INSERT INTO dbo.AspNetUsers
	(
		Id,
		UserName,
		NormalizedUserName,
		Email,
		NormalizedEmail,
		EmailConfirmed,
		PasswordHash,
		SecurityStamp,
		ConcurrencyStamp,
		PhoneNumber,
		PhoneNumberConfirmed,
		TwoFactorEnabled,
		LockoutEnd,
		LockoutEnabled,
		AccessFailedCount
	)
	SELECT
		Id,
		UserName,
		NormalizedUserName,
		Email,
		NormalizedEmail,
		EmailConfirmed,
		PasswordHash,
		SecurityStamp,
		ConcurrencyStamp,
		PhoneNumber,
		PhoneNumberConfirmed,
		TwoFactorEnabled,
		LockoutEnd,
		LockoutEnabled,
		AccessFailedCount
	FROM #Keep_AspNetUsers;

	-- AspNetUsers_TriggerInsert may synchronise administrator and phone fields.
	-- Reapply the snapshot so recommissioning preserves the complete Identity
	-- record, including confirmation and lockout state, byte for byte.
	UPDATE target
	SET
		UserName = source.UserName,
		NormalizedUserName = source.NormalizedUserName,
		Email = source.Email,
		NormalizedEmail = source.NormalizedEmail,
		EmailConfirmed = source.EmailConfirmed,
		PasswordHash = source.PasswordHash,
		SecurityStamp = source.SecurityStamp,
		ConcurrencyStamp = source.ConcurrencyStamp,
		PhoneNumber = source.PhoneNumber,
		PhoneNumberConfirmed = source.PhoneNumberConfirmed,
		TwoFactorEnabled = source.TwoFactorEnabled,
		LockoutEnd = source.LockoutEnd,
		LockoutEnabled = source.LockoutEnabled,
		AccessFailedCount = source.AccessFailedCount
	FROM dbo.AspNetUsers target
		JOIN #Keep_AspNetUsers source ON source.Id = target.Id;

	-- Remove any role rows added by the insert trigger, then restore the exact
	-- pre-recommissioning security assignments.
	DELETE r
	FROM dbo.AspNetUserRoles r
		JOIN #Keep_AspNetUsers u ON u.Id = r.UserId;

	INSERT INTO dbo.AspNetUserRoles (UserId, RoleId)
	SELECT UserId, RoleId
	FROM #Keep_AspNetUserRoles;

	INSERT INTO dbo.AspNetUserClaims (UserId, ClaimType, ClaimValue)
	SELECT UserId, ClaimType, ClaimValue
	FROM #Keep_AspNetUserClaims;

	INSERT INTO dbo.AspNetUserLogins (LoginProvider, ProviderKey, ProviderDisplayName, UserId)
	SELECT LoginProvider, ProviderKey, ProviderDisplayName, UserId
	FROM #Keep_AspNetUserLogins;

	INSERT INTO dbo.AspNetUserTokens (UserId, LoginProvider, Name, Value)
	SELECT UserId, LoginProvider, Name, Value
	FROM #Keep_AspNetUserTokens;

	IF (SELECT COUNT(*) FROM Usr.tbUser) <> @KeepDomainUserCount
		OR (SELECT COUNT(*) FROM dbo.AspNetUsers) <> @KeepIdentityUserCount
		OR (SELECT COUNT(*) FROM dbo.AspNetUserRoles) <> @KeepIdentityRoleCount
		OR (SELECT COUNT(*) FROM dbo.AspNetUserClaims) <> @KeepIdentityClaimCount
		OR (SELECT COUNT(*) FROM dbo.AspNetUserLogins) <> @KeepIdentityLoginCount
		OR (SELECT COUNT(*) FROM dbo.AspNetUserTokens) <> @KeepIdentityTokenCount
		OR (SELECT COUNT(*) FROM dbo.AspNetRoles) <> @KeepRoleCatalogueCount
		OR (SELECT COUNT(*) FROM dbo.AspNetRoleClaims) <> @KeepRoleClaimCount
		THROW 51008, 'DatasetSyntheticMIS: tenant user directory was not restored exactly.', 1;

	DROP TABLE #Keep_UsrUsers;
	DROP TABLE #Keep_AspNetUsers;
	DROP TABLE #Keep_AspNetUserRoles;
	DROP TABLE #Keep_AspNetUserClaims;
	DROP TABLE #Keep_AspNetUserLogins;
	DROP TABLE #Keep_AspNetUserTokens;

	EXEC App.proc_BasicSetup
		@TemplateCode = @TemplateCode,
		@FinancialMonth = @FinancialMonth,
		@CoinTypeCode = @CoinTypeCode,
		@GovAccountName = @GovAccountName,
		@BankName = @BankName,
		@BankAddress = @BankAddress,
		@DummyAccount = @DummyAccount,
		@CurrentAccount = @CurrentAccount,
		@CA_SortCode = @CA_SortCode,
		@CA_AccountNumber = @CA_AccountNumber,
		@ReserveAccount = @ReserveAccount,
		@RA_SortCode = @RA_SortCode,
		@RA_AccountNumber = @RA_AccountNumber,
		@IsVatRegistered = @IsVatRegistered,
		@ExpectedAnnualProfit = @ExpectedAnnualProfit,
		@AsOfDate = @AsOfDate;

	DECLARE @ExternalRootCode nvarchar(50) = NULL;

	EXEC App.proc_DefaultCodeGenerator
		@Description = N'External',
		@CheckSql = N'SELECT @cnt = COUNT(*) FROM Subject.tbSubject WHERE SubjectCode = @Code;',
		@UseWholeWords = 1,
		@Code = @ExternalRootCode OUTPUT;

	IF @ExternalRootCode IS NULL
		THROW 51005, 'DatasetSyntheticMIS: failed to generate SubjectCode for External root.', 1;

	IF NOT EXISTS (SELECT 1 FROM Subject.tbSubject WHERE SubjectCode = @ExternalRootCode)
	BEGIN
		INSERT INTO Subject.tbSubject
		(
			SubjectCode,
			SubjectName,
			SubjectTypeCode,
			SubjectStatusCode,
			TransmitStatusCode,
			TaxCode,
			AddressCode,
			AreaCode,
			PhoneNumber,
			EmailAddress
		)
		VALUES
		(
			@ExternalRootCode,
			N'External',
			10,
			1,
			0,
			N'N/A',
			NULL,
			NULL,
			NULL,
			NULL
		);

		INSERT INTO Subject.tbStructural
		(
			SubjectCode,
			Notes
		)
		VALUES
		(
			@ExternalRootCode,
			N'Dataset root for external trading partners'
		);
	END

	MERGE #DatasetCodes AS t
	USING
	(
		SELECT
			N'SUBJECT' AS CodeType,
			N'ExternalRoot' AS CodeName,
			@ExternalRootCode AS CodeValue,
			NULL AS RelatedName,
			N'External structural root' AS Notes
	) AS s
		ON t.CodeType = s.CodeType
		AND t.CodeName = s.CodeName
	WHEN NOT MATCHED THEN
		INSERT (CodeType, CodeName, CodeValue, RelatedName, Notes)
		VALUES (s.CodeType, s.CodeName, s.CodeValue, s.RelatedName, s.Notes)
	WHEN MATCHED THEN
		UPDATE SET
			CodeValue = s.CodeValue,
			RelatedName = s.RelatedName,
			Notes = s.Notes;

	DECLARE
		@ExistingMinYear smallint = (SELECT MIN(YearNumber) FROM App.tbYear),
		@ExistingStartMonth smallint = (SELECT TOP (1) StartMonth FROM App.tbYear WHERE YearNumber = (SELECT MIN(YearNumber) FROM App.tbYear)),
		@ExistingCompletedYearCount smallint = (SELECT COUNT(*) FROM App.tbYear WHERE CashStatusCode = 2),
		@PriorYear smallint;

	IF @ExistingMinYear IS NULL
		THROW 51003, 'DatasetSyntheticMIS: App.tbYear is empty after App.proc_BasicSetup.', 1;

	IF @ExistingStartMonth IS NULL
		SET @ExistingStartMonth = @FinancialMonth;

	-- App.proc_BasicSetup creates the ordinary current horizon. Extend only the
	-- closed historical edge required by the deterministic synthetic scenario.
	-- The default of two completed years preserves the original generator span.
	WHILE @ExistingCompletedYearCount < @CompletedYearCount
	BEGIN
		SET @PriorYear = @ExistingMinYear - 1;

		INSERT INTO App.tbYear (YearNumber, StartMonth, CashStatusCode, Description)
		VALUES
		(
			@PriorYear,
			@ExistingStartMonth,
			2,
			CASE WHEN @ExistingStartMonth > 1
				THEN CONCAT(@PriorYear, '-', @PriorYear - ROUND(@PriorYear, -2) + 1)
				ELSE CONCAT(@PriorYear, '.')
			END
		);

		UPDATE App.tbYear
		SET CashStatusCode = 0
		WHERE YearNumber = @PriorYear;

		EXEC Cash.proc_GeneratePeriods;

		UPDATE App.tbYearPeriod
		SET CashStatusCode = 2
		WHERE YearNumber = @PriorYear;

		UPDATE App.tbYear
		SET CashStatusCode = 2
		WHERE YearNumber = @PriorYear;

		SET @ExistingMinYear = @PriorYear;
		SET @ExistingCompletedYearCount += 1;
	END

    UPDATE App.tbYearPeriod
    SET BusinessTaxRate = 0.19;

	DECLARE
		@CurrentAccountCode nvarchar(10),
		@ReserveAccountCode nvarchar(10);

	SELECT @CurrentAccountCode = AccountCode FROM Cash.vwCurrentAccount;
	SELECT @ReserveAccountCode = AccountCode FROM Cash.vwReserveAccount;

	IF @CurrentAccountCode IS NULL
	BEGIN
		SET @CurrentAccountCode = N'DSCA01';

		IF NOT EXISTS (SELECT 1 FROM Subject.tbAccount WHERE AccountCode = @CurrentAccountCode)
		BEGIN
			INSERT INTO Subject.tbAccount (AccountCode, SubjectCode, AccountName, SortCode, AccountNumber, CashCode, OpeningBalance, CoinTypeCode, AccountTypeCode, LiquidityLevel)
			VALUES (@CurrentAccountCode, @NodeSubjectCode, N'Dataset Current Account', N'00-00-00', N'00000000',
					'CC-BANK', 0, @CoinTypeCode, 0, 0);
		END
	END

	IF @ReserveAccountCode IS NULL
	BEGIN
		SET @ReserveAccountCode = N'DSRA01';

		IF NOT EXISTS (SELECT 1 FROM Subject.tbAccount WHERE AccountCode = @ReserveAccountCode)
		BEGIN
			INSERT INTO Subject.tbAccount (AccountCode, SubjectCode, AccountName, SortCode, AccountNumber, CashCode, OpeningBalance, CoinTypeCode, AccountTypeCode, LiquidityLevel)
			VALUES (@ReserveAccountCode, @NodeSubjectCode, N'Dataset Reserve Account', N'00-00-00', N'00000000',
					NULL, 0, @CoinTypeCode, 0, 1);
		END
	END

	DECLARE
		@OpeningCurrentCash decimal(18,5) = (CASE @EnableOpeningBalance WHEN 1 THEN 25000.00000 ELSE 0 END),
		@OpeningReserveCash decimal(18,5) = (CASE @EnableOpeningBalance WHEN 1 THEN 10000.00000 ELSE 0 END);

	UPDATE Subject.tbAccount
	SET OpeningBalance = @OpeningCurrentCash
	WHERE AccountCode = (SELECT AccountCode FROM Cash.vwCurrentAccount);

	UPDATE Subject.tbAccount
	SET OpeningBalance = @OpeningReserveCash
	WHERE AccountCode = (SELECT AccountCode FROM Cash.vwReserveAccount);

	DECLARE
		@BuyerRootCode nvarchar(50) = NULL,
		@SellerRootCode nvarchar(50) = NULL,
		@StateRootCode nvarchar(50) = NULL;

	EXEC Subject.proc_AddNamespace
		@RootSubjectCode = @ExternalRootCode,
		@SubjectName = N'Buyer',
		@SubjectTypeCode = 10,
		@SubjectCode = @BuyerRootCode OUTPUT;

	EXEC Subject.proc_AddNamespace
		@RootSubjectCode = @ExternalRootCode,
		@SubjectName = N'Seller',
		@SubjectTypeCode = 10,
		@SubjectCode = @SellerRootCode OUTPUT;

	EXEC Subject.proc_AddNamespace
		@RootSubjectCode = @ExternalRootCode,
		@SubjectName = N'State',
		@SubjectTypeCode = 10,
		@SubjectCode = @StateRootCode OUTPUT;

	MERGE #DatasetCodes AS t
	USING
	(
		SELECT N'SUBJECT' AS CodeType, N'BuyerRoot' AS CodeName, @BuyerRootCode AS CodeValue, N'ExternalRoot' AS RelatedName, N'Buyer structural root' AS Notes
		UNION ALL
		SELECT N'SUBJECT', N'SellerRoot', @SellerRootCode, N'ExternalRoot', N'Seller structural root'
		UNION ALL
		SELECT N'SUBJECT', N'StateRoot', @StateRootCode, N'ExternalRoot', N'State structural root'
	) AS s
		ON t.CodeType = s.CodeType
		AND t.CodeName = s.CodeName
	WHEN NOT MATCHED THEN
		INSERT (CodeType, CodeName, CodeValue, RelatedName, Notes)
		VALUES (s.CodeType, s.CodeName, s.CodeValue, s.RelatedName, s.Notes)
	WHEN MATCHED THEN
		UPDATE SET
			CodeValue = s.CodeValue,
			RelatedName = s.RelatedName,
			Notes = s.Notes;
GO
PRINT N'Altering Procedure [App].[proc_DatasetSyntheticMIS_ProjectPay]...';


GO
ALTER   PROCEDURE App.proc_DatasetSyntheticMIS_ProjectPay
(
	@IsCompany bit,
	@IsVatRegistered bit
)
AS
	SET NOCOUNT, XACT_ABORT ON;

	IF OBJECT_ID('tempdb..#DatasetCodes') IS NULL
		THROW 51215, 'DatasetSyntheticMIS_ProjectPay: missing temp table #DatasetCodes. Ensure ProjectTran ran.', 1;

	DECLARE @LastClosedStartOn date =
		TRY_CONVERT(date, (SELECT CodeValue FROM #DatasetCodes WHERE CodeType = N'LINK' AND CodeName = N'LastClosedStartOn'));

	DECLARE @SettlementAccountCode nvarchar(10) =
		(SELECT CodeValue FROM #DatasetCodes WHERE CodeType = N'LINK' AND CodeName = N'SettlementAccountCode');

	IF @LastClosedStartOn IS NULL OR @SettlementAccountCode IS NULL
		THROW 51216, 'DatasetSyntheticMIS_ProjectPay: missing LINK/LastClosedStartOn or LINK/SettlementAccountCode.', 1;

	IF OBJECT_ID('tempdb..#Payables') IS NOT NULL DROP TABLE #Payables;

	SELECT DISTINCT i.SubjectCode
	INTO #Payables
	FROM Invoice.tbInvoice i;

	DECLARE
		@PayMonthStart date,
		@PayMonthEnd date,
		@PaySubjectCode nvarchar(50),
		@Balance float,
		@PaidOn date,
		@PaymentCode nvarchar(20),
		@PayPct decimal(9,6) = 0.80,
		@PayAmount decimal(18,5);

	DECLARE curPayMonths CURSOR LOCAL FAST_FORWARD FOR
		SELECT MonthStartOn, MonthEndOn
		FROM App.fnDatasetMonths(@LastClosedStartOn)
		ORDER BY MonthStartOn
		OPTION (MAXRECURSION 0);

	OPEN curPayMonths;
	FETCH NEXT FROM curPayMonths INTO @PayMonthStart, @PayMonthEnd;

	WHILE @@FETCH_STATUS = 0
	BEGIN
		SET @PaidOn = @PayMonthEnd;

		DECLARE curSubjects CURSOR LOCAL FAST_FORWARD FOR
			SELECT SubjectCode
			FROM #Payables
			ORDER BY SubjectCode;

		OPEN curSubjects;
		FETCH NEXT FROM curSubjects INTO @PaySubjectCode;

		WHILE @@FETCH_STATUS = 0
		BEGIN
			SELECT TOP (1) @Balance = COALESCE(Balance, 0)
			FROM Subject.vwStatement
			WHERE SubjectCode = @PaySubjectCode
				AND CAST(TransactedOn AS date) <= @PayMonthEnd
			ORDER BY TransactedOn DESC, RowNumber DESC;

			IF @Balance <> 0
			BEGIN
				SET @PayAmount =
					CAST(ROUND(ABS(CAST(@Balance AS decimal(18,5))) * @PayPct, 2) AS decimal(18,5));

				IF @PayAmount > 0
				BEGIN
					SET @PaymentCode = NULL;
					EXEC Cash.proc_NextPaymentCode @PaymentCode = @PaymentCode OUTPUT;

					INSERT INTO Cash.tbPayment
					(
						PaymentCode,
						UserId,
						PaymentStatusCode,
						SubjectCode,
						AccountCode,
						CashCode,
						TaxCode,
						PaidOn,
						PaidInValue,
						PaidOutValue,
						PaymentReference
					)
					SELECT
						@PaymentCode,
						(SELECT UserId FROM Usr.vwCredentials),
						0,
						@PaySubjectCode,
						@SettlementAccountCode,
						NULL,
						NULL,
						@PaidOn,
						CASE WHEN @Balance < 0 THEN @PayAmount ELSE CAST(0 AS decimal(18,5)) END,
						CASE WHEN @Balance > 0 THEN @PayAmount ELSE CAST(0 AS decimal(18,5)) END,
						CONCAT(N'DS SETTLE ', FORMAT(@PaidOn, 'yyyy-MM'), N' ', CAST(@PayPct * 100 AS int), N'%');

					EXEC Cash.proc_PaymentPost;
				END
			END

			FETCH NEXT FROM curSubjects INTO @PaySubjectCode;
		END

		CLOSE curSubjects;
		DEALLOCATE curSubjects;

		FETCH NEXT FROM curPayMonths INTO @PayMonthStart, @PayMonthEnd;
	END

	CLOSE curPayMonths;
	DEALLOCATE curPayMonths;
GO
PRINT N'Altering Procedure [App].[proc_DatasetSyntheticMIS_PayMisc]...';


GO
ALTER   PROCEDURE App.proc_DatasetSyntheticMIS_PayMisc
(
	@IsCompany bit,
	@IsVatRegistered bit
)
AS
	SET NOCOUNT, XACT_ABORT ON;

	IF OBJECT_ID('tempdb..#DatasetCodes') IS NULL
		THROW 51215, 'DatasetSyntheticMIS_ProjectPay: missing temp table #DatasetCodes. Ensure ProjectTran ran.', 1;

	DECLARE @LastClosedStartOn date =
		TRY_CONVERT(date, (SELECT CodeValue FROM #DatasetCodes WHERE CodeType = N'LINK' AND CodeName = N'LastClosedStartOn'));

	DECLARE @SettlementAccountCode nvarchar(10) =
		(SELECT CodeValue FROM #DatasetCodes WHERE CodeType = N'LINK' AND CodeName = N'SettlementAccountCode');

	IF @LastClosedStartOn IS NULL OR @SettlementAccountCode IS NULL
		THROW 51222, 'DatasetSyntheticMIS_PayMisc: missing LINK/LastClosedStartOn or LINK/SettlementAccountCode.', 1;

	DECLARE
		@L2_UserId nvarchar(10) = (SELECT TOP (1) UserId FROM Usr.vwCredentials),
		@L2_WalkInSubjectCode nvarchar(50) = (SELECT CodeValue FROM #DatasetCodes WHERE CodeType = N'SUBJECT' AND CodeName = N'MiscCustomer1'),
		@SellerRootCode nvarchar(50) = (SELECT CodeValue FROM #DatasetCodes WHERE CodeType = N'SUBJECT' AND CodeName = N'SellerRoot');

	IF @L2_WalkInSubjectCode IS NULL
		THROW 51101, 'SyntheticDataset Layer2: missing SUBJECT/MiscCustomer1 (walk-in) in #DatasetCodes.', 1;

	IF @SellerRootCode IS NULL
		THROW 51226, 'DatasetSyntheticMIS_PayMisc: missing SUBJECT/SellerRoot in #DatasetCodes.', 1;

	DECLARE @PayMiscTaxCode nvarchar(10) =
		CASE WHEN ISNULL(@IsVatRegistered, 0) <> 0 THEN N'T1' ELSE N'T0' END;

	DECLARE @EnergyCashCode nvarchar(50) =
		CASE
			WHEN EXISTS (SELECT 1 FROM Cash.tbCode WHERE CashCode = N'CC-UTILS' AND IsEnabled = 1)
			 AND (ISNULL(@IsVatRegistered, 0) = 0 OR EXISTS (SELECT 1 FROM App.vwTaxVatCashCodes WHERE CashCode = N'CC-UTILS')) THEN N'CC-UTILS'
			WHEN EXISTS (SELECT 1 FROM Cash.tbCode WHERE CashCode = N'CC-ADMIN' AND IsEnabled = 1)
			 AND (ISNULL(@IsVatRegistered, 0) = 0 OR EXISTS (SELECT 1 FROM App.vwTaxVatCashCodes WHERE CashCode = N'CC-ADMIN')) THEN N'CC-ADMIN'
		END;

	DECLARE @ProvisionsCashCode nvarchar(50) =
		CASE
			WHEN EXISTS (SELECT 1 FROM Cash.tbCode WHERE CashCode = N'CC-OTHER' AND IsEnabled = 1)
			 AND (ISNULL(@IsVatRegistered, 0) = 0 OR EXISTS (SELECT 1 FROM App.vwTaxVatCashCodes WHERE CashCode = N'CC-OTHER')) THEN N'CC-OTHER'
			WHEN EXISTS (SELECT 1 FROM Cash.tbCode WHERE CashCode = N'CC-ADMIN' AND IsEnabled = 1)
			 AND (ISNULL(@IsVatRegistered, 0) = 0 OR EXISTS (SELECT 1 FROM App.vwTaxVatCashCodes WHERE CashCode = N'CC-ADMIN')) THEN N'CC-ADMIN'
		END;

	IF @EnergyCashCode IS NULL OR @ProvisionsCashCode IS NULL
		THROW 51227, 'DatasetSyntheticMIS_PayMisc: no enabled VAT-compatible CashCode is available for energy or provisions.', 1;

	DECLARE
		@L2_EnergySupplierCode nvarchar(50) = NULL,
		@L2_SupermarketSupplierCode nvarchar(50) = NULL;

	EXEC Subject.proc_AddNamespace
		@RootSubjectCode = @SellerRootCode,
		@SubjectName = N'Dataset Energy Supplier',
		@SubjectTypeCode = 0,
		@SubjectCode = @L2_EnergySupplierCode OUTPUT;

	UPDATE Subject.tbSubject
	SET
		SubjectStatusCode = 1,
		TaxCode = N'T1',
		ExportTypeCode = 0,
		PaymentTerms = N'30 days',
		ExpectedDays = 0,
		PaymentDays = 30,
		PayDaysFromMonthEnd = 0,
		PayBalance = 1
	WHERE SubjectCode = @L2_EnergySupplierCode;

	EXEC Subject.proc_AddNamespace
		@RootSubjectCode = @SellerRootCode,
		@SubjectName = N'Dataset Supermarket',
		@SubjectTypeCode = 0,
		@SubjectCode = @L2_SupermarketSupplierCode OUTPUT;

	UPDATE Subject.tbSubject
	SET
		SubjectStatusCode = 1,
		TaxCode = N'T1',
		ExportTypeCode = 0,
		PaymentTerms = N'30 days',
		ExpectedDays = 0,
		PaymentDays = 30,
		PayDaysFromMonthEnd = 0,
		PayBalance = 1
	WHERE SubjectCode = @L2_SupermarketSupplierCode;

	DECLARE
		@L2_MonthStart date,
		@L2_MonthEnd date,
		@L2_MonthIndex int,
		@L2_PaymentCode nvarchar(20),
		@L2_Amount decimal(18, 5);

	DECLARE curL2Months CURSOR LOCAL FAST_FORWARD FOR
		SELECT MonthStartOn, MonthEndOn, MonthIndex
		FROM App.fnDatasetMonths(@LastClosedStartOn)
		ORDER BY MonthStartOn
		OPTION (MAXRECURSION 0);

	OPEN curL2Months;
	FETCH NEXT FROM curL2Months INTO @L2_MonthStart, @L2_MonthEnd, @L2_MonthIndex;

	WHILE @@FETCH_STATUS = 0
	BEGIN
		IF (@L2_MonthIndex % 3) = 0
		BEGIN
			SET @L2_Amount = CAST(250 + (ABS(CHECKSUM(CONCAT(N'DS:L2:ENERGY:', @L2_MonthIndex))) % 750) AS decimal(18,5));

			SET @L2_PaymentCode = NULL;
			EXEC Cash.proc_NextPaymentCode @PaymentCode = @L2_PaymentCode OUTPUT;

			INSERT INTO Cash.tbPayment
			(
				PaymentCode, UserId, PaymentStatusCode,
				SubjectCode, AccountCode,
				CashCode, TaxCode,
				PaidOn, PaidInValue, PaidOutValue,
				PaymentReference
			)
			VALUES
			(
				@L2_PaymentCode, @L2_UserId, 0,
				@L2_EnergySupplierCode, @SettlementAccountCode,
				@EnergyCashCode, @PayMiscTaxCode,
				@L2_MonthEnd, 0, @L2_Amount,
				N'Electricity Charge'
			);

			EXEC Cash.proc_PaymentPost;
		END

		SET @L2_Amount = CAST(60 + (ABS(CHECKSUM(CONCAT(N'DS:L2:PROV:', @L2_MonthIndex))) % 140) AS decimal(18,5));

		SET @L2_PaymentCode = NULL;
		EXEC Cash.proc_NextPaymentCode @PaymentCode = @L2_PaymentCode OUTPUT;

		INSERT INTO Cash.tbPayment
		(
			PaymentCode, UserId, PaymentStatusCode,
			SubjectCode, AccountCode,
			CashCode, TaxCode,
			PaidOn, PaidInValue, PaidOutValue,
			PaymentReference
		)
		VALUES
		(
			@L2_PaymentCode, @L2_UserId, 0,
			@L2_SupermarketSupplierCode, @SettlementAccountCode,
			@ProvisionsCashCode, @PayMiscTaxCode,
			@L2_MonthEnd, 0, @L2_Amount,
			N'Provisions'
		);

		EXEC Cash.proc_PaymentPost;

		SET @L2_Amount = CAST(25 + (ABS(CHECKSUM(CONCAT(N'DS:L2:WALKIN:', @L2_MonthIndex))) % 125) AS decimal(18,5));

		SET @L2_PaymentCode = NULL;
		EXEC Cash.proc_NextPaymentCode @PaymentCode = @L2_PaymentCode OUTPUT;

		INSERT INTO Cash.tbPayment
		(
			PaymentCode, UserId, PaymentStatusCode,
			SubjectCode, AccountCode,
			CashCode, TaxCode,
			PaidOn, PaidInValue, PaidOutValue,
			PaymentReference
		)
		VALUES
		(
			@L2_PaymentCode, @L2_UserId, 0,
			@L2_WalkInSubjectCode, @SettlementAccountCode,
			N'CC-INCME', @PayMiscTaxCode,
			@L2_MonthEnd, @L2_Amount, 0,
			N'Widget Purchase'
		);

		EXEC Cash.proc_PaymentPost;

		FETCH NEXT FROM curL2Months INTO @L2_MonthStart, @L2_MonthEnd, @L2_MonthIndex;
	END

	CLOSE curL2Months;
	DEALLOCATE curL2Months;
GO
PRINT N'Altering Procedure [App].[proc_DatasetSyntheticMIS_PayWages]...';


GO
ALTER   PROCEDURE App.proc_DatasetSyntheticMIS_PayWages
(
	@IsCompany bit,
	@IsVatRegistered bit
)
AS
	SET NOCOUNT, XACT_ABORT ON;

	IF OBJECT_ID('tempdb..#DatasetCodes') IS NULL
		THROW 51215, 'DatasetSyntheticMIS_ProjectPay: missing temp table #DatasetCodes. Ensure ProjectTran ran.', 1;

	DECLARE @LastClosedStartOn date =
		TRY_CONVERT(date, (SELECT CodeValue FROM #DatasetCodes WHERE CodeType = N'LINK' AND CodeName = N'LastClosedStartOn'));

	DECLARE @SettlementAccountCode nvarchar(10) =
		(SELECT CodeValue FROM #DatasetCodes WHERE CodeType = N'LINK' AND CodeName = N'SettlementAccountCode');

	IF @LastClosedStartOn IS NULL OR @SettlementAccountCode IS NULL
		THROW 51231, 'DatasetSyntheticMIS_PayWages: missing LINK/LastClosedStartOn or LINK/SettlementAccountCode.', 1;

	DECLARE
		@L2_UserId nvarchar(10) = (SELECT TOP (1) UserId FROM Usr.vwCredentials),
		@L2_EmployeeSubjectCode nvarchar(50) = (SELECT CodeValue FROM #DatasetCodes WHERE CodeType = N'SUBJECT' AND CodeName = N'Employee');

	IF @L2_EmployeeSubjectCode IS NULL
		THROW 51100, 'SyntheticDataset Layer2: missing SUBJECT/Employee in #DatasetCodes.', 1;

	-----------------------------------------------------------------
	-- Loop closed months and create wages + NI
	-----------------------------------------------------------------
	DECLARE
		@L2_MonthStart date,
		@L2_MonthEnd date,
		@L2_MonthIndex int,
		@L2_PaymentCode nvarchar(20),
		@L2_Amount decimal(18, 5);

	DECLARE curL2Months CURSOR LOCAL FAST_FORWARD FOR
		SELECT MonthStartOn, MonthEndOn, MonthIndex
		FROM App.fnDatasetMonths(@LastClosedStartOn)
		ORDER BY MonthStartOn
		OPTION (MAXRECURSION 0);

	OPEN curL2Months;
	FETCH NEXT FROM curL2Months INTO @L2_MonthStart, @L2_MonthEnd, @L2_MonthIndex;

	WHILE @@FETCH_STATUS = 0
	BEGIN
		-- Wages A
		SET @L2_Amount = CAST(1200 + (ABS(CHECKSUM(CONCAT(N'DS:L2:WAGEA:', @L2_MonthIndex))) % 250) AS decimal(18,5));

		SET @L2_PaymentCode = NULL;
		EXEC Cash.proc_NextPaymentCode @PaymentCode = @L2_PaymentCode OUTPUT;

		INSERT INTO Cash.tbPayment
		(
			PaymentCode, UserId, PaymentStatusCode,
			SubjectCode, AccountCode,
			CashCode, TaxCode,
			PaidOn, PaidInValue, PaidOutValue,
			PaymentReference
		)
		VALUES
		(
			@L2_PaymentCode, @L2_UserId, 0,
			@L2_EmployeeSubjectCode, @SettlementAccountCode,
			N'CC-WAGES', N'N/A',
			@L2_MonthEnd, 0, @L2_Amount,
			N'Wages'
		);

		EXEC Cash.proc_PaymentPost;

		-- Wages B
		SET @L2_Amount = CAST(950 + (ABS(CHECKSUM(CONCAT(N'DS:L2:WAGEB:', @L2_MonthIndex))) % 250) AS decimal(18,5));

		SET @L2_PaymentCode = NULL;
		EXEC Cash.proc_NextPaymentCode @PaymentCode = @L2_PaymentCode OUTPUT;

		INSERT INTO Cash.tbPayment
		(
			PaymentCode, UserId, PaymentStatusCode,
			SubjectCode, AccountCode,
			CashCode, TaxCode,
			PaidOn, PaidInValue, PaidOutValue,
			PaymentReference
		)
		VALUES
		(
			@L2_PaymentCode, @L2_UserId, 0,
			@L2_EmployeeSubjectCode, @SettlementAccountCode,
			N'CC-WAGES', N'N/A',
			@L2_MonthEnd, 0, @L2_Amount,
			N'Wages'
		);

		EXEC Cash.proc_PaymentPost;

		-- NI (10% of wages this month)
		DECLARE @L2_WagesMonthTotal decimal(18,5) =
		(
			SELECT SUM(p.PaidOutValue)
			FROM Cash.tbPayment p
			WHERE p.SubjectCode = @L2_EmployeeSubjectCode
				AND p.CashCode = N'CC-WAGES'
				AND CAST(p.PaidOn AS date) = @L2_MonthEnd
		);

		DECLARE @HMRC_NI_Account nvarchar(50), @HMRC_NI_CashCode nvarchar(50);
		SELECT @HMRC_NI_Account = SubjectCode, @HMRC_NI_CashCode = CashCode
		FROM Cash.tbTaxType
		WHERE TaxTypeCode = 2;

		SET @L2_Amount = CAST(ROUND(COALESCE(@L2_WagesMonthTotal, 0) * 0.10, 2) AS decimal(18,5));

		IF @L2_Amount > 0
		BEGIN
			SET @L2_PaymentCode = NULL;
			EXEC Cash.proc_NextPaymentCode @PaymentCode = @L2_PaymentCode OUTPUT;

			INSERT INTO Cash.tbPayment
			(
				PaymentCode, UserId, PaymentStatusCode,
				SubjectCode, AccountCode,
				CashCode, TaxCode,
				PaidOn, PaidInValue, PaidOutValue,
				PaymentReference
			)
			VALUES
			(
				@L2_PaymentCode, @L2_UserId, 0,
				@HMRC_NI_Account, @SettlementAccountCode,
				@HMRC_NI_CashCode, N'N/A',
				@L2_MonthEnd, 0, @L2_Amount,
				N'Employee NI'
			);

			EXEC Cash.proc_PaymentPost;
		END

		FETCH NEXT FROM curL2Months INTO @L2_MonthStart, @L2_MonthEnd, @L2_MonthIndex;
	END

	CLOSE curL2Months;
	DEALLOCATE curL2Months;
GO
PRINT N'Altering Procedure [App].[proc_DatasetSyntheticMIS_Expenses]...';


GO
ALTER   PROCEDURE App.proc_DatasetSyntheticMIS_Expenses
(
	@IsCompany bit,
	@IsVatRegistered bit
)
AS
	SET NOCOUNT, XACT_ABORT ON;

	IF OBJECT_ID('tempdb..#DatasetCodes') IS NULL
		THROW 51215, 'DatasetSyntheticMIS_ProjectPay: missing temp table #DatasetCodes. Ensure ProjectTran ran.', 1;

	DECLARE @LastClosedStartOn date =
		TRY_CONVERT(date, (SELECT CodeValue FROM #DatasetCodes WHERE CodeType = N'LINK' AND CodeName = N'LastClosedStartOn'));

	IF @LastClosedStartOn IS NULL
		THROW 51241, 'DatasetSyntheticMIS_Expenses: missing LINK/LastClosedStartOn.', 1;

	-----------------------------------------------------------------
	-- Ensure Category + CashCode for Employee Expenses
	-----------------------------------------------------------------

	IF NOT EXISTS (SELECT 1 FROM Cash.tbCode WHERE CashCode = N'CC-EXPENSE')
	BEGIN
		INSERT INTO Cash.tbCode
		(
			CashCode,
			CashDescription,
			CategoryCode,
			TaxCode,
			IsEnabled
		)
		VALUES
		(
			N'CC-EXPENSE',
			N'Employee Expenses',
			N'CA-ADMIN',
			N'T0',
			1
		);
	END

	IF NOT EXISTS (SELECT 1 FROM Object.tbObject WHERE ObjectCode = 'EXPENSE')
	BEGIN
		INSERT INTO Object.tbObject
		(
			ObjectCode,
			ProjectStatusCode,
			UnitOfMeasure,
			CashCode,
			Printed,
			RegisterName,
			ObjectDescription,
			UnitCharge
		)
		VALUES
		(
			'EXPENSE',
			1,
			'each',
			'CC-EXPENSE',
			1,
			'Purchase Order',
			'Employee Expense Claim',
			0
		);
	END

	-----------------------------------------------------------------
	-- Resolve subjects
	-----------------------------------------------------------------
	DECLARE
		@L2_UserId nvarchar(10) = (SELECT TOP (1) UserId FROM Usr.vwCredentials),
		@L2_EmployeeSubjectCode nvarchar(50) = (SELECT CodeValue FROM #DatasetCodes WHERE CodeType = N'SUBJECT' AND CodeName = N'Employee');

	IF @L2_EmployeeSubjectCode IS NULL
		THROW 51100, 'SyntheticDataset Layer2: missing SUBJECT/Employee in #DatasetCodes.', 1;

	-----------------------------------------------------------------
	-- Employee Expenses: container project + monthly claim child projects
	-----------------------------------------------------------------
	DECLARE
		@L2_ClaimsContainerProjectCode nvarchar(20) = NULL,
		@L2_ClaimsChildProjectCode nvarchar(20) = NULL,
		@L2_ClaimPaymentCode nvarchar(20) = NULL,
		@L2_ClaimsMonthEnd date,
		@L2_ClaimsMonthIndex int,
		@ObjectCode nvarchar(50);

	-- Container
	SET @ObjectCode = 'PROJECT';
	EXEC Project.proc_NextCode @ObjectCode = @ObjectCode, @ProjectCode = @L2_ClaimsContainerProjectCode OUTPUT;

	IF @L2_ClaimsContainerProjectCode IS NULL
		THROW 51110, 'SyntheticDataset Layer2: Project.proc_NextCode returned NULL.', 1;

	IF NOT EXISTS (SELECT 1 FROM Project.tbProject WHERE ProjectCode = @L2_ClaimsContainerProjectCode)
	BEGIN
		INSERT INTO Project.tbProject
		(
			ProjectCode,
			UserId,
			SubjectCode,
			ProjectTitle,
			ObjectCode,
			ProjectStatusCode,
			ActionById,
			ActionOn,
			Quantity,
			CashCode,
			TaxCode,
			UnitCharge,
			TotalCharge
		)
		VALUES
		(
			@L2_ClaimsContainerProjectCode,
			@L2_UserId,
			@L2_EmployeeSubjectCode,
			N'John Smith''s Expense Claims',
			@ObjectCode,
			0,
			@L2_UserId,
			EOMONTH(@LastClosedStartOn),
			0,
			NULL,
			NULL,
			0,
			0
		);
	END

	-- One claim per closed month
	DECLARE curClaims CURSOR LOCAL FAST_FORWARD FOR
		SELECT MonthEndOn, MonthIndex
		FROM App.fnDatasetMonths(@LastClosedStartOn)
		ORDER BY MonthStartOn
		OPTION (MAXRECURSION 0);

	OPEN curClaims;
	FETCH NEXT FROM curClaims INTO @L2_ClaimsMonthEnd, @L2_ClaimsMonthIndex;

	WHILE @@FETCH_STATUS = 0
	BEGIN
		DECLARE @ClaimCashCode nvarchar(50) = N'CC-EXPENSE';

		-- Exercise the richer standard-company accounting classifications when
		-- they exist. MIN and non-company profiles retain the generic fallback.
		IF @IsCompany = 1
		BEGIN
			DECLARE @StdClaimCandidate nvarchar(50) =
				CASE (@L2_ClaimsMonthIndex % 4)
					WHEN 0 THEN N'CC-TRAV'
					WHEN 1 THEN N'CC-PHONE'
					WHEN 2 THEN N'CC-PROF'
					ELSE N'CC-REPA'
				END;

			IF EXISTS (SELECT 1 FROM Cash.tbCode WHERE CashCode = @StdClaimCandidate AND IsEnabled = 1)
				SET @ClaimCashCode = @StdClaimCandidate;
		END

		SET @ObjectCode = 'EXPENSE';
		EXEC Project.proc_NextCode @ObjectCode = @ObjectCode, @ProjectCode = @L2_ClaimsChildProjectCode OUTPUT;

		IF @L2_ClaimsChildProjectCode IS NULL
			THROW 51111, 'SyntheticDataset Layer2: Project.proc_NextCode returned NULL for claim child project.', 1;

		INSERT INTO Project.tbProject
		(
			ProjectCode,
			UserId,
			SubjectCode,
			ProjectTitle,
			ObjectCode,
			ProjectStatusCode,
			ActionById,
			ActionOn,
			Quantity,
			CashCode,
			TaxCode,
			UnitCharge,
			TotalCharge
		)
		VALUES
		(
			@L2_ClaimsChildProjectCode,
			@L2_UserId,
			@L2_EmployeeSubjectCode,
			CASE @ClaimCashCode
				WHEN N'CC-TRAV' THEN N'Travel and subsistence'
				WHEN N'CC-PHONE' THEN N'Telephone and internet'
				WHEN N'CC-PROF' THEN N'Professional fees'
				WHEN N'CC-REPA' THEN N'Repairs and maintenance'
				ELSE CASE WHEN (@L2_ClaimsMonthIndex % 2) = 0 THEN N'Travel Costs' ELSE N'Entertainment' END
			END,
			@ObjectCode,
			0,
			@L2_UserId,
			@L2_ClaimsMonthEnd,
			1,
			@ClaimCashCode,
			N'T0',
			CAST(25 + (ABS(CHECKSUM(CONCAT(N'DS:L2:CLAIM:', @L2_ClaimsMonthIndex))) % 175) AS decimal(18,7)),
			0
		);

		EXEC Project.proc_AssignToParent
			@ChildProjectCode = @L2_ClaimsChildProjectCode,
			@ParentProjectCode = @L2_ClaimsContainerProjectCode;

		SET @L2_ClaimPaymentCode = NULL;
		EXEC Project.proc_Pay
			@ProjectCode = @L2_ClaimsChildProjectCode,
			@Post = 1,
			@PaymentCode = @L2_ClaimPaymentCode OUTPUT;

		FETCH NEXT FROM curClaims INTO @L2_ClaimsMonthEnd, @L2_ClaimsMonthIndex;
	END

	CLOSE curClaims;
	DEALLOCATE curClaims;
GO
PRINT N'Altering Procedure [App].[proc_Template_CO_MICRO_CUR_MIN_2026]...';


GO
ALTER PROCEDURE App.proc_Template_CO_MICRO_CUR_MIN_2026
(
    @FinancialMonth SMALLINT = 4,
    @GovAccountName NVARCHAR(255),
    @BankName NVARCHAR(255) = NULL,
    @BankAddress NVARCHAR(MAX) = NULL,
    @DummyAccount NVARCHAR(50),
    @CurrentAccount NVARCHAR(50) = NULL,
    @CA_SortCode NVARCHAR(10) = NULL,
    @CA_AccountNumber NVARCHAR(20) = NULL,
    @ReserveAccount NVARCHAR(50) = NULL,
    @RA_SortCode NVARCHAR(10) = NULL,
    @RA_AccountNumber NVARCHAR(20) = NULL,
    @IsVATRegistered BIT = 1      -- Micro entity default to VAT Registered
)
AS
    SET NOCOUNT, XACT_ABORT ON;

    BEGIN TRY

        BEGIN TRAN MicroMinTemplate;

        EXEC [App].[proc_Template_CO_MICRO_CUR_2026]
             @FinancialMonth   = @FinancialMonth,
             @GovAccountName   = @GovAccountName,
             @BankName         = @BankName,
             @BankAddress      = @BankAddress,
             @DummyAccount     = @DummyAccount,
             @CurrentAccount   = @CurrentAccount,
             @CA_SortCode      = @CA_SortCode,
             @CA_AccountNumber = @CA_AccountNumber,
             @ReserveAccount   = @ReserveAccount,
             @RA_SortCode      = @RA_SortCode,
             @RA_AccountNumber = @RA_AccountNumber;

        -- MIN-specific deltas

        ----------------------------------------------------------------
        -- 1. EXPRESSION CATEGORIES (CategoryTypeCode = 2)
        ----------------------------------------------------------------
        INSERT INTO Cash.tbCategory
            (CategoryCode, Category, CategoryTypeCode, CashPolarityCode, CashTypeCode, DisplayOrder, IsEnabled)
        VALUES
            ('CE-CO', 'Cash Operating Surplus %', 2, 2, 0, 10, 1);

        INSERT INTO Cash.tbCategoryExp
            (CategoryCode, Expression, Format, SyntaxTypeCode, IsError, ErrorMessage)
        VALUES
            ('CE-CO', 'IF([CA-SALES]=0,0,(([CA-SALES]+[CT-OTHRIN]-[CA-DIRECT]-[CA-WAGES]-[CA-ADMIN])/[CA-SALES]))', 'Pct0', 0, 0, NULL);

        ----------------------------------------------------------------
        -- 2. VAT handling for non‑registered businesses
        ----------------------------------------------------------------
        IF @IsVATRegistered = 0
            EXEC App.proc_Template_DisableVAT;

        ----------------------------------------------------------------
        -- 3. Enable Asset Accounts
        ----------------------------------------------------------------
        UPDATE Subject.tbAccount
        SET AccountClosed = 0
        WHERE AccountClosed = 1;

        ----------------------------------------------------------------
        -- 4. Company statutory projection (separate from accounting bootstrap)
        ----------------------------------------------------------------
        EXEC App.proc_Template_CO_MICRO_CUR_TAX_2026;

        EXEC Cash.proc_TaxTagMapValidate @TaxSourceCode = 'UK-CO-ACCTS-2026';
        EXEC Cash.proc_TaxTagMapValidate @TaxSourceCode = 'UK-CO-CT-2026';
        EXEC Cash.proc_TaxTagMapValidate @TaxSourceCode = 'UK-CO-CT600-2026';

        COMMIT TRAN MicroMinTemplate;

    END TRY
    BEGIN CATCH
        EXEC App.proc_ErrorLog;
    END CATCH;
GO
PRINT N'Altering Procedure [App].[proc_DatasetCreateProjectTemplate]...';


GO
ALTER PROCEDURE App.proc_DatasetCreateProjectTemplate
(
	@ParentProjectCode nvarchar(20) OUTPUT,          -- container; created if null/empty
	@ParentProjectTitle nvarchar(100) = NULL,        -- defaults if container created
	@CustomerSubjectCode nvarchar(50),               -- customer for the sales/service project
	@ObjectCode nvarchar(50),                        -- the FG/service object being sold
	@ActionOn date,                                  -- dead-year date
	@Quantity decimal(18,4) = 100,

	@PriceRatio decimal(18,7) = 1.0000000,           -- adjust selling price (profit/loss lever)

	@BoxSupplierSubjectCode nvarchar(50) = NULL,
	@PlasticSupplierSubjectCode nvarchar(50) = NULL,
	@InsertSupplierSubjectCode nvarchar(50) = NULL,
	@MouldingHaulierSubjectCode nvarchar(50) = NULL,
	@PrinterSubjectCode nvarchar(50) = NULL,
	@PrintHaulierSubjectCode nvarchar(50) = NULL,

	@ProjectCode nvarchar(20) OUTPUT                 -- master/template project created
)
AS
	SET NOCOUNT, XACT_ABORT ON;

	BEGIN TRY
		IF NOT EXISTS (SELECT 1 FROM Usr.vwCredentials WHERE IsAdministrator <> 0)
		BEGIN
			DECLARE @Msg nvarchar(100) = CONCAT('Access Denied: User ', Usr.fnUserName(), ' is not an administrsator');
			RAISERROR ('%s', 13, 1, @Msg);
		END

		IF @PriceRatio IS NULL OR @PriceRatio <= 0
			THROW 51031, 'Dataset: @PriceRatio must be > 0.', 1;

		DECLARE
			@UserId nvarchar(10) = (SELECT UserId FROM Usr.vwCredentials),
			@DefaultSubjectCode nvarchar(50) = (SELECT TOP (1) SubjectCode FROM App.tbOptions),
			@ObjectDescription nvarchar(100),
			@ObjectCashCode nvarchar(50),
			@ObjectUnitCharge decimal(18,7),
			@ObjectPrinted bit;

		SELECT
			@ObjectDescription = o.ObjectDescription,
			@ObjectCashCode = o.CashCode,
			@ObjectUnitCharge = o.UnitCharge,
			@ObjectPrinted = o.Printed
		FROM Object.tbObject o
		WHERE o.ObjectCode = @ObjectCode;

		IF @ObjectDescription IS NULL
			THROW 51030, 'Dataset: @ObjectCode not found in Object.tbObject.', 1;

		-----------------------------------------------------------------
		-- Ensure container parent project
		-----------------------------------------------------------------
		IF ISNULL(@ParentProjectCode, N'') = N''
		BEGIN
			EXEC Project.proc_NextCode N'PROJECT', @ParentProjectCode OUTPUT;

			INSERT INTO Project.tbProject
			(
				ProjectCode,
				UserId,
				SubjectCode,
				ProjectTitle,
				ObjectCode,
				ProjectStatusCode,
				ActionById,
				ActionOn,
				ActionedOn
			)
			VALUES
			(
				@ParentProjectCode,
				@UserId,
				@CustomerSubjectCode,
				ISNULL(@ParentProjectTitle, CONCAT(N'Dataset Container ', @CustomerSubjectCode)),
				N'PROJECT',
				0,
				@UserId,
				@ActionOn,
				@ActionOn
			);
		END

		-----------------------------------------------------------------
		-- Create template/master project for the object
		-----------------------------------------------------------------
		EXEC Project.proc_NextCode @ObjectCode, @ProjectCode OUTPUT;

		INSERT INTO Project.tbProject
		(
			ProjectCode,
			UserId,
			SubjectCode,
			ProjectTitle,
			ContactName,
			ObjectCode,
			ProjectStatusCode,
			ActionById,
			ActionOn,
			ActionedOn,
			ProjectNotes,
			Quantity,
			CashCode,
			TaxCode,
			UnitCharge,
			TotalCharge,
			AddressCodeFrom,
			AddressCodeTo,
			Printed
		)
		SELECT
			@ProjectCode,
			@UserId,
			@CustomerSubjectCode,
			@ObjectDescription,
			dc.ContactName,
			@ObjectCode,
			1,
			@UserId,
			@ActionOn,
			@ActionOn,
			@ObjectDescription,
			@Quantity,
			@ObjectCashCode,
			s.TaxCode,
			CAST(ROUND(@ObjectUnitCharge * @PriceRatio, 2) AS decimal(18,7)),
			CAST(ROUND(@ObjectUnitCharge * @PriceRatio, 2) AS decimal(18,7)) * @Quantity,
			s.AddressCode,
			s.AddressCode,
			CASE WHEN @ObjectPrinted = 0 THEN 1 ELSE 0 END
		FROM Subject.tbSubject s
		OUTER APPLY
		(
			SELECT TOP (1)
				c.SubjectName AS ContactName
			FROM Subject.tbNamespace n
			JOIN Subject.tbSubject c
				ON c.SubjectCode = n.ChildSubjectCode
			JOIN Subject.tbType t
				ON t.SubjectTypeCode = c.SubjectTypeCode
			WHERE n.ParentSubjectCode = s.SubjectCode
			  AND n.IsDefault <> 0
			  AND t.SubjectClassCode = 1
			ORDER BY n.Ordinal
		) dc
		WHERE s.SubjectCode = @CustomerSubjectCode;

		EXEC Project.proc_Configure @ProjectCode;
		EXEC Project.proc_AssignToParent @ProjectCode, @ParentProjectCode;

		-----------------------------------------------------------------
		-- Normalize suppliers for exploded child projects (dataset object codes)
		-----------------------------------------------------------------
		-- Boxes + pallets (purchase orders)
		IF @BoxSupplierSubjectCode IS NOT NULL
		BEGIN
			UPDATE p
			SET
				p.SubjectCode = @BoxSupplierSubjectCode,
				p.AddressCodeFrom = s.AddressCode,
				p.AddressCodeTo = s.AddressCode
			FROM Project.tbProject p
			JOIN Subject.tbSubject s ON s.SubjectCode = @BoxSupplierSubjectCode
			WHERE p.ProjectTitle = (SELECT ProjectTitle FROM Project.tbProject WHERE ProjectCode = @ProjectCode)
			  AND p.ObjectCode LIKE N'DS/PRD/CMP/BOX/%';
		END

		-- Plastic material
		IF @PlasticSupplierSubjectCode IS NOT NULL
		BEGIN
			UPDATE p
			SET
				p.SubjectCode = @PlasticSupplierSubjectCode,
				p.AddressCodeFrom = s.AddressCode,
				p.AddressCodeTo = s.AddressCode
			FROM Project.tbProject p
			JOIN Subject.tbSubject s ON s.SubjectCode = @PlasticSupplierSubjectCode
			WHERE p.ProjectTitle = (SELECT ProjectTitle FROM Project.tbProject WHERE ProjectCode = @ProjectCode)
			  AND p.ObjectCode LIKE N'DS/PRD/MTR/%';
		END

		-- Inserts
		IF @InsertSupplierSubjectCode IS NOT NULL
		BEGIN
			UPDATE p
			SET
				p.SubjectCode = @InsertSupplierSubjectCode,
				p.AddressCodeFrom = s.AddressCode,
				p.AddressCodeTo = s.AddressCode
			FROM Project.tbProject p
			JOIN Subject.tbSubject s ON s.SubjectCode = @InsertSupplierSubjectCode
			WHERE p.ProjectTitle = (SELECT ProjectTitle FROM Project.tbProject WHERE ProjectCode = @ProjectCode)
			  AND p.ObjectCode LIKE N'DS/PRD/CMP/INS/%';
		END

		-- Delivery: choose print vs moulding haulier based on object family
		IF @ObjectCode LIKE N'DS/PRD/FG/%'
		BEGIN
			IF @MouldingHaulierSubjectCode IS NOT NULL
			BEGIN
				UPDATE p
				SET
					p.SubjectCode = @MouldingHaulierSubjectCode,
					p.AddressCodeFrom = (SELECT TOP (1) AddressCode FROM Subject.tbSubject WHERE SubjectCode = @DefaultSubjectCode),
					p.AddressCodeTo = (SELECT TOP (1) AddressCode FROM Subject.tbSubject WHERE SubjectCode = @CustomerSubjectCode)
				FROM Project.tbProject p
				WHERE p.ProjectTitle = (SELECT ProjectTitle FROM Project.tbProject WHERE ProjectCode = @ProjectCode)
				  AND p.ObjectCode LIKE N'DS/SRV/SHP/DELIVERY/%';
			END
		END
		ELSE
		BEGIN
			IF @PrintHaulierSubjectCode IS NOT NULL
			BEGIN
				UPDATE p
				SET
					p.SubjectCode = @PrintHaulierSubjectCode,
					p.AddressCodeFrom = (SELECT TOP (1) AddressCode FROM Subject.tbSubject WHERE SubjectCode = @DefaultSubjectCode),
					p.AddressCodeTo = (SELECT TOP (1) AddressCode FROM Subject.tbSubject WHERE SubjectCode = @CustomerSubjectCode)
				FROM Project.tbProject p
				WHERE p.ProjectTitle = (SELECT ProjectTitle FROM Project.tbProject WHERE ProjectCode = @ProjectCode)
				  AND p.ObjectCode LIKE N'DS/SRV/SHP/DELIVERY/%';
			END
		END

		-- Ensure internal works orders stay on node subject (as DemoBom does)
		UPDATE p
		SET
			p.SubjectCode = @DefaultSubjectCode,
			p.AddressCodeFrom = s.AddressCode,
			p.AddressCodeTo = s.AddressCode
		FROM Project.tbProject p
		JOIN Subject.tbSubject s ON s.SubjectCode = @DefaultSubjectCode
		WHERE p.ProjectTitle = (SELECT ProjectTitle FROM Project.tbProject WHERE ProjectCode = @ProjectCode)
		  AND p.CashCode IS NULL
		  AND p.SubjectCode <> @BoxSupplierSubjectCode;

		-----------------------------------------------------------------
		-- Resolve ContactName from the default real child of the final Subject
		-----------------------------------------------------------------
		UPDATE p
		SET ContactName = dc.ContactName
		FROM Project.tbProject p
		OUTER APPLY
		(
			SELECT TOP (1)
				c.SubjectName AS ContactName
			FROM Subject.tbNamespace n
			JOIN Subject.tbSubject c
				ON c.SubjectCode = n.ChildSubjectCode
			JOIN Subject.tbType t
				ON t.SubjectTypeCode = c.SubjectTypeCode
			WHERE n.ParentSubjectCode = p.SubjectCode
			  AND n.IsDefault <> 0
			  AND t.SubjectClassCode = 1
			ORDER BY n.Ordinal
		) dc
		WHERE p.ProjectTitle = (SELECT ProjectTitle FROM Project.tbProject WHERE ProjectCode = @ProjectCode);

		EXEC Project.proc_Schedule @ProjectCode;

	END TRY
	BEGIN CATCH
		EXEC App.proc_ErrorLog;
	END CATCH
GO
PRINT N'Altering Procedure [App].[proc_DatasetSyntheticMIS]...';


GO
ALTER PROCEDURE App.proc_DatasetSyntheticMIS
(
	@IsCompany bit = 1,
	@IsVatRegistered bit = NULL,

	@MisOrdersPerMonth int = 2,
	@MonthsForward int = 3,    

    -- ratios
    @PriceRatio decimal(18,7) = 1.0000000,
    @QuantityRatio decimal(18,7) = 1.0000000,
	@FloatRatio decimal(18,7) = 0.25,

	-- execution switches
	@EnableProjects bit = 1,
	@EnableInvoices bit = 1,
	@EnableProjectPayments bit = 1,
	@EnablePayables bit = 1,
	@EnableMiscPayments bit = 1,
	@EnableWages bit = 1,
	@EnableExpenses bit = 1,
    @EnableAssets bit = 1,
    @EnableTax bit = 1,
	@EnableTransfers bit = 1,
    @EnableOpeningBalance bit = 0,

	@UseStdCompanyTemplate bit = 0,
	@CompletedYearCount smallint = 2,
	@FinancialMonth smallint = NULL,

	-- Test-only temporal anchor for disposable synthetic nodes. NULL preserves ordinary behaviour.
	@AsOfDate date = NULL
)
AS
	SET NOCOUNT, XACT_ABORT ON;

	BEGIN TRY
		BEGIN TRAN;

		DECLARE @TemplateCode nvarchar(10) =
			CASE
				WHEN @IsCompany = 1 AND @UseStdCompanyTemplate <> 0
					THEN N'COSTD26'
				WHEN @IsCompany = 1
					THEN N'COMIN26'
				WHEN @UseStdCompanyTemplate <> 0
					THEN N'STSTD26'
				ELSE N'STMIN26'
			END;

		-- If caller didn't specify VAT setting, inherit from template default.
		IF @IsVatRegistered IS NULL
		BEGIN
			SELECT @IsVatRegistered = IsVatRegistered
			FROM App.tbTemplate
			WHERE TemplateCode = @TemplateCode;
		END

		---------------------------------------------------------------------
		-- Shared lookup table for the whole run (visible to nested procs)
		---------------------------------------------------------------------
		IF OBJECT_ID('tempdb..#DatasetCodes') IS NOT NULL
			DROP TABLE #DatasetCodes;

		CREATE TABLE #DatasetCodes
		(
			CodeType nvarchar(20) NOT NULL,        -- 'SUBJECT' | 'OBJECT' | 'LINK' | 'PROJECT' etc
			CodeName nvarchar(100) NOT NULL,       -- logical name (unique within CodeType)
			CodeValue nvarchar(50) NOT NULL,       -- SubjectCode (10) or ObjectCode (50) or ProjectCode (20) etc
			RelatedName nvarchar(100) NULL,
			Notes nvarchar(255) NULL,
			PRIMARY KEY (CodeType, CodeName)
		);

		---------------------------------------------------------------------
		-- 1) Bootstrap (ALWAYS resets node inside the proc)
		---------------------------------------------------------------------
        EXEC App.proc_DatasetSyntheticMIS_Bootstrap
	        @TemplateCode = @TemplateCode,
	        @IsVatRegistered = @IsVatRegistered,
            @EnableOpeningBalance = @EnableOpeningBalance,
			@CompletedYearCount = @CompletedYearCount,
			@FinancialMonth = @FinancialMonth,
			@AsOfDate = @AsOfDate;

        EXEC App.proc_DatasetSyntheticMIS_StatutoryProfile @AsOfDate = @AsOfDate;

		---------------------------------------------------------------------
		-- 2) Project side
		---------------------------------------------------------------------
		IF @EnableProjects <> 0
		BEGIN
			EXEC App.proc_DatasetSyntheticMIS_ProjectInit
				@IsCompany = @IsCompany,
				@IsVatRegistered = @IsVatRegistered,
            @EnableOpeningBalance = @EnableOpeningBalance;

			EXEC App.proc_DatasetSyntheticMIS_ProjectTemplates
				@IsCompany = @IsCompany,
				@IsVatRegistered = @IsVatRegistered,
                @PriceRatio = @PriceRatio,
                @QuantityRatio = @QuantityRatio;

			EXEC App.proc_DatasetSyntheticMIS_ProjectTran
				@IsCompany = @IsCompany,
				@IsVatRegistered = @IsVatRegistered,
				@MisOrdersPerMonth = @MisOrdersPerMonth,
				@MonthsForward = @MonthsForward;

		    IF @EnableInvoices <> 0
		    BEGIN
			    EXEC App.proc_DatasetSyntheticMIS_ProjectInvoice
				    @IsCompany = @IsCompany,
				    @IsVatRegistered = @IsVatRegistered;
		    END

		    IF @EnableProjectPayments <> 0 
		    BEGIN
			    EXEC App.proc_DatasetSyntheticMIS_ProjectPay
				    @IsCompany = @IsCompany,
				    @IsVatRegistered = @IsVatRegistered;
		    END
		END

		---------------------------------------------------------------------
		-- 3a) Payables side (Accounts mode)
		---------------------------------------------------------------------
		IF @EnablePayables <> 0
		BEGIN
			EXEC App.proc_DatasetSyntheticMIS_PayInit
				@IsCompany = @IsCompany,
				@IsVatRegistered = @IsVatRegistered;

		    IF @EnableMiscPayments <> 0
		    BEGIN
			    EXEC App.proc_DatasetSyntheticMIS_PayMisc
				    @IsCompany = @IsCompany,
				    @IsVatRegistered = @IsVatRegistered;
		    END

		    -- company-only behavior (typical): wages/NI should not run for sole trader
		    IF @EnableWages <> 0 AND @IsCompany <> 0
		    BEGIN
			    EXEC App.proc_DatasetSyntheticMIS_PayWages
				    @IsCompany = @IsCompany,
				    @IsVatRegistered = @IsVatRegistered;
		    END

		    IF @EnableExpenses <> 0
		    BEGIN
			    EXEC App.proc_DatasetSyntheticMIS_Expenses
				    @IsCompany = @IsCompany,
				    @IsVatRegistered = @IsVatRegistered;
		    END
		END

		---------------------------------------------------------------------
		-- 3b) Sole Trader owner movements
		---------------------------------------------------------------------
		IF @IsCompany = 0
		BEGIN
			EXEC App.proc_DatasetSyntheticMIS_SoleTraderCapitalIntroduced
				@IsCompany = @IsCompany;

			EXEC App.proc_DatasetSyntheticMIS_SoleTraderDrawings
				@IsCompany = @IsCompany;

			EXEC App.proc_DatasetSyntheticMIS_SoleTraderPersonalTaxRate
				@IsCompany = @IsCompany;
		END

		---------------------------------------------------------------------
		-- 3c) Company Assets
		---------------------------------------------------------------------        
        IF @IsCompany <> 0 AND @EnableAssets <> 0
        BEGIN
	        EXEC App.proc_DatasetSyntheticMIS_Assets
		        @IsCompany = @IsCompany,
		        @IsVatRegistered = @IsVatRegistered;

            EXEC App.proc_DatasetSyntheticMIS_CompanyLoanPayback
                @IsCompany = @IsCompany;
        END

		---------------------------------------------------------------------
		-- 4) Tax
		---------------------------------------------------------------------        
        IF @IsVatRegistered != 0 AND @EnableTax != 0
        BEGIN
            EXEC App.proc_DatasetSyntheticMIS_TaxVat
		        @IsCompany = @IsCompany,
		        @IsVatRegistered = @IsVatRegistered;
        END

		---------------------------------------------------------------------
		-- 5) Transfers (Current -> Reserve sweep)
		---------------------------------------------------------------------
		IF @EnableTransfers <> 0
		BEGIN
			EXEC App.proc_DatasetSyntheticMIS_Transfers
				@FloatRatio = @FloatRatio;
		END

		---------------------------------------------------------------------
		-- 6) Corporation Tax (annual; paid from Reserve via transfer to Current)
		---------------------------------------------------------------------
		IF @IsCompany <> 0 AND @EnableTax <> 0
		BEGIN
			EXEC App.proc_DatasetSyntheticMIS_TaxOnProfit
				@IsCompany = @IsCompany;
		END

        EXEC App.proc_SystemRebuild;

		COMMIT TRAN;
	END TRY
	BEGIN CATCH
		EXEC App.proc_ErrorLog;
	END CATCH
GO
