GO
IF NOT EXISTS
(
    SELECT 1
    FROM App.tbInstall
    WHERE SQLDataVersion = 4.0
      AND SQLRelease = 1
      AND SQLBuild = 18
)
    INSERT App.tbInstall (SQLDataVersion, SQLRelease, SQLBuild)
    VALUES (4.0, 1, 18);
GO

SET NOCOUNT ON;
SET XACT_ABORT ON;
SET ANSI_NULLS, ANSI_PADDING, ANSI_WARNINGS, ARITHABORT,
    CONCAT_NULL_YIELDS_NULL, QUOTED_IDENTIFIER ON;
SET NUMERIC_ROUNDABORT OFF;

DECLARE
    @DatabaseName SYSNAME = DB_NAME(),
    @ExpectedSourceVersion NVARCHAR(20) = N'4.1.18',
    @TargetVersion NVARCHAR(20) = N'4.1.20';

IF @DatabaseName NOT IN
(
    N'tcNodeDb4-COMIPFVT1-COMIN26',
    N'tcNodeDb4-STMIPFVT1-STMIN26',
    N'tcNodeDb4-STSIPFVT1-STSTD26'
)
    THROW 51251, 'The current database is not an allowed Category Tree migration target.', 1;

IF OBJECT_ID(N'App.tbInstall', N'U') IS NULL
    THROW 51252, 'The target does not contain the expected tcNodeDb4 installation ledger.', 1;

DECLARE @InstalledVersion NVARCHAR(20) =
(
    SELECT TOP (1)
        CONCAT(CONVERT(VARCHAR(10), SQLDataVersion), N'.', SQLRelease, N'.', SQLBuild)
    FROM App.tbInstall
    ORDER BY InstallId DESC
);

IF @InstalledVersion = @TargetVersion
BEGIN
    DECLARE @InstalledPointerCount INT = 0;

    IF COL_LENGTH(N'App.tbOptions', N'CategoryVersionId') IS NOT NULL
        EXEC sys.sp_executesql
            N'SELECT @PointerCount = COUNT(*) FROM App.tbOptions WHERE CategoryVersionId IS NOT NULL;',
            N'@PointerCount INT OUTPUT',
            @PointerCount = @InstalledPointerCount OUTPUT;

    IF @InstalledPointerCount = 1
       AND OBJECT_ID(N'Cash.tbCategoryVersion', N'U') IS NOT NULL
       AND OBJECT_ID(N'Cash.tbCategoryCodeMap', N'U') IS NOT NULL
       AND OBJECT_ID(N'Cash.tbCategoryRoot', N'U') IS NOT NULL
    BEGIN
        PRINT 'Category Tree migration is already installed.';
        RETURN;
    END;

    THROW 51253, 'The target reports the new build but its Category Tree migration state is incomplete.', 1;
END;

IF @InstalledVersion <> @ExpectedSourceVersion
    THROW 51254, 'The target database build is not the expected pre-migration build.', 1;

IF (SELECT COUNT(*) FROM App.tbOptions) <> 1
    THROW 51255, 'The target must contain exactly one App.tbOptions row.', 1;

IF COL_LENGTH(N'App.tbOptions', N'CategoryVersionId') IS NOT NULL
   OR OBJECT_ID(N'Cash.tbCategoryVersion', N'U') IS NOT NULL
   OR OBJECT_ID(N'Cash.tbCategoryCodeMap', N'U') IS NOT NULL
   OR OBJECT_ID(N'Cash.tbCategoryRoot', N'U') IS NOT NULL
    THROW 51256, 'The target already contains Category Tree migration objects or a partial prior attempt.', 1;

IF COL_LENGTH(N'Cash.tbCode', N'CategoryCode') IS NULL
   OR COL_LENGTH(N'App.tbOptions', N'NetProfitCode') IS NULL
   OR COL_LENGTH(N'App.tbOptions', N'VatCategoryCode') IS NULL
    THROW 51257, 'The expected legacy Category Tree authorities are not present.', 1;

IF EXISTS
(
    SELECT 1
    FROM Cash.tbCode AS code
    LEFT JOIN Cash.tbCategory AS category
      ON category.CategoryCode = code.CategoryCode
    WHERE code.CategoryCode IS NULL
       OR category.CategoryCode IS NULL
)
    THROW 51258, 'The legacy Cash Code classification contains null or orphaned mappings.', 1;

/*
    Current coverage (kept in the same order as the schema plan):

      [implemented above] build 4.1.13 to 4.1.18 ordinary prerequisite;
      [implemented below] build 4.1.18 preflight, source build and singleton checks;
      [implemented below] vocabulary, version header/event and sequence;
      [implemented below] explicit in-place category/category-total PK conversion;
      [implemented below] mapping/root backfill and nullable options pointer;
      [implemented below] current-build programmable-object deployment payload;
      [implemented below] canonicalise, publish and pointer-swap finalisation;
      [implemented below] retired authority-column and compatibility-trigger removal;
      [implemented below] build ledger and compact migration evidence;
      [implemented beside] paired accounting differential baseline;
      [implemented beside] recovery by reviewed pre-migration BACPAC and full rerun.

    The generated DACPAC comparison is inventory only. In particular, its automatic
    table rebuilds are not an approved way to convert the two Category Tree primary
    keys. The DDL below changes those keys explicitly and preserves every source row.

    This file remains blocked in its first batch pending human review. The SQL below
    is source-controlled migration work, not permission to bypass that guard.
    The completed file must contain every amended table, constraint, function, view,
    procedure and trigger required by build 4.1.19. A production schema comparison is
    run afterwards only to prove zero remaining differences; it is not a second
    deployment stage and must never be used to finish this script.
*/

DECLARE
    @InitialVersionId NVARCHAR(10) = N'CV00000001',
    @MigrationOn DATETIME2(3) = SYSUTCDATETIME(),
    @MigrationUserId NVARCHAR(10),
    @MigrationUserName NVARCHAR(50),
    @CategoryCount INT = (SELECT COUNT(*) FROM Cash.tbCategory),
    @TotalCount INT = (SELECT COUNT(*) FROM Cash.tbCategoryTotal),
    @CashCodeCount INT = (SELECT COUNT(*) FROM Cash.tbCode),
    @NetProfitCode NVARCHAR(10) = (SELECT NetProfitCode FROM App.tbOptions),
    @VatCategoryCode NVARCHAR(10) = (SELECT VatCategoryCode FROM App.tbOptions);

SELECT TOP (1)
    @MigrationUserId = UserId,
    @MigrationUserName = UserName
FROM Usr.tbUser
WHERE IsEnabled <> 0
ORDER BY IsAdministrator DESC, UserId;

IF @MigrationUserId IS NULL
    THROW 51259, 'The Category Tree migration requires an enabled application user for its audit actor.', 1;

IF @NetProfitCode IS NULL OR @VatCategoryCode IS NULL
    THROW 51260, 'Both legacy Category Tree roots must be populated before migration.', 1;

IF @NetProfitCode = @VatCategoryCode
    THROW 51261, 'The Net Profit and VAT roots must be different categories.', 1;

IF EXISTS
(
    SELECT root_code.CategoryCode
    FROM (VALUES (@NetProfitCode), (@VatCategoryCode)) AS root_code (CategoryCode)
    LEFT JOIN Cash.tbCategory AS category
      ON category.CategoryCode = root_code.CategoryCode
    WHERE category.CategoryCode IS NULL
       OR category.CategoryTypeCode <> 1
       OR category.IsEnabled = 0
       OR EXISTS
          (
              SELECT 1
              FROM Cash.tbCategoryTotal AS parent
              WHERE parent.ChildCode = root_code.CategoryCode
          )
       OR NOT EXISTS
          (
              SELECT 1
              FROM Cash.tbCategoryTotal AS child
              WHERE child.ParentCode = root_code.CategoryCode
          )
)
    THROW 51262, 'A legacy root is not an enabled Total root with children.', 1;

BEGIN TRY
    BEGIN TRANSACTION;

    CREATE TABLE Cash.tbCategoryVersionStatus
    (
        VersionStatusCode SMALLINT NOT NULL,
        VersionStatus NVARCHAR(20) NOT NULL,
        CONSTRAINT PK_Cash_tbCategoryVersionStatus PRIMARY KEY CLUSTERED (VersionStatusCode),
        CONSTRAINT UQ_Cash_tbCategoryVersionStatus_VersionStatus UNIQUE (VersionStatus),
        CONSTRAINT CK_Cash_tbCategoryVersionStatus_Code CHECK (VersionStatusCode BETWEEN 0 AND 3)
    );

    INSERT Cash.tbCategoryVersionStatus (VersionStatusCode, VersionStatus)
    VALUES (0, N'Draft'), (1, N'Published'), (2, N'Submitted'), (3, N'Archived');

    CREATE TABLE Cash.tbCategoryRootType
    (
        RootTypeCode SMALLINT NOT NULL,
        RootType NVARCHAR(20) NOT NULL,
        CONSTRAINT PK_Cash_tbCategoryRootType PRIMARY KEY CLUSTERED (RootTypeCode),
        CONSTRAINT UQ_Cash_tbCategoryRootType_RootType UNIQUE (RootType),
        CONSTRAINT CK_Cash_tbCategoryRootType_Code CHECK (RootTypeCode BETWEEN 0 AND 1)
    );

    INSERT Cash.tbCategoryRootType (RootTypeCode, RootType)
    VALUES (0, N'NET_PROFIT'), (1, N'VAT');

    CREATE TABLE Cash.tbCategoryVersion
    (
        VersionId NVARCHAR(10) NOT NULL,
        VersionStatusCode SMALLINT NOT NULL,
        Description NVARCHAR(100) NOT NULL,
        Notes NVARCHAR(MAX) NULL,
        PredecessorVersionId NVARCHAR(10) NULL,
        BaseContentSha256 BINARY(32) NULL,
        CanonicalProfile NVARCHAR(50) NOT NULL
            CONSTRAINT DF_Cash_tbCategoryVersion_CanonicalProfile DEFAULT (N'trade-control-category-tree-v1'),
        CanonicalSha256 BINARY(32) NULL,
        CanonicalByteLength BIGINT NULL,
        ContentChangedOn DATETIME2(3) NOT NULL
            CONSTRAINT DF_Cash_tbCategoryVersion_ContentChangedOn DEFAULT (SYSUTCDATETIME()),
        EffectiveFromOn DATE NULL,
        EffectiveToOn DATE NULL,
        CreatedOn DATETIME2(3) NOT NULL
            CONSTRAINT DF_Cash_tbCategoryVersion_CreatedOn DEFAULT (SYSUTCDATETIME()),
        CreatedByUserId NVARCHAR(10) NOT NULL,
        RowVer ROWVERSION NOT NULL,
        CONSTRAINT PK_Cash_tbCategoryVersion PRIMARY KEY CLUSTERED (VersionId),
        CONSTRAINT FK_Cash_tbCategoryVersion_Cash_tbCategoryVersionStatus
            FOREIGN KEY (VersionStatusCode) REFERENCES Cash.tbCategoryVersionStatus (VersionStatusCode),
        CONSTRAINT FK_Cash_tbCategoryVersion_Cash_tbCategoryVersion_Predecessor
            FOREIGN KEY (PredecessorVersionId) REFERENCES Cash.tbCategoryVersion (VersionId),
        CONSTRAINT FK_Cash_tbCategoryVersion_Usr_tbUser
            FOREIGN KEY (CreatedByUserId) REFERENCES Usr.tbUser (UserId),
        CONSTRAINT CK_Cash_tbCategoryVersion_VersionId
            CHECK (LEN(VersionId) = 10 AND VersionId LIKE N'CV[0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9]'),
        CONSTRAINT CK_Cash_tbCategoryVersion_Description CHECK (LEN(LTRIM(RTRIM(Description))) > 0),
        CONSTRAINT CK_Cash_tbCategoryVersion_Predecessor
            CHECK (PredecessorVersionId IS NULL OR PredecessorVersionId <> VersionId),
        CONSTRAINT CK_Cash_tbCategoryVersion_PredecessorEvidence
            CHECK ((PredecessorVersionId IS NULL AND BaseContentSha256 IS NULL)
                OR (PredecessorVersionId IS NOT NULL AND BaseContentSha256 IS NOT NULL)),
        CONSTRAINT CK_Cash_tbCategoryVersion_CanonicalProfile CHECK (LEN(LTRIM(RTRIM(CanonicalProfile))) > 0),
        CONSTRAINT CK_Cash_tbCategoryVersion_CanonicalEvidence
            CHECK ((CanonicalSha256 IS NULL AND CanonicalByteLength IS NULL)
                OR (CanonicalSha256 IS NOT NULL AND CanonicalByteLength >= 0)),
        CONSTRAINT CK_Cash_tbCategoryVersion_EffectiveInterval
            CHECK ((VersionStatusCode = 0 AND EffectiveToOn IS NULL)
                OR (VersionStatusCode > 0 AND VersionStatusCode < 3
                    AND EffectiveFromOn IS NOT NULL AND EffectiveToOn IS NULL)
                OR (VersionStatusCode = 3 AND EffectiveFromOn IS NOT NULL
                    AND EffectiveToOn IS NOT NULL AND EffectiveToOn >= EffectiveFromOn))
    );

    CREATE INDEX IX_Cash_tbCategoryVersion_StatusCreated
        ON Cash.tbCategoryVersion (VersionStatusCode, CreatedOn, VersionId);
    CREATE INDEX IX_Cash_tbCategoryVersion_EffectiveInterval
        ON Cash.tbCategoryVersion (EffectiveFromOn, EffectiveToOn, VersionId);

    EXEC(N'CREATE SEQUENCE Cash.seqCategoryVersion AS BIGINT START WITH 1 INCREMENT BY 1 MINVALUE 1 MAXVALUE 99999999 CACHE 20 NO CYCLE;');
    EXEC(N'DECLARE @CommissionedValue BIGINT = NEXT VALUE FOR Cash.seqCategoryVersion;');

    EXEC
    (
        N'CREATE FUNCTION Cash.fnCategoryVersionDefault()
          RETURNS NVARCHAR(10)
          AS
          BEGIN
              DECLARE @VersionId NVARCHAR(10);
              SELECT @VersionId = MIN(VersionId)
              FROM Cash.tbCategoryVersion
              HAVING COUNT(*) = 1;
              RETURN @VersionId;
          END;'
    );

    CREATE TABLE Cash.tbCategoryVersionEvent
    (
        VersionEventId BIGINT IDENTITY(1, 1) NOT NULL,
        VersionId NVARCHAR(10) NOT NULL,
        EventTypeCode SMALLINT NOT NULL,
        FromStatusCode SMALLINT NULL,
        ToStatusCode SMALLINT NULL,
        EventOn DATETIME2(3) NOT NULL CONSTRAINT DF_Cash_tbCategoryVersionEvent_EventOn DEFAULT (SYSUTCDATETIME()),
        UserId NVARCHAR(10) NOT NULL,
        UserName NVARCHAR(50) NOT NULL,
        ChangeNote NVARCHAR(MAX) NULL,
        ContentSha256 BINARY(32) NULL,
        CONSTRAINT PK_Cash_tbCategoryVersionEvent PRIMARY KEY CLUSTERED (VersionEventId),
        CONSTRAINT FK_Cash_tbCategoryVersionEvent_Cash_tbCategoryVersion
            FOREIGN KEY (VersionId) REFERENCES Cash.tbCategoryVersion (VersionId) ON DELETE CASCADE,
        CONSTRAINT FK_Cash_tbCategoryVersionEvent_Cash_tbCategoryVersionStatus_From
            FOREIGN KEY (FromStatusCode) REFERENCES Cash.tbCategoryVersionStatus (VersionStatusCode),
        CONSTRAINT FK_Cash_tbCategoryVersionEvent_Cash_tbCategoryVersionStatus_To
            FOREIGN KEY (ToStatusCode) REFERENCES Cash.tbCategoryVersionStatus (VersionStatusCode),
        CONSTRAINT FK_Cash_tbCategoryVersionEvent_Usr_tbUser
            FOREIGN KEY (UserId) REFERENCES Usr.tbUser (UserId),
        CONSTRAINT CK_Cash_tbCategoryVersionEvent_EventTypeCode CHECK (EventTypeCode BETWEEN 0 AND 6)
    );
    CREATE INDEX IX_Cash_tbCategoryVersionEvent_VersionEventOn
        ON Cash.tbCategoryVersionEvent (VersionId, EventOn, VersionEventId);

    INSERT Cash.tbCategoryVersion
    (
        VersionId, VersionStatusCode, Description, Notes,
        ContentChangedOn, CreatedOn, CreatedByUserId
    )
    VALUES
    (
        @InitialVersionId, 0, N'Initial migrated Category Tree',
        N'Created from the retained sandbox operational Category Tree.',
        @MigrationOn, @MigrationOn, @MigrationUserId
    );

    INSERT Cash.tbCategoryVersionEvent
        (VersionId, EventTypeCode, ToStatusCode, EventOn, UserId, UserName, ChangeNote)
    VALUES
        (@InitialVersionId, 0, 0, @MigrationOn, @MigrationUserId, @MigrationUserName,
         N'Initial version created by the IAM-01 sandbox migration.');

    /* Break only the known legacy single-code dependencies before changing the PK. */
    ALTER TABLE Cash.tbCategoryTotal DROP CONSTRAINT FK_Cash_tbCategoryTotal_Cash_tbCategory_Parent;
    ALTER TABLE Cash.tbCategoryTotal DROP CONSTRAINT FK_Cash_tbCategoryTotal_Cash_tbCategory_Child;
    ALTER TABLE Cash.tbCode DROP CONSTRAINT FK_Cash_tbCode_Cash_tbCategory1;
    ALTER TABLE Cash.tbCategoryExp DROP CONSTRAINT FK_Cash_tbCategoryExp_Cash_tbCategory;
    ALTER TABLE App.tbOptions DROP CONSTRAINT FK_App_tbOption_Cash_tbCategory;

    ALTER TABLE Cash.tbCategory ADD VersionId NVARCHAR(10) NULL;
    EXEC sys.sp_executesql
        N'UPDATE Cash.tbCategory SET VersionId = @VersionId;',
        N'@VersionId NVARCHAR(10)',
        @VersionId = @InitialVersionId;
    ALTER TABLE Cash.tbCategory ALTER COLUMN VersionId NVARCHAR(10) NOT NULL;
    ALTER TABLE Cash.tbCategory ADD CONSTRAINT DF_Cash_tbCategory_VersionId
        DEFAULT (Cash.fnCategoryVersionDefault()) FOR VersionId;

    DROP INDEX IX_Cash_tbCategory_DisplayOrder ON Cash.tbCategory;
    DROP INDEX IX_Cash_tbCategory_IsEnabled_Category ON Cash.tbCategory;
    DROP INDEX IX_Cash_tbCategory_IsEnabled_CategoryCode ON Cash.tbCategory;
    DROP INDEX IX_Cash_tbCategory_Name ON Cash.tbCategory;
    DROP INDEX IX_Cash_tbCategory_TypeCategory ON Cash.tbCategory;
    DROP INDEX IX_Cash_tbCategory_TypeOrderCategory ON Cash.tbCategory;
    ALTER TABLE Cash.tbCategory DROP CONSTRAINT PK_Cash_tbCategory;
    ALTER TABLE Cash.tbCategory ADD CONSTRAINT PK_Cash_tbCategory
        PRIMARY KEY CLUSTERED (VersionId, CategoryCode) WITH (FILLFACTOR = 90);
    ALTER TABLE Cash.tbCategory ADD CONSTRAINT FK_Cash_tbCategory_Cash_tbCategoryVersion
        FOREIGN KEY (VersionId) REFERENCES Cash.tbCategoryVersion (VersionId);

    CREATE INDEX IX_Cash_tbCategory_DisplayOrder
        ON Cash.tbCategory (VersionId, DisplayOrder, Category) WITH (FILLFACTOR = 90);
    CREATE UNIQUE INDEX IX_Cash_tbCategory_IsEnabled_Category
        ON Cash.tbCategory (VersionId, IsEnabled, Category);
    CREATE UNIQUE INDEX IX_Cash_tbCategory_IsEnabled_CategoryCode
        ON Cash.tbCategory (VersionId, IsEnabled, CategoryCode);
    CREATE INDEX IX_Cash_tbCategory_Name
        ON Cash.tbCategory (VersionId, Category) WITH (FILLFACTOR = 90);
    CREATE INDEX IX_Cash_tbCategory_TypeCategory
        ON Cash.tbCategory (VersionId, CategoryTypeCode, Category) WITH (FILLFACTOR = 90);
    CREATE INDEX IX_Cash_tbCategory_TypeOrderCategory
        ON Cash.tbCategory (VersionId, CategoryTypeCode, DisplayOrder, Category) WITH (FILLFACTOR = 90);

    ALTER TABLE Cash.tbCategoryTotal ADD VersionId NVARCHAR(10) NULL;
    EXEC sys.sp_executesql
        N'UPDATE Cash.tbCategoryTotal SET VersionId = @VersionId;',
        N'@VersionId NVARCHAR(10)',
        @VersionId = @InitialVersionId;
    ALTER TABLE Cash.tbCategoryTotal ALTER COLUMN VersionId NVARCHAR(10) NOT NULL;
    ALTER TABLE Cash.tbCategoryTotal ADD CONSTRAINT DF_Cash_tbCategoryTotal_VersionId
        DEFAULT (Cash.fnCategoryVersionDefault()) FOR VersionId;
    ALTER TABLE Cash.tbCategoryTotal DROP CONSTRAINT PK_Cash_tbCategoryTotal;
    ALTER TABLE Cash.tbCategoryTotal ADD CONSTRAINT PK_Cash_tbCategoryTotal
        PRIMARY KEY CLUSTERED (VersionId, ParentCode, ChildCode) WITH (FILLFACTOR = 90);
    ALTER TABLE Cash.tbCategoryTotal ADD CONSTRAINT FK_Cash_tbCategoryTotal_Cash_tbCategoryVersion
        FOREIGN KEY (VersionId) REFERENCES Cash.tbCategoryVersion (VersionId);
    ALTER TABLE Cash.tbCategoryTotal ADD CONSTRAINT FK_Cash_tbCategoryTotal_Cash_tbCategory_ChildVersion
        FOREIGN KEY (VersionId, ChildCode) REFERENCES Cash.tbCategory (VersionId, CategoryCode);
    ALTER TABLE Cash.tbCategoryTotal ADD CONSTRAINT FK_Cash_tbCategoryTotal_Cash_tbCategory_ParentVersion
        FOREIGN KEY (VersionId, ParentCode) REFERENCES Cash.tbCategory (VersionId, CategoryCode);
    CREATE INDEX IX_Cash_tbCategoryTotal_VersionParentDisplayChild
        ON Cash.tbCategoryTotal (VersionId, ParentCode, DisplayOrder, ChildCode);
    CREATE INDEX IX_Cash_tbCategoryTotal_VersionChildParent
        ON Cash.tbCategoryTotal (VersionId, ChildCode, ParentCode);

    CREATE TABLE Cash.tbCategoryCodeMap
    (
        VersionId NVARCHAR(10) NOT NULL,
        CashCode NVARCHAR(50) NOT NULL,
        CategoryCode NVARCHAR(10) NOT NULL,
        RowVer ROWVERSION NOT NULL,
        CONSTRAINT PK_Cash_tbCategoryCodeMap PRIMARY KEY CLUSTERED (VersionId, CashCode),
        CONSTRAINT FK_Cash_tbCategoryCodeMap_Cash_tbCategoryVersion
            FOREIGN KEY (VersionId) REFERENCES Cash.tbCategoryVersion (VersionId),
        CONSTRAINT FK_Cash_tbCategoryCodeMap_Cash_tbCategory
            FOREIGN KEY (VersionId, CategoryCode) REFERENCES Cash.tbCategory (VersionId, CategoryCode) ON UPDATE CASCADE
    );
    CREATE INDEX IX_Cash_tbCategoryCodeMap_VersionCategoryCashCode
        ON Cash.tbCategoryCodeMap (VersionId, CategoryCode, CashCode);

    INSERT Cash.tbCategoryCodeMap (VersionId, CashCode, CategoryCode)
    SELECT @InitialVersionId, CashCode, CategoryCode
    FROM Cash.tbCode;

    CREATE TABLE Cash.tbCategoryRoot
    (
        VersionId NVARCHAR(10) NOT NULL,
        RootTypeCode SMALLINT NOT NULL,
        CategoryCode NVARCHAR(10) NOT NULL,
        RowVer ROWVERSION NOT NULL,
        CONSTRAINT PK_Cash_tbCategoryRoot PRIMARY KEY CLUSTERED (VersionId, RootTypeCode),
        CONSTRAINT FK_Cash_tbCategoryRoot_Cash_tbCategoryVersion
            FOREIGN KEY (VersionId) REFERENCES Cash.tbCategoryVersion (VersionId),
        CONSTRAINT FK_Cash_tbCategoryRoot_Cash_tbCategoryRootType
            FOREIGN KEY (RootTypeCode) REFERENCES Cash.tbCategoryRootType (RootTypeCode),
        CONSTRAINT FK_Cash_tbCategoryRoot_Cash_tbCategory
            FOREIGN KEY (VersionId, CategoryCode) REFERENCES Cash.tbCategory (VersionId, CategoryCode)
    );

    INSERT Cash.tbCategoryRoot (VersionId, RootTypeCode, CategoryCode)
    VALUES (@InitialVersionId, 0, @NetProfitCode), (@InitialVersionId, 1, @VatCategoryCode);

    ALTER TABLE App.tbOptions ADD CategoryVersionId NVARCHAR(10) NULL;
    ALTER TABLE App.tbOptions ADD CONSTRAINT FK_App_tbOptions_Cash_tbCategoryVersion
        FOREIGN KEY (CategoryVersionId) REFERENCES Cash.tbCategoryVersion (VersionId);

    DECLARE
        @MigratedCategoryCount INT,
        @MigratedTotalCount INT;

    EXEC sys.sp_executesql
        N'SELECT @Count = COUNT(*) FROM Cash.tbCategory WHERE VersionId = @VersionId;',
        N'@VersionId NVARCHAR(10), @Count INT OUTPUT',
        @VersionId = @InitialVersionId,
        @Count = @MigratedCategoryCount OUTPUT;

    EXEC sys.sp_executesql
        N'SELECT @Count = COUNT(*) FROM Cash.tbCategoryTotal WHERE VersionId = @VersionId;',
        N'@VersionId NVARCHAR(10), @Count INT OUTPUT',
        @VersionId = @InitialVersionId,
        @Count = @MigratedTotalCount OUTPUT;

    IF @MigratedCategoryCount <> @CategoryCount
        THROW 51263, 'Category row count changed during key conversion.', 1;
    IF @MigratedTotalCount <> @TotalCount
        THROW 51264, 'Category-total row count changed during key conversion.', 1;
    IF (SELECT COUNT(*) FROM Cash.tbCategoryCodeMap WHERE VersionId = @InitialVersionId) <> @CashCodeCount
        THROW 51265, 'Cash Code mapping coverage changed during conversion.', 1;
    IF (SELECT COUNT(*) FROM Cash.tbCategoryRoot WHERE VersionId = @InitialVersionId) <> 2
        THROW 51266, 'The migrated version does not contain exactly two roots.', 1;

    /* Deliberately leave the version Draft and the options pointer null here. */
    COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
    THROW;
END CATCH;

GO

/*
    Complete build 4.1.18-to-4.1.19 payload generated from the reviewed SSDT
    model after the explicit Category Tree conversion above.

    The build-18 source has two known non-Category-Tree differences from the
    repository model which are deliberately preserved: the environment-managed
    Platform schema/DatabaseIdentity object, and the physical ordinal position
    of the existing App.tbYearPeriod VAT adjustment-note columns. The persistent
    Cash.tbTaxTag check-constraint text normalisation is also excluded because it
    is unchanged VAT work and has no semantic schema difference.

    The generated target header, database settings, post-deployment footer and
    those three exclusions are not copied here. Every remaining table rebuild,
    dependency refresh and programmable-object change is part of this single
    migration; the later schema comparison is a validator only.
*/
ALTER DATABASE CURRENT SET RECURSIVE_TRIGGERS ON;
