PRINT N'Creating Trigger [Cash].[Cash_tbCategory_TriggerVersionGuard]...';


GO

CREATE TRIGGER [Cash].[Cash_tbCategory_TriggerVersionGuard]
ON [Cash].[tbCategory]
AFTER INSERT, UPDATE, DELETE
AS
BEGIN
	SET NOCOUNT ON;

	IF EXISTS
	(
		SELECT 1
		FROM
		(
			SELECT VersionId FROM inserted
			UNION
			SELECT VersionId FROM deleted
		) AS affected
		JOIN Cash.tbCategoryVersion AS version
		  ON version.VersionId = affected.VersionId
		WHERE version.VersionStatusCode IN (2, 3)
	)
		THROW 51097, 'Submitted and Archived Category Tree categories are immutable.', 1;

	;WITH affected AS
	(
		SELECT VersionId FROM inserted
		UNION
		SELECT VersionId FROM deleted
	)
	UPDATE version
	SET CanonicalSha256 = NULL,
		CanonicalByteLength = NULL,
		ContentChangedOn = SYSUTCDATETIME()
	FROM Cash.tbCategoryVersion AS version
	JOIN affected
	  ON affected.VersionId = version.VersionId
	WHERE version.VersionStatusCode IN (0, 1);
END;
GO

PRINT N'Creating Trigger [Cash].[Cash_tbCategoryTotal_Trigger_NoCycles]...';


GO

CREATE TRIGGER [Cash].[Cash_tbCategoryTotal_Trigger_NoCycles]
ON [Cash].[tbCategoryTotal]
AFTER INSERT, UPDATE, DELETE
AS
BEGIN
    SET NOCOUNT ON;

    IF EXISTS (SELECT 1 FROM inserted WHERE ParentCode = ChildCode)
    BEGIN
        RAISERROR ('ParentCode cannot equal ChildCode.', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END

    IF EXISTS (
        SELECT 1
        FROM inserted i
        JOIN Cash.tbCategory p ON p.VersionId = i.VersionId AND p.CategoryCode = i.ParentCode
        WHERE ISNULL(p.CategoryTypeCode, -1) <> 1
    )
    BEGIN
        RAISERROR ('Invalid parent: only Total-type categories may be parents in Cash.tbCategoryTotal.', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END

    DECLARE @violations TABLE (ChildCode nvarchar(10), ParentCode nvarchar(10));

    ;WITH down_paths AS
    (
        SELECT i.VersionId, i.ChildCode AS StartChild, e.ChildCode AS Descendant
        FROM inserted i
        JOIN Cash.tbCategoryTotal e
          ON e.VersionId = i.VersionId
         AND e.ParentCode = i.ChildCode

        UNION ALL

        SELECT dp.VersionId, dp.StartChild, e.ChildCode
        FROM down_paths dp
        JOIN Cash.tbCategoryTotal e
          ON e.VersionId = dp.VersionId
         AND e.ParentCode = dp.Descendant
    )
    INSERT INTO @violations (ChildCode, ParentCode)
    SELECT DISTINCT i.ChildCode, i.ParentCode
    FROM inserted i
    JOIN down_paths dp
      ON dp.VersionId = i.VersionId
     AND dp.StartChild = i.ChildCode
     AND dp.Descendant = i.ParentCode
    OPTION (MAXRECURSION 1000);

    IF EXISTS (SELECT 1 FROM @violations)
    BEGIN
        RAISERROR ('Insert/Update would create a cyclic hierarchy in Cash.tbCategoryTotal.', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END

    IF EXISTS
    (
        SELECT 1
        FROM
        (
            SELECT VersionId FROM inserted
            UNION
            SELECT VersionId FROM deleted
        ) AS affected
        JOIN Cash.tbCategoryVersion AS version
          ON version.VersionId = affected.VersionId
        WHERE version.VersionStatusCode IN (2, 3)
    )
        THROW 51098, 'Submitted and Archived Category Tree totals are immutable.', 1;

    ;WITH affected AS
    (
        SELECT VersionId FROM inserted
        UNION
        SELECT VersionId FROM deleted
    )
    UPDATE version
    SET CanonicalSha256 = NULL,
        CanonicalByteLength = NULL,
        ContentChangedOn = SYSUTCDATETIME()
    FROM Cash.tbCategoryVersion AS version
    JOIN affected
      ON affected.VersionId = version.VersionId
    WHERE version.VersionStatusCode IN (0, 1);
END
GO

PRINT N'Creating Trigger [Cash].[Cash_tbCategoryCodeMap_TriggerValidate]...';


GO

CREATE TRIGGER [Cash].[Cash_tbCategoryCodeMap_TriggerValidate]
ON [Cash].[tbCategoryCodeMap]
AFTER INSERT, UPDATE, DELETE
AS
BEGIN
    SET NOCOUNT ON;

    IF EXISTS
    (
        SELECT 1
        FROM inserted AS i
        JOIN Cash.tbCategory AS c
          ON c.VersionId = i.VersionId
         AND c.CategoryCode = i.CategoryCode
        WHERE c.CategoryTypeCode <> 0
    )
        THROW 51073, 'A Cash Code mapping must target a Nominal category in the same version.', 1;

    IF EXISTS
    (
        SELECT 1
        FROM
        (
            SELECT VersionId FROM inserted
            UNION
            SELECT VersionId FROM deleted
        ) AS affected
        JOIN Cash.tbCategoryVersion AS version
          ON version.VersionId = affected.VersionId
        WHERE version.VersionStatusCode IN (2, 3)
    )
        THROW 51099, 'Submitted and Archived Category Tree Cash Code mappings are immutable.', 1;

    ;WITH affected AS
    (
        SELECT VersionId FROM inserted
        UNION
        SELECT VersionId FROM deleted
    )
    UPDATE version
    SET CanonicalSha256 = NULL,
        CanonicalByteLength = NULL,
        ContentChangedOn = SYSUTCDATETIME()
    FROM Cash.tbCategoryVersion AS version
    JOIN affected
      ON affected.VersionId = version.VersionId
    WHERE version.VersionStatusCode IN (0, 1);
END;
GO

PRINT N'Creating Trigger [Cash].[Cash_tbCategoryRoot_TriggerValidate]...';


GO

CREATE TRIGGER [Cash].[Cash_tbCategoryRoot_TriggerValidate]
ON [Cash].[tbCategoryRoot]
AFTER INSERT, UPDATE, DELETE
AS
BEGIN
    SET NOCOUNT ON;

    IF EXISTS
    (
        SELECT 1
        FROM inserted AS i
        JOIN Cash.tbCategory AS category
          ON category.VersionId = i.VersionId
         AND category.CategoryCode = i.CategoryCode
        WHERE category.CategoryTypeCode <> 1
           OR category.IsEnabled = 0
           OR EXISTS
              (
                  SELECT 1
                  FROM Cash.tbCategoryTotal AS parent
                  WHERE parent.VersionId = i.VersionId
                    AND parent.ChildCode = i.CategoryCode
              )
           OR NOT EXISTS
              (
                  SELECT 1
                  FROM Cash.tbCategoryTotal AS child
                  WHERE child.VersionId = i.VersionId
                    AND child.ParentCode = i.CategoryCode
              )
    )
        THROW 51100, 'A Category Tree root must be an enabled Total category with children and no parent.', 1;

    IF EXISTS
    (
        SELECT 1
        FROM
        (
            SELECT VersionId FROM inserted
            UNION
            SELECT VersionId FROM deleted
        ) AS affected
        JOIN Cash.tbCategoryVersion AS version
          ON version.VersionId = affected.VersionId
        WHERE version.VersionStatusCode IN (2, 3)
    )
        THROW 51101, 'Submitted and Archived Category Tree roots are immutable.', 1;

    ;WITH affected AS
    (
        SELECT VersionId FROM inserted
        UNION
        SELECT VersionId FROM deleted
    )
    UPDATE version
    SET CanonicalSha256 = NULL,
        CanonicalByteLength = NULL,
        ContentChangedOn = SYSUTCDATETIME()
    FROM Cash.tbCategoryVersion AS version
    JOIN affected
      ON affected.VersionId = version.VersionId
    WHERE version.VersionStatusCode IN (0, 1);
END;
GO

PRINT N'Creating Trigger [Cash].[Cash_tbCategoryVersion_TriggerActiveStatus]...';


GO

CREATE TRIGGER [Cash].[Cash_tbCategoryVersion_TriggerActiveStatus]
ON [Cash].[tbCategoryVersion]
AFTER UPDATE
AS
BEGIN
    SET NOCOUNT ON;

    IF EXISTS
    (
        SELECT 1
        FROM inserted AS version
        JOIN App.tbOptions AS options
          ON options.CategoryVersionId = version.VersionId
        WHERE version.VersionStatusCode NOT IN (1, 2)
    )
        THROW 51092, 'The options-selected Category Tree version must remain Published or Submitted.', 1;
END;
GO

PRINT N'Creating Trigger [Cash].[Cash_tbCode_TriggerCategoryVersionShadow]...';


GO

CREATE TRIGGER [Cash].[Cash_tbCode_TriggerCategoryVersionShadow]
ON [Cash].[tbCode]
AFTER INSERT, UPDATE, DELETE
AS
BEGIN
    SET NOCOUNT, XACT_ABORT ON;

    IF TRY_CONVERT(BIT, SESSION_CONTEXT(N'CategoryTreeExplicitMapping')) = 1
        RETURN;

    DECLARE @VersionId NVARCHAR(10) =
    (
        SELECT CategoryVersionId
        FROM App.tbOptions
    );

    -- Commissioning supplies its Draft VersionId explicitly. Once a version is
    -- active, this compatibility trigger keeps legacy Cash Code writers mapped.
    IF @VersionId IS NULL
        RETURN;

    DELETE map
    FROM Cash.tbCategoryCodeMap AS map
    JOIN deleted AS d
      ON d.CashCode = map.CashCode
    LEFT JOIN inserted AS i
      ON i.CashCode = d.CashCode
    WHERE map.VersionId = @VersionId
      AND i.CashCode IS NULL;

    UPDATE map
    SET CategoryCode = i.CategoryCode
    FROM Cash.tbCategoryCodeMap AS map
    JOIN inserted AS i
      ON i.CashCode = map.CashCode
    WHERE map.VersionId = @VersionId
      AND map.CategoryCode <> i.CategoryCode;

    INSERT INTO Cash.tbCategoryCodeMap (VersionId, CashCode, CategoryCode)
    SELECT @VersionId, i.CashCode, i.CategoryCode
    FROM inserted AS i
    WHERE NOT EXISTS
    (
        SELECT 1
        FROM Cash.tbCategoryCodeMap AS map
        WHERE map.VersionId = @VersionId
          AND map.CashCode = i.CashCode
    );
END;
GO

