PRINT N'Altering View [Cash].[vwTaxVatAccruals]...';


GO
ALTER VIEW Cash.vwTaxVatAccruals
AS
	WITH Project_invoiced_quantity AS
	(
		SELECT
			ip.ProjectCode,
			SUM(ip.Quantity) AS InvoiceQuantity
		FROM Invoice.tbProject AS ip
			INNER JOIN Invoice.tbInvoice AS i
				ON ip.InvoiceNumber = i.InvoiceNumber
		WHERE i.InvoiceTypeCode IN (0, 2)
		GROUP BY
			ip.ProjectCode
	),
	Project_transactions AS
	(
		SELECT
			(
				SELECT TOP (1) yp.StartOn
				FROM App.tbYearPeriod AS yp
				WHERE yp.StartOn <= p.ActionOn
				ORDER BY yp.StartOn DESC
			) AS StartOn,
			p.ProjectCode,
			p.TaxCode,
			p.Quantity - ISNULL(iq.InvoiceQuantity, 0) AS QuantityRemaining,
			p.UnitCharge * (p.Quantity - ISNULL(iq.InvoiceQuantity, 0)) AS TotalValue,
			p.UnitCharge * (p.Quantity - ISNULL(iq.InvoiceQuantity, 0)) * tc.TaxRate AS TaxValue,
			tc.TaxRate,
			ISNULL(s.ExportTypeCode, 0) AS ExportTypeCode,
			cat.CashPolarityCode
		FROM Project.tbProject AS p
			INNER JOIN Subject.tbSubject AS s
				ON p.SubjectCode = s.SubjectCode
			INNER JOIN Cash.vwCodeActive AS c
				ON p.CashCode = c.CashCode
			INNER JOIN Cash.vwCategoryActive AS cat
				ON c.CategoryCode = cat.CategoryCode
			INNER JOIN App.tbTaxCode AS tc
				ON p.TaxCode = tc.TaxCode
			LEFT OUTER JOIN Project_invoiced_quantity AS iq
				ON p.ProjectCode = iq.ProjectCode
		WHERE tc.TaxTypeCode = 1
			AND p.ProjectStatusCode > 0
			AND p.ProjectStatusCode < 3
			AND p.ActionOn <= (SELECT DATEADD(DAY, TaxHorizon, CURRENT_TIMESTAMP) FROM App.tbOptions)
			AND ISNULL(s.ExportTypeCode, 0) <> 1
	)
	SELECT
		pt.StartOn,
		pt.ProjectCode,
		pt.TaxCode,
		pt.TaxRate,
		pt.TotalValue,
		pt.TaxValue,
		pt.QuantityRemaining,
		CAST
		(
			CASE
				WHEN pt.ExportTypeCode IN (0, 2) AND pt.CashPolarityCode = 1 THEN pt.TaxValue
				ELSE 0
			END
			AS decimal(18,5)
		) AS vatDueSales,
		CAST
		(
			CASE
				WHEN pt.ExportTypeCode = 2 AND pt.CashPolarityCode = 0 THEN pt.TaxValue * -1
				ELSE 0
			END
			AS decimal(18,5)
		) AS vatDueAcquisitions,
		CAST
		(
			CASE
				WHEN pt.ExportTypeCode = 0 AND pt.CashPolarityCode = 0 THEN pt.TaxValue * -1
				ELSE 0
			END
			AS decimal(18,5)
		) AS vatReclaimedCurrPeriod,
		CAST
		(
			CASE
				WHEN pt.ExportTypeCode IN (0, 2) AND pt.CashPolarityCode = 1 THEN pt.TotalValue
				ELSE 0
			END
			AS decimal(18,5)
		) AS totalValueSalesExVAT,
		CAST
		(
			CASE
				WHEN pt.ExportTypeCode IN (0, 2) AND pt.CashPolarityCode = 0 THEN pt.TotalValue
				ELSE 0
			END
			AS decimal(18,5)
		) AS totalValuePurchasesExVAT,
		CAST(0 AS decimal(18,5)) AS totalValueGoodsSuppliedExVAT,
		CAST(0 AS decimal(18,5)) AS totalValueGoodsReceivedExVAT,
		CAST
		(
			CASE
				WHEN pt.ExportTypeCode IN (0, 2) AND pt.CashPolarityCode = 1 THEN pt.TaxValue
				ELSE 0
			END
			+
			CASE
				WHEN pt.ExportTypeCode = 0 AND pt.CashPolarityCode = 0 THEN pt.TaxValue * -1
				ELSE 0
			END
			+
			CASE
				WHEN pt.ExportTypeCode = 2 AND pt.CashPolarityCode = 0 THEN pt.TaxValue * -1
				ELSE 0
			END
			AS decimal(18,5)
		) AS netVatDue
	FROM Project_transactions AS pt
		INNER JOIN App.tbYearPeriod AS yp
			ON pt.StartOn = yp.StartOn
		INNER JOIN App.tbYear AS y
			ON yp.YearNumber = y.YearNumber
		INNER JOIN App.tbMonth AS m
			ON yp.MonthNumber = m.MonthNumber;
GO

PRINT N'Altering View [Cash].[vwTaxBizAccruals]...';


GO
ALTER VIEW Cash.vwTaxBizAccruals
AS
	WITH corptax_ordered_confirmed AS
	(
		SELECT Project.ProjectCode, Project.ActionOn, Project.Quantity, CASE WHEN category.CashPolarityCode = 0 THEN Project.TotalCharge * - 1 ELSE Project.TotalCharge END AS TotalCharge
		FROM            Project.tbProject AS Project INNER JOIN
								 Cash.vwCodeActive AS code ON Project.CashCode = code.CashCode INNER JOIN
								 Cash.vwCategoryActive AS category ON code.CategoryCode = category.CategoryCode
		WHERE        (Project.ProjectStatusCode BETWEEN 1 AND 2) AND (Project.ActionOn <= (SELECT DATEADD(d, TaxHorizon, CURRENT_TIMESTAMP) AS HorizonOn FROM App.tbOptions))
	), corptax_ordered_invoices AS
	(
		SELECT corptax_ordered_confirmed.ProjectCode, Project_invoice.Quantity,
			CASE WHEN invoice_type.CashPolarityCode = 0 THEN Project_invoice.InvoiceValue * -1 ELSE Project_invoice.InvoiceValue END AS InvoiceValue
		FROM corptax_ordered_confirmed JOIN Invoice.tbProject Project_invoice ON corptax_ordered_confirmed.ProjectCode = Project_invoice.ProjectCode
			JOIN Invoice.tbInvoice invoice ON Project_invoice.InvoiceNumber = invoice.InvoiceNumber
			JOIN Invoice.tbType invoice_type ON invoice_type.InvoiceTypeCode = invoice.InvoiceTypeCode
	), corptax_ordered AS
	(
		SELECT (SELECT TOP (1) StartOn FROM App.tbYearPeriod WHERE (StartOn <= corptax_ordered_confirmed.ActionOn) ORDER BY StartOn DESC) AS StartOn, 
			corptax_ordered_confirmed.ProjectCode,
			corptax_ordered_confirmed.Quantity - ISNULL(corptax_ordered_invoices.Quantity, 0) AS QuantityRemaining,
			corptax_ordered_confirmed.TotalCharge - ISNULL(corptax_ordered_invoices.InvoiceValue, 0) AS OrderValue
		FROM corptax_ordered_confirmed 
			LEFT JOIN corptax_ordered_invoices ON corptax_ordered_confirmed.ProjectCode = corptax_ordered_invoices.ProjectCode
	)
	SELECT corptax_ordered.StartOn, ProjectCode, QuantityRemaining, OrderValue, OrderValue * BusinessTaxRate AS TaxDue
	FROM corptax_ordered JOIN App.tbYearPeriod year_period ON corptax_ordered.StartOn = year_period.StartOn;
GO

PRINT N'Altering View [Project].[vwNetworkDeployments]...';


GO
ALTER VIEW Project.vwNetworkDeployments
AS
	SELECT DISTINCT Project.tbProject.ProjectCode, Project.tbProject.SubjectCode, Project.tbProject.ObjectCode, Object.tbObject.ObjectDescription, Project.tbProject.ProjectTitle, Project.tbProject.ProjectStatusCode, Project.tbStatus.ProjectStatus, Project.tbProject.ActionOn, Project.tbProject.Quantity, 
							 Cash.vwCategoryActive.CashPolarityCode, Cash.tbPolarity.CashPolarity, App.tbTaxCode.TaxRate, Project.tbProject.UnitCharge, Object.tbObject.UnitOfMeasure,
								 (SELECT        UnitOfCharge
								   FROM            App.tbOptions) AS UnitOfCharge
	FROM            Project.tbChangeLog INNER JOIN
							 Project.tbProject ON Project.tbChangeLog.ProjectCode = Project.tbProject.ProjectCode INNER JOIN
							 Cash.vwCodeActive ON Project.tbProject.CashCode = Cash.vwCodeActive.CashCode INNER JOIN
							 Cash.vwCategoryActive ON Cash.vwCodeActive.CategoryCode = Cash.vwCategoryActive.CategoryCode AND Cash.vwCodeActive.CategoryCode = Cash.vwCategoryActive.CategoryCode INNER JOIN
							 App.tbTaxCode ON Project.tbProject.TaxCode = App.tbTaxCode.TaxCode AND Project.tbProject.TaxCode = App.tbTaxCode.TaxCode INNER JOIN
							 Object.tbObject ON Project.tbProject.ObjectCode = Object.tbObject.ObjectCode AND Project.tbProject.ObjectCode = Object.tbObject.ObjectCode INNER JOIN
							 Project.tbStatus ON Project.tbProject.ProjectStatusCode = Project.tbStatus.ProjectStatusCode INNER JOIN
							 Cash.tbPolarity ON Cash.vwCategoryActive.CashPolarityCode = Cash.tbPolarity.CashPolarityCode AND Cash.vwCategoryActive.CashPolarityCode = Cash.tbPolarity.CashPolarityCode
	WHERE        (Project.tbChangeLog.TransmitStatusCode = 1)
GO

