PRINT N'Altering Function [Project].[fnIsExpense]...';


GO
ALTER   FUNCTION Project.fnIsExpense
	(
	@ProjectCode nvarchar(20)
	)
RETURNS bit
AS
	BEGIN
	/* An expense is a Project assigned to an outgoing cash code that is not linked to a sale */
	DECLARE @IsExpense bit
	IF EXISTS (SELECT     Project.tbProject.ProjectCode
	           FROM         Project.tbProject INNER JOIN
	                                 Cash.vwCodeActive ON Project.tbProject.CashCode = Cash.vwCodeActive.CashCode INNER JOIN
	                                 Cash.vwCategoryActive ON Cash.vwCodeActive.CategoryCode = Cash.vwCategoryActive.CategoryCode
	           WHERE     ( Cash.vwCategoryActive.CashPolarityCode = 1) AND ( Project.tbProject.ProjectCode = @ProjectCode))
		SET @IsExpense = 0			          
	ELSE IF EXISTS(SELECT     ParentProjectCode
	          FROM         Project.tbFlow
	          WHERE     (ChildProjectCode = @ProjectCode))
		BEGIN
		DECLARE @ParentProjectCode nvarchar(20)
		SELECT  @ParentProjectCode = ParentProjectCode
		FROM         Project.tbFlow
		WHERE     (ChildProjectCode = @ProjectCode)		
		SET @IsExpense = Project.fnIsExpense(@ParentProjectCode)		
		END	              
	ELSE
		SET @IsExpense = 1
			
	RETURN @IsExpense
	END
GO

PRINT N'Creating Function [Cash].[fnCategoryNamespaceByVersion]...';


GO
CREATE FUNCTION [Cash].[fnCategoryNamespaceByVersion]
(
    @VersionId NVARCHAR(10),
    @CategoryCode NVARCHAR(10)
)
RETURNS NVARCHAR(MAX)
AS
BEGIN
    DECLARE @Result NVARCHAR(MAX);

    IF @VersionId IS NULL OR @CategoryCode IS NULL OR LEN(@CategoryCode) = 0
        RETURN NULL;

    IF NOT EXISTS
    (
        SELECT 1 FROM Cash.tbCategory
        WHERE VersionId = @VersionId AND CategoryCode = @CategoryCode
    )
        RETURN NULL;

    IF NOT EXISTS
    (
        SELECT 1 FROM Cash.tbCategoryTotal
        WHERE VersionId = @VersionId
          AND (ParentCode = @CategoryCode OR ChildCode = @CategoryCode)
    )
    BEGIN
        SELECT @Result = N'Disconnected.' + REPLACE(Category, N' ', N'_')
        FROM Cash.tbCategory
        WHERE VersionId = @VersionId AND CategoryCode = @CategoryCode;

        RETURN App.fnToAlphaNumeric(@Result);
    END;

    ;WITH ParentChoice AS
    (
        SELECT
            edge.ChildCode,
            edge.ParentCode,
            ROW_NUMBER() OVER
            (
                PARTITION BY edge.ChildCode
                ORDER BY parent.DisplayOrder, parent.Category, parent.CategoryCode
            ) AS rn
        FROM Cash.tbCategoryTotal AS edge
        JOIN Cash.tbCategory AS parent
          ON parent.VersionId = edge.VersionId
         AND parent.CategoryCode = edge.ParentCode
        WHERE edge.VersionId = @VersionId
    ),
    ParentCTE AS
    (
        SELECT
            category.CategoryCode,
            REPLACE(category.Category, N' ', N'_') AS [Path],
            CAST(0 AS INT) AS Depth
        FROM Cash.tbCategory AS category
        WHERE category.VersionId = @VersionId
          AND category.CategoryCode = @CategoryCode

        UNION ALL

        SELECT
            parent_choice.ParentCode,
            REPLACE(parent.Category, N' ', N'_') + N'.' + category_path.[Path],
            category_path.Depth + 1
        FROM ParentCTE AS category_path
        JOIN ParentChoice AS parent_choice
          ON parent_choice.ChildCode = category_path.CategoryCode
         AND parent_choice.rn = 1
        JOIN Cash.tbCategory AS parent
          ON parent.VersionId = @VersionId
         AND parent.CategoryCode = parent_choice.ParentCode
    )
    SELECT TOP (1) @Result = [Path]
    FROM ParentCTE
    ORDER BY Depth DESC;

    RETURN App.fnToAlphaNumeric(@Result);
END;
GO

PRINT N'Creating Function [Cash].[fnCategoryNamespaceInContextByVersion]...';


GO
CREATE FUNCTION [Cash].[fnCategoryNamespaceInContextByVersion]
(
    @VersionId NVARCHAR(10),
    @CategoryCode NVARCHAR(10),
    @ParentCode NVARCHAR(10) = NULL
)
RETURNS NVARCHAR(MAX)
AS
BEGIN
    DECLARE @Result NVARCHAR(MAX);

    IF @VersionId IS NULL OR @CategoryCode IS NULL OR LEN(@CategoryCode) = 0
        RETURN NULL;

    IF NOT EXISTS
    (
        SELECT 1 FROM Cash.tbCategory
        WHERE VersionId = @VersionId AND CategoryCode = @CategoryCode
    )
        RETURN NULL;

    IF NOT EXISTS
    (
        SELECT 1 FROM Cash.tbCategoryTotal
        WHERE VersionId = @VersionId
          AND (ParentCode = @CategoryCode OR ChildCode = @CategoryCode)
    )
    BEGIN
        SELECT @Result = N'Disconnected.' + REPLACE(Category, N' ', N'_')
        FROM Cash.tbCategory
        WHERE VersionId = @VersionId AND CategoryCode = @CategoryCode;

        RETURN App.fnToAlphaNumeric(@Result);
    END;

    ;WITH ParentGiven AS
    (
        SELECT edge.ChildCode, edge.ParentCode, 1 AS rn
        FROM Cash.tbCategoryTotal AS edge
        WHERE edge.VersionId = @VersionId
          AND @ParentCode IS NOT NULL
          AND edge.ChildCode = @CategoryCode
          AND edge.ParentCode = @ParentCode
    ),
    ParentRank AS
    (
        SELECT
            edge.ChildCode,
            edge.ParentCode,
            ROW_NUMBER() OVER
            (
                PARTITION BY edge.ChildCode
                ORDER BY parent.DisplayOrder, parent.Category, parent.CategoryCode
            ) AS rn
        FROM Cash.tbCategoryTotal AS edge
        JOIN Cash.tbCategory AS parent
          ON parent.VersionId = edge.VersionId
         AND parent.CategoryCode = edge.ParentCode
        WHERE edge.VersionId = @VersionId
    ),
    ParentMap AS
    (
        SELECT ChildCode, ParentCode FROM ParentGiven
        UNION ALL
        SELECT ranked.ChildCode, ranked.ParentCode
        FROM ParentRank AS ranked
        WHERE ranked.rn = 1
          AND NOT EXISTS
          (
              SELECT 1 FROM ParentGiven AS given
              WHERE given.ChildCode = ranked.ChildCode
          )
    ),
    ParentCTE AS
    (
        SELECT
            category.CategoryCode,
            REPLACE(category.Category, N' ', N'_') AS [Path],
            CAST(0 AS INT) AS Depth
        FROM Cash.tbCategory AS category
        WHERE category.VersionId = @VersionId
          AND category.CategoryCode = @CategoryCode

        UNION ALL

        SELECT
            parent_map.ParentCode,
            REPLACE(parent.Category, N' ', N'_') + N'.' + category_path.[Path],
            category_path.Depth + 1
        FROM ParentCTE AS category_path
        JOIN ParentMap AS parent_map
          ON parent_map.ChildCode = category_path.CategoryCode
        JOIN Cash.tbCategory AS parent
          ON parent.VersionId = @VersionId
         AND parent.CategoryCode = parent_map.ParentCode
    )
    SELECT TOP (1) @Result = [Path]
    FROM ParentCTE
    ORDER BY Depth DESC;

    RETURN App.fnToAlphaNumeric(@Result);
END;
GO

