PRINT N'Creating Function [App].[fnTaxBizCashCodesByVersion]...';


GO
CREATE FUNCTION [App].[fnTaxBizCashCodesByVersion]
(
    @VersionId NVARCHAR(10)
)
RETURNS TABLE
AS
RETURN
(
    WITH category_relations AS
    (
        SELECT
            edge.ParentCode,
            edge.ChildCode,
            category.CategoryTypeCode,
            category.CategoryCode,
            code.CashCode,
            category.CashTypeCode,
            category.CashPolarityCode
        FROM Cash.tbCategoryTotal AS edge
        JOIN Cash.tbCategory AS category
          ON category.VersionId = edge.VersionId
         AND category.CategoryCode = edge.ChildCode
        LEFT JOIN Cash.tbCategoryCodeMap AS map
          ON map.VersionId = category.VersionId
         AND map.CategoryCode = category.CategoryCode
        LEFT JOIN Cash.tbCode AS code
          ON code.CashCode = map.CashCode
        WHERE edge.VersionId = @VersionId
    ),
    cashcode_candidates AS
    (
        SELECT
            relation.ChildCode,
            relation.CategoryCode,
            relation.CashCode,
            relation.CashTypeCode,
            relation.CashPolarityCode
        FROM category_relations AS relation
        JOIN Cash.tbCategoryRoot AS root
          ON root.VersionId = @VersionId
         AND root.RootTypeCode = 0
         AND root.CategoryCode = relation.ParentCode
        WHERE relation.CategoryTypeCode = 1

        UNION ALL

        SELECT
            relation.ChildCode,
            relation.CategoryCode,
            relation.CashCode,
            relation.CashTypeCode,
            relation.CashPolarityCode
        FROM category_relations AS relation
        JOIN cashcode_candidates AS candidate
          ON candidate.ChildCode = relation.ParentCode
    ),
    cashcode_selected AS
    (
        SELECT CategoryCode, CashCode, CashTypeCode, CashPolarityCode
        FROM cashcode_candidates

        UNION

        SELECT
            relation.CategoryCode,
            relation.CashCode,
            relation.CashTypeCode,
            relation.CashPolarityCode
        FROM category_relations AS relation
        JOIN Cash.tbCategoryRoot AS root
          ON root.VersionId = @VersionId
         AND root.RootTypeCode = 0
         AND root.CategoryCode = relation.ParentCode
    )
    SELECT CategoryCode, CashCode, CashTypeCode, CashPolarityCode
    FROM cashcode_selected
    WHERE CashCode IS NOT NULL
);
GO

PRINT N'Creating Function [App].[fnTaxVatCashCodesByVersion]...';


GO
CREATE FUNCTION [App].[fnTaxVatCashCodesByVersion]
(
    @VersionId NVARCHAR(10)
)
RETURNS TABLE
AS
RETURN
(
    WITH vat_enabled AS
    (
        SELECT IsEnabled
        FROM Cash.tbTaxType
        WHERE TaxTypeCode = 1
    ),
    category_relations AS
    (
        SELECT
            edge.ParentCode,
            edge.ChildCode,
            category.CategoryTypeCode,
            code.CashCode
        FROM Cash.tbCategoryTotal AS edge
        JOIN Cash.tbCategory AS category
          ON category.VersionId = edge.VersionId
         AND category.CategoryCode = edge.ChildCode
        LEFT JOIN Cash.tbCategoryCodeMap AS map
          ON map.VersionId = category.VersionId
         AND map.CategoryCode = category.CategoryCode
        LEFT JOIN Cash.tbCode AS code
          ON code.CashCode = map.CashCode
        CROSS JOIN vat_enabled AS vat
        WHERE edge.VersionId = @VersionId
          AND vat.IsEnabled = 1
          AND category.CashTypeCode = 0
          AND category.IsEnabled = 1
          AND (code.CashCode IS NULL OR code.IsEnabled = 1)
    ),
    cashcode_candidates AS
    (
        SELECT relation.ChildCode, relation.CashCode
        FROM category_relations AS relation
        JOIN Cash.tbCategoryRoot AS root
          ON root.VersionId = @VersionId
         AND root.RootTypeCode = 1
         AND root.CategoryCode = relation.ParentCode
        WHERE relation.CategoryTypeCode = 1

        UNION ALL

        SELECT relation.ChildCode, relation.CashCode
        FROM category_relations AS relation
        JOIN cashcode_candidates AS candidate
          ON candidate.ChildCode = relation.ParentCode
    ),
    cashcode_selected AS
    (
        SELECT CashCode
        FROM cashcode_candidates

        UNION

        SELECT relation.CashCode
        FROM category_relations AS relation
        JOIN Cash.tbCategoryRoot AS root
          ON root.VersionId = @VersionId
         AND root.RootTypeCode = 1
         AND root.CategoryCode = relation.ParentCode
    )
    SELECT CashCode
    FROM cashcode_selected
    WHERE CashCode IS NOT NULL
);
GO

PRINT N'Creating Function [Cash].[fnCategoryCashCodesByVersion]...';


GO
CREATE FUNCTION [Cash].[fnCategoryCashCodesByVersion]
(
    @VersionId NVARCHAR(10),
    @CategoryCode NVARCHAR(10)
)
RETURNS TABLE
AS
RETURN
(
    WITH category_tree AS
    (
        SELECT c.CategoryCode, c.CategoryTypeCode
        FROM Cash.tbCategory AS c
        WHERE c.VersionId = @VersionId
          AND c.CategoryCode = @CategoryCode

        UNION ALL

        SELECT edge.ChildCode, child.CategoryTypeCode
        FROM category_tree AS parent
        JOIN Cash.tbCategoryTotal AS edge
          ON edge.VersionId = @VersionId
         AND edge.ParentCode = parent.CategoryCode
        JOIN Cash.tbCategory AS child
          ON child.VersionId = edge.VersionId
         AND child.CategoryCode = edge.ChildCode
        WHERE child.IsEnabled <> 0
    ),
    nominal_categories AS
    (
        SELECT CategoryCode
        FROM category_tree
        WHERE CategoryTypeCode = 0
    )
    SELECT map.CashCode, map.CategoryCode
    FROM Cash.tbCategoryCodeMap AS map
    JOIN nominal_categories AS category
      ON category.CategoryCode = map.CategoryCode
    JOIN Cash.tbCode AS code
      ON code.CashCode = map.CashCode
    WHERE map.VersionId = @VersionId
      AND code.IsEnabled <> 0
);
GO

PRINT N'Creating Function [Cash].[fnCategoryPrimaryParentByVersion]...';


GO
CREATE FUNCTION [Cash].[fnCategoryPrimaryParentByVersion]
(
    @VersionId NVARCHAR(10)
)
RETURNS TABLE
AS
RETURN
(
    WITH roots AS
    (
        SELECT
            root.CategoryCode AS RootCode,
            CASE root.RootTypeCode
                WHEN 0 THEN CAST(N'Profit' AS NVARCHAR(10))
                WHEN 1 THEN CAST(N'VAT' AS NVARCHAR(10))
            END AS PrimaryKind
        FROM Cash.tbCategoryRoot AS root
        WHERE root.VersionId = @VersionId
          AND root.RootTypeCode IN (0, 1)
    ),
    paths AS
    (
        SELECT
            root.RootCode,
            root.PrimaryKind,
            edge.ParentCode,
            edge.ChildCode,
            1 AS Depth
        FROM roots AS root
        JOIN Cash.tbCategoryTotal AS edge
          ON edge.VersionId = @VersionId
         AND edge.ParentCode = root.RootCode

        UNION ALL

        SELECT
            path.RootCode,
            path.PrimaryKind,
            edge.ParentCode,
            edge.ChildCode,
            path.Depth + 1
        FROM paths AS path
        JOIN Cash.tbCategoryTotal AS edge
          ON edge.VersionId = @VersionId
         AND edge.ParentCode = path.ChildCode
    ),
    ranked AS
    (
        SELECT
            path.ChildCode,
            path.ParentCode,
            path.RootCode,
            path.PrimaryKind,
            path.Depth,
            ROW_NUMBER() OVER
            (
                PARTITION BY path.ChildCode
                ORDER BY path.Depth, parent.DisplayOrder, parent.Category, parent.CategoryCode
            ) AS rn
        FROM paths AS path
        JOIN Cash.tbCategory AS parent
          ON parent.VersionId = @VersionId
         AND parent.CategoryCode = path.ParentCode
    ),
    parent_aggregate AS
    (
        SELECT edge.ChildCode, COUNT(*) AS ParentCount
        FROM Cash.tbCategoryTotal AS edge
        WHERE edge.VersionId = @VersionId
        GROUP BY edge.ChildCode
    )
    SELECT
        ranked.ChildCode,
        ranked.ParentCode,
        ranked.RootCode,
        ranked.PrimaryKind,
        ranked.Depth,
        ranked.rn,
        parent_aggregate.ParentCount
    FROM ranked
    LEFT JOIN parent_aggregate
      ON parent_aggregate.ChildCode = ranked.ChildCode
);
GO

PRINT N'Creating Function [Cash].[fnTaxTagCashCodeByVersion]...';


GO
CREATE FUNCTION [Cash].[fnTaxTagCashCodeByVersion]
(
    @VersionId NVARCHAR(10)
)
RETURNS TABLE
AS
RETURN
(
    WITH CategoryTree AS
    (
        SELECT map.TaxSourceCode, map.TagCode,
               map.CategoryCode AS MappingRoot, map.CategoryCode
        FROM Cash.tbTaxTagMap AS map
        JOIN Cash.tbCategory AS root
          ON root.VersionId = @VersionId
         AND root.CategoryCode = map.CategoryCode
         AND root.CategoryTypeCode IN (0, 1)
         AND root.IsEnabled = 1
        WHERE map.MapTypeCode = 0 AND map.IsEnabled = 1

        UNION ALL

        SELECT parent.TaxSourceCode, parent.TagCode,
               parent.MappingRoot, edge.ChildCode
        FROM CategoryTree AS parent
        JOIN Cash.tbCategoryTotal AS edge
          ON edge.VersionId = @VersionId
         AND edge.ParentCode = parent.CategoryCode
        JOIN Cash.tbCategory AS child
          ON child.VersionId = edge.VersionId
         AND child.CategoryCode = edge.ChildCode
         AND child.CategoryTypeCode IN (0, 1)
         AND child.IsEnabled = 1
    ),
    CategoryMappings AS
    (
        SELECT tree.TaxSourceCode, tree.TagCode,
               CONVERT(TINYINT, 0) AS MapTypeCode, tree.MappingRoot,
               map.CashCode, map.CategoryCode AS LeafCategoryCode,
               category.CashPolarityCode
        FROM CategoryTree AS tree
        JOIN Cash.tbCategory AS category
          ON category.VersionId = @VersionId
         AND category.CategoryCode = tree.CategoryCode
         AND category.CategoryTypeCode = 0
         AND category.IsEnabled = 1
        JOIN Cash.tbCategoryCodeMap AS map
          ON map.VersionId = @VersionId
         AND map.CategoryCode = category.CategoryCode
        JOIN Cash.tbCode AS code
          ON code.CashCode = map.CashCode
         AND code.IsEnabled = 1
    ),
    CashCodeMappings AS
    (
        SELECT tag_map.TaxSourceCode, tag_map.TagCode,
               CONVERT(TINYINT, 1) AS MapTypeCode,
               tag_map.CashCode AS MappingRoot, code.CashCode,
               map.CategoryCode AS LeafCategoryCode,
               category.CashPolarityCode
        FROM Cash.tbTaxTagMap AS tag_map
        JOIN Cash.tbCode AS code
          ON code.CashCode = tag_map.CashCode
         AND code.IsEnabled = 1
        JOIN Cash.tbCategoryCodeMap AS map
          ON map.VersionId = @VersionId
         AND map.CashCode = code.CashCode
        JOIN Cash.tbCategory AS category
          ON category.VersionId = map.VersionId
         AND category.CategoryCode = map.CategoryCode
         AND category.CategoryTypeCode = 0
         AND category.IsEnabled = 1
        WHERE tag_map.MapTypeCode = 1 AND tag_map.IsEnabled = 1
    )
    SELECT TaxSourceCode, TagCode, MapTypeCode, MappingRoot,
           CashCode, LeafCategoryCode, CashPolarityCode
    FROM CategoryMappings
    UNION ALL
    SELECT TaxSourceCode, TagCode, MapTypeCode, MappingRoot,
           CashCode, LeafCategoryCode, CashPolarityCode
    FROM CashCodeMappings
);
GO

PRINT N'Creating Function [Cash].[fnCategoryNamespacePrimaryByVersion]...';


GO
CREATE FUNCTION [Cash].[fnCategoryNamespacePrimaryByVersion]
(
    @VersionId NVARCHAR(10),
    @CategoryCode NVARCHAR(10)
)
RETURNS NVARCHAR(MAX)
AS
BEGIN
    DECLARE @Result NVARCHAR(MAX);

    IF @VersionId IS NULL OR @CategoryCode IS NULL OR LEN(@CategoryCode) = 0
        RETURN NULL;

    IF NOT EXISTS
    (
        SELECT 1 FROM Cash.tbCategory
        WHERE VersionId = @VersionId AND CategoryCode = @CategoryCode
    )
        RETURN NULL;

    IF NOT EXISTS
    (
        SELECT 1 FROM Cash.tbCategoryTotal
        WHERE VersionId = @VersionId
          AND (ParentCode = @CategoryCode OR ChildCode = @CategoryCode)
    )
    BEGIN
        SELECT @Result = N'Disconnected.' + REPLACE(Category, N' ', N'_')
        FROM Cash.tbCategory
        WHERE VersionId = @VersionId AND CategoryCode = @CategoryCode;

        RETURN App.fnToAlphaNumeric(@Result);
    END;

    ;WITH ParentMap AS
    (
        SELECT ChildCode, ParentCode
        FROM Cash.fnCategoryPrimaryParentByVersion(@VersionId)
        WHERE rn = 1
    ),
    ParentCTE AS
    (
        SELECT
            category.CategoryCode,
            REPLACE(category.Category, N' ', N'_') AS [Path],
            CAST(0 AS INT) AS Depth
        FROM Cash.tbCategory AS category
        WHERE category.VersionId = @VersionId
          AND category.CategoryCode = @CategoryCode

        UNION ALL

        SELECT
            parent_map.ParentCode,
            REPLACE(parent.Category, N' ', N'_') + N'.' + category_path.[Path],
            category_path.Depth + 1
        FROM ParentCTE AS category_path
        JOIN ParentMap AS parent_map
          ON parent_map.ChildCode = category_path.CategoryCode
        JOIN Cash.tbCategory AS parent
          ON parent.VersionId = @VersionId
         AND parent.CategoryCode = parent_map.ParentCode
    )
    SELECT TOP (1) @Result = [Path]
    FROM ParentCTE
    ORDER BY Depth DESC;

    RETURN App.fnToAlphaNumeric(@Result);
END;
GO

