PRINT N'Altering View [Cash].[vwStatementBase]...';


GO
ALTER VIEW Cash.vwStatementBase
AS
	--invoiced taxes
	WITH biz_taxcode AS
	(
		SELECT TOP (1) SubjectCode, CashCode 
		FROM Cash.tbTaxType WHERE (TaxTypeCode = 0)
	), biztax_invoiced_entries AS
	(
		SELECT SubjectCode, CashCode, StartOn, TaxDue, Balance,
			ROW_NUMBER() OVER (ORDER BY StartOn) AS RowNumber 
		FROM Cash.vwTaxBizStatement CROSS JOIN biz_taxcode
		WHERE (Balance <> 0) AND (StartOn >= (SELECT MIN(StartOn) FROM App.tbYearPeriod WHERE CashStatusCode < 2))
	), biztax_invoiced_owing AS
	(
		SELECT SubjectCode, CashCode EntryDescription, StartOn AS TransactOn, 4 AS CashEntryTypeCode, 
			(SELECT CAST(Message AS NVARCHAR) FROM App.tbText WHERE TextId = 1214) ReferenceCode, 0 AS PayIn,
			CASE RowNumber WHEN 1 THEN Balance ELSE TaxDue END AS PayOut
		FROM biztax_invoiced_entries
	), vat_taxcode AS
	(
		SELECT TOP (1) SubjectCode, CashCode 
		FROM Cash.tbTaxType WHERE (TaxTypeCode = 1)
	), vat_totals AS
	(
		SELECT ROW_NUMBER() OVER (ORDER BY RowNumber DESC) AS Id, StartOn AS TransactOn, VatDue,
			CASE WHEN VatPaid  < 0 OR Balance <= 0 THEN NULL ELSE 1 END IsLive
		FROM Cash.vwTaxVatStatement
	), vat_invoiced_owing AS
	(
		SELECT SubjectCode, CashCode EntryDescription, TransactOn, 5 AS CashEntryTypeCode, 
			(SELECT CAST(Message AS NVARCHAR) FROM App.tbText WHERE TextId = 1214) ReferenceCode, 
			CASE WHEN VatDue < 0 THEN ABS(VatDue) ELSE 0 END AS PayIn,
			CASE WHEN VatDue >= 0 THEN VatDue ELSE 0 END AS PayOut
		FROM vat_totals CROSS JOIN vat_taxcode
		WHERE Id < COALESCE((SELECT TOP 1 t.Id FROM vat_totals t WHERE t.IsLive IS NULL ORDER BY Id), (SELECT MIN(Id) + 1 FROM vat_totals))
	)
	--uninvoiced taxes
	, biztax_dates AS
	(
		SELECT PayOn, PayFrom, PayTo FROM Cash.fnTaxTypeDueDates(0, 0)
	), biztax_accrual_entries AS
	(
		SELECT StartOn, SUM(TaxDue) AS TaxDue
		FROM Cash.vwTaxBizAccruals
		GROUP BY StartOn
	), biztax_accrual_candidates AS
	(
		SELECT (SELECT PayOn FROM biztax_dates WHERE biztax_accrual_entries.StartOn >= PayFrom AND biztax_accrual_entries.StartOn < PayTo) AS TransactOn, TaxDue
		FROM biztax_accrual_entries 
	), biztax_accrual_totals AS
	(
		SELECT TransactOn, SUM(TaxDue) AS TaxDue
		FROM biztax_accrual_candidates
		GROUP BY TransactOn
	)
	, biztax_accruals AS
	(
		SELECT SubjectCode, CashCode EntryDescription, TransactOn, 4 AS CashEntryTypeCode, 
			(SELECT CAST(Message AS NVARCHAR) FROM App.tbText WHERE TextId = 1215) ReferenceCode, 
			CASE WHEN TaxDue < 0 THEN ABS(TaxDue) ELSE 0 END AS PayIn,
			CASE WHEN TaxDue >= 0 THEN TaxDue ELSE 0 END AS PayOut
		FROM biztax_accrual_totals CROSS JOIN biz_taxcode
	), vat_dates AS
	(
		SELECT PayOn, PayFrom, PayTo FROM Cash.fnTaxTypeDueDates(1, 0)
	), vat_accrual_entries AS
	(
		SELECT StartOn, SUM(netVatDue) AS TaxDue 
		FROM Cash.vwTaxVatAccruals vat_audit
		WHERE vat_audit.netVatDue <> 0
		GROUP BY StartOn
	), vat_accrual_candidates AS
	(
		SELECT (SELECT PayOn FROM vat_dates WHERE vat_accrual_entries.StartOn >= PayFrom AND vat_accrual_entries.StartOn < PayTo) AS TransactOn, TaxDue
		FROM vat_accrual_entries 
	), vat_accrual_totals AS
	(
		SELECT TransactOn, SUM(TaxDue) AS TaxDue
		FROM vat_accrual_candidates
		GROUP BY TransactOn
	), vat_accruals AS
	(
		SELECT vat_taxcode.SubjectCode, vat_taxcode.CashCode EntryDescription, TransactOn, 5 AS CashEntryTypeCode, 
			(SELECT CAST(Message AS NVARCHAR) FROM App.tbText WHERE TextId = 1215) ReferenceCode,
			CASE WHEN TaxDue < 0 THEN ABS(TaxDue) ELSE 0 END AS PayIn,
			CASE WHEN TaxDue >= 0 THEN TaxDue ELSE 0 END AS PayOut
		FROM vat_accrual_totals
			CROSS JOIN vat_taxcode
	)
	--unpaid invoices
	, invoice_desc_candidates AS
	(
		SELECT invoice_Projects.InvoiceNumber, 0 OrderBy, 
			FIRST_VALUE(invoiced_Project.ObjectCode) OVER (PARTITION BY invoice_Projects.InvoiceNumber ORDER BY invoice_Projects.ProjectCode) EntryDescription
		FROM Invoice.tbProject invoice_Projects 
			JOIN Project.tbProject invoiced_Project ON invoice_Projects.ProjectCode = invoiced_Project.ProjectCode
			JOIN Invoice.tbInvoice invoices ON invoices.InvoiceNumber = invoice_Projects.InvoiceNumber
		WHERE (InvoiceStatusCode BETWEEN 1 AND 2)
		UNION
		SELECT invoice_items.InvoiceNumber, 1 OrderBy, 
			FIRST_VALUE(cash_code.CashDescription) OVER (PARTITION BY invoice_items.InvoiceNumber ORDER BY invoice_items.CashCode) EntryDescription
		FROM Invoice.tbItem invoice_items 
			JOIN Cash.tbCode cash_code ON invoice_items.CashCode = cash_code.CashCode
			JOIN Invoice.tbInvoice invoices ON invoices.InvoiceNumber = invoice_items.InvoiceNumber
		WHERE (InvoiceStatusCode BETWEEN 1 AND 2)
	), invoice_desc AS
	(
		SELECT InvoiceNumber,
			FIRST_VALUE(EntryDescription) OVER (PARTITION BY InvoiceNumber ORDER BY OrderBy) EntryDescription
		FROM invoice_desc_candidates
	), invoices_outstanding AS
	(
		SELECT invoices.SubjectCode, invoice_desc.EntryDescription, invoices.ExpectedOn AS TransactOn, 1 AS CashEntryTypeCode, invoices.InvoiceNumber AS ReferenceCode, 
			CASE CashPolarityCode WHEN 1 THEN InvoiceValue + TaxValue - (PaidValue + PaidTaxValue) ELSE 0 END AS PayIn, 
			CASE CashPolarityCode WHEN 0 THEN (InvoiceValue + TaxValue) - (PaidValue + PaidTaxValue) ELSE 0 END AS PayOut
		FROM Invoice.tbInvoice invoices
			JOIN Invoice.tbType invoice_type ON invoices.InvoiceTypeCode = invoice_type.InvoiceTypeCode
			JOIN invoice_desc ON invoices.InvoiceNumber = invoice_desc.InvoiceNumber
		WHERE (InvoiceStatusCode < 3) AND ((InvoiceValue + TaxValue - PaidValue + PaidTaxValue) > 0)
	), Project_invoiced_quantity AS
	(
		SELECT Invoice.tbProject.ProjectCode, SUM(Invoice.tbProject.Quantity) AS InvoiceQuantity
		FROM Invoice.tbProject
			INNER JOIN Invoice.tbInvoice ON Invoice.tbProject.InvoiceNumber = Invoice.tbInvoice.InvoiceNumber
		WHERE (Invoice.tbInvoice.InvoiceTypeCode = 0) OR (Invoice.tbInvoice.InvoiceTypeCode = 2)
		GROUP BY Invoice.tbProject.ProjectCode
	), Projects_confirmed AS
	(
		SELECT
			Project.tbProject.ProjectCode AS ReferenceCode,
			Project.tbProject.SubjectCode,
			Project.tbProject.PaymentOn AS TransactOn,
			Project.tbProject.PaymentOn,
			2 AS CashEntryTypeCode,
			CASE WHEN category.CashPolarityCode = 0 THEN (Project.tbProject.UnitCharge + Project.tbProject.UnitCharge * App.tbTaxCode.TaxRate) * (Project.tbProject.Quantity - ISNULL(Project_invoiced_quantity.InvoiceQuantity, 0)) ELSE 0 END AS PayOut,
			CASE WHEN category.CashPolarityCode = 1 THEN (Project.tbProject.UnitCharge + Project.tbProject.UnitCharge * App.tbTaxCode.TaxRate) * (Project.tbProject.Quantity - ISNULL(Project_invoiced_quantity.InvoiceQuantity, 0)) ELSE 0 END AS PayIn,
			Project.tbProject.ObjectCode EntryDescription
		FROM App.tbTaxCode
			INNER JOIN Project.tbProject ON App.tbTaxCode.TaxCode = Project.tbProject.TaxCode
			INNER JOIN Cash.vwCodeActive AS code ON Project.tbProject.CashCode = code.CashCode
			INNER JOIN Cash.vwCategoryActive AS category ON code.CategoryCode = category.CategoryCode
			LEFT OUTER JOIN Project_invoiced_quantity ON Project.tbProject.ProjectCode = Project_invoiced_quantity.ProjectCode
		WHERE (Project.tbProject.ProjectStatusCode > 0) AND (Project.tbProject.ProjectStatusCode < 3) AND (Project.tbProject.Quantity - ISNULL(Project_invoiced_quantity.InvoiceQuantity, 0) > 0)
	)
	--interbank transfers
	, transfer_current_account AS
	(
		SELECT Subject.tbAccount.AccountCode
		FROM Subject.tbAccount
			INNER JOIN Cash.vwCodeActive AS code ON Subject.tbAccount.CashCode = code.CashCode
			INNER JOIN Cash.vwCategoryActive AS category ON code.CategoryCode = category.CategoryCode
		WHERE category.CashTypeCode = 2
	), transfer_accruals AS
	(
		SELECT Cash.tbPayment.SubjectCode, Cash.tbPayment.CashCode EntryDescription, Cash.tbPayment.PaidOn AS TransactOn, Cash.tbPayment.PaymentCode AS ReferenceCode, 
			6 AS CashEntryTypeCode, Cash.tbPayment.PaidInValue AS PayIn, Cash.tbPayment.PaidOutValue AS PayOut
		FROM transfer_current_account
			INNER JOIN Cash.tbPayment ON transfer_current_account.AccountCode = Cash.tbPayment.AccountCode
		WHERE (Cash.tbPayment.PaymentStatusCode = 2)
	)
	SELECT SubjectCode, EntryDescription, TransactOn, ReferenceCode, CashEntryTypeCode, PayIn, PayOut FROM biztax_invoiced_owing
	UNION
	SELECT SubjectCode, EntryDescription, TransactOn, ReferenceCode, CashEntryTypeCode, PayIn, PayOut FROM vat_invoiced_owing
	UNION
	SELECT SubjectCode, EntryDescription, TransactOn, ReferenceCode, CashEntryTypeCode, PayIn, PayOut FROM biztax_accruals
	UNION
	SELECT SubjectCode, EntryDescription, TransactOn, ReferenceCode, CashEntryTypeCode, PayIn, PayOut FROM vat_accruals
	UNION
	SELECT SubjectCode, EntryDescription, TransactOn, ReferenceCode, CashEntryTypeCode, PayIn, PayOut FROM invoices_outstanding
	UNION 
	SELECT SubjectCode, EntryDescription, TransactOn, ReferenceCode, CashEntryTypeCode, PayIn, PayOut FROM Projects_confirmed
	UNION
	SELECT SubjectCode, EntryDescription, TransactOn, ReferenceCode, CashEntryTypeCode, PayIn, PayOut FROM transfer_accruals;
GO

PRINT N'Creating Function [Cash].[fnTaxBizBalanceSheet]...';


GO
CREATE FUNCTION Cash.fnTaxBizBalanceSheet
(
    @TaxSourceCode NVARCHAR(20),
    @AsOfDate DATE
)
RETURNS @Projection TABLE
(
    TaxSourceCode NVARCHAR(20) NOT NULL,
    AsOfDate DATE NOT NULL,
    PeriodStart DATE NULL,
    ValidationStatus NVARCHAR(12) NOT NULL,
    TagCode NVARCHAR(64) NOT NULL,
    ValueState NVARCHAR(20) NOT NULL,
    SupportStatus NVARCHAR(16) NOT NULL,
    StatutoryAmount DECIMAL(18, 5) NULL,
    SnapshotRowVer BINARY(8) NOT NULL
)
AS
BEGIN
    DECLARE @SnapshotPeriodStart DATE =
    (
        SELECT MAX(CONVERT(DATE, StartOn))
        FROM App.tbYearPeriod
        WHERE CONVERT(DATE, StartOn) <= @AsOfDate
    );
    DECLARE @MappingsValid BIT = CASE WHEN EXISTS
        (SELECT 1 FROM Cash.fnTaxTagMapValidate(@TaxSourceCode) WHERE IsError = 1)
        THEN 0 ELSE 1 END;
    DECLARE @SnapshotRowVer BINARY(8) = CONVERT(BINARY(8), @@DBTS);
    DECLARE @NonCurrentAssets DECIMAL(18, 5) = 0;
    DECLARE @CurrentAssets DECIMAL(18, 5) = 0;
    DECLARE @CurrentLiabilities DECIMAL(18, 5) = 0;
    DECLARE @NonCurrentLiabilities DECIMAL(18, 5) = 0;

    ;WITH EffectiveAccountMappings AS
    (
        SELECT DISTINCT
            CASE mapping.MappingRoot
                WHEN N'CA-LIAB' THEN N'BalanceSheet.NonCurrentLiabilities'
                ELSE N'BalanceSheet.NonCurrentAssets'
            END AS BalanceClassCode,
            account.AccountCode
        FROM Cash.vwTaxTagCashCode mapping
        JOIN Subject.tbAccount account
          ON account.CashCode = mapping.CashCode
         AND account.AccountTypeCode = 2
         AND account.AccountClosed = 0
        WHERE mapping.TaxSourceCode = @TaxSourceCode
          AND mapping.MappingRoot IN (N'CA-ASSET', N'CA-DEPREC', N'CA-LIAB')
    )
    SELECT
        @NonCurrentAssets = COALESCE(SUM(CONVERT(DECIMAL(18, 5),
            CASE mapping.BalanceClassCode
                WHEN N'BalanceSheet.NonCurrentAssets' THEN balance.Balance
                ELSE 0
            END)), 0),
        @NonCurrentLiabilities = COALESCE(SUM(CONVERT(DECIMAL(18, 5),
            CASE mapping.BalanceClassCode
                WHEN N'BalanceSheet.NonCurrentLiabilities' THEN balance.Balance * -1
                ELSE 0
            END)), 0)
    FROM EffectiveAccountMappings mapping
    JOIN Cash.vwBalanceSheetAssets balance
      ON balance.AssetCode = mapping.AccountCode
     AND CONVERT(DATE, balance.StartOn) = @SnapshotPeriodStart;

    SELECT @CurrentAssets = COALESCE(SUM(source.StatutoryAmount), 0)
    FROM
    (
        SELECT CONVERT(DECIMAL(18, 5), Balance) AS StatutoryAmount
        FROM Cash.vwBalanceSheetSubjects
        WHERE AssetTypeCode = 0
          AND CONVERT(DATE, StartOn) = @SnapshotPeriodStart

        UNION ALL

        SELECT CONVERT(DECIMAL(18, 5), Balance)
        FROM Cash.vwBalanceSheetAccounts
        WHERE AssetTypeCode IN (2, 3)
          AND CONVERT(DATE, StartOn) = @SnapshotPeriodStart
    ) source;

    SELECT @CurrentLiabilities = COALESCE(SUM(source.StatutoryAmount), 0)
    FROM
    (
        SELECT CONVERT(DECIMAL(18, 5), Balance * -1) AS StatutoryAmount
        FROM Cash.vwBalanceSheetSubjects
        WHERE AssetTypeCode = 1
          AND CONVERT(DATE, StartOn) = @SnapshotPeriodStart

        UNION ALL

        SELECT CONVERT(DECIMAL(18, 5), Balance * -1)
        FROM Cash.vwBalanceSheetTax
        WHERE CONVERT(DATE, StartOn) = @SnapshotPeriodStart

        UNION ALL

        SELECT CONVERT(DECIMAL(18, 5), Balance * -1)
        FROM Cash.vwBalanceSheetVat
        WHERE CONVERT(DATE, StartOn) = @SnapshotPeriodStart
    ) source;

    INSERT INTO @Projection
    SELECT
        @TaxSourceCode,
        @AsOfDate,
        @SnapshotPeriodStart,
        CASE WHEN @SnapshotPeriodStart IS NOT NULL AND @MappingsValid = 1 THEN N'Ready' ELSE N'Invalid' END,
        value.TagCode,
        N'Source',
        CASE WHEN @SnapshotPeriodStart IS NOT NULL AND @MappingsValid = 1 THEN N'Supported' ELSE N'Invalid' END,
        CASE WHEN @SnapshotPeriodStart IS NOT NULL AND @MappingsValid = 1 THEN value.StatutoryAmount END,
        @SnapshotRowVer
    FROM
    (
        VALUES
            (N'BalanceSheet.NonCurrentAssets', @NonCurrentAssets),
            (N'BalanceSheet.CurrentAssets', @CurrentAssets),
            (N'BalanceSheet.CurrentLiabilities', @CurrentLiabilities),
            (N'BalanceSheet.NonCurrentLiabilities', @NonCurrentLiabilities)
    ) value(TagCode, StatutoryAmount);

    RETURN;
END;
GO

PRINT N'Creating Function [Cash].[fnTaxBizBalanceSheetUK]...';


GO
CREATE FUNCTION Cash.fnTaxBizBalanceSheetUK
(
    @TaxSourceCode NVARCHAR(20),
    @AsOfDate DATE
)
RETURNS TABLE
AS
RETURN
(
    SELECT
        TaxSourceCode,
        AsOfDate,
        PeriodStart,
        ValidationStatus,
        CONVERT(NVARCHAR(64), CASE TagCode
            WHEN N'BalanceSheet.NonCurrentAssets' THEN N'BalanceSheet.FixedAssets'
            WHEN N'BalanceSheet.CurrentAssets' THEN N'BalanceSheet.CurrentAssets'
            WHEN N'BalanceSheet.CurrentLiabilities' THEN N'BalanceSheet.CreditorsDueWithinOneYear'
            WHEN N'BalanceSheet.NonCurrentLiabilities' THEN N'BalanceSheet.CreditorsDueAfterOneYear'
        END) AS TagCode,
        ValueState,
        SupportStatus,
        StatutoryAmount,
        SnapshotRowVer
    FROM Cash.fnTaxBizBalanceSheet(@TaxSourceCode, @AsOfDate)
);
GO

PRINT N'Creating Function [Cash].[fnTaxBizCumulative]...';


GO
CREATE FUNCTION Cash.fnTaxBizCumulative
(
    @TaxSourceCode NVARCHAR(20),
    @PeriodStart DATE,
    @PeriodEnd DATE
)
RETURNS @Projection TABLE
(
    TaxSourceCode NVARCHAR(20) NOT NULL,
    PeriodStart DATE NOT NULL,
    PeriodEnd DATE NOT NULL,
    ValidationStatus NVARCHAR(12) NOT NULL,
    TagCode NVARCHAR(64) NOT NULL,
    CashPolarityCode SMALLINT NOT NULL,
    Orientation NVARCHAR(10) NOT NULL,
    SupportStatus NVARCHAR(12) NOT NULL,
    TradeControlAmount DECIMAL(18, 5) NULL,
    StatutoryAmount DECIMAL(18, 5) NULL
)
AS
BEGIN
    DECLARE @DatesValid BIT = CASE
        WHEN @PeriodStart < @PeriodEnd THEN 1 ELSE 0 END;
    DECLARE @MappingsValid BIT = CASE WHEN EXISTS
        (SELECT 1 FROM Cash.fnTaxTagMapValidate(@TaxSourceCode) WHERE IsError = 1)
        THEN 0 ELSE 1 END;

    ;WITH Effective AS
    (
        SELECT DISTINCT TaxSourceCode, TagCode, CashCode, CashPolarityCode
        FROM Cash.vwTaxTagCashCode
        WHERE TaxSourceCode = @TaxSourceCode
    ),
    Amounts AS
    (
        SELECT
            e.TagCode,
            SUM(COALESCE(p.InvoiceValue, 0)) AS TradeControlAmount
        FROM Effective e
        LEFT JOIN Cash.vwCashCodePeriodValues p
          ON p.CashCode = e.CashCode
         AND p.CashPolarityCode = e.CashPolarityCode
         AND CAST(p.StartOn AS DATE) >= @PeriodStart
         AND CAST(p.StartOn AS DATE) < @PeriodEnd
        GROUP BY e.TagCode
    )
    INSERT INTO @Projection
    SELECT
        t.TaxSourceCode,
        @PeriodStart,
        @PeriodEnd,
        CASE WHEN @DatesValid = 1 AND @MappingsValid = 1 THEN N'Ready' ELSE N'Invalid' END,
        t.TagCode,
        t.CashPolarityCode,
        CASE t.CashPolarityCode WHEN 1 THEN N'Income' ELSE N'Expense' END,
        CASE
            WHEN @DatesValid = 0 OR @MappingsValid = 0 THEN N'Invalid'
            WHEN a.TagCode IS NULL THEN N'Unsupported'
            ELSE N'Supported'
        END,
        CASE WHEN @DatesValid = 1 AND @MappingsValid = 1 THEN a.TradeControlAmount END,
        CASE
            WHEN @DatesValid = 0 OR @MappingsValid = 0 OR a.TagCode IS NULL THEN NULL
            WHEN t.CashPolarityCode = 0 THEN a.TradeControlAmount * -1
            ELSE a.TradeControlAmount
        END
    FROM Cash.tbTaxTag t
    LEFT JOIN Amounts a ON a.TagCode = t.TagCode
    WHERE t.TaxSourceCode = @TaxSourceCode;

    RETURN;
END;
GO

