PRINT N'Altering Procedure [Cash].[proc_TaxAdjustmentGet]...';


GO
ALTER PROCEDURE [Cash].[proc_TaxAdjustmentGet]
(
	@StartOn datetime,
	@TaxTypeCode smallint,
	@TaxAdjustment decimal(18, 5) OUTPUT,
	@TaxAdjustmentNote nvarchar(max) OUTPUT
)
AS
	SET NOCOUNT, XACT_ABORT ON;

	BEGIN TRY
		DECLARE
			@PayTo datetime,
			@PayFrom datetime;

		SELECT
			@PayFrom = PayFrom,
			@PayTo = PayTo
		FROM Cash.fnTaxTypeDueDates(@TaxTypeCode, 0) due_dates
		WHERE @StartOn >= due_dates.PayFrom AND @StartOn < due_dates.PayTo;

		SELECT @StartOn = MAX(StartOn)
		FROM App.tbYearPeriod
		WHERE StartOn < @PayTo;

		SELECT @TaxAdjustment =
			CASE 
				WHEN @TaxTypeCode IN (0, 4) THEN BusinessTaxAdjustment
				WHEN @TaxTypeCode = 1 THEN VatAdjustment
				ELSE 0
			END
		FROM App.tbYearPeriod
		WHERE StartOn = @StartOn;

		SELECT @TaxAdjustmentNote =
			CASE
				WHEN @TaxTypeCode IN (0, 4) THEN BusinessTaxAdjustmentNote
				WHEN @TaxTypeCode = 1 THEN VatAdjustmentNote
				ELSE NULL
			END
		FROM App.tbYearPeriod
		WHERE StartOn = @StartOn;
	END TRY
	BEGIN CATCH
		EXEC App.proc_ErrorLog;
	END CATCH
GO

PRINT N'Altering Procedure [Cash].[proc_FlowCategoryCodeFromName]...';


GO

ALTER   PROCEDURE Cash.proc_FlowCategoryCodeFromName
	(
		@Category nvarchar(100),
		@CategoryCode nvarchar(50) output
	)
AS
	SET NOCOUNT, XACT_ABORT ON;

	BEGIN TRY
		IF EXISTS (SELECT 1 FROM Cash.vwCategoryActive WHERE CategoryCode = @Category)
			SET @CategoryCode = @Category;
		ELSE IF EXISTS (SELECT 1 FROM Cash.vwCodeActive WHERE CashCode = @Category)
			SET @CategoryCode = @Category;
		ELSE IF (SELECT COUNT(*) FROM Cash.vwCategoryActive WHERE Category = @Category) = 1
			SELECT @CategoryCode = CategoryCode FROM Cash.vwCategoryActive WHERE Category = @Category;
		ELSE IF NOT EXISTS (SELECT 1 FROM Cash.vwCategoryActive WHERE Category = @Category)
			AND (SELECT COUNT(*) FROM Cash.vwCodeActive WHERE CashDescription = @Category) = 1
			SELECT @CategoryCode = CashCode FROM Cash.vwCodeActive WHERE CashDescription = @Category;
		ELSE
			SET @CategoryCode = N'';
    END TRY
	BEGIN CATCH
		EXEC App.proc_ErrorLog;
	END CATCH
GO

PRINT N'Altering Procedure [App].[proc_Template_DisableVAT]...';


GO
ALTER PROCEDURE [App].[proc_Template_DisableVAT]
    @CategoryVersionId NVARCHAR(10)
AS
SET NOCOUNT, XACT_ABORT ON;

BEGIN TRY

    BEGIN TRAN DisableVAT;

    ----------------------------------------------------------------
    -- 1. Disable VAT categories
    ----------------------------------------------------------------
    UPDATE Cash.tbCategory
    SET IsEnabled = 0
    WHERE VersionId = @CategoryVersionId
      AND CategoryCode IN ('TC-VAT', 'TC-TAXGD');

    ----------------------------------------------------------------
    -- 2. Disable VAT control Cash Codes
    ----------------------------------------------------------------
    UPDATE Cash.tbCode
    SET IsEnabled = 0
    WHERE CashCode IN ('TC600', 'TC501', 'TC602');

    ----------------------------------------------------------------
    -- 3. Default all VAT-bearing Cash Codes to zero-rated (T0)
    --    Preserve special codes such as 'N/A'
    ----------------------------------------------------------------
    UPDATE C
    SET C.TaxCode = 'T0'
    FROM Cash.tbCode C
    WHERE C.TaxCode <> 'T0'
      AND C.TaxCode NOT IN ('N/A');

    ----------------------------------------------------------------
    -- 4. Zero VAT Rates
    ----------------------------------------------------------------
    UPDATE App.tbTaxCode
    SET TaxRate = 0
    WHERE TaxRate != 0;

    ----------------------------------------------------------------
    -- 5. Disable VAT postings/statements via tax type enablement
    --    Leave App.tbTaxCode rates intact for "what-if" analysis.
    ----------------------------------------------------------------
    UPDATE Cash.tbTaxType
    SET IsEnabled = 0
    WHERE TaxTypeCode = 1;

    COMMIT TRAN DisableVAT;

END TRY
BEGIN CATCH
    EXEC App.proc_ErrorLog;
END CATCH;
GO

