PRINT N'Altering Procedure [Cash].[proc_GeneratePeriods]...';


GO
ALTER PROCEDURE Cash.proc_GeneratePeriods
AS
 	SET NOCOUNT, XACT_ABORT ON;

	BEGIN TRY
	DECLARE 
		@YearNumber smallint
		, @StartOn datetime
		, @PeriodStartOn datetime
		, @CashStatusCode smallint
		, @Period smallint
	
		DECLARE curYr cursor for	
			SELECT     YearNumber, CAST(CONCAT(FORMAT(YearNumber, '0000'), FORMAT(StartMonth, '00'), FORMAT(1, '00')) AS DATE) AS StartOn, CashStatusCode
			FROM         App.tbYear
			WHERE CashStatusCode < 2

		OPEN curYr
	
		FETCH NEXT FROM curYr INTO @YearNumber, @StartOn, @CashStatusCode
		WHILE @@FETCH_STATUS = 0
			BEGIN
			SET @PeriodStartOn = @StartOn
			SET @Period = 1
			WHILE @Period < 13
				BEGIN
				IF not EXISTS (SELECT MonthNumber FROM App.tbYearPeriod WHERE YearNumber = @YearNumber and MonthNumber = DATEPART(m, @PeriodStartOn))
					BEGIN
					INSERT INTO App.tbYearPeriod (YearNumber, StartOn, MonthNumber, CashStatusCode)
					VALUES (@YearNumber, @PeriodStartOn, DATEPART(m, @PeriodStartOn), 0)				
					END
				SET @PeriodStartOn = DATEADD(m, 1, @PeriodStartOn)	
				SET @Period = @Period + 1
				END		
				
			FETCH NEXT FROM curYr INTO @YearNumber, @StartOn, @CashStatusCode
			END
	
		CLOSE curYr
		DEALLOCATE curYr
	
		INSERT INTO Cash.tbPeriod
							  (CashCode, StartOn)
		SELECT     Cash.vwPeriods.CashCode, Cash.vwPeriods.StartOn
		FROM         Cash.vwPeriods LEFT OUTER JOIN
							  Cash.tbPeriod ON Cash.vwPeriods.CashCode = Cash.tbPeriod.CashCode AND Cash.vwPeriods.StartOn = Cash.tbPeriod.StartOn
		WHERE     ( Cash.tbPeriod.CashCode IS NULL)
		 
		UPDATE Cash.tbPeriod
		SET InvoiceValue = 0, InvoiceTax = 0;
		
		WITH invoice_entries AS
		(
			SELECT invoices.CashCode, invoices.StartOn, categories.CashPolarityCode, SUM(invoices.InvoiceValue) InvoiceValue, SUM(invoices.TaxValue) TaxValue
			FROM  Invoice.vwRegisterDetail invoices
				JOIN Cash.vwCodeActive cash_codes ON invoices.CashCode = cash_codes.CashCode 
				JOIN Cash.vwCategoryActive categories ON cash_codes.CategoryCode = categories .CategoryCode
			WHERE   (StartOn < (SELECT StartOn FROM App.fnActivePeriod()))
			GROUP BY invoices.CashCode, invoices.StartOn, categories.CashPolarityCode
		), invoice_summary AS
		(
			SELECT CashCode, StartOn,
				CASE CashPolarityCode 
					WHEN 0 THEN
						InvoiceValue * -1
					ELSE 
						InvoiceValue
				END AS InvoiceValue,
				CASE CashPolarityCode 
					WHEN 0 THEN
						TaxValue * -1
					ELSE 
						TaxValue
				END AS TaxValue						
			FROM invoice_entries
		)
		UPDATE Cash.tbPeriod
		SET InvoiceValue = invoice_summary.InvoiceValue, 
			InvoiceTax = invoice_summary.TaxValue
		FROM    Cash.tbPeriod 
			JOIN invoice_summary 
				ON Cash.tbPeriod.CashCode = invoice_summary.CashCode AND Cash.tbPeriod.StartOn = invoice_summary.StartOn;

		WITH asset_entries AS
		(
			SELECT payment.CashCode, 
				(SELECT TOP 1 StartOn FROM App.tbYearPeriod WHERE (StartOn <= payment.PaidOn) ORDER BY StartOn DESC) AS StartOn,
				CASE cash_category.CashPolarityCode
					WHEN 0 THEN 
						(PaidInValue + (PaidOutValue * -1)) * -1
					ELSE 
						PaidInValue + (PaidOutValue * -1)
				END AssetValue
			FROM Cash.tbPayment payment
				JOIN Subject.tbAccount account ON payment.AccountCode = account.AccountCode
				JOIN Cash.vwCodeActive cash_code ON account.CashCode = cash_code.CashCode
				JOIN Cash.vwCategoryActive cash_category ON cash_code.CategoryCode = cash_category.CategoryCode
			WHERE account.AccountTypeCode = 2 AND PaidOn < (SELECT StartOn FROM App.fnActivePeriod())
		), asset_summary AS
		(
			SELECT CashCode, StartOn, SUM(AssetValue) AssetValue
			FROM asset_entries
			GROUP BY CashCode, StartOn
		)
		UPDATE Cash.tbPeriod
		SET InvoiceValue = AssetValue
		FROM  Cash.tbPeriod 
			JOIN asset_summary 
				ON Cash.tbPeriod.CashCode = asset_summary.CashCode AND Cash.tbPeriod.StartOn = asset_summary.StartOn;	

  	END TRY
	BEGIN CATCH
		EXEC App.proc_ErrorLog;
	END CATCH
GO

PRINT N'Creating Trigger [Cash].[Cash_tbCategory_TriggerUpdate]...';


GO
CREATE TRIGGER Cash.Cash_tbCategory_TriggerUpdate 
   ON  Cash.tbCategory
   AFTER UPDATE, INSERT
AS 
BEGIN
	SET NOCOUNT ON;
	BEGIN TRY	
		IF EXISTS (SELECT * FROM inserted i WHERE App.fnParsePrimaryKey(CategoryCode) = 0)
		BEGIN
			DECLARE @Msg NVARCHAR(MAX);
			SELECT @Msg = Message FROM App.tbText WHERE TextId = 2004;
			RAISERROR (@Msg, 10, 1)
			ROLLBACK
		END

		IF NOT UPDATE(UpdatedBy)
		BEGIN
			UPDATE Cash.tbCategory
			SET UpdatedBy = Usr.fnUserName(), UpdatedOn = CURRENT_TIMESTAMP
			FROM Cash.tbCategory
			INNER JOIN inserted AS i
				ON tbCategory.VersionId = i.VersionId
				AND tbCategory.CategoryCode = i.CategoryCode;
		END

	END TRY
	BEGIN CATCH
		EXEC App.proc_ErrorLog;
	END CATCH
END
GO

PRINT N'Altering Procedure [App].[proc_Template_CO_MICRO_CUR_STD_EXP_2026]...';


GO
ALTER PROCEDURE App.proc_Template_CO_MICRO_CUR_STD_EXP_2026
    @CategoryVersionId NVARCHAR(10)
AS
BEGIN

    ----------------------------------------------------------------
    -- STD-SPECIFIC EXPRESSION CATEGORIES (CategoryTypeCode = 2)
    ----------------------------------------------------------------
    INSERT INTO Cash.tbCategory
        (VersionId, CategoryCode, Category, CategoryTypeCode, CashPolarityCode, CashTypeCode, DisplayOrder, IsEnabled)
    SELECT
        @CategoryVersionId,
        CategoryCode,
        Category,
        CategoryTypeCode,
        CashPolarityCode,
        CashTypeCode,
        DisplayOrder,
        IsEnabled
    FROM
    (VALUES
        -- Enabled by default (the “big four”)
        ('CE-COS',  'Cash Operating Surplus % (Structured)', 2, 2, 0, 20, 1),
        ('CE-LM',   'Labour Margin %',                       2, 2, 0, 21, 1),
        ('CE-MM',   'Materials Margin %',                    2, 2, 0, 22, 1),
        ('CE-SDR',  'Subcontractor Dependency Ratio',        2, 2, 0, 23, 1),

        -- Effective tax rate (enabled)
        ('CE-ETR',  'Effective Tax Rate',                    2, 2, 0, 24, 1),

        -- Disabled by default (progressive disclosure)
        ('CE-VCR',  'Vehicle Cost Ratio',                    2, 2, 0, 25, 0),

        ('CE-WPR',  'Wages % of Staff Costs',                2, 2, 0, 26, 0),
        ('CE-NPR',  'Employer NI % of Staff Costs',          2, 2, 0, 27, 0),
        ('CE-PPR',  'Pension % of Staff Costs',              2, 2, 0, 28, 0),

        ('CE-RPR',  'Rent % of Admin Expenses',              2, 2, 0, 29, 0),
        ('CE-UPR',  'Utilities % of Admin Expenses',         2, 2, 0, 30, 0),
        ('CE-IPR',  'Insurance % of Admin Expenses',         2, 2, 0, 31, 0),
        ('CE-MPR',  'Repairs % of Admin Expenses',           2, 2, 0, 32, 0),
        ('CE-TPR',  'Telephone % of Admin Expenses',         2, 2, 0, 33, 0),
        ('CE-APR',  'Advertising % of Admin Expenses',       2, 2, 0, 34, 0),
        ('CE-TRR',  'Travel % of Admin Expenses',            2, 2, 0, 35, 0),
        ('CE-PFR',  'Professional Fees % of Admin Expenses', 2, 2, 0, 36, 0),
        ('CE-BCR',  'Bank Charges % of Admin Expenses',      2, 2, 0, 37, 0),

        ('CE-DPL',  'Plant Depreciation % of Depreciation',  2, 2, 0, 38, 0),
        ('CE-DMV',  'Motor Depreciation % of Depreciation',  2, 2, 0, 39, 0),
        ('CE-DFX',  'Fixtures Depreciation % of Depreciation', 2, 2, 0, 40, 0)
    ) AS category
    (
        CategoryCode,
        Category,
        CategoryTypeCode,
        CashPolarityCode,
        CashTypeCode,
        DisplayOrder,
        IsEnabled
    );

    ----------------------------------------------------------------
    -- STD-SPECIFIC EXPRESSIONS (STABLE CODE REFERENCES)
    ----------------------------------------------------------------
    INSERT INTO Cash.tbCategoryExp
        (CategoryCode, Expression, Format, SyntaxTypeCode, IsError, ErrorMessage)
    VALUES
        -- Structured Cash Operating Surplus %
        ('CE-COS', 'IF([CT-TURNOV]=0,0,([CT-TURNOV]-[CT-CSTSAL]-[CT-STAFFC]-[CA-ADMIN])/[CT-TURNOV])', 'Pct0', 0, 0, NULL),

        -- Labour Margin %
        ('CE-LM', 'IF([CC-SALAB]=0,0,([CC-SALAB]-[CC-SALRY]-[CC-EMPNI]-[CC-PENSN])/[CC-SALAB])', 'Pct0', 0, 0, NULL),

        -- Materials Margin %
        ('CE-MM', 'IF([CC-SAMAT]=0,0,([CC-SAMAT]-[CC-MAT])/[CC-SAMAT])', 'Pct0', 0, 0, NULL),

        -- Subcontractor Dependency Ratio
        ('CE-SDR', 'IF([CT-CSTSAL]=0,0,[CC-SUB]/[CT-CSTSAL])', 'Pct0', 0, 0, NULL),

        -- Effective Tax Rate
        ('CE-ETR',
            'IF(([CT-TURNOV]-[CT-CSTSAL]-[CT-STAFFC]-[CA-ADMIN])=0,0,(ABS([CA-TAXCO])/([CT-TURNOV]-[CT-CSTSAL]-[CT-STAFFC]-[CA-ADMIN])))',
            'Pct0', 0, 0, NULL),

        -- Vehicle Cost Ratio
        ('CE-VCR', 'IF([CT-TURNOV]=0,0,([CC-FUEL]+[CC-MTRAV])/[CT-TURNOV])', 'Pct0', 0, 0, NULL),

        -- Staff Cost Structure
        ('CE-WPR', 'IF([CT-STAFFC]=0,0,[CC-SALRY]/[CT-STAFFC])', 'Pct0', 0, 0, NULL),
        ('CE-NPR', 'IF([CT-STAFFC]=0,0,[CC-EMPNI]/[CT-STAFFC])', 'Pct0', 0, 0, NULL),
        ('CE-PPR', 'IF([CT-STAFFC]=0,0,[CC-PENSN]/[CT-STAFFC])', 'Pct0', 0, 0, NULL),

        -- Admin Cost Structure
        ('CE-RPR', 'IF([CA-ADMIN]=0,0,[CC-RENT]/[CA-ADMIN])', 'Pct0', 0, 0, NULL),
        ('CE-UPR', 'IF([CA-ADMIN]=0,0,[CC-LHEAT]/[CA-ADMIN])', 'Pct0', 0, 0, NULL),
        ('CE-IPR', 'IF([CA-ADMIN]=0,0,[CC-INS]/[CA-ADMIN])', 'Pct0', 0, 0, NULL),
        ('CE-MPR', 'IF([CA-ADMIN]=0,0,[CC-REPA]/[CA-ADMIN])', 'Pct0', 0, 0, NULL),
        ('CE-TPR', 'IF([CA-ADMIN]=0,0,[CC-PHONE]/[CA-ADMIN])', 'Pct0', 0, 0, NULL),
        ('CE-APR', 'IF([CA-ADMIN]=0,0,[CC-ADVT]/[CA-ADMIN])', 'Pct0', 0, 0, NULL),
        ('CE-TRR', 'IF([CA-ADMIN]=0,0,[CC-TRAV]/[CA-ADMIN])', 'Pct0', 0, 0, NULL),
        ('CE-PFR', 'IF([CA-ADMIN]=0,0,[CC-PROF]/[CA-ADMIN])', 'Pct0', 0, 0, NULL),
        ('CE-BCR', 'IF([CA-ADMIN]=0,0,[CC-BANKC]/[CA-ADMIN])', 'Pct0', 0, 0, NULL),

        -- Depreciation Structure
        ('CE-DPL', 'IF([CA-DEPREC]=0,0,[CC-DEPPL]/[CA-DEPREC])', 'Pct0', 0, 0, NULL),
        ('CE-DMV', 'IF([CA-DEPREC]=0,0,[CC-DEPMV]/[CA-DEPREC])', 'Pct0', 0, 0, NULL),
        ('CE-DFX', 'IF([CA-DEPREC]=0,0,[CC-DEPFX]/[CA-DEPREC])', 'Pct0', 0, 0, NULL);

END;
GO

PRINT N'Altering Trigger [Cash].[Cash_tbPayment_TriggerInsert]...';


GO

ALTER TRIGGER Cash.Cash_tbPayment_TriggerInsert
ON Cash.tbPayment
FOR INSERT
AS
    SET NOCOUNT ON;
    BEGIN TRY

		IF EXISTS
		(
			SELECT 1
			FROM inserted i
			JOIN Cash.tbCode cash_code ON cash_code.CashCode = i.CashCode
			WHERE cash_code.IsEnabled = 0
		)
			THROW 51016, 'A Payment cannot be assigned a disabled CashCode.', 1;

        ;WITH namespace_candidates AS
        (
            SELECT
                payment.PaymentCode,
                payment.SubjectCode,
                payment.ParentSubjectCode,
                ParentCount = (
                    SELECT COUNT(*)
                    FROM Subject.tbNamespace tbNamespace
                    WHERE tbNamespace.ChildSubjectCode = payment.SubjectCode
                ),
                SingleParentSubjectCode = (
                    SELECT MIN(tbNamespace.ParentSubjectCode)
                    FROM Subject.tbNamespace tbNamespace
                    WHERE tbNamespace.ChildSubjectCode = payment.SubjectCode
                )
            FROM Cash.tbPayment payment
                JOIN inserted i ON payment.PaymentCode = i.PaymentCode
        )
        UPDATE payment
        SET ParentSubjectCode = namespace_candidates.SingleParentSubjectCode
        FROM Cash.tbPayment payment
            JOIN namespace_candidates ON payment.PaymentCode = namespace_candidates.PaymentCode
        WHERE namespace_candidates.ParentSubjectCode IS NULL
          AND namespace_candidates.ParentCount = 1;

        IF EXISTS
        (
            SELECT 1
            FROM Cash.tbPayment payment
                JOIN inserted i ON payment.PaymentCode = i.PaymentCode
            WHERE payment.ParentSubjectCode IS NULL
              AND (
                    SELECT COUNT(*)
                    FROM Subject.tbNamespace tbNamespace
                    WHERE tbNamespace.ChildSubjectCode = payment.SubjectCode
                  ) > 1
        )
        BEGIN
            RAISERROR('ParentSubjectCode must be selected when Subject has multiple namespace parents.', 16, 1);
            ROLLBACK TRANSACTION;
            RETURN;
        END

        IF EXISTS
        (
            SELECT 1
            FROM Cash.tbPayment payment
                JOIN inserted i ON payment.PaymentCode = i.PaymentCode
            WHERE payment.ParentSubjectCode IS NOT NULL
              AND NOT EXISTS
              (
                  SELECT 1
                  FROM Subject.tbNamespace tbNamespace
                  WHERE tbNamespace.ChildSubjectCode = payment.SubjectCode
                    AND tbNamespace.ParentSubjectCode = payment.ParentSubjectCode
              )
        )
        BEGIN
            RAISERROR('ParentSubjectCode must reference a valid namespace parent for the Subject.', 16, 1);
            ROLLBACK TRANSACTION;
            RETURN;
        END

        UPDATE payment
        SET PaymentStatusCode = 2
        FROM inserted
            JOIN Cash.tbPayment payment ON inserted.PaymentCode = payment.PaymentCode
            JOIN Subject.tbAccount account ON payment.AccountCode = account.AccountCode
			JOIN Cash.vwCodeActive AS code ON inserted.CashCode = code.CashCode
			JOIN Cash.vwCategoryActive category ON code.CategoryCode = category.CategoryCode
        WHERE category.CashTypeCode = 2
          AND inserted.PaymentStatusCode = 0
          AND account.AccountTypeCode = 0;

        WITH assets AS
        (
            SELECT account.AccountCode
            FROM inserted i
                JOIN Subject.tbAccount account ON account.AccountCode = i.AccountCode
            WHERE AccountTypeCode = 2
              AND PaymentStatusCode = 1
        ),
        balance AS
        (
            SELECT account.AccountCode, SUM(PaidInValue + (PaidOutValue * -1)) CurrentBalance
            FROM Subject.tbAccount account
                JOIN assets ON account.AccountCode = assets.AccountCode
                JOIN Cash.tbPayment payment ON account.AccountCode = payment.AccountCode
            WHERE payment.PaymentStatusCode = 1
            GROUP BY account.AccountCode
        )
        UPDATE account
        SET CurrentBalance = balance.CurrentBalance + OpeningBalance
        FROM Subject.tbAccount account
            JOIN balance ON account.AccountCode = balance.AccountCode;

        IF EXISTS
        (
            SELECT 1
            FROM inserted i
                JOIN Subject.tbAccount a ON a.AccountCode = i.AccountCode
            WHERE i.PaymentStatusCode = 1
              AND a.AccountTypeCode = 2
              AND
              (
                    (a.BalanceConstraintCode = 1 AND a.CurrentBalance < 0)
                 OR (a.BalanceConstraintCode = 2 AND a.CurrentBalance > 0)
              )
        )
        BEGIN
            RAISERROR('Balance constraint violation on asset account.', 16, 1);
            ROLLBACK TRANSACTION;
            RETURN;
        END

    END TRY
    BEGIN CATCH
        EXEC App.proc_ErrorLog;
    END CATCH
GO

PRINT N'Altering Trigger [Cash].[Cash_tbPeriod_Trigger_Update]...';


GO
ALTER   TRIGGER Cash.Cash_tbPeriod_Trigger_Update 
ON Cash.tbPeriod FOR INSERT, UPDATE
AS
	SET NOCOUNT ON;

	BEGIN TRY
	IF UPDATE (ForecastValue)
		BEGIN
		UPDATE tbPeriod
		SET ForecastTax = inserted.ForecastValue * tax_code.TaxRate
		FROM inserted 
			JOIN Cash.tbPeriod tbPeriod ON inserted.CashCode = tbPeriod.CashCode AND inserted.StartOn = tbPeriod.StartOn
			JOIN Cash.vwCodeActive cash_code ON tbPeriod.CashCode = cash_code.CashCode
			JOIN Cash.vwCategoryActive category ON cash_code.CategoryCode = category.CategoryCode
            JOIN App.tbTaxCode tax_code ON cash_code.TaxCode = tax_code.TaxCode
		END
	END TRY
	BEGIN CATCH
		EXEC App.proc_ErrorLog;
	END CATCH
GO

PRINT N'Creating Procedure [Cash].[proc_CategoryCodeMapMove]...';


GO
CREATE PROCEDURE [Cash].[proc_CategoryCodeMapMove]
(
    @VersionId NVARCHAR(10),
    @CashCode NVARCHAR(50),
    @CategoryCode NVARCHAR(10),
    @ChangeNote NVARCHAR(MAX) = NULL
)
AS
BEGIN
    SET NOCOUNT, XACT_ABORT ON;

    DECLARE @StatusCode SMALLINT, @UserId NVARCHAR(10), @UserName NVARCHAR(50);
    SELECT TOP (1) @UserId = UserId, @UserName = UserName FROM Usr.vwCredentials;
    IF @UserId IS NULL THROW 51157, 'Cash Code mapping mutation requires an enabled application user.', 1;

    BEGIN TRY
        BEGIN TRAN;

        SELECT @StatusCode = VersionStatusCode
        FROM Cash.tbCategoryVersion WITH (UPDLOCK, HOLDLOCK)
        WHERE VersionId = @VersionId;

    IF @StatusCode NOT IN (0, 1)
        THROW 51152, 'Cash Code mappings can be changed only in Draft or Published versions.', 1;
    IF @StatusCode = 1
       AND NOT EXISTS (SELECT 1 FROM App.tbOptions WHERE CategoryVersionId = @VersionId)
        THROW 51153, 'Only the active Published version can be edited.', 1;
    IF NOT EXISTS (SELECT 1 FROM Cash.tbCode WHERE CashCode = @CashCode)
        THROW 51154, 'The persistent Cash Code was not found.', 1;
    IF NOT EXISTS
    (
        SELECT 1 FROM Cash.tbCategory
        WHERE VersionId = @VersionId AND CategoryCode = @CategoryCode AND CategoryTypeCode = 0
    )
        THROW 51155, 'A Cash Code mapping must target a Nominal category in the same version.', 1;

    UPDATE Cash.tbCategoryCodeMap
    SET CategoryCode = @CategoryCode
    WHERE VersionId = @VersionId AND CashCode = @CashCode;

    IF @@ROWCOUNT <> 1
        THROW 51156, 'The version does not contain the Cash Code mapping.', 1;

        INSERT Cash.tbCategoryVersionEvent
            (VersionId, EventTypeCode, FromStatusCode, ToStatusCode, UserId, UserName, ChangeNote)
        VALUES
            (@VersionId, 1, @StatusCode, @StatusCode, @UserId, @UserName,
             COALESCE(NULLIF(LTRIM(RTRIM(@ChangeNote)), N''), N'Cash Code mapping moved.'));

        COMMIT TRAN;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRAN;
        THROW;
    END CATCH;
END;
GO

PRINT N'Creating Procedure [Cash].[proc_CategoryDelete]...';


GO
CREATE PROCEDURE [Cash].[proc_CategoryDelete]
(
    @VersionId NVARCHAR(10),
    @CategoryCode NVARCHAR(10),
    @ChangeNote NVARCHAR(MAX) = NULL
)
AS
BEGIN
    SET NOCOUNT, XACT_ABORT ON;

    DECLARE @StatusCode SMALLINT, @UserId NVARCHAR(10), @UserName NVARCHAR(50);
    SELECT TOP (1) @UserId = UserId, @UserName = UserName FROM Usr.vwCredentials;
    IF @UserId IS NULL THROW 51147, 'Category mutation requires an enabled application user.', 1;

    BEGIN TRY
        BEGIN TRAN;

        SELECT @StatusCode = VersionStatusCode
        FROM Cash.tbCategoryVersion WITH (UPDLOCK, HOLDLOCK)
        WHERE VersionId = @VersionId;

    IF @StatusCode NOT IN (0, 1)
        THROW 51141, 'Categories can be deleted only from Draft or Published versions.', 1;

    IF @StatusCode = 1
       AND NOT EXISTS (SELECT 1 FROM App.tbOptions WHERE CategoryVersionId = @VersionId)
        THROW 51142, 'Only the active Published version can be edited.', 1;

    IF EXISTS (SELECT 1 FROM Cash.tbCategoryCodeMap WHERE VersionId = @VersionId AND CategoryCode = @CategoryCode)
        THROW 51143, 'Move the blocking Cash Codes before deleting this category.', 1;
    IF EXISTS (SELECT 1 FROM Cash.tbCategoryRoot WHERE VersionId = @VersionId AND CategoryCode = @CategoryCode)
        THROW 51144, 'Change the configured root before deleting this category.', 1;
    IF EXISTS
    (
        SELECT 1 FROM Cash.tbCategoryTotal
        WHERE VersionId = @VersionId AND (ParentCode = @CategoryCode OR ChildCode = @CategoryCode)
    )
        THROW 51145, 'Remove the category edges before deleting this category.', 1;

    DELETE FROM Cash.tbCategory
    WHERE VersionId = @VersionId AND CategoryCode = @CategoryCode;

    IF @@ROWCOUNT <> 1
        THROW 51146, 'The Category Tree category was not found.', 1;

        INSERT Cash.tbCategoryVersionEvent
            (VersionId, EventTypeCode, FromStatusCode, ToStatusCode, UserId, UserName, ChangeNote)
        VALUES
            (@VersionId, 1, @StatusCode, @StatusCode, @UserId, @UserName,
             COALESCE(NULLIF(LTRIM(RTRIM(@ChangeNote)), N''), N'Category deleted.'));

        COMMIT TRAN;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRAN;
        THROW;
    END CATCH;
END;
GO

PRINT N'Creating Procedure [Cash].[proc_CategoryRootSet]...';


GO
CREATE PROCEDURE [Cash].[proc_CategoryRootSet]
(
    @VersionId NVARCHAR(10),
    @RootTypeCode SMALLINT,
    @CategoryCode NVARCHAR(10),
    @ChangeNote NVARCHAR(MAX) = NULL
)
AS
BEGIN
    SET NOCOUNT, XACT_ABORT ON;

    DECLARE @StatusCode SMALLINT, @UserId NVARCHAR(10), @UserName NVARCHAR(50);
    SELECT TOP (1) @UserId = UserId, @UserName = UserName FROM Usr.vwCredentials;
    IF @UserId IS NULL THROW 51160, 'Root mutation requires an enabled application user.', 1;

    BEGIN TRY
        BEGIN TRAN;

        SELECT @StatusCode = VersionStatusCode
        FROM Cash.tbCategoryVersion WITH (UPDLOCK, HOLDLOCK)
        WHERE VersionId = @VersionId;

    IF @StatusCode NOT IN (0, 1)
        THROW 51158, 'Roots can be changed only in Draft or Published versions.', 1;
    IF @StatusCode = 1
       AND NOT EXISTS (SELECT 1 FROM App.tbOptions WHERE CategoryVersionId = @VersionId)
        THROW 51159, 'Only the active Published version can be edited.', 1;

    UPDATE Cash.tbCategoryRoot
    SET CategoryCode = @CategoryCode
    WHERE VersionId = @VersionId AND RootTypeCode = @RootTypeCode;

    IF @@ROWCOUNT = 0
        INSERT Cash.tbCategoryRoot (VersionId, RootTypeCode, CategoryCode)
        VALUES (@VersionId, @RootTypeCode, @CategoryCode);

        INSERT Cash.tbCategoryVersionEvent
            (VersionId, EventTypeCode, FromStatusCode, ToStatusCode, UserId, UserName, ChangeNote)
        VALUES
            (@VersionId, 1, @StatusCode, @StatusCode, @UserId, @UserName,
             COALESCE(NULLIF(LTRIM(RTRIM(@ChangeNote)), N''), N'Category Tree root changed.'));

        COMMIT TRAN;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRAN;
        THROW;
    END CATCH;
END;
GO

PRINT N'Creating Procedure [Cash].[proc_CategorySave]...';


GO
CREATE PROCEDURE [Cash].[proc_CategorySave]
(
    @VersionId NVARCHAR(10),
    @CategoryCode NVARCHAR(10),
    @Category NVARCHAR(50),
    @CategoryTypeCode SMALLINT,
    @CashPolarityCode SMALLINT,
    @CashTypeCode SMALLINT,
    @DisplayOrder SMALLINT = 0,
    @IsEnabled SMALLINT = 1,
    @ChangeNote NVARCHAR(MAX) = NULL
)
AS
BEGIN
    SET NOCOUNT, XACT_ABORT ON;

    DECLARE @StatusCode SMALLINT, @UserId NVARCHAR(10), @UserName NVARCHAR(50);
    SELECT TOP (1) @UserId = UserId, @UserName = UserName FROM Usr.vwCredentials;
    IF @UserId IS NULL THROW 51140, 'Category mutation requires an enabled application user.', 1;

    BEGIN TRY
        BEGIN TRAN;

        SELECT @StatusCode = VersionStatusCode
        FROM Cash.tbCategoryVersion WITH (UPDLOCK, HOLDLOCK)
        WHERE VersionId = @VersionId;

    IF @StatusCode NOT IN (0, 1)
        THROW 51137, 'Categories can be changed only in Draft or Published versions.', 1;

    IF @StatusCode = 1
       AND NOT EXISTS (SELECT 1 FROM App.tbOptions WHERE CategoryVersionId = @VersionId)
        THROW 51138, 'Only the active Published version can be edited.', 1;

    IF EXISTS
    (
        SELECT 1
        FROM Cash.tbCategoryCodeMap
        WHERE VersionId = @VersionId AND CategoryCode = @CategoryCode
    ) AND @CategoryTypeCode <> 0
        THROW 51139, 'A mapped Nominal category cannot change type.', 1;

    IF EXISTS
    (
        SELECT 1
        FROM Cash.tbCategory
        WHERE VersionId = @VersionId AND CategoryCode = @CategoryCode
    )
        UPDATE Cash.tbCategory
        SET Category = @Category,
            CategoryTypeCode = @CategoryTypeCode,
            CashPolarityCode = @CashPolarityCode,
            CashTypeCode = @CashTypeCode,
            DisplayOrder = @DisplayOrder,
            IsEnabled = @IsEnabled
        WHERE VersionId = @VersionId AND CategoryCode = @CategoryCode;
    ELSE
        INSERT INTO Cash.tbCategory
        (
            VersionId, CategoryCode, Category, CategoryTypeCode,
            CashPolarityCode, CashTypeCode, DisplayOrder, IsEnabled
        )
        VALUES
        (
            @VersionId, @CategoryCode, @Category, @CategoryTypeCode,
            @CashPolarityCode, @CashTypeCode, @DisplayOrder, @IsEnabled
        );

        INSERT Cash.tbCategoryVersionEvent
            (VersionId, EventTypeCode, FromStatusCode, ToStatusCode, UserId, UserName, ChangeNote)
        VALUES
            (@VersionId, 1, @StatusCode, @StatusCode, @UserId, @UserName,
             COALESCE(NULLIF(LTRIM(RTRIM(@ChangeNote)), N''), N'Category saved.'));

        COMMIT TRAN;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRAN;
        THROW;
    END CATCH;
END;
GO

PRINT N'Creating Procedure [Cash].[proc_CategoryTotalSave]...';


GO
CREATE PROCEDURE [Cash].[proc_CategoryTotalSave]
(
    @VersionId NVARCHAR(10),
    @ParentCode NVARCHAR(10),
    @ChildCode NVARCHAR(10),
    @DisplayOrder SMALLINT = 0,
    @IsDelete BIT = 0,
    @ChangeNote NVARCHAR(MAX) = NULL
)
AS
BEGIN
    SET NOCOUNT, XACT_ABORT ON;

    DECLARE @StatusCode SMALLINT, @UserId NVARCHAR(10), @UserName NVARCHAR(50);
    SELECT TOP (1) @UserId = UserId, @UserName = UserName FROM Usr.vwCredentials;
    IF @UserId IS NULL THROW 51151, 'Category edge mutation requires an enabled application user.', 1;

    BEGIN TRY
        BEGIN TRAN;

        SELECT @StatusCode = VersionStatusCode
        FROM Cash.tbCategoryVersion WITH (UPDLOCK, HOLDLOCK)
        WHERE VersionId = @VersionId;

    IF @StatusCode NOT IN (0, 1)
        THROW 51148, 'Category edges can be changed only in Draft or Published versions.', 1;
    IF @StatusCode = 1
       AND NOT EXISTS (SELECT 1 FROM App.tbOptions WHERE CategoryVersionId = @VersionId)
        THROW 51149, 'Only the active Published version can be edited.', 1;

    IF @IsDelete = 1
    BEGIN
        DELETE FROM Cash.tbCategoryTotal
        WHERE VersionId = @VersionId AND ParentCode = @ParentCode AND ChildCode = @ChildCode;
        IF @@ROWCOUNT <> 1 THROW 51150, 'The Category Tree edge was not found.', 1;
    END
    ELSE IF EXISTS
    (
        SELECT 1 FROM Cash.tbCategoryTotal
        WHERE VersionId = @VersionId AND ParentCode = @ParentCode AND ChildCode = @ChildCode
    )
        UPDATE Cash.tbCategoryTotal
        SET DisplayOrder = @DisplayOrder
        WHERE VersionId = @VersionId AND ParentCode = @ParentCode AND ChildCode = @ChildCode;
    ELSE
        INSERT Cash.tbCategoryTotal (VersionId, ParentCode, ChildCode, DisplayOrder)
        VALUES (@VersionId, @ParentCode, @ChildCode, @DisplayOrder);

        INSERT Cash.tbCategoryVersionEvent
            (VersionId, EventTypeCode, FromStatusCode, ToStatusCode, UserId, UserName, ChangeNote)
        VALUES
            (@VersionId, 1, @StatusCode, @StatusCode, @UserId, @UserName,
             COALESCE(NULLIF(LTRIM(RTRIM(@ChangeNote)), N''),
                      CASE WHEN @IsDelete = 1 THEN N'Category edge deleted.' ELSE N'Category edge saved.' END));

        COMMIT TRAN;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRAN;
        THROW;
    END CATCH;
END;
GO

PRINT N'Creating Procedure [Cash].[proc_CategoryVersionCanonicalise]...';


GO
CREATE PROCEDURE [Cash].[proc_CategoryVersionCanonicalise]
(
    @VersionId NVARCHAR(10),
    @CanonicalSha256 BINARY(32) = NULL OUTPUT,
    @CanonicalByteLength BIGINT = NULL OUTPUT,
    @CanonicalJson NVARCHAR(MAX) = NULL OUTPUT
)
AS
BEGIN
    SET NOCOUNT, XACT_ABORT ON;

    DECLARE @VersionStatusCode SMALLINT;

    SELECT @VersionStatusCode = VersionStatusCode
    FROM Cash.tbCategoryVersion WITH (UPDLOCK, HOLDLOCK)
    WHERE VersionId = @VersionId;

    IF @VersionStatusCode IS NULL
        THROW 51093, 'Category Tree canonicalisation requires a known version.', 1;

    IF @VersionStatusCode NOT IN (0, 1)
        THROW 51094, 'Submitted and Archived Category Tree versions cannot be recanonicalised.', 1;

    IF NOT EXISTS (SELECT 1 FROM Cash.tbCategory WHERE VersionId = @VersionId)
        THROW 51095, 'Category Tree canonicalisation requires at least one category.', 1;

    IF (SELECT COUNT(*) FROM Cash.tbCategoryRoot WHERE VersionId = @VersionId) <> 2
        OR EXISTS
        (
            SELECT required.RootTypeCode
            FROM (VALUES (CAST(0 AS SMALLINT)), (CAST(1 AS SMALLINT))) AS required (RootTypeCode)
            EXCEPT
            SELECT RootTypeCode
            FROM Cash.tbCategoryRoot
            WHERE VersionId = @VersionId
        )
        THROW 51096, 'The v1 Category Tree profile requires exactly NET_PROFIT and VAT roots.', 1;

    DECLARE
        @Categories NVARCHAR(MAX),
        @Totals NVARCHAR(MAX),
        @CodeMap NVARCHAR(MAX),
        @Roots NVARCHAR(MAX);

    SELECT @Categories = STUFF
    (
        (
        SELECT
            N',' +
            CAST
        (
            N'{"categoryCode":"' + REPLACE(STRING_ESCAPE(CategoryCode, 'json'), N'\/', N'/')
            + N'","category":"' + REPLACE(STRING_ESCAPE(Category, 'json'), N'\/', N'/')
            + N'","categoryTypeCode":' + CONVERT(NVARCHAR(6), CategoryTypeCode)
            + N',"cashPolarityCode":' + COALESCE(CONVERT(NVARCHAR(6), CashPolarityCode), N'null')
            + N',"cashTypeCode":' + COALESCE(CONVERT(NVARCHAR(6), CashTypeCode), N'null')
            + N',"displayOrder":' + CONVERT(NVARCHAR(6), DisplayOrder)
            + N',"isEnabled":' + CASE WHEN IsEnabled = 0 THEN N'false' ELSE N'true' END
            + N'}'
            AS NVARCHAR(MAX)
        )
        FROM Cash.tbCategory
        WHERE VersionId = @VersionId
        ORDER BY CategoryCode COLLATE Latin1_General_100_BIN2
        FOR XML PATH(N''), TYPE
        ).value(N'.', N'nvarchar(max)'),
        1,
        1,
        N''
    );

    SELECT @Totals = COALESCE
    (
        STUFF
        (
            (
            SELECT
                N',' +
                CAST
            (
                N'{"parentCode":"' + REPLACE(STRING_ESCAPE(ParentCode, 'json'), N'\/', N'/')
                + N'","childCode":"' + REPLACE(STRING_ESCAPE(ChildCode, 'json'), N'\/', N'/')
                + N'","displayOrder":' + CONVERT(NVARCHAR(6), DisplayOrder)
                + N'}'
                AS NVARCHAR(MAX)
            )
            FROM Cash.tbCategoryTotal
            WHERE VersionId = @VersionId
            ORDER BY
                ParentCode COLLATE Latin1_General_100_BIN2,
                ChildCode COLLATE Latin1_General_100_BIN2
            FOR XML PATH(N''), TYPE
            ).value(N'.', N'nvarchar(max)'),
            1,
            1,
            N''
        ),
        N''
    );

    SELECT @CodeMap = COALESCE
    (
        STUFF
        (
            (
            SELECT
                N',' +
                CAST
            (
                N'{"cashCode":"' + REPLACE(STRING_ESCAPE(CashCode, 'json'), N'\/', N'/')
                + N'","categoryCode":"' + REPLACE(STRING_ESCAPE(CategoryCode, 'json'), N'\/', N'/')
                + N'"}'
                AS NVARCHAR(MAX)
            )
            FROM Cash.tbCategoryCodeMap
            WHERE VersionId = @VersionId
            ORDER BY CashCode COLLATE Latin1_General_100_BIN2
            FOR XML PATH(N''), TYPE
            ).value(N'.', N'nvarchar(max)'),
            1,
            1,
            N''
        ),
        N''
    );

    SELECT @Roots = STUFF
    (
        (
        SELECT
            N',' +
            CAST
        (
            N'{"rootType":"' + REPLACE(STRING_ESCAPE(root_type.RootType, 'json'), N'\/', N'/')
            + N'","categoryCode":"' + REPLACE(STRING_ESCAPE(root.CategoryCode, 'json'), N'\/', N'/')
            + N'"}'
            AS NVARCHAR(MAX)
        )
        FROM Cash.tbCategoryRoot AS root
        JOIN Cash.tbCategoryRootType AS root_type
          ON root_type.RootTypeCode = root.RootTypeCode
        WHERE root.VersionId = @VersionId
        ORDER BY root.RootTypeCode
        FOR XML PATH(N''), TYPE
        ).value(N'.', N'nvarchar(max)'),
        1,
        1,
        N''
    );

    SET @CanonicalJson =
        N'{"profile":"trade-control-category-tree-v1","categories":[' + @Categories
        + N'],"totals":[' + @Totals
        + N'],"codeMap":[' + @CodeMap
        + N'],"roots":[' + @Roots + N']}';

    DECLARE @CanonicalBytes VARBINARY(MAX) = CONVERT
    (
        VARBINARY(MAX),
        CONVERT(VARCHAR(MAX), @CanonicalJson COLLATE Latin1_General_100_BIN2_UTF8)
    );

    SET @CanonicalByteLength = DATALENGTH(@CanonicalBytes);
    SET @CanonicalSha256 = HASHBYTES('SHA2_256', @CanonicalBytes);

    UPDATE Cash.tbCategoryVersion
    SET CanonicalProfile = N'trade-control-category-tree-v1',
        CanonicalSha256 = @CanonicalSha256,
        CanonicalByteLength = @CanonicalByteLength,
        ContentChangedOn = SYSUTCDATETIME()
    WHERE VersionId = @VersionId;
END;
GO

PRINT N'Creating Procedure [Cash].[proc_CategoryVersionDiscard]...';


GO
CREATE PROCEDURE [Cash].[proc_CategoryVersionDiscard]
(
    @VersionId NVARCHAR(10)
)
AS
BEGIN
    SET NOCOUNT, XACT_ABORT ON;

    IF EXISTS (SELECT 1 FROM App.tbOptions WHERE CategoryVersionId = @VersionId)
        THROW 51135, 'The active Category Tree version cannot be discarded.', 1;

    IF NOT EXISTS
    (
        SELECT 1
        FROM Cash.tbCategoryVersion
        WHERE VersionId = @VersionId AND VersionStatusCode = 0
    )
        THROW 51136, 'Only an inactive Draft Category Tree version can be discarded.', 1;

    BEGIN TRY
        BEGIN TRAN;

        DELETE FROM Cash.tbCategoryRoot WHERE VersionId = @VersionId;
        DELETE FROM Cash.tbCategoryCodeMap WHERE VersionId = @VersionId;
        DELETE FROM Cash.tbCategoryTotal WHERE VersionId = @VersionId;
        DELETE FROM Cash.tbCategory WHERE VersionId = @VersionId;
        DELETE FROM Cash.tbCategoryVersionEvent WHERE VersionId = @VersionId;
        DELETE FROM Cash.tbCategoryVersion WHERE VersionId = @VersionId;

        COMMIT TRAN;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRAN;
        THROW;
    END CATCH;
END;
GO

PRINT N'Creating Procedure [Cash].[proc_CategoryVersionIdNext]...';


GO
CREATE PROCEDURE [Cash].[proc_CategoryVersionIdNext]
    @VersionId NVARCHAR(10) OUTPUT
AS
BEGIN
    SET NOCOUNT, XACT_ABORT ON;

    DECLARE @SequenceValue BIGINT = NEXT VALUE FOR [Cash].[seqCategoryVersion];

    SET @VersionId = CONCAT
    (
        N'CV',
        RIGHT(REPLICATE(N'0', 8) + CONVERT(NVARCHAR(8), @SequenceValue), 8)
    );

    IF EXISTS
    (
        SELECT 1
        FROM [Cash].[tbCategoryVersion]
        WHERE [VersionId] = @VersionId
    )
        THROW 51060, 'The allocated Category Tree version identifier already exists.', 1;
END;
GO

PRINT N'Creating Procedure [Cash].[proc_CategoryVersionNotesSet]...';


GO
CREATE PROCEDURE [Cash].[proc_CategoryVersionNotesSet]
(
    @VersionId NVARCHAR(10),
    @Description NVARCHAR(100),
    @Notes NVARCHAR(MAX) = NULL,
    @ChangeNote NVARCHAR(MAX) = NULL
)
AS
BEGIN
    SET NOCOUNT, XACT_ABORT ON;

    DECLARE @StatusCode SMALLINT, @CanonicalSha256 BINARY(32),
            @UserId NVARCHAR(10), @UserName NVARCHAR(50);

    SELECT TOP (1) @UserId = UserId, @UserName = UserName FROM Usr.vwCredentials;
    IF @UserId IS NULL THROW 51161, 'Category Tree metadata mutation requires an enabled application user.', 1;
    IF LEN(LTRIM(RTRIM(COALESCE(@Description, N'')))) = 0
        THROW 51162, 'A Category Tree version requires a description.', 1;

    BEGIN TRY
        BEGIN TRAN;

        SELECT @StatusCode = VersionStatusCode, @CanonicalSha256 = CanonicalSha256
        FROM Cash.tbCategoryVersion WITH (UPDLOCK, HOLDLOCK)
        WHERE VersionId = @VersionId;

        IF @StatusCode NOT IN (0, 1)
            THROW 51163, 'Only Draft or Published Category Tree metadata can be changed.', 1;
        IF @StatusCode = 1
           AND NOT EXISTS (SELECT 1 FROM App.tbOptions WHERE CategoryVersionId = @VersionId)
            THROW 51164, 'Only the active Published version can be edited.', 1;

        UPDATE Cash.tbCategoryVersion
        SET Description = @Description,
            Notes = @Notes
        WHERE VersionId = @VersionId;

        INSERT Cash.tbCategoryVersionEvent
            (VersionId, EventTypeCode, FromStatusCode, ToStatusCode,
             UserId, UserName, ChangeNote, ContentSha256)
        VALUES
            (@VersionId, 1, @StatusCode, @StatusCode,
             @UserId, @UserName,
             COALESCE(NULLIF(LTRIM(RTRIM(@ChangeNote)), N''), N'Category Tree description or notes changed.'),
             @CanonicalSha256);

        COMMIT TRAN;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRAN;
        THROW;
    END CATCH;
END;
GO

PRINT N'Creating Procedure [Cash].[proc_CategoryVersionRefresh]...';


GO
CREATE PROCEDURE [Cash].[proc_CategoryVersionRefresh]
(
    @VersionId NVARCHAR(10),
    @ChangeNote NVARCHAR(MAX)
)
AS
BEGIN
    SET NOCOUNT, XACT_ABORT ON;

    DECLARE @PredecessorVersionId NVARCHAR(10), @ActiveVersionId NVARCHAR(10),
            @PredecessorStatusCode SMALLINT, @PredecessorSha256 BINARY(32),
            @DraftSha256 BINARY(32), @CanonicalByteLength BIGINT,
            @UserId NVARCHAR(10), @UserName NVARCHAR(50), @LockResult INT;

    SELECT TOP (1) @UserId = UserId, @UserName = UserName FROM Usr.vwCredentials;
    IF @UserId IS NULL THROW 51165, 'Category Tree refresh requires an enabled application user.', 1;
    IF LEN(LTRIM(RTRIM(COALESCE(@ChangeNote, N'')))) = 0
        THROW 51166, 'Category Tree refresh requires a change note.', 1;

    BEGIN TRY
        BEGIN TRAN;

        EXEC @LockResult = sys.sp_getapplock
            @Resource = N'Cash.CategoryTree.Publish',
            @LockMode = N'Exclusive',
            @LockOwner = N'Transaction',
            @LockTimeout = 15000;
        IF @LockResult < 0 THROW 51167, 'The Category Tree lifecycle lock could not be acquired.', 1;

        SELECT @ActiveVersionId = CategoryVersionId
        FROM App.tbOptions WITH (UPDLOCK, HOLDLOCK);

        SELECT @PredecessorVersionId = PredecessorVersionId
        FROM Cash.tbCategoryVersion WITH (UPDLOCK, HOLDLOCK)
        WHERE VersionId = @VersionId AND VersionStatusCode = 0;

        IF @PredecessorVersionId IS NULL OR @PredecessorVersionId <> @ActiveVersionId
            THROW 51168, 'Only a Draft cloned from the active version can be refreshed.', 1;

        SELECT @PredecessorStatusCode = VersionStatusCode,
               @PredecessorSha256 = CanonicalSha256
        FROM Cash.tbCategoryVersion WITH (UPDLOCK, HOLDLOCK)
        WHERE VersionId = @PredecessorVersionId;

        IF @PredecessorStatusCode NOT IN (1, 2)
            THROW 51169, 'The active predecessor is not eligible for Draft refresh.', 1;

        IF @PredecessorStatusCode = 1
            EXEC Cash.proc_CategoryVersionCanonicalise
                @VersionId = @PredecessorVersionId,
                @CanonicalSha256 = @PredecessorSha256 OUTPUT,
                @CanonicalByteLength = @CanonicalByteLength OUTPUT;

        IF @PredecessorSha256 IS NULL
            THROW 51170, 'The active predecessor does not have canonical evidence.', 1;

        DELETE FROM Cash.tbCategoryRoot WHERE VersionId = @VersionId;
        DELETE FROM Cash.tbCategoryCodeMap WHERE VersionId = @VersionId;
        DELETE FROM Cash.tbCategoryTotal WHERE VersionId = @VersionId;
        DELETE FROM Cash.tbCategory WHERE VersionId = @VersionId;

        INSERT Cash.tbCategory
            (VersionId, CategoryCode, Category, CategoryTypeCode,
             CashPolarityCode, CashTypeCode, DisplayOrder, IsEnabled)
        SELECT @VersionId, CategoryCode, Category, CategoryTypeCode,
               CashPolarityCode, CashTypeCode, DisplayOrder, IsEnabled
        FROM Cash.tbCategory
        WHERE VersionId = @PredecessorVersionId;

        INSERT Cash.tbCategoryTotal (VersionId, ParentCode, ChildCode, DisplayOrder)
        SELECT @VersionId, ParentCode, ChildCode, DisplayOrder
        FROM Cash.tbCategoryTotal
        WHERE VersionId = @PredecessorVersionId;

        INSERT Cash.tbCategoryCodeMap (VersionId, CashCode, CategoryCode)
        SELECT @VersionId, CashCode, CategoryCode
        FROM Cash.tbCategoryCodeMap
        WHERE VersionId = @PredecessorVersionId;

        INSERT Cash.tbCategoryRoot (VersionId, RootTypeCode, CategoryCode)
        SELECT @VersionId, RootTypeCode, CategoryCode
        FROM Cash.tbCategoryRoot
        WHERE VersionId = @PredecessorVersionId;

        UPDATE Cash.tbCategoryVersion
        SET BaseContentSha256 = @PredecessorSha256
        WHERE VersionId = @VersionId;

        EXEC Cash.proc_CategoryVersionCanonicalise
            @VersionId = @VersionId,
            @CanonicalSha256 = @DraftSha256 OUTPUT,
            @CanonicalByteLength = @CanonicalByteLength OUTPUT;

        INSERT Cash.tbCategoryVersionEvent
            (VersionId, EventTypeCode, FromStatusCode, ToStatusCode,
             UserId, UserName, ChangeNote, ContentSha256)
        VALUES
            (@VersionId, 6, 0, 0, @UserId, @UserName, @ChangeNote, @DraftSha256);

        COMMIT TRAN;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRAN;
        THROW;
    END CATCH;
END;
GO

PRINT N'Creating Procedure [Cash].[proc_CategoryVersionValidate]...';


GO
CREATE PROCEDURE [Cash].[proc_CategoryVersionValidate]
(
    @VersionId NVARCHAR(10),
    @CanonicalSha256 BINARY(32) = NULL OUTPUT,
    @CanonicalByteLength BIGINT = NULL OUTPUT
)
AS
BEGIN
    SET NOCOUNT, XACT_ABORT ON;

    DECLARE
        @VersionStatusCode SMALLINT,
        @UserId NVARCHAR(10),
        @UserName NVARCHAR(50);

    SELECT TOP (1) @UserId = UserId, @UserName = UserName
    FROM Usr.vwCredentials;

    IF @UserId IS NULL
        THROW 51110, 'Category Tree validation requires an enabled application user.', 1;

    BEGIN TRY
        BEGIN TRAN;

        SELECT @VersionStatusCode = VersionStatusCode
        FROM Cash.tbCategoryVersion WITH (UPDLOCK, HOLDLOCK)
        WHERE VersionId = @VersionId;

    IF @VersionStatusCode IS NULL
        THROW 51111, 'Category Tree validation requires a known version.', 1;

    IF @VersionStatusCode NOT IN (0, 1)
        THROW 51112, 'Only Draft or Published Category Tree versions can be validated.', 1;

    IF NOT EXISTS (SELECT 1 FROM Cash.tbCategory WHERE VersionId = @VersionId)
        THROW 51113, 'A Category Tree version must contain categories.', 1;

    IF EXISTS
    (
        SELECT 1
        FROM Cash.tbCategory
        WHERE VersionId = @VersionId
          AND (CashPolarityCode IS NULL OR CashTypeCode IS NULL)
    )
        THROW 51175, 'Every Category Tree category requires a Cash Polarity and Cash Type.', 1;

    IF EXISTS
    (
        SELECT 1
        FROM Cash.tbCategoryTotal AS edge
        JOIN Cash.tbCategory AS parent
          ON parent.VersionId = edge.VersionId
         AND parent.CategoryCode = edge.ParentCode
        WHERE edge.VersionId = @VersionId
          AND parent.CategoryTypeCode <> 1
    )
        THROW 51114, 'Every Category Tree parent must be a Total category.', 1;

    IF (SELECT COUNT(*) FROM Cash.tbCategoryRoot WHERE VersionId = @VersionId) <> 2
       OR EXISTS
          (
              SELECT required.RootTypeCode
              FROM (VALUES (CAST(0 AS SMALLINT)), (CAST(1 AS SMALLINT))) AS required (RootTypeCode)
              EXCEPT
              SELECT RootTypeCode
              FROM Cash.tbCategoryRoot
              WHERE VersionId = @VersionId
          )
        THROW 51115, 'A Category Tree version requires exactly the Net Profit and VAT roots.', 1;

    IF EXISTS
    (
        SELECT code.CashCode
        FROM Cash.tbCode AS code
        EXCEPT
        SELECT map.CashCode
        FROM Cash.tbCategoryCodeMap AS map
        WHERE map.VersionId = @VersionId
    )
        THROW 51116, 'Every persistent Cash Code requires a mapping in the Category Tree version.', 1;

    IF EXISTS
    (
        SELECT 1
        FROM Cash.tbCategoryCodeMap AS map
        LEFT JOIN Cash.tbCode AS code
          ON code.CashCode = map.CashCode
        JOIN Cash.tbCategory AS category
          ON category.VersionId = map.VersionId
         AND category.CategoryCode = map.CategoryCode
        WHERE map.VersionId = @VersionId
          AND (code.CashCode IS NULL OR category.CategoryTypeCode <> 0)
    )
        THROW 51117, 'Every mapping must reference a persistent Cash Code and a Nominal category.', 1;

    IF EXISTS
    (
        SELECT 1
        FROM Cash.tbTaxTagSource AS source
        CROSS APPLY Cash.fnTaxTagMapValidateByVersion(source.TaxSourceCode, @VersionId) AS validation
        WHERE validation.IsError = 1
    )
        THROW 51118, 'Tax Tag validation failed for the Category Tree version.', 1;

    EXEC Cash.proc_CategoryVersionCanonicalise
        @VersionId = @VersionId,
        @CanonicalSha256 = @CanonicalSha256 OUTPUT,
        @CanonicalByteLength = @CanonicalByteLength OUTPUT;

        INSERT INTO Cash.tbCategoryVersionEvent
        (
            VersionId, EventTypeCode, FromStatusCode, ToStatusCode,
            UserId, UserName, ChangeNote, ContentSha256
        )
        VALUES
        (
            @VersionId, 2, @VersionStatusCode, @VersionStatusCode,
            @UserId, @UserName, N'Category Tree validation passed.', @CanonicalSha256
        );

        COMMIT TRAN;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRAN;
        THROW;
    END CATCH;
END;
GO

PRINT N'Creating Procedure [Cash].[proc_CodeAdd]...';


GO
CREATE PROCEDURE [Cash].[proc_CodeAdd]
(
    @VersionId NVARCHAR(10),
    @CashCode NVARCHAR(50),
    @CashDescription NVARCHAR(100),
    @CategoryCode NVARCHAR(10),
    @TaxCode NVARCHAR(10),
    @IsEnabled SMALLINT = 1
)
AS
BEGIN
    SET NOCOUNT, XACT_ABORT ON;

    DECLARE @UserId NVARCHAR(10), @UserName NVARCHAR(50);
    SELECT TOP (1) @UserId = UserId, @UserName = UserName FROM Usr.vwCredentials;
    IF @UserId IS NULL THROW 51174, 'Cash Code creation requires an enabled application user.', 1;

    BEGIN TRY
        BEGIN TRAN;

        IF NOT EXISTS
        (
            SELECT 1
            FROM App.tbOptions WITH (UPDLOCK, HOLDLOCK)
            WHERE CategoryVersionId = @VersionId
        )
            THROW 51106, 'A new Cash Code must be added to the active Category Tree version.', 1;

        IF NOT EXISTS
        (
            SELECT 1
            FROM Cash.tbCategoryVersion WITH (UPDLOCK, HOLDLOCK)
            WHERE VersionId = @VersionId
              AND VersionStatusCode = 1
        )
            THROW 51107, 'A new Cash Code requires an editable active Published Category Tree version.', 1;

        IF NOT EXISTS
        (
            SELECT 1
            FROM Cash.tbCategory
            WHERE VersionId = @VersionId
              AND CategoryCode = @CategoryCode
              AND CategoryTypeCode = 0
        )
            THROW 51108, 'A new Cash Code must map to a Nominal category in the active version.', 1;

        IF EXISTS (SELECT 1 FROM Cash.tbCode WHERE CashCode = @CashCode)
            OR EXISTS
               (
                   SELECT 1
                   FROM Cash.tbCategoryCodeMap
                   WHERE VersionId = @VersionId
                     AND CashCode = @CashCode
               )
            THROW 51109, 'The Cash Code or its active Category Tree mapping already exists.', 1;

        EXEC sys.sp_set_session_context
            @key = N'CategoryTreeExplicitMapping',
            @value = 1;

        INSERT INTO Cash.tbCode
        (
            CashCode,
            CashDescription,
            CategoryCode,
            TaxCode,
            IsEnabled
        )
        VALUES
        (
            @CashCode,
            @CashDescription,
            @CategoryCode,
            @TaxCode,
            @IsEnabled
        );

        INSERT INTO Cash.tbCategoryCodeMap
        (
            VersionId,
            CashCode,
            CategoryCode
        )
        VALUES
        (
            @VersionId,
            @CashCode,
            @CategoryCode
        );

        INSERT Cash.tbCategoryVersionEvent
            (VersionId, EventTypeCode, FromStatusCode, ToStatusCode,
             UserId, UserName, ChangeNote)
        VALUES
            (@VersionId, 1, 1, 1, @UserId, @UserName,
             N'Cash Code created with its active-version mapping.');

        EXEC sys.sp_set_session_context
            @key = N'CategoryTreeExplicitMapping',
            @value = NULL;

        COMMIT TRAN;
    END TRY
    BEGIN CATCH
        EXEC sys.sp_set_session_context
            @key = N'CategoryTreeExplicitMapping',
            @value = NULL;

        IF XACT_STATE() <> 0 ROLLBACK TRAN;
        THROW;
    END CATCH
END;
GO

PRINT N'Creating Procedure [Cash].[proc_CodeDelete]...';


GO
CREATE PROCEDURE [Cash].[proc_CodeDelete]
(
    @CashCode NVARCHAR(50),
    @ChangeNote NVARCHAR(MAX) = NULL
)
AS
BEGIN
    SET NOCOUNT, XACT_ABORT ON;

    DECLARE @UserId NVARCHAR(10), @UserName NVARCHAR(50);
    DECLARE @AffectedVersions TABLE
    (
        VersionId NVARCHAR(10) NOT NULL PRIMARY KEY,
        VersionStatusCode SMALLINT NOT NULL
    );

    SELECT TOP (1) @UserId = UserId, @UserName = UserName FROM Usr.vwCredentials;
    IF @UserId IS NULL THROW 51171, 'Cash Code deletion requires an enabled application user.', 1;

    BEGIN TRY
        BEGIN TRAN;

        IF NOT EXISTS (SELECT 1 FROM Cash.tbCode WITH (UPDLOCK, HOLDLOCK) WHERE CashCode = @CashCode)
            THROW 51172, 'The Cash Code was not found.', 1;

        IF EXISTS
        (
            SELECT 1
            FROM Cash.tbCategoryCodeMap AS map WITH (UPDLOCK, HOLDLOCK)
            JOIN Cash.tbCategoryVersion AS version
              ON version.VersionId = map.VersionId
            WHERE map.CashCode = @CashCode
              AND version.VersionStatusCode IN (2, 3)
        )
            THROW 51173, 'A Cash Code mapped by a Submitted or Archived version cannot be deleted; disable it instead.', 1;

        INSERT @AffectedVersions (VersionId, VersionStatusCode)
        SELECT map.VersionId, version.VersionStatusCode
        FROM Cash.tbCategoryCodeMap AS map
        JOIN Cash.tbCategoryVersion AS version
          ON version.VersionId = map.VersionId
        WHERE map.CashCode = @CashCode
          AND version.VersionStatusCode IN (0, 1);

        EXEC sys.sp_set_session_context @key = N'CategoryTreeExplicitMapping', @value = 1;

        DELETE map
        FROM Cash.tbCategoryCodeMap AS map
        JOIN @AffectedVersions AS affected
          ON affected.VersionId = map.VersionId
        WHERE map.CashCode = @CashCode;

        DELETE FROM Cash.tbCode WHERE CashCode = @CashCode;

        INSERT Cash.tbCategoryVersionEvent
            (VersionId, EventTypeCode, FromStatusCode, ToStatusCode,
             UserId, UserName, ChangeNote)
        SELECT affected.VersionId, 1, affected.VersionStatusCode, affected.VersionStatusCode,
               @UserId, @UserName,
               COALESCE(NULLIF(LTRIM(RTRIM(@ChangeNote)), N''), N'Cash Code deleted with its editable-version mappings.')
        FROM @AffectedVersions AS affected;

        EXEC sys.sp_set_session_context @key = N'CategoryTreeExplicitMapping', @value = NULL;
        COMMIT TRAN;
    END TRY
    BEGIN CATCH
        EXEC sys.sp_set_session_context @key = N'CategoryTreeExplicitMapping', @value = NULL;
        IF XACT_STATE() <> 0 ROLLBACK TRAN;
        THROW;
    END CATCH;
END;
GO

PRINT N'Creating Trigger [App].[App_tbOptions_TriggerUpdate]...';


GO
CREATE TRIGGER App.App_tbOptions_TriggerUpdate 
   ON App.tbOptions
   AFTER INSERT, UPDATE
AS 
BEGIN
	SET NOCOUNT ON;
	BEGIN TRY
		IF (SELECT COUNT_BIG(*) FROM App.tbOptions WITH (TABLOCKX, HOLDLOCK)) > 1
			THROW 51089, 'App.tbOptions must contain no more than one row.', 1;

		IF EXISTS
		(
			SELECT 1
			FROM inserted AS i
			WHERE i.IsInitialised = 1
			  AND i.CategoryVersionId IS NULL
		)
			THROW 51090, 'An initialised node requires an active Category Tree version.', 1;

		IF EXISTS
		(
			SELECT 1
			FROM inserted AS i
			LEFT JOIN Cash.tbCategoryVersion AS version
			  ON version.VersionId = i.CategoryVersionId
			WHERE i.CategoryVersionId IS NOT NULL
			  AND (version.VersionId IS NULL OR version.VersionStatusCode NOT IN (1, 2))
		)
			THROW 51091, 'The active Category Tree pointer must reference a Published or Submitted version.', 1;

		UPDATE App.tbOptions
		SET UpdatedBy = Usr.fnUserName(), UpdatedOn = CURRENT_TIMESTAMP
		FROM App.tbOptions INNER JOIN inserted AS i ON tbOptions.Identifier = i.Identifier;

		IF UPDATE(CoinTypeCode)
		BEGIN
			UPDATE Subject.tbAccount
			SET CoinTypeCode = (SELECT CoinTypeCode FROM inserted)
		END

        DECLARE @Candidates TABLE (Code nvarchar(10) NOT NULL PRIMARY KEY);

        INSERT INTO @Candidates(Code)
        SELECT i.NetProfitCode FROM inserted i WHERE i.NetProfitCode IS NOT NULL
        UNION
        SELECT i.VatCategoryCode FROM inserted i WHERE i.VatCategoryCode IS NOT NULL;

        -- Rule 1: must be an enabled category
        IF EXISTS
        (
            SELECT 1
            FROM @Candidates x
            LEFT JOIN Cash.tbCategory c ON c.CategoryCode = x.Code
            WHERE c.CategoryCode IS NULL OR c.IsEnabled = 0
        )
        BEGIN
            RAISERROR('Primary root must be an enabled category.', 16, 1);
            RETURN;
        END

        -- Rule 2: must be a true root (no parent edge)
        IF EXISTS
        (
            SELECT 1
            FROM @Candidates x
            JOIN Cash.tbCategoryTotal t ON t.ChildCode = x.Code
        )
        BEGIN
            RAISERROR('Only root categories (no parents) can be assigned as primary roots.', 16, 1);
            RETURN;
        END

        -- Rule 3: must participate as a parent in the graph (has at least one child)
        IF EXISTS
        (
            SELECT 1
            FROM @Candidates x
            WHERE NOT EXISTS (SELECT 1 FROM Cash.tbCategoryTotal t WHERE t.ParentCode = x.Code)
        )
        BEGIN
            RAISERROR('Primary root must be a parent in the totals graph (has at least one child).', 16, 1);
            RETURN;
        END

		IF UPDATE(CategoryVersionId) OR UPDATE(NetProfitCode) OR UPDATE(VatCategoryCode)
		BEGIN
			UPDATE root
			SET CategoryCode = source.CategoryCode
			FROM Cash.tbCategoryRoot AS root
			JOIN
			(
				SELECT i.CategoryVersionId AS VersionId, CAST(0 AS SMALLINT) AS RootTypeCode, i.NetProfitCode AS CategoryCode
				FROM inserted AS i
				UNION ALL
				SELECT i.CategoryVersionId, CAST(1 AS SMALLINT), i.VatCategoryCode
				FROM inserted AS i
			) AS source
			  ON source.VersionId = root.VersionId
			 AND source.RootTypeCode = root.RootTypeCode
			WHERE source.CategoryCode IS NOT NULL
			  AND root.CategoryCode <> source.CategoryCode;

			INSERT INTO Cash.tbCategoryRoot (VersionId, RootTypeCode, CategoryCode)
			SELECT source.VersionId, source.RootTypeCode, source.CategoryCode
			FROM
			(
				SELECT i.CategoryVersionId AS VersionId, CAST(0 AS SMALLINT) AS RootTypeCode, i.NetProfitCode AS CategoryCode
				FROM inserted AS i
				UNION ALL
				SELECT i.CategoryVersionId, CAST(1 AS SMALLINT), i.VatCategoryCode
				FROM inserted AS i
			) AS source
			WHERE source.VersionId IS NOT NULL
			  AND source.CategoryCode IS NOT NULL
			  AND NOT EXISTS
			  (
				SELECT 1
				FROM Cash.tbCategoryRoot AS root
				WHERE root.VersionId = source.VersionId
				  AND root.RootTypeCode = source.RootTypeCode
			  );
		END

	END TRY
	BEGIN CATCH
		EXEC App.proc_ErrorLog;
	END CATCH
END
GO

PRINT N'Altering Procedure [App].[proc_BasicSetup]...';


GO
ALTER PROCEDURE App.proc_BasicSetup
(
	@TemplateCode NVARCHAR(10),
	@FinancialMonth SMALLINT = 4,
	@CoinTypeCode SMALLINT,
	@GovAccountName NVARCHAR(255),
	@BankName NVARCHAR(255) = null,
	@BankAddress NVARCHAR(MAX) = null,
	@DummyAccount NVARCHAR(50) = null, 
	@CurrentAccount NVARCHAR(50) = null,
	@CA_SortCode NVARCHAR(10) = null,
	@CA_AccountNumber NVARCHAR(20) = null,
	@ReserveAccount NVARCHAR(50) = null, 
	@RA_SortCode NVARCHAR(10) = null,
	@RA_AccountNumber NVARCHAR(20) = null,
	@IsVatRegistered BIT = 0,
	@ExpectedAnnualProfit DECIMAL(18, 2) = NULL,
	@AsOfDate DATE = NULL
)
AS
	SET @AsOfDate = COALESCE(@AsOfDate, CONVERT(DATE, CURRENT_TIMESTAMP));

	DECLARE 
		@FinancialYear SMALLINT = DATEPART(YEAR, @AsOfDate),
		@IsCompany bit;

	SELECT @IsCompany = IsCompany
	FROM App.tbTemplate
	WHERE TemplateCode = @TemplateCode;

	IF @IsCompany IS NULL
		THROW 51001, 'BasicSetup: template was not found in App.tbTemplate.', 1;

	IF @IsCompany = 0 AND (@ExpectedAnnualProfit IS NULL OR @ExpectedAnnualProfit <= 0)
		THROW 51002, 'BasicSetup: expected annual profit must be greater than zero for a sole trader.', 1;

	IF EXISTS (SELECT 1 FROM App.tbOptions WHERE UnitOfCharge <> 'BTC')
		AND NULLIF(LTRIM(RTRIM(@BankName)), '') IS NULL
		THROW 51003, 'BasicSetup: bank name is required for a fiat-currency node.', 1;

	IF EXISTS (SELECT 1 FROM App.tbOptions WHERE UnitOfCharge <> 'BTC')
		AND NULLIF(LTRIM(RTRIM(@CurrentAccount)), '') IS NULL
		THROW 51004, 'BasicSetup: current account name is required for a fiat-currency node.', 1;

		IF EXISTS (SELECT * FROM App.tbOptions WHERE UnitOfCharge <> 'BTC') AND (@CoinTypeCode <> 2)
			SET @CoinTypeCode = 2;

		IF DATEPART(MONTH, @AsOfDate) < @FinancialMonth
			 SET @FinancialYear -= 1;
		
	DECLARE 
		@Year SMALLINT = @FinancialYear - 1;

	SET NOCOUNT, XACT_ABORT ON;

	BEGIN TRY
		BEGIN TRAN
		
		UPDATE App.tbOptions
		SET CoinTypeCode = @CoinTypeCode;

		IF EXISTS (SELECT 1 FROM Cash.tbCategoryVersion)
			THROW 51005, 'BasicSetup: a Category Tree version already exists.', 1;

		DECLARE
			@CategoryVersionId NVARCHAR(10),
			@CreatedByUserId NVARCHAR(10),
			@CreatedByUserName NVARCHAR(50),
			@CategoryVersionDescription NVARCHAR(100);

		SELECT
			@CreatedByUserId = UserId,
			@CreatedByUserName = UserName
		FROM Usr.vwCredentials;

		IF @CreatedByUserId IS NULL
			THROW 51006, 'BasicSetup: no current application user was found.', 1;

		SELECT @CategoryVersionDescription = LEFT(TemplateName, 100)
		FROM App.tbTemplate
		WHERE TemplateCode = @TemplateCode;

		EXEC Cash.proc_CategoryVersionIdNext @VersionId = @CategoryVersionId OUTPUT;

		INSERT INTO Cash.tbCategoryVersion
		(
			VersionId,
			VersionStatusCode,
			Description,
			CreatedByUserId
		)
		VALUES
		(
			@CategoryVersionId,
			0,
			@CategoryVersionDescription,
			@CreatedByUserId
		);

		INSERT INTO Cash.tbCategoryVersionEvent
		(
			VersionId,
			EventTypeCode,
			ToStatusCode,
			UserId,
			UserName,
			ChangeNote
		)
		VALUES
		(
			@CategoryVersionId,
			0,
			0,
			@CreatedByUserId,
			@CreatedByUserName,
			N'Initial Category Tree version created by node commissioning.'
		);

		DECLARE @ProcName nvarchar(100) =
			(SELECT StoredProcedure FROM App.tbTemplate WHERE TemplateCode = @TemplateCode);

		EXEC @ProcName
				@CategoryVersionId = @CategoryVersionId,
				@FinancialMonth = @FinancialMonth,
				@GovAccountName = @GovAccountName, 
				@BankName = @BankName, 
				@BankAddress = @BankAddress, 
				@DummyAccount = @DummyAccount, 
				@CurrentAccount = @CurrentAccount, 
				@CA_SortCode = @CA_SortCode, 
				@CA_AccountNumber = @CA_AccountNumber, 
				@ReserveAccount = @ReserveAccount, 
				@RA_SortCode = @RA_SortCode, 
				@RA_AccountNumber = @RA_AccountNumber,
				@IsVATRegistered = @IsVatRegistered;

		--TIME PERIODS
		WHILE (@Year < DATEPART(YEAR, @AsOfDate) + 2)
		BEGIN
		
			INSERT INTO App.tbYear (YearNumber, StartMonth, CashStatusCode, Description)
			VALUES (@Year, @FinancialMonth, 0, 
						CASE WHEN @FinancialMonth > 1 THEN CONCAT(@Year, '-', @Year - ROUND(@Year, -2) + 1) ELSE CONCAT(@Year, '.') END
					);
			SET @Year += 1;
		END

		EXEC Cash.proc_GeneratePeriods;

		UPDATE App.tbYearPeriod
		SET BusinessTaxRate = CASE
			WHEN @IsCompany <> 0 THEN CAST(0.19 AS decimal(9, 6))
			ELSE CAST(Cash.fnPersonalEffectiveRateCalculator(@ExpectedAnnualProfit) AS decimal(9, 6))
		END;

		UPDATE App.tbYearPeriod
		SET CashStatusCode = 2
		WHERE StartOn < DATEADD(MONTH, -1, @AsOfDate)

		IF EXISTS(SELECT * FROM App.tbYearPeriod WHERE CashStatusCode = 3)
			WITH current_month AS
			(
				SELECT MAX(StartOn) AS StartOn
				FROM App.tbYearPeriod
				WHERE CashStatusCode = 2
			)
			UPDATE App.tbYearPeriod
			SET CashStatusCode = 1
			FROM App.tbYearPeriod JOIN current_month ON App.tbYearPeriod.StartOn = current_month.StartOn;	
		ELSE
			WITH current_month AS
			(
				SELECT MIN(StartOn) AS StartOn
				FROM App.tbYearPeriod
				WHERE CashStatusCode = 0
			)
			UPDATE App.tbYearPeriod
			SET CashStatusCode = 1
			FROM App.tbYearPeriod JOIN current_month ON App.tbYearPeriod.StartOn = current_month.StartOn;
	
	
		WITH current_month AS
		(
			SELECT YearNumber
			FROM App.tbYearPeriod
			WHERE CashStatusCode = 1
		)
		UPDATE App.tbYear
		SET CashStatusCode = 1
		FROM App.tbYear JOIN current_month ON App.tbYear.YearNumber = current_month.YearNumber;

		UPDATE App.tbYear
		SET CashStatusCode = 2
		WHERE YearNumber < 	(SELECT YearNumber FROM App.tbYear	WHERE CashStatusCode = 1);

		IF EXISTS
		(
			SELECT 1
			FROM Cash.tbCode AS code
			LEFT JOIN Cash.tbCategoryCodeMap AS map
			  ON map.VersionId = @CategoryVersionId
			 AND map.CashCode = code.CashCode
			WHERE map.CashCode IS NULL
		)
			THROW 51007, 'BasicSetup: one or more Cash Codes lack a shadow Category mapping.', 1;

		IF (SELECT COUNT(*) FROM Cash.tbCategoryRoot WHERE VersionId = @CategoryVersionId) <> 2
			THROW 51008, 'BasicSetup: the Category Tree requires Net Profit and VAT roots.', 1;

		DECLARE
			@CategoryVersionSha256 BINARY(32),
			@CategoryVersionByteLength BIGINT;

		EXEC Cash.proc_CategoryVersionCanonicalise
			@VersionId = @CategoryVersionId,
			@CanonicalSha256 = @CategoryVersionSha256 OUTPUT,
			@CanonicalByteLength = @CategoryVersionByteLength OUTPUT;

		UPDATE Cash.tbCategoryVersion
		SET VersionStatusCode = 1,
			EffectiveFromOn = @AsOfDate
		WHERE VersionId = @CategoryVersionId;

		UPDATE App.tbOptions
		SET CategoryVersionId = @CategoryVersionId;

		INSERT INTO Cash.tbCategoryVersionEvent
		(
			VersionId,
			EventTypeCode,
			FromStatusCode,
			ToStatusCode,
			UserId,
			UserName,
			ChangeNote,
			ContentSha256
		)
		VALUES
		(
			@CategoryVersionId,
			3,
			0,
			1,
			@CreatedByUserId,
			@CreatedByUserName,
			N'Initial Category Tree version captured from the commissioned template.',
			@CategoryVersionSha256
		);

		COMMIT TRAN
	END TRY
	BEGIN CATCH
		EXEC App.proc_ErrorLog
	END CATCH
GO

