PRINT N'Altering Procedure [Cash].[proc_PaymentPostMisc]...';


GO
ALTER PROCEDURE Cash.proc_PaymentPostMisc
	(
	@PaymentCode nvarchar(20) 
	)
 AS
 	SET NOCOUNT, XACT_ABORT ON;

	BEGIN TRY
		DECLARE 
			@InvoiceNumber nvarchar(20), 
			@NextNumber int, 
			@InvoiceTypeCode smallint;

		IF NOT EXISTS (SELECT Cash.tbPayment.PaymentCode
						FROM Cash.tbPayment
							INNER JOIN Cash.vwCodeActive ON Cash.tbPayment.CashCode = Cash.vwCodeActive.CashCode
							INNER JOIN Cash.vwCategoryActive ON Cash.vwCodeActive.CategoryCode = Cash.vwCategoryActive.CategoryCode
						WHERE (Cash.tbPayment.PaymentStatusCode <> 1)
							AND Cash.tbPayment.UserId = (SELECT UserId FROM Usr.vwCredentials))
			RETURN;

		------------------------------------------------------------------------
		-- Guard: if VAT is being charged, cash code must be in enabled VAT tree
		------------------------------------------------------------------------
		IF EXISTS
		(
			SELECT 1
			FROM Cash.tbPayment p
				JOIN App.tbTaxCode tc
                    ON p.TaxCode = tc.TaxCode
                JOIN Cash.tbTaxType tt
                    ON tc.TaxTypeCode = tt.TaxTypeCode
			WHERE p.PaymentCode = @PaymentCode
			  AND tc.TaxTypeCode = 1
			  AND tc.TaxRate <> 0
			  AND NOT EXISTS (SELECT 1 FROM App.vwTaxVatCashCodes v WHERE v.CashCode = p.CashCode)
              AND tt.IsEnabled != 0
		)
		BEGIN
			DECLARE @CashCode nvarchar(50) = (SELECT CashCode FROM Cash.tbPayment WHERE PaymentCode = @PaymentCode);
			DECLARE @TaxCode nvarchar(10) = (SELECT TaxCode FROM Cash.tbPayment WHERE PaymentCode = @PaymentCode);
            DECLARE @ErrorMessage nvarchar(255) = CONCAT('PaymentPostMisc: VAT tax code ', @TaxCode, ' used with cash code ', @CashCode, ' not in VAT category tree.');
			THROW 51410, @ErrorMessage, 1;
		END

		SELECT @InvoiceTypeCode = CASE WHEN PaidInValue != 0 THEN 0 ELSE 2 END 
		FROM Cash.tbPayment
		WHERE (PaymentCode = @PaymentCode)
	
		SELECT @NextNumber = NextNumber
		FROM Invoice.tbType
		WHERE InvoiceTypeCode = @InvoiceTypeCode;
		
		SET @InvoiceNumber = FORMAT(@NextNumber, '000000') + '.' + (SELECT UserId FROM Usr.vwCredentials)

		WHILE EXISTS (SELECT InvoiceNumber
					  FROM Invoice.tbInvoice
					  WHERE (InvoiceNumber = @InvoiceNumber))
			BEGIN
			SET @NextNumber += @NextNumber 
			SET @InvoiceNumber = FORMAT(@NextNumber, '000000') + '.' + (SELECT UserId FROM Usr.vwCredentials)
			END
		
		BEGIN TRANSACTION

		UPDATE Invoice.tbType
		SET NextNumber = @NextNumber + 1
		WHERE (InvoiceTypeCode = @InvoiceTypeCode);

		WITH payment AS
		(
			SELECT
				UserId,
				SubjectCode,
				ParentSubjectCode,
				PaidOn,
				PaidInValue,
				PaidOutValue,
				CASE TaxRate WHEN 0 THEN 0
					ELSE
					(
						CASE App.tbTaxCode.RoundingCode 
							WHEN 0 THEN ROUND(Cash.tbPayment.PaidInValue - (Cash.tbPayment.PaidInValue / (1 + App.tbTaxCode.TaxRate)), Decimals) 
							WHEN 1 THEN ROUND(Cash.tbPayment.PaidInValue - (Cash.tbPayment.PaidInValue / (1 + App.tbTaxCode.TaxRate)), Decimals, 1) 
						END
					)
				END TaxInValue,
				CASE TaxRate WHEN 0 THEN 0
					ELSE
					(
						CASE App.tbTaxCode.RoundingCode 
							WHEN 0 THEN ROUND(Cash.tbPayment.PaidOutValue - (Cash.tbPayment.PaidOutValue / (1 + App.tbTaxCode.TaxRate)), Decimals) 
							WHEN 1 THEN ROUND(Cash.tbPayment.PaidOutValue - (Cash.tbPayment.PaidOutValue / (1 + App.tbTaxCode.TaxRate)), Decimals, 1) 
						END
					)
				END TaxOutValue
			FROM Cash.tbPayment
				INNER JOIN App.tbTaxCode ON Cash.tbPayment.TaxCode = App.tbTaxCode.TaxCode
			WHERE (PaymentCode = @PaymentCode)
		)
		INSERT INTO Invoice.tbInvoice
			(InvoiceNumber, UserId, SubjectCode, ParentSubjectCode, InvoiceTypeCode, InvoiceStatusCode, InvoicedOn, DueOn, ExpectedOn, InvoiceValue, TaxValue, PaidValue, PaidTaxValue, Printed)
		SELECT
			@InvoiceNumber AS InvoiceNumber,
			payment.UserId,
			payment.SubjectCode,
			payment.ParentSubjectCode,
			@InvoiceTypeCode AS InvoiceTypeCode,
			3 AS InvoiceStatusCode,
			payment.PaidOn,
			payment.PaidOn AS DueOn,
			payment.PaidOn AS ExpectedOn,
			CASE WHEN PaidInValue > 0 THEN PaidInValue - TaxInValue
				WHEN PaidOutValue > 0 THEN PaidOutValue - TaxOutValue
			END AS InvoiceValue,
			CASE WHEN payment.PaidInValue > 0 THEN payment.TaxInValue
				WHEN payment.PaidOutValue > 0 THEN payment.TaxOutValue
			END AS TaxValue,
			CASE WHEN PaidInValue > 0 THEN PaidInValue - TaxInValue
				WHEN PaidOutValue > 0 THEN PaidOutValue - TaxOutValue
			END AS PaidValue,
			CASE WHEN payment.PaidInValue > 0 THEN payment.TaxInValue
				WHEN payment.PaidOutValue > 0 THEN payment.TaxOutValue
			END AS PaidTaxValue,
			1 AS Printed
		FROM payment;

		WITH payment AS
		(
			SELECT CashCode, TaxCode
			FROM Cash.tbPayment
			WHERE (Cash.tbPayment.PaymentCode = @PaymentCode)
		), invoice_header AS
		(
			SELECT InvoiceNumber, InvoiceValue, TaxValue
			FROM Invoice.tbInvoice
			WHERE InvoiceNumber = @InvoiceNumber
		)
		INSERT INTO Invoice.tbItem
			(InvoiceNumber, CashCode, InvoiceValue, TaxValue, TaxCode)
		SELECT TOP 1 InvoiceNumber, CashCode, InvoiceValue, TaxValue, TaxCode
		FROM payment
			CROSS JOIN invoice_header;

		UPDATE Subject.tbAccount
		SET CurrentBalance = CASE WHEN PaidInValue > 0 THEN Subject.tbAccount.CurrentBalance + PaidInValue ELSE Subject.tbAccount.CurrentBalance - PaidOutValue END
		FROM Subject.tbAccount
			INNER JOIN Cash.tbPayment ON Subject.tbAccount.AccountCode = Cash.tbPayment.AccountCode
		WHERE Cash.tbPayment.PaymentCode = @PaymentCode

		UPDATE Cash.tbPayment
		SET PaymentStatusCode = 1
		WHERE (PaymentCode = @PaymentCode)

		COMMIT TRANSACTION

  	END TRY
	BEGIN CATCH
		EXEC App.proc_ErrorLog;
	END CATCH
GO

PRINT N'Altering Procedure [Cash].[proc_PaymentPostById]...';


GO
ALTER PROCEDURE Cash.proc_PaymentPostById
    @UserId nvarchar(10)
AS
    SET NOCOUNT, XACT_ABORT ON;

    BEGIN TRY
        DECLARE @PaymentCode nvarchar(20);

        DECLARE curMisc CURSOR LOCAL FOR
            SELECT payment.PaymentCode
            FROM Cash.tbPayment AS payment
                INNER JOIN Cash.vwCodeActive AS code
                    ON payment.CashCode = code.CashCode
                INNER JOIN Cash.vwCategoryActive AS category
                    ON code.CategoryCode = category.CategoryCode
                INNER JOIN Subject.tbAccount AS account
                    ON account.AccountCode = payment.AccountCode
            WHERE account.AccountTypeCode < 2
              AND payment.PaymentStatusCode = 0
              AND payment.UserId = @UserId
            ORDER BY
                payment.SubjectCode,
                payment.ParentSubjectCode,
                payment.PaidOn,
                payment.PaymentCode;

        DECLARE curInv CURSOR LOCAL FOR
            SELECT payment.PaymentCode
            FROM Cash.tbPayment AS payment
            WHERE payment.PaymentStatusCode = 0
              AND payment.CashCode IS NULL
              AND payment.UserId = @UserId
            ORDER BY
                payment.SubjectCode,
                payment.ParentSubjectCode,
                payment.PaidOn,
                payment.PaymentCode;

        BEGIN TRANSACTION;

        OPEN curMisc;
        FETCH NEXT FROM curMisc INTO @PaymentCode;

        WHILE @@FETCH_STATUS = 0
        BEGIN
            EXEC Cash.proc_PaymentPostMisc @PaymentCode;
            FETCH NEXT FROM curMisc INTO @PaymentCode;
        END;

        CLOSE curMisc;
        DEALLOCATE curMisc;

        OPEN curInv;
        FETCH NEXT FROM curInv INTO @PaymentCode;

        WHILE @@FETCH_STATUS = 0
        BEGIN
            EXEC Cash.proc_PaymentPostInvoiced @PaymentCode;
            FETCH NEXT FROM curInv INTO @PaymentCode;
        END;

        CLOSE curInv;
        DEALLOCATE curInv;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        EXEC App.proc_ErrorLog;
    END CATCH
GO

PRINT N'Altering Procedure [Invoice].[proc_Mirror]...';


GO
ALTER PROCEDURE Invoice.proc_Mirror(@ContractAddress nvarchar(42), @InvoiceNumber nvarchar(20) OUTPUT)
AS
 	SET NOCOUNT, XACT_ABORT ON;

	BEGIN TRY
	DECLARE 
		@UserId nvarchar(10)
		, @NextNumber int
		, @InvoiceSuffix nvarchar(4)
		, @SubjectCode nvarchar(50)
		, @InvoiceTypeCode smallint
	
		SELECT @UserId = UserId FROM Usr.vwCredentials
		SET @InvoiceSuffix = '.' + @UserId

		SELECT 
			@InvoiceTypeCode = CASE InvoiceTypeCode 
								WHEN 0 THEN 2
								WHEN 1 THEN 3
								WHEN 2 THEN 0
								WHEN 3 THEN 1
							END
		FROM Invoice.tbMirror
		WHERE ContractAddress = @ContractAddress
	
		SELECT @NextNumber = NextNumber
		FROM Invoice.tbType
		WHERE InvoiceTypeCode = @InvoiceTypeCode
	
		SELECT @InvoiceNumber = FORMAT(@NextNumber, '000000') + @InvoiceSuffix
	
		WHILE EXISTS (SELECT     InvoiceNumber
						FROM         Invoice.tbInvoice
						WHERE     (InvoiceNumber = @InvoiceNumber))
			BEGIN
			SET @NextNumber = @NextNumber + 1
			SET @InvoiceNumber = FORMAT(@NextNumber, '000000') + @InvoiceSuffix
			END

		BEGIN TRAN

		UPDATE    Invoice.tbType
		SET              NextNumber = @NextNumber + 1
		WHERE     (InvoiceTypeCode = @InvoiceTypeCode)
	
		INSERT INTO Invoice.tbInvoice
							(InvoiceNumber, UserId, SubjectCode, InvoiceTypeCode, InvoicedOn, DueOn, ExpectedOn, InvoiceStatusCode, PaymentTerms)
		SELECT     @InvoiceNumber AS InvoiceNumber, @UserId AS UserId, mirror.SubjectCode, 
				@InvoiceTypeCode AS InvoiceTypeCode, CAST(mirror.InvoicedOn AS DATE) AS InvoicedOn, mirror.DueOn, mirror.DueOn ExpectedOn, 0 AS InvoiceStatusCode, 
				CASE WHEN Subject.tbSubject.PaymentTerms IS NULL THEN mirror.PaymentTerms ELSE Subject.tbSubject.PaymentTerms END PaymentTerms
		FROM Invoice.tbMirror mirror
			JOIN Subject.tbSubject ON mirror.SubjectCode = Subject.tbSubject.SubjectCode
		WHERE ContractAddress = @ContractAddress;

		INSERT INTO Invoice.tbMirrorReference (ContractAddress, InvoiceNumber)
		VALUES (@ContractAddress, @InvoiceNumber);

		WITH allocations AS
		(
			SELECT 0 Allocationid, 
				allocation.ProjectCode,
				Object_mirror.ObjectCode, allocation.SubjectCode, 
					CASE allocation.CashPolarityCode 
						WHEN 0 THEN Project_mirror.Quantity * -1
						WHEN 1 THEN Project_mirror.Quantity
					END Quantity, allocation.CashPolarityCode
			FROM Invoice.tbMirror invoice_mirror
				JOIN Invoice.tbMirrorProject Project_mirror ON invoice_mirror.ContractAddress = Project_mirror.ContractAddress
				JOIN Project.tbAllocation allocation ON invoice_mirror.SubjectCode = allocation.SubjectCode AND Project_mirror.ProjectCode = allocation.ProjectCode			
				JOIN Object.tbMirror Object_mirror ON invoice_mirror.SubjectCode = Object_mirror.SubjectCode AND allocation.AllocationCode = Object_mirror.AllocationCode
			WHERE invoice_mirror.ContractAddress = @ContractAddress
		), Projects AS
		(
			SELECT ROW_NUMBER() OVER (PARTITION BY Projects.SubjectCode, Projects.ObjectCode ORDER BY ActionOn) Allocationid,
				Projects.ProjectCode, Projects.ObjectCode, Projects.SubjectCode, Projects.Quantity, category.CashPolarityCode
			FROM allocations
				JOIN Project.tbProject Projects ON Projects.ObjectCode = allocations.ObjectCode AND Projects.SubjectCode = allocations.SubjectCode
				JOIN Cash.vwCodeActive cash_code ON Projects.CashCode = cash_code.CashCode
				JOIN Cash.vwCategoryActive category ON cash_code.CategoryCode = category.CategoryCode
			WHERE Projects.ProjectStatusCode BETWEEN 1 AND 2
		), order_book AS
		(
			SELECT Projects.ProjectCode, SUM(COALESCE(invoice_quantity.Quantity, 0)) InvoiceQuantity
			FROM Projects
				OUTER APPLY 
					(
						SELECT CASE invoice.InvoiceTypeCode 
									WHEN 1 THEN delivery.Quantity * -1 
									WHEN 3 THEN delivery.Quantity * -1 
									ELSE delivery.Quantity 
								END Quantity
						FROM Invoice.tbProject delivery 
							JOIN Invoice.tbInvoice invoice ON delivery.InvoiceNumber = invoice.InvoiceNumber
						WHERE delivery.ProjectCode = Projects.ProjectCode
					) invoice_quantity
			GROUP BY Projects.ProjectCode
		), deliveries AS
		(
			SELECT Allocationid, Projects.ProjectCode, ObjectCode, SubjectCode,
						CASE CashPolarityCode 
							WHEN 0 THEN (Projects.Quantity - order_book.InvoiceQuantity) * -1
							WHEN 1 THEN Projects.Quantity - order_book.InvoiceQuantity
						END Quantity, CashPolarityCode		
			FROM Projects
				JOIN order_book ON Projects.ProjectCode = order_book.ProjectCode
		), svd_union AS
		(
			SELECT * FROM deliveries
			UNION 
			SELECT * FROM allocations
		), svd_projected AS
		(
			SELECT *,
				SUM(Quantity) OVER (PARTITION BY SubjectCode, ObjectCode  ORDER BY AllocationId ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS Balance
			FROM svd_union
		), svd_balance AS
		(
			SELECT *, LAG(Balance) OVER (PARTITION BY SubjectCode, ObjectCode  ORDER BY AllocationId) PreviousBalance
			FROM svd_projected
		), alloc_deliveries AS
		(
			SELECT *, 
					CASE CashPolarityCode 
						WHEN 0 THEN
							CASE WHEN Balance > 0 THEN ABS(Quantity) 
								WHEN PreviousBalance > 0 THEN PreviousBalance
								ELSE 0
							END 
						WHEN 1 THEN
							CASE WHEN Balance < 0 THEN Quantity
								WHEN PreviousBalance < 0 THEN ABS(PreviousBalance)
								ELSE 0
							END 
					END QuantityDelivered
			FROM svd_balance
		)
		INSERT INTO Invoice.tbProject (InvoiceNumber, ProjectCode, Quantity, InvoiceValue, CashCode, TaxCode)
		SELECT @InvoiceNumber InvoiceNumber, alloc_deliveries.ProjectCode, alloc_deliveries.QuantityDelivered, Project.UnitCharge * alloc_deliveries.QuantityDelivered, Project.CashCode, Project.TaxCode 
		FROM alloc_deliveries
			JOIN Project.tbProject Project ON alloc_deliveries.ProjectCode = Project.ProjectCode
		WHERE QuantityDelivered > 0;

		INSERT INTO Invoice.tbItem (InvoiceNumber, CashCode, TaxCode, InvoiceValue, ItemReference)
		SELECT @InvoiceNumber InvoiceNumber, cash_code_mirror.CashCode, 
			CASE WHEN (item_mirror.TaxValue / item_mirror.InvoiceValue) <> tax_code.TaxRate 
				THEN (SELECT TOP 1 TaxCode FROM App.tbTaxCode WHERE TaxTypeCode = 1 AND ROUND(TaxRate, 3) =  ROUND((item_mirror.TaxValue / item_mirror.InvoiceValue), 3))
				ELSE tax_code.TaxCode 
				END TaxCode,
				item_mirror.InvoiceValue, item_mirror.ChargeDescription ItemReference
		FROM Invoice.tbMirror invoice_mirror 
			JOIN Invoice.tbMirrorItem item_mirror ON invoice_mirror.ContractAddress = item_mirror.ContractAddress			
			JOIN Cash.tbMirror cash_code_mirror ON item_mirror.ChargeCode = cash_code_mirror.ChargeCode and invoice_mirror.SubjectCode = cash_code_mirror.SubjectCode
			JOIN Cash.vwCodeActive cash_code ON cash_code_mirror.CashCode = cash_code.CashCode
			JOIN App.tbTaxCode tax_code ON cash_code.TaxCode = tax_code.TaxCode
		WHERE invoice_mirror.ContractAddress = @ContractAddress

		EXEC Invoice.proc_Total @InvoiceNumber	

		COMMIT TRAN

  	END TRY
	BEGIN CATCH
		EXEC App.proc_ErrorLog;
	END CATCH
GO

PRINT N'Altering Procedure [App].[proc_PeriodClose]...';


GO
ALTER PROCEDURE App.proc_PeriodClose
AS
 	SET NOCOUNT, XACT_ABORT ON;

	BEGIN TRY
		IF EXISTS(SELECT * FROM App.fnActivePeriod())
			BEGIN
			DECLARE @StartOn datetime, @YearNumber smallint

			SELECT @StartOn = StartOn, @YearNumber = YearNumber
			FROM App.fnActivePeriod() fnSystemActivePeriod
		 	
			EXEC Cash.proc_GeneratePeriods

			BEGIN TRAN

			UPDATE       Cash.tbPeriod
			SET                InvoiceValue = 0, InvoiceTax = 0
			FROM            Cash.tbPeriod 
			WHERE        (Cash.tbPeriod.StartOn = @StartOn);

			WITH invoice_entries AS
			(
				SELECT invoices.CashCode, invoices.StartOn, categories.CashPolarityCode, SUM(invoices.InvoiceValue) InvoiceValue, SUM(invoices.TaxValue) TaxValue
				FROM  Invoice.vwRegisterDetail invoices
					JOIN Cash.vwCodeActive cash_codes ON invoices.CashCode = cash_codes.CashCode 
					JOIN Cash.vwCategoryActive categories ON cash_codes.CategoryCode = categories .CategoryCode
				WHERE StartOn = @StartOn
				GROUP BY invoices.CashCode, invoices.StartOn, categories.CashPolarityCode
			), invoice_summary AS
			(
				SELECT CashCode, StartOn,
					CASE CashPolarityCode 
						WHEN 0 THEN
							InvoiceValue * -1
						ELSE 
							InvoiceValue
					END AS InvoiceValue,
					CASE CashPolarityCode 
						WHEN 0 THEN
							TaxValue * -1
						ELSE 
							TaxValue
					END AS TaxValue						
				FROM invoice_entries
			)
			UPDATE Cash.tbPeriod
			SET InvoiceValue = invoice_summary.InvoiceValue, 
				InvoiceTax = invoice_summary.TaxValue
			FROM    Cash.tbPeriod 
				JOIN invoice_summary 
					ON Cash.tbPeriod.CashCode = invoice_summary.CashCode AND Cash.tbPeriod.StartOn = invoice_summary.StartOn;

			WITH asset_entries AS
			(
				SELECT payment.CashCode, 
					(SELECT TOP 1 StartOn FROM App.tbYearPeriod WHERE (StartOn <= payment.PaidOn) ORDER BY StartOn DESC) AS StartOn,
					(PaidInValue - PaidOutValue) AssetValue
				FROM Cash.tbPayment payment
					JOIN Subject.tbAccount account ON payment.AccountCode = account.AccountCode
				WHERE account.AccountTypeCode = 2 AND PaidOn >= @StartOn
			), asset_summary AS
			(
				SELECT CashCode, StartOn, SUM(AssetValue) AssetValue
				FROM asset_entries
				WHERE StartOn = @StartOn
				GROUP BY CashCode, StartOn				
			)
			UPDATE Cash.tbPeriod
			SET InvoiceValue = AssetValue
			FROM  Cash.tbPeriod 
				JOIN asset_summary 
					ON Cash.tbPeriod.CashCode = asset_summary.CashCode AND Cash.tbPeriod.StartOn = asset_summary.StartOn;		
	
			UPDATE App.tbYearPeriod
			SET CashStatusCode = 2
			WHERE StartOn = @StartOn			
		
			IF NOT EXISTS (SELECT     CashStatusCode
						FROM         App.tbYearPeriod
						WHERE     (YearNumber = @YearNumber) AND (CashStatusCode < 2)) 
				BEGIN
				UPDATE App.tbYear
				SET CashStatusCode = 2
				WHERE YearNumber = @YearNumber	
				END
			IF EXISTS(SELECT * FROM App.fnActivePeriod())
				BEGIN
				UPDATE App.tbYearPeriod
				SET CashStatusCode = 1
				FROM App.fnActivePeriod() fnSystemActivePeriod INNER JOIN
									App.tbYearPeriod ON fnSystemActivePeriod.YearNumber = App.tbYearPeriod.YearNumber AND fnSystemActivePeriod.MonthNumber = App.tbYearPeriod.MonthNumber
			
				END		
			IF EXISTS(SELECT * FROM App.fnActivePeriod())
				BEGIN
				UPDATE App.tbYear
				SET CashStatusCode = 1
				FROM App.fnActivePeriod() fnSystemActivePeriod INNER JOIN
									App.tbYear ON fnSystemActivePeriod.YearNumber = App.tbYear.YearNumber  
				END

			COMMIT TRAN

			END
					
  	END TRY
	BEGIN CATCH
		EXEC App.proc_ErrorLog;
	END CATCH
GO

PRINT N'Altering Procedure [App].[proc_DatasetSyntheticMIS_SoleTraderDrawings]...';


GO
ALTER PROCEDURE App.proc_DatasetSyntheticMIS_SoleTraderDrawings
(
	@IsCompany bit
)
AS
	SET NOCOUNT, XACT_ABORT ON;

	IF @IsCompany <> 0
		RETURN;

	IF OBJECT_ID('tempdb..#DatasetCodes') IS NULL
		THROW 51290, 'DatasetSyntheticMIS_SoleTraderDrawings: missing temp table #DatasetCodes. Run via App.proc_DatasetSyntheticMIS.', 1;

	DECLARE @UserId nvarchar(10) = (SELECT TOP (1) UserId FROM Usr.vwCredentials);
	DECLARE @BusinessRootCode nvarchar(50) = (SELECT TOP (1) SubjectCode FROM App.tbOptions);

	IF @BusinessRootCode IS NULL OR NOT EXISTS (SELECT 1 FROM Subject.tbSubject WHERE SubjectCode = @BusinessRootCode)
		THROW 51295, 'DatasetSyntheticMIS_SoleTraderDrawings: unable to resolve the business root subject.', 1;

	DECLARE @Year1 smallint = (SELECT MIN(YearNumber) FROM App.tbYear);

	IF @Year1 IS NULL
		THROW 51291, 'DatasetSyntheticMIS_SoleTraderDrawings: App.tbYear is empty.', 1;

	DECLARE @Year1FirstStartOn date =
	(
		SELECT MIN(CAST(yp.StartOn AS date))
		FROM App.tbYearPeriod yp
		WHERE yp.YearNumber = @Year1
	);

	IF @Year1FirstStartOn IS NULL
		THROW 51292, 'DatasetSyntheticMIS_SoleTraderDrawings: unable to resolve year 1 start period.', 1;

	DECLARE @SettlementAccountCode nvarchar(10) =
		(SELECT CodeValue FROM #DatasetCodes WHERE CodeType = N'LINK' AND CodeName = N'SettlementAccountCode');

	IF @SettlementAccountCode IS NULL
		SELECT @SettlementAccountCode = AccountCode FROM Cash.vwCurrentAccount;

	IF @SettlementAccountCode IS NULL
		THROW 51293, 'DatasetSyntheticMIS_SoleTraderDrawings: unable to resolve SettlementAccountCode.', 1;

	DECLARE @OwnerCapitalAccountCode nvarchar(10) = N'OWNCAP';

	IF NOT EXISTS (SELECT 1 FROM Subject.tbAccount WHERE AccountCode = @OwnerCapitalAccountCode)
		THROW 51294, 'DatasetSyntheticMIS_SoleTraderDrawings: unable to resolve owner capital AccountCode (OWNCAP).', 1;

	DECLARE @CashCode nvarchar(50) = N'CC-OWNCAP';

	DECLARE @Drawing1 decimal(18,5) = 750.00000;
	DECLARE @Drawing2 decimal(18,5) = 900.00000;

	DECLARE @PaidOn1 date = DATEADD(DAY, 40, @Year1FirstStartOn);
	DECLARE @PaidOn2 date = DATEADD(DAY, 75, @Year1FirstStartOn);

	-- Event 1
	IF NOT EXISTS
	(
		SELECT 1
		FROM Cash.tbPayment p
		WHERE p.SubjectCode = @BusinessRootCode
		  AND p.AccountCode = @SettlementAccountCode
		  AND p.CashCode = @CashCode
		  AND CAST(p.PaidOn AS date) = @PaidOn1
		  AND p.PaymentReference = N'Owner Drawings'
	)
	BEGIN
		DECLARE @PayCode1 nvarchar(20) = NULL;
		EXEC Cash.proc_NextPaymentCode @PaymentCode = @PayCode1 OUTPUT;

		INSERT INTO Cash.tbPayment
		(
			PaymentCode,
			UserId,
			PaymentStatusCode,
			SubjectCode,
			AccountCode,
			CashCode,
			TaxCode,
			PaidOn,
			PaidInValue,
			PaidOutValue,
			PaymentReference
		)
		VALUES
		(
			@PayCode1,
			@UserId,
			1,
			@BusinessRootCode,
			@SettlementAccountCode,
			@CashCode,
			N'N/A',
			@PaidOn1,
			0.00000,
			@Drawing1,
			N'Owner Drawings'
		);
	END

	IF NOT EXISTS
	(
		SELECT 1
		FROM Cash.tbPayment p
		WHERE p.SubjectCode = @BusinessRootCode
		  AND p.AccountCode = @OwnerCapitalAccountCode
		  AND p.CashCode = @CashCode
		  AND CAST(p.PaidOn AS date) = @PaidOn1
		  AND p.PaymentReference = N'Owner Drawings'
	)
	BEGIN
		DECLARE @PayCode2 nvarchar(20) = NULL;
		EXEC Cash.proc_NextPaymentCode @PaymentCode = @PayCode2 OUTPUT;

		INSERT INTO Cash.tbPayment
		(
			PaymentCode,
			UserId,
			PaymentStatusCode,
			SubjectCode,
			AccountCode,
			CashCode,
			TaxCode,
			PaidOn,
			PaidInValue,
			PaidOutValue,
			PaymentReference
		)
		VALUES
		(
			@PayCode2,
			@UserId,
			1,
			@BusinessRootCode,
			@OwnerCapitalAccountCode,
			@CashCode,
			N'N/A',
			@PaidOn1,
			@Drawing1,
			0.00000,
			N'Owner Drawings'
		);
	END

	-- Event 2
	IF NOT EXISTS
	(
		SELECT 1
		FROM Cash.tbPayment p
		WHERE p.SubjectCode = @BusinessRootCode
		  AND p.AccountCode = @SettlementAccountCode
		  AND p.CashCode = @CashCode
		  AND CAST(p.PaidOn AS date) = @PaidOn2
		  AND p.PaymentReference = N'Owner Drawings'
	)
	BEGIN
		DECLARE @PayCode3 nvarchar(20) = NULL;
		EXEC Cash.proc_NextPaymentCode @PaymentCode = @PayCode3 OUTPUT;

		INSERT INTO Cash.tbPayment
		(
			PaymentCode,
			UserId,
			PaymentStatusCode,
			SubjectCode,
			AccountCode,
			CashCode,
			TaxCode,
			PaidOn,
			PaidInValue,
			PaidOutValue,
			PaymentReference
		)
		VALUES
		(
			@PayCode3,
			@UserId,
			1,
			@BusinessRootCode,
			@SettlementAccountCode,
			@CashCode,
			N'N/A',
			@PaidOn2,
			0.00000,
			@Drawing2,
			N'Owner Drawings'
		);
	END

	IF NOT EXISTS
	(
		SELECT 1
		FROM Cash.tbPayment p
		WHERE p.SubjectCode = @BusinessRootCode
		  AND p.AccountCode = @OwnerCapitalAccountCode
		  AND p.CashCode = @CashCode
		  AND CAST(p.PaidOn AS date) = @PaidOn2
		  AND p.PaymentReference = N'Owner Drawings'
	)
	BEGIN
		DECLARE @PayCode4 nvarchar(20) = NULL;
		EXEC Cash.proc_NextPaymentCode @PaymentCode = @PayCode4 OUTPUT;

		INSERT INTO Cash.tbPayment
		(
			PaymentCode,
			UserId,
			PaymentStatusCode,
			SubjectCode,
			AccountCode,
			CashCode,
			TaxCode,
			PaidOn,
			PaidInValue,
			PaidOutValue,
			PaymentReference
		)
		VALUES
		(
			@PayCode4,
			@UserId,
			1,
			@BusinessRootCode,
			@OwnerCapitalAccountCode,
			@CashCode,
			N'N/A',
			@PaidOn2,
			@Drawing2,
			0.00000,
			N'Owner Drawings'
		);
	END

	EXEC Cash.proc_PaymentPost;
GO

PRINT N'Altering Procedure [App].[proc_DatasetSyntheticMIS_SoleTraderCapitalIntroduced]...';


GO
ALTER PROCEDURE App.proc_DatasetSyntheticMIS_SoleTraderCapitalIntroduced
(
	@IsCompany bit
)
AS
	SET NOCOUNT, XACT_ABORT ON;

	IF @IsCompany <> 0
		RETURN;

	IF OBJECT_ID('tempdb..#DatasetCodes') IS NULL
		THROW 51280, 'DatasetSyntheticMIS_SoleTraderCapitalIntroduced: missing temp table #DatasetCodes. Run via App.proc_DatasetSyntheticMIS.', 1;

	DECLARE @UserId nvarchar(10) = (SELECT TOP (1) UserId FROM Usr.vwCredentials);
	DECLARE @BusinessRootCode nvarchar(50) = (SELECT TOP (1) SubjectCode FROM App.tbOptions);

	IF @BusinessRootCode IS NULL OR NOT EXISTS (SELECT 1 FROM Subject.tbSubject WHERE SubjectCode = @BusinessRootCode)
		THROW 51285, 'DatasetSyntheticMIS_SoleTraderCapitalIntroduced: unable to resolve the business root subject.', 1;

	DECLARE @Year1 smallint = (SELECT MIN(YearNumber) FROM App.tbYear);

	IF @Year1 IS NULL
		THROW 51281, 'DatasetSyntheticMIS_SoleTraderCapitalIntroduced: App.tbYear is empty.', 1;

	DECLARE @Year1FirstStartOn date =
	(
		SELECT MIN(CAST(yp.StartOn AS date))
		FROM App.tbYearPeriod yp
		WHERE yp.YearNumber = @Year1
	);

	IF @Year1FirstStartOn IS NULL
		THROW 51282, 'DatasetSyntheticMIS_SoleTraderCapitalIntroduced: unable to resolve year 1 start period.', 1;

	DECLARE @SettlementAccountCode nvarchar(10) =
		(SELECT CodeValue FROM #DatasetCodes WHERE CodeType = N'LINK' AND CodeName = N'SettlementAccountCode');

	IF @SettlementAccountCode IS NULL
		SELECT @SettlementAccountCode = AccountCode FROM Cash.vwCurrentAccount;

	IF @SettlementAccountCode IS NULL
		THROW 51283, 'DatasetSyntheticMIS_SoleTraderCapitalIntroduced: unable to resolve SettlementAccountCode.', 1;

	DECLARE @OwnerCapitalAccountCode nvarchar(10) = N'OWNCAP';

	IF NOT EXISTS (SELECT 1 FROM Subject.tbAccount WHERE AccountCode = @OwnerCapitalAccountCode)
		THROW 51284, 'DatasetSyntheticMIS_SoleTraderCapitalIntroduced: unable to resolve owner capital AccountCode (OWNCAP).', 1;

	DECLARE @CashCode nvarchar(50) = N'CC-OWNCAP';

	DECLARE @CapitalIntroduced decimal(18,5) = 5000.00000;
	DECLARE @PaidOn date = DATEADD(DAY, 10, @Year1FirstStartOn);

	-- Leg 1: Bank-side (cash enters the bank)
	IF NOT EXISTS
	(
		SELECT 1
		FROM Cash.tbPayment p
		WHERE p.SubjectCode = @BusinessRootCode
		  AND p.AccountCode = @SettlementAccountCode
		  AND p.CashCode = @CashCode
		  AND CAST(p.PaidOn AS date) = @PaidOn
		  AND p.PaymentReference = N'Owner Capital'
	)
	BEGIN
		DECLARE @PayCode1 nvarchar(20) = NULL;
		EXEC Cash.proc_NextPaymentCode @PaymentCode = @PayCode1 OUTPUT;

		INSERT INTO Cash.tbPayment
		(
			PaymentCode,
			UserId,
			PaymentStatusCode,
			SubjectCode,
			AccountCode,
			CashCode,
			TaxCode,
			PaidOn,
			PaidInValue,
			PaidOutValue,
			PaymentReference
		)
		VALUES
		(
			@PayCode1,
			@UserId,
			0,
			@BusinessRootCode,
			@SettlementAccountCode,
			@CashCode,
			N'N/A',
			@PaidOn,
			@CapitalIntroduced,
			0.00000,
			N'Owner Capital'
		);

		EXEC Cash.proc_PaymentPost;
	END

	-- Leg 2: Owner capital account
	IF NOT EXISTS
	(
		SELECT 1
		FROM Cash.tbPayment p
		WHERE p.SubjectCode = @BusinessRootCode
		  AND p.AccountCode = @OwnerCapitalAccountCode
		  AND p.CashCode = @CashCode
		  AND CAST(p.PaidOn AS date) = @PaidOn
		  AND p.PaymentReference = N'Owner Capital'
	)
	BEGIN
		DECLARE @PayCode2 nvarchar(20) = NULL;
		EXEC Cash.proc_NextPaymentCode @PaymentCode = @PayCode2 OUTPUT;

		INSERT INTO Cash.tbPayment
		(
			PaymentCode,
			UserId,
			PaymentStatusCode,
			SubjectCode,
			AccountCode,
			CashCode,
			TaxCode,
			PaidOn,
			PaidInValue,
			PaidOutValue,
			PaymentReference
		)
		VALUES
		(
			@PayCode2,
			@UserId,
			1,
			@BusinessRootCode,
			@OwnerCapitalAccountCode,
			@CashCode,
			N'N/A',
			@PaidOn,
			0.00000,
			@CapitalIntroduced,
			N'Owner Capital'
		);
	END
GO

PRINT N'Altering Procedure [App].[proc_DatasetSyntheticMIS_CompanyLoanPayback]...';


GO
ALTER PROCEDURE App.proc_DatasetSyntheticMIS_CompanyLoanPayback
(
	@IsCompany bit
)
AS
	SET NOCOUNT, XACT_ABORT ON;

	IF @IsCompany = 0
		RETURN;

	IF OBJECT_ID('tempdb..#DatasetCodes') IS NULL
		THROW 51296, 'DatasetSyntheticMIS_CompanyLoanPayback: missing temp table #DatasetCodes. Run via App.proc_DatasetSyntheticMIS.', 1;

	DECLARE @UserId nvarchar(10) = (SELECT TOP (1) UserId FROM Usr.vwCredentials);
	DECLARE @BusinessRootCode nvarchar(50) = (SELECT TOP (1) SubjectCode FROM App.tbOptions);

	IF @BusinessRootCode IS NULL OR NOT EXISTS (SELECT 1 FROM Subject.tbSubject WHERE SubjectCode = @BusinessRootCode)
		THROW 51301, 'DatasetSyntheticMIS_CompanyLoanPayback: unable to resolve the business root subject.', 1;

	DECLARE @Year1 smallint = (SELECT MIN(YearNumber) FROM App.tbYear);

	IF @Year1 IS NULL
		THROW 51297, 'DatasetSyntheticMIS_CompanyLoanPayback: App.tbYear is empty.', 1;

	DECLARE @Year1FirstStartOn date =
	(
		SELECT MIN(CAST(yp.StartOn AS date))
		FROM App.tbYearPeriod yp
		WHERE yp.YearNumber = @Year1
	);

	IF @Year1FirstStartOn IS NULL
		THROW 51298, 'DatasetSyntheticMIS_CompanyLoanPayback: unable to resolve year 1 start period.', 1;

	DECLARE @SettlementAccountCode nvarchar(10) =
		(SELECT CodeValue FROM #DatasetCodes WHERE CodeType = N'LINK' AND CodeName = N'SettlementAccountCode');

	IF @SettlementAccountCode IS NULL
		SELECT @SettlementAccountCode = AccountCode FROM Cash.vwCurrentAccount;

	IF @SettlementAccountCode IS NULL
		THROW 51299, 'DatasetSyntheticMIS_CompanyLoanPayback: unable to resolve SettlementAccountCode.', 1;

	-- Director loan liability account (created by base template)
	DECLARE @LoanLiabilityAccountCode nvarchar(10) = N'LONLIA';

	IF NOT EXISTS (SELECT 1 FROM Subject.tbAccount WHERE AccountCode = @LoanLiabilityAccountCode AND AccountClosed = 0)
		THROW 51300, 'DatasetSyntheticMIS_CompanyLoanPayback: unable to resolve loan liability AccountCode (LONLIA).', 1;

	-- Cash code used on the loan liability account
	DECLARE @LoanCashCode nvarchar(50) =
	(
		SELECT CashCode
		FROM Subject.tbAccount
		WHERE AccountCode = @LoanLiabilityAccountCode
	);

	IF @LoanCashCode IS NULL
		SET @LoanCashCode = N'CC-LOAN';

	---------------------------------------------------------------------
	-- Add payback events (polarity-driven on CC-LOAN)
	-- These are posted against the loan liability account (AssetTypeCode=2).
	-- Positive vs negative is expressed by PaidInValue/PaidOutValue.
	---------------------------------------------------------------------
	DECLARE @Payback1 decimal(18,5) = 1200.00000;
	DECLARE @Payback2 decimal(18,5) = 800.00000;

	DECLARE @PaidOn1 date = DATEADD(DAY, 55, @Year1FirstStartOn);
	DECLARE @PaidOn2 date = DATEADD(DAY, 95, @Year1FirstStartOn);

	-- Event 1: bank payment out (cash leaves settlement account)
	IF NOT EXISTS
	(
		SELECT 1
		FROM Cash.tbPayment p
		WHERE p.SubjectCode = @BusinessRootCode
		  AND p.AccountCode = @SettlementAccountCode
		  AND p.CashCode = @LoanCashCode
		  AND CAST(p.PaidOn AS date) = @PaidOn1
		  AND p.PaymentReference = N'Director Loan Payback'
	)
	BEGIN
		DECLARE @PayCode1 nvarchar(20) = NULL;
		EXEC Cash.proc_NextPaymentCode @PaymentCode = @PayCode1 OUTPUT;

		INSERT INTO Cash.tbPayment
		(
			PaymentCode,
			UserId,
			PaymentStatusCode,
			SubjectCode,
			AccountCode,
			CashCode,
			TaxCode,
			PaidOn,
			PaidInValue,
			PaidOutValue,
			PaymentReference
		)
		VALUES
		(
			@PayCode1,
			@UserId,
			1,
			@BusinessRootCode,
			@SettlementAccountCode,
			@LoanCashCode,
			N'N/A',
			@PaidOn1,
			0.00000,
			@Payback1,
			N'Director Loan Payback'
		);
	END

	-- Event 1: loan liability leg (reduce liability)
	IF NOT EXISTS
	(
		SELECT 1
		FROM Cash.tbPayment p
		WHERE p.SubjectCode = @BusinessRootCode
		  AND p.AccountCode = @LoanLiabilityAccountCode
		  AND p.CashCode = @LoanCashCode
		  AND CAST(p.PaidOn AS date) = @PaidOn1
		  AND p.PaymentReference = N'Director Loan Payback'
	)
	BEGIN
		DECLARE @PayCode2 nvarchar(20) = NULL;
		EXEC Cash.proc_NextPaymentCode @PaymentCode = @PayCode2 OUTPUT;

		INSERT INTO Cash.tbPayment
		(
			PaymentCode,
			UserId,
			PaymentStatusCode,
			SubjectCode,
			AccountCode,
			CashCode,
			TaxCode,
			PaidOn,
			PaidInValue,
			PaidOutValue,
			PaymentReference
		)
		VALUES
		(
			@PayCode2,
			@UserId,
			1,
			@BusinessRootCode,
			@LoanLiabilityAccountCode,
			@LoanCashCode,
			N'N/A',
			@PaidOn1,
			@Payback1,
			0.00000,
			N'Director Loan Payback'
		);
	END

	-- Event 2: bank payment out
	IF NOT EXISTS
	(
		SELECT 1
		FROM Cash.tbPayment p
		WHERE p.SubjectCode = @BusinessRootCode
		  AND p.AccountCode = @SettlementAccountCode
		  AND p.CashCode = @LoanCashCode
		  AND CAST(p.PaidOn AS date) = @PaidOn2
		  AND p.PaymentReference = N'Director Loan Payback'
	)
	BEGIN
		DECLARE @PayCode3 nvarchar(20) = NULL;
		EXEC Cash.proc_NextPaymentCode @PaymentCode = @PayCode3 OUTPUT;

		INSERT INTO Cash.tbPayment
		(
			PaymentCode,
			UserId,
			PaymentStatusCode,
			SubjectCode,
			AccountCode,
			CashCode,
			TaxCode,
			PaidOn,
			PaidInValue,
			PaidOutValue,
			PaymentReference
		)
		VALUES
		(
			@PayCode3,
			@UserId,
			1,
			@BusinessRootCode,
			@SettlementAccountCode,
			@LoanCashCode,
			N'N/A',
			@PaidOn2,
			0.00000,
			@Payback2,
			N'Director Loan Payback'
		);
	END

	-- Event 2: loan liability leg
	IF NOT EXISTS
	(
		SELECT 1
		FROM Cash.tbPayment p
		WHERE p.SubjectCode = @BusinessRootCode
		  AND p.AccountCode = @LoanLiabilityAccountCode
		  AND p.CashCode = @LoanCashCode
		  AND CAST(p.PaidOn AS date) = @PaidOn2
		  AND p.PaymentReference = N'Director Loan Payback'
	)
	BEGIN
		DECLARE @PayCode4 nvarchar(20) = NULL;
		EXEC Cash.proc_NextPaymentCode @PaymentCode = @PayCode4 OUTPUT;

		INSERT INTO Cash.tbPayment
		(
			PaymentCode,
			UserId,
			PaymentStatusCode,
			SubjectCode,
			AccountCode,
			CashCode,
			TaxCode,
			PaidOn,
			PaidInValue,
			PaidOutValue,
			PaymentReference
		)
		VALUES
		(
			@PayCode4,
			@UserId,
			1,
			@BusinessRootCode,
			@LoanLiabilityAccountCode,
			@LoanCashCode,
			N'N/A',
			@PaidOn2,
			@Payback2,
			0.00000,
			N'Director Loan Payback'
		);
	END

	EXEC Cash.proc_PaymentPost;
GO

PRINT N'Altering Trigger [Project].[Project_tbProject_TriggerInsert]...';


GO

ALTER TRIGGER Project.Project_tbProject_TriggerInsert
ON Project.tbProject
FOR INSERT
AS
    SET NOCOUNT ON;
    BEGIN TRY

		IF EXISTS
		(
			SELECT 1
			FROM inserted i
			JOIN Cash.vwCodeActive cash_code ON cash_code.CashCode = i.CashCode
			WHERE cash_code.IsEnabled = 0
		)
			THROW 51013, 'A Project cannot be assigned a disabled CashCode.', 1;

        EXEC sys.sp_set_session_context @key = N'ProjectSkipNamespaceValidation', @value = 1;

        ;WITH namespace_candidates AS
        (
            SELECT
                Project.ProjectCode,
                Project.SubjectCode,
                Project.ParentSubjectCode,
                ParentCount = (
                    SELECT COUNT(*)
                    FROM Subject.tbNamespace tbNamespace
                    WHERE tbNamespace.ChildSubjectCode = Project.SubjectCode
                ),
                SingleParentSubjectCode = (
                    SELECT MIN(tbNamespace.ParentSubjectCode)
                    FROM Subject.tbNamespace tbNamespace
                    WHERE tbNamespace.ChildSubjectCode = Project.SubjectCode
                )
            FROM Project.tbProject Project
                JOIN inserted i ON Project.ProjectCode = i.ProjectCode
        )
        UPDATE Project
        SET ParentSubjectCode = namespace_candidates.SingleParentSubjectCode
        FROM Project.tbProject Project
            JOIN namespace_candidates ON Project.ProjectCode = namespace_candidates.ProjectCode
        WHERE namespace_candidates.ParentSubjectCode IS NULL
          AND namespace_candidates.ParentCount = 1;

        EXEC sys.sp_set_session_context @key = N'ProjectSkipNamespaceValidation', @value = NULL;

        IF EXISTS
        (
            SELECT 1
            FROM Project.tbProject Project
                JOIN inserted i ON Project.ProjectCode = i.ProjectCode
            WHERE Project.ParentSubjectCode IS NULL
              AND (
                    SELECT COUNT(*)
                    FROM Subject.tbNamespace tbNamespace
                    WHERE tbNamespace.ChildSubjectCode = Project.SubjectCode
                  ) > 1
        )
        BEGIN
            RAISERROR('ParentSubjectCode must be selected when Subject has multiple namespace parents.', 16, 1);
            ROLLBACK TRANSACTION;
            RETURN;
        END

        IF EXISTS
        (
            SELECT 1
            FROM Project.tbProject Project
                JOIN inserted i ON Project.ProjectCode = i.ProjectCode
            WHERE Project.ParentSubjectCode IS NOT NULL
              AND NOT EXISTS
              (
                  SELECT 1
                  FROM Subject.tbNamespace tbNamespace
                  WHERE tbNamespace.ChildSubjectCode = Project.SubjectCode
                    AND tbNamespace.ParentSubjectCode = Project.ParentSubjectCode
              )
        )
        BEGIN
            RAISERROR('ParentSubjectCode must reference a valid namespace parent for the Subject.', 16, 1);
            ROLLBACK TRANSACTION;
            RETURN;
        END

        UPDATE Project
        SET Project.ActionOn = CAST(Project.ActionOn AS DATE)
        FROM Project.tbProject Project
            JOIN inserted i ON Project.ProjectCode = i.ProjectCode
        WHERE DATEDIFF(SECOND, CAST(i.ActionOn AS DATE), i.ActionOn) <> 0;

        UPDATE Project
        SET Project.TotalCharge = i.UnitCharge * i.Quantity
        FROM Project.tbProject Project
            JOIN inserted i ON Project.ProjectCode = i.ProjectCode
        WHERE i.TotalCharge = 0;

        UPDATE Project
        SET Project.UnitCharge = i.TotalCharge / i.Quantity
        FROM Project.tbProject Project
            JOIN inserted i ON Project.ProjectCode = i.ProjectCode
        WHERE i.UnitCharge = 0
          AND i.Quantity > 0;

        UPDATE Project
        SET PaymentOn = App.fnAdjustToCalendar(
                CASE
                    WHEN Subject.PayDaysFromMonthEnd <> 0 THEN
                        DATEADD(d, -1, DATEADD(m, 1, CONCAT(FORMAT(DATEADD(d, Subject.PaymentDays + Subject.ExpectedDays, Project.ActionOn), 'yyyyMM'), '01')))
                    ELSE
                        DATEADD(d, Subject.PaymentDays + Subject.ExpectedDays, Project.ActionOn)
                END, 0)
        FROM Project.tbProject Project
            JOIN Subject.tbSubject Subject ON Project.SubjectCode = Subject.SubjectCode
            JOIN inserted i ON Project.ProjectCode = i.ProjectCode
        WHERE NOT Project.CashCode IS NULL;

        DECLARE @Xml NVARCHAR(MAX);

        SELECT @Xml =
        (
            SELECT
                i.SubjectCode,
                i.ContactName
            FROM inserted AS i
            WHERE NULLIF(LTRIM(RTRIM(i.ContactName)), N'') IS NOT NULL
              AND NOT EXISTS
              (
                  SELECT 1
                  FROM Subject.tbNamespace AS n
                      INNER JOIN Subject.tbSubject AS s ON s.SubjectCode = n.ChildSubjectCode
                  WHERE n.ParentSubjectCode = i.SubjectCode
                    AND s.SubjectName = i.ContactName
              )
            FOR XML PATH('Contact'), ROOT('Contacts'), TYPE
        ).value('.', 'nvarchar(max)');

        IF NULLIF(@Xml, N'') IS NOT NULL
            EXEC Subject.proc_AddContacts @Xml = @Xml;

        INSERT INTO Project.tbChangeLog
                                    (ProjectCode, TransmitStatusCode, SubjectCode, ObjectCode, ProjectStatusCode, ActionOn, Quantity, CashCode, TaxCode, UnitCharge)
        SELECT inserted.ProjectCode,
               Subject.tbSubject.TransmitStatusCode,
               inserted.SubjectCode,
               inserted.ObjectCode,
               inserted.ProjectStatusCode,
               inserted.ActionOn,
               inserted.Quantity,
               inserted.CashCode,
               inserted.TaxCode,
               inserted.UnitCharge
        FROM inserted
            JOIN Subject.tbSubject ON inserted.SubjectCode = Subject.tbSubject.SubjectCode
            JOIN Cash.vwCodeActive ON inserted.CashCode = Cash.vwCodeActive.CashCode;

    END TRY
    BEGIN CATCH
        EXEC sys.sp_set_session_context @key = N'ProjectSkipNamespaceValidation', @value = NULL;
        EXEC App.proc_ErrorLog;
    END CATCH
GO

PRINT N'Altering Trigger [Project].[Project_tbProject_TriggerUpdate]...';


GO

ALTER TRIGGER Project.Project_tbProject_TriggerUpdate
ON Project.tbProject
FOR UPDATE
AS
    SET NOCOUNT ON;

    BEGIN TRY

		IF UPDATE(CashCode) AND EXISTS
		(
			SELECT 1
			FROM inserted i
			JOIN Cash.vwCodeActive cash_code ON cash_code.CashCode = i.CashCode
			WHERE cash_code.IsEnabled = 0
		)
			THROW 51013, 'A Project cannot be assigned a disabled CashCode.', 1;

        IF UPDATE(SubjectCode)
        BEGIN
            UPDATE Project
            SET ParentSubjectCode = NULL
            FROM Project.tbProject Project
                JOIN inserted i ON Project.ProjectCode = i.ProjectCode
                JOIN deleted d ON i.ProjectCode = d.ProjectCode
            WHERE ISNULL(i.SubjectCode, N'') <> ISNULL(d.SubjectCode, N'');
        END

        IF UPDATE(SubjectCode) OR UPDATE(ParentSubjectCode)
        BEGIN
            ;WITH namespace_candidates AS
            (
                SELECT
                    Project.ProjectCode,
                    Project.SubjectCode,
                    Project.ParentSubjectCode,
                    ParentCount = (
                        SELECT COUNT(*)
                        FROM Subject.tbNamespace tbNamespace
                        WHERE tbNamespace.ChildSubjectCode = Project.SubjectCode
                    ),
                    SingleParentSubjectCode = (
                        SELECT MIN(tbNamespace.ParentSubjectCode)
                        FROM Subject.tbNamespace tbNamespace
                        WHERE tbNamespace.ChildSubjectCode = Project.SubjectCode
                    )
                FROM Project.tbProject Project
                    JOIN inserted i ON Project.ProjectCode = i.ProjectCode
            )
            UPDATE Project
            SET ParentSubjectCode = namespace_candidates.SingleParentSubjectCode
            FROM Project.tbProject Project
                JOIN namespace_candidates ON Project.ProjectCode = namespace_candidates.ProjectCode
            WHERE namespace_candidates.ParentSubjectCode IS NULL
              AND namespace_candidates.ParentCount = 1;

            IF EXISTS
            (
                SELECT 1
                FROM Project.tbProject Project
                    JOIN inserted i ON Project.ProjectCode = i.ProjectCode
                WHERE Project.ParentSubjectCode IS NULL
                  AND (
                        SELECT COUNT(*)
                        FROM Subject.tbNamespace tbNamespace
                        WHERE tbNamespace.ChildSubjectCode = Project.SubjectCode
                      ) > 1
            )
            BEGIN
                RAISERROR('ParentSubjectCode must be selected when Subject has multiple namespace parents.', 16, 1);
                ROLLBACK TRANSACTION;
                RETURN;
            END

            IF EXISTS
            (
                SELECT 1
                FROM Project.tbProject Project
                    JOIN inserted i ON Project.ProjectCode = i.ProjectCode
                WHERE Project.ParentSubjectCode IS NOT NULL
                  AND NOT EXISTS
                  (
                      SELECT 1
                      FROM Subject.tbNamespace tbNamespace
                      WHERE tbNamespace.ChildSubjectCode = Project.SubjectCode
                        AND tbNamespace.ParentSubjectCode = Project.ParentSubjectCode
                  )
            )
            BEGIN
                RAISERROR('ParentSubjectCode must reference a valid namespace parent for the Subject.', 16, 1);
                ROLLBACK TRANSACTION;
                RETURN;
            END
        END

        UPDATE Project
        SET Project.ActionOn = CAST(Project.ActionOn AS DATE)
        FROM Project.tbProject Project
            JOIN inserted i ON Project.ProjectCode = i.ProjectCode
        WHERE DATEDIFF(SECOND, CAST(i.ActionOn AS DATE), i.ActionOn) <> 0;

        IF UPDATE(ProjectStatusCode)
        BEGIN
            UPDATE ops
            SET OpStatusCode = 2
            FROM inserted
                JOIN Project.tbOp ops ON inserted.ProjectCode = ops.ProjectCode
            WHERE ProjectStatusCode > 1
              AND OpStatusCode < 2;

            WITH first_ops AS
            (
                SELECT ops.ProjectCode, MIN(ops.OperationNumber) AS OperationNumber
                FROM inserted i
                    JOIN Project.tbOp ops ON i.ProjectCode = ops.ProjectCode
                WHERE i.ProjectStatusCode = 1
                GROUP BY ops.ProjectCode
            ),
            next_ops AS
            (
                SELECT ops.ProjectCode,
                       ops.OperationNumber,
                       ops.SyncTypeCode,
                       LEAD(ops.OperationNumber) OVER (PARTITION BY ops.ProjectCode ORDER BY ops.OperationNumber) AS NextOpNo
                FROM inserted i
                    JOIN Project.tbOp ops ON i.ProjectCode = ops.ProjectCode
            ),
            async_ops AS
            (
                SELECT first_ops.ProjectCode, first_ops.OperationNumber, next_ops.NextOpNo
                FROM first_ops
                    JOIN next_ops ON first_ops.ProjectCode = next_ops.ProjectCode
                                 AND first_ops.OperationNumber = next_ops.OperationNumber

                UNION ALL

                SELECT next_ops.ProjectCode, next_ops.OperationNumber, next_ops.NextOpNo
                FROM next_ops
                    JOIN async_ops ON next_ops.ProjectCode = async_ops.ProjectCode
                                  AND next_ops.OperationNumber = async_ops.NextOpNo
                WHERE next_ops.SyncTypeCode = 1
            )
            UPDATE ops
            SET OpStatusCode = 1
            FROM async_ops
                JOIN Project.tbOp ops ON async_ops.ProjectCode = ops.ProjectCode
                                     AND async_ops.OperationNumber = ops.OperationNumber;

            WITH cascade_status AS
            (
                SELECT inserted.ProjectCode, inserted.ProjectStatusCode
                FROM inserted
                    JOIN deleted ON inserted.ProjectCode = deleted.ProjectCode
                WHERE inserted.CashCode IS NOT NULL
                  AND inserted.ProjectStatusCode <> deleted.ProjectStatusCode
            ),
            Project_flow AS
            (
                SELECT cascade_status.ProjectStatusCode ParentStatusCode,
                       child.ParentProjectCode,
                       child.ChildProjectCode,
                       child_Project.ProjectStatusCode
                FROM Project.tbFlow child
                    JOIN cascade_status ON child.ParentProjectCode = cascade_status.ProjectCode
                    JOIN Project.tbProject child_Project ON child.ChildProjectCode = child_Project.ProjectCode

                UNION ALL

                SELECT parent.ParentStatusCode,
                       child.ParentProjectCode,
                       child.ChildProjectCode,
                       child_Project.ProjectStatusCode
                FROM Project.tbFlow child
                    JOIN Project_flow parent ON child.ParentProjectCode = parent.ChildProjectCode
                    JOIN Project.tbProject child_Project ON child.ChildProjectCode = child_Project.ProjectCode
            )
            UPDATE Project
            SET ProjectStatusCode = CASE Project_flow.ParentStatusCode WHEN 3 THEN 2 ELSE Project_flow.ParentStatusCode END
            FROM Project.tbProject Project
                JOIN Project_flow ON Project_flow.ChildProjectCode = Project.ProjectCode
            WHERE Project.ProjectStatusCode < 2
              AND Project.ProjectStatusCode <> CASE Project_flow.ParentStatusCode WHEN 3 THEN 2 ELSE Project_flow.ParentStatusCode END;

            WITH cascade_status AS
            (
                SELECT inserted.ProjectCode, inserted.ProjectStatusCode
                FROM inserted
                    JOIN deleted ON inserted.ProjectCode = deleted.ProjectCode
                WHERE inserted.CashCode IS NOT NULL
                  AND inserted.ProjectStatusCode > 1
                  AND inserted.ProjectStatusCode <> deleted.ProjectStatusCode
            ),
            Project_flow AS
            (
                SELECT cascade_status.ProjectStatusCode ParentStatusCode,
                       child.ParentProjectCode,
                       child.ChildProjectCode,
                       child_Project.ProjectStatusCode
                FROM Project.tbFlow child
                    JOIN cascade_status ON child.ParentProjectCode = cascade_status.ProjectCode
                    JOIN Project.tbProject child_Project ON child.ChildProjectCode = child_Project.ProjectCode
                WHERE CashCode IS NULL

                UNION ALL

                SELECT parent.ParentStatusCode,
                       child.ParentProjectCode,
                       child.ChildProjectCode,
                       child_Project.ProjectStatusCode
                FROM Project.tbFlow child
                    JOIN Project_flow parent ON child.ParentProjectCode = parent.ChildProjectCode
                    JOIN Project.tbProject child_Project ON child.ChildProjectCode = child_Project.ProjectCode
                WHERE CashCode IS NULL
            )
            UPDATE ops
            SET OpStatusCode = 2
            FROM Project.tbOp ops
                JOIN Project_flow ON Project_flow.ChildProjectCode = ops.ProjectCode
            WHERE ops.OpStatusCode < 2;

            DELETE cost_set
            FROM inserted
                JOIN Project.tbCostSet cost_set ON inserted.ProjectCode = cost_set.ProjectCode
            WHERE inserted.ProjectStatusCode > 0;
        END

        IF UPDATE(Quantity)
        BEGIN
            UPDATE flow
            SET UsedOnQuantity = inserted.Quantity / parent_Project.Quantity
            FROM Project.tbFlow AS flow
                JOIN inserted ON flow.ChildProjectCode = inserted.ProjectCode
                JOIN Project.tbProject AS parent_Project ON flow.ParentProjectCode = parent_Project.ProjectCode
                JOIN Cash.vwCodeActive ON parent_Project.CashCode = Cash.vwCodeActive.CashCode
            WHERE (flow.UsedOnQuantity <> 0)
              AND (inserted.Quantity <> 0)
              AND (inserted.Quantity / parent_Project.Quantity <> flow.UsedOnQuantity);
        END

        IF UPDATE(Quantity) OR UPDATE(UnitCharge)
        BEGIN
            UPDATE Project
            SET Project.TotalCharge = i.Quantity * i.UnitCharge
            FROM Project.tbProject Project
                JOIN inserted i ON Project.ProjectCode = i.ProjectCode;
        END

        IF UPDATE(TotalCharge)
        BEGIN
            UPDATE Project
            SET Project.UnitCharge = CASE i.TotalCharge + i.Quantity WHEN 0 THEN 0 ELSE i.TotalCharge / i.Quantity END
            FROM Project.tbProject Project
                JOIN inserted i ON Project.ProjectCode = i.ProjectCode;
        END

        IF UPDATE(ActionOn)
        BEGIN
            WITH parent_Project AS
            (
                SELECT ParentProjectCode
                FROM Project.tbFlow flow
                    JOIN Project.tbProject Project ON flow.ParentProjectCode = Project.ProjectCode
                    JOIN Cash.vwCodeActive cash ON Project.CashCode = cash.CashCode
                    JOIN inserted ON flow.ChildProjectCode = inserted.ProjectCode
                WHERE (SELECT SUM(UsedOnQuantity) FROM inserted JOIN Project.tbFlow ON inserted.ProjectCode = Project.tbFlow.ChildProjectCode) = 0
            ),
            Project_flow AS
            (
                SELECT flow.ParentProjectCode,
                       flow.StepNumber,
                       Project.ActionOn,
                       LAG(Project.ActionOn, 1, Project.ActionOn) OVER (PARTITION BY flow.ParentProjectCode ORDER BY StepNumber) AS PrevActionOn
                FROM Project.tbFlow flow
                    JOIN Project.tbProject Project ON flow.ChildProjectCode = Project.ProjectCode
                    JOIN parent_Project ON flow.ParentProjectCode = parent_Project.ParentProjectCode
            ),
            step_disordered AS
            (
                SELECT ParentProjectCode
                FROM Project_flow
                WHERE ActionOn < PrevActionOn
                GROUP BY ParentProjectCode
            ),
            step_ordered AS
            (
                SELECT flow.ParentProjectCode,
                       flow.ChildProjectCode,
                       ROW_NUMBER() OVER (PARTITION BY flow.ParentProjectCode ORDER BY Project.ActionOn, flow.StepNumber) * 10 AS StepNumber
                FROM step_disordered
                    JOIN Project.tbFlow flow ON step_disordered.ParentProjectCode = flow.ParentProjectCode
                    JOIN Project.tbProject Project ON flow.ChildProjectCode = Project.ProjectCode
            )
            UPDATE flow
            SET StepNumber = step_ordered.StepNumber
            FROM Project.tbFlow flow
                JOIN step_ordered ON flow.ParentProjectCode = step_ordered.ParentProjectCode
                                 AND flow.ChildProjectCode = step_ordered.ChildProjectCode;

            IF EXISTS(SELECT * FROM App.tbOptions WHERE IsAutoOffsetDays <> 0)
            BEGIN
                UPDATE flow
                SET OffsetDays = App.fnOffsetDays(inserted.ActionOn, parent_Project.ActionOn)
                                 - ISNULL((SELECT SUM(OffsetDays) FROM Project.tbFlow sub_flow WHERE sub_flow.ParentProjectCode = flow.ParentProjectCode AND sub_flow.StepNumber > flow.StepNumber), 0)
                FROM Project.tbFlow AS flow
                    JOIN inserted ON flow.ChildProjectCode = inserted.ProjectCode
                    JOIN Project.tbProject AS parent_Project ON flow.ParentProjectCode = parent_Project.ProjectCode
                    JOIN Cash.vwCodeActive ON parent_Project.CashCode = Cash.vwCodeActive.CashCode
                WHERE (SELECT SUM(UsedOnQuantity) FROM inserted JOIN Project.tbFlow ON inserted.ProjectCode = Project.tbFlow.ChildProjectCode) = 0;
            END

            UPDATE Project
            SET PaymentOn = App.fnAdjustToCalendar(
                    CASE
                        WHEN Subject.PayDaysFromMonthEnd <> 0 THEN
                            DATEADD(d, -1, DATEADD(m, 1, CONCAT(FORMAT(DATEADD(d, Subject.PaymentDays + Subject.ExpectedDays, i.ActionOn), 'yyyyMM'), '01')))
                        ELSE
                            DATEADD(d, Subject.PaymentDays + Subject.ExpectedDays, i.ActionOn)
                    END, 0)
            FROM Project.tbProject Project
                JOIN inserted i ON Project.ProjectCode = i.ProjectCode
                JOIN Subject.tbSubject Subject ON i.SubjectCode = Subject.SubjectCode
            WHERE NOT Project.CashCode IS NULL;
        END

        IF UPDATE(ProjectTitle)
        BEGIN
            WITH cascade_title_change AS
            (
                SELECT inserted.ProjectCode,
                       inserted.ProjectTitle AS NewTitle,
                       deleted.ProjectTitle AS PreviousTitle
                FROM inserted
                    JOIN deleted ON inserted.ProjectCode = deleted.ProjectCode
            ),
            Project_flow AS
            (
                SELECT cascade_title_change.NewTitle,
                       cascade_title_change.PreviousTitle,
                       child.ParentProjectCode,
                       child.ChildProjectCode,
                       child_Project.ProjectTitle
                FROM Project.tbFlow child
                    JOIN cascade_title_change ON child.ParentProjectCode = cascade_title_change.ProjectCode
                    JOIN Project.tbProject child_Project ON child.ChildProjectCode = child_Project.ProjectCode

                UNION ALL

                SELECT parent.NewTitle,
                       parent.PreviousTitle,
                       child.ParentProjectCode,
                       child.ChildProjectCode,
                       child_Project.ProjectTitle
                FROM Project.tbFlow child
                    JOIN Project_flow parent ON child.ParentProjectCode = parent.ChildProjectCode
                    JOIN Project.tbProject child_Project ON child.ChildProjectCode = child_Project.ProjectCode
            )
            UPDATE Project
            SET ProjectTitle = NewTitle
            FROM Project.tbProject Project
                JOIN Project_flow ON Project.ProjectCode = Project_flow.ChildProjectCode
            WHERE Project_flow.PreviousTitle = Project_flow.ProjectTitle;
        END

        IF UPDATE(Spooled)
        BEGIN
            INSERT INTO App.tbDocSpool (DocTypeCode, DocumentNumber)
            SELECT CASE
                       WHEN CashPolarityCode = 0 THEN CASE WHEN ProjectStatusCode = 0 THEN 2 ELSE 3 END
                       WHEN CashPolarityCode = 1 THEN CASE WHEN ProjectStatusCode = 0 THEN 0 ELSE 1 END
                   END AS DocTypeCode,
                   Project.ProjectCode
            FROM inserted Project
                INNER JOIN Cash.vwCodeActive ON Project.CashCode = Cash.vwCodeActive.CashCode
                INNER JOIN Cash.vwCategoryActive ON Cash.vwCodeActive.CategoryCode = Cash.vwCategoryActive.CategoryCode
            WHERE (Project.Spooled <> 0);

            DELETE App.tbDocSpool
            FROM inserted i
                INNER JOIN App.tbDocSpool ON i.ProjectCode = App.tbDocSpool.DocumentNumber
            WHERE (i.Spooled = 0) AND (App.tbDocSpool.DocTypeCode <= 3);
        END

        IF UPDATE(ContactName)
        BEGIN
            DECLARE @Xml NVARCHAR(MAX);

            SELECT @Xml =
            (
                SELECT
                    i.SubjectCode,
                    i.ContactName
                FROM inserted AS i
                WHERE NULLIF(LTRIM(RTRIM(i.ContactName)), N'') IS NOT NULL
                FOR XML PATH('Contact'), ROOT('Contacts'), TYPE
            ).value('.', 'nvarchar(max)');

            IF NULLIF(@Xml, N'') IS NOT NULL
                EXEC Subject.proc_AddContacts @Xml = @Xml;
        END

        UPDATE Project.tbProject
        SET UpdatedBy = Usr.fnUserName(), UpdatedOn = CURRENT_TIMESTAMP
        FROM Project.tbProject
            INNER JOIN inserted AS i ON tbProject.ProjectCode = i.ProjectCode;

        IF UPDATE(ProjectStatusCode) OR UPDATE(Quantity) OR UPDATE(ActionOn) OR UPDATE(UnitCharge) OR UPDATE(ObjectCode) OR UPDATE(CashCode) OR UPDATE(TaxCode)
        BEGIN
            WITH candidates AS
            (
                SELECT ProjectCode, SubjectCode, ObjectCode, ProjectStatusCode, ActionOn, Quantity, CashCode, TaxCode, UnitCharge
                FROM inserted
                WHERE EXISTS (SELECT * FROM Project.tbChangeLog WHERE ProjectCode = inserted.ProjectCode)
            ),
            logs AS
            (
                SELECT clog.LogId,
                       clog.ProjectCode,
                       clog.SubjectCode,
                       clog.ObjectCode,
                       clog.ProjectStatusCode,
                       clog.TransmitStatusCode,
                       clog.ActionOn,
                       clog.Quantity,
                       clog.CashCode,
                       clog.TaxCode,
                       clog.UnitCharge
                FROM Project.tbChangeLog clog
                    JOIN candidates ON clog.ProjectCode = candidates.ProjectCode
                                   AND LogId = (SELECT MAX(LogId) FROM Project.tbChangeLog WHERE ProjectCode = candidates.ProjectCode)
            )
            INSERT INTO Project.tbChangeLog
                                    (ProjectCode, TransmitStatusCode, SubjectCode, ObjectCode, ProjectStatusCode, ActionOn, Quantity, CashCode, TaxCode, UnitCharge)
            SELECT candidates.ProjectCode,
                   CASE Subjects.TransmitStatusCode WHEN 1 THEN 2 ELSE 0 END TransmitStatusCode,
                   candidates.SubjectCode,
                   candidates.ObjectCode,
                   candidates.ProjectStatusCode,
                   candidates.ActionOn,
                   candidates.Quantity,
                   candidates.CashCode,
                   candidates.TaxCode,
                   candidates.UnitCharge
            FROM candidates
                JOIN Subject.tbSubject Subjects ON candidates.SubjectCode = Subjects.SubjectCode
                JOIN logs ON candidates.ProjectCode = logs.ProjectCode
            WHERE (logs.ProjectStatusCode <> candidates.ProjectStatusCode)
               OR (logs.TransmitStatusCode < 2)
               OR (logs.ActionOn <> candidates.ActionOn)
               OR (logs.Quantity <> candidates.Quantity)
               OR (logs.UnitCharge <> candidates.UnitCharge)
               OR (logs.TaxCode <> candidates.TaxCode);
        END;

        IF UPDATE(SubjectCode)
        BEGIN
            WITH candidates AS
            (
                SELECT inserted.*
                FROM inserted
                    JOIN deleted ON inserted.ProjectCode = deleted.ProjectCode
                WHERE inserted.SubjectCode <> deleted.SubjectCode
            )
            INSERT INTO Project.tbChangeLog
                                    (ProjectCode, TransmitStatusCode, SubjectCode, ObjectCode, ProjectStatusCode, ActionOn, Quantity, CashCode, TaxCode, UnitCharge)
            SELECT candidates.ProjectCode,
                   Subject.tbSubject.TransmitStatusCode,
                   candidates.SubjectCode,
                   candidates.ObjectCode,
                   candidates.ProjectStatusCode,
                   candidates.ActionOn,
                   candidates.Quantity,
                   candidates.CashCode,
                   candidates.TaxCode,
                   candidates.UnitCharge
            FROM candidates
                JOIN Subject.tbSubject ON candidates.SubjectCode = Subject.tbSubject.SubjectCode
                JOIN Cash.vwCodeActive ON candidates.CashCode = Cash.vwCodeActive.CashCode;
        END

    END TRY
    BEGIN CATCH
        EXEC App.proc_ErrorLog;
    END CATCH
GO

PRINT N'Creating Procedure [Cash].[proc_CategoryVersionClone]...';


GO
CREATE PROCEDURE [Cash].[proc_CategoryVersionClone]
(
    @Description NVARCHAR(100),
    @Notes NVARCHAR(MAX) = NULL,
    @EffectiveFromOn DATE = NULL,
    @VersionId NVARCHAR(10) = NULL OUTPUT
)
AS
BEGIN
    SET NOCOUNT, XACT_ABORT ON;

    DECLARE
        @PredecessorVersionId NVARCHAR(10),
        @PredecessorStatusCode SMALLINT,
        @BaseContentSha256 BINARY(32),
        @CanonicalByteLength BIGINT,
        @UserId NVARCHAR(10),
        @UserName NVARCHAR(50),
        @LockResult INT;

    SELECT TOP (1) @UserId = UserId, @UserName = UserName
    FROM Usr.vwCredentials;

    IF @UserId IS NULL
        THROW 51119, 'Category Tree cloning requires an enabled application user.', 1;

    IF LEN(LTRIM(RTRIM(COALESCE(@Description, N'')))) = 0
        THROW 51120, 'A successor Draft requires a description.', 1;

    BEGIN TRY
        BEGIN TRAN;

        EXEC @LockResult = sys.sp_getapplock
            @Resource = N'Cash.CategoryTree.Publish',
            @LockMode = N'Exclusive',
            @LockOwner = N'Transaction',
            @LockTimeout = 15000;

        IF @LockResult < 0
            THROW 51121, 'The Category Tree lifecycle lock could not be acquired.', 1;

        SELECT @PredecessorVersionId = CategoryVersionId
        FROM App.tbOptions WITH (UPDLOCK, HOLDLOCK);

        SELECT
            @PredecessorStatusCode = VersionStatusCode,
            @BaseContentSha256 = CanonicalSha256
        FROM Cash.tbCategoryVersion WITH (UPDLOCK, HOLDLOCK)
        WHERE VersionId = @PredecessorVersionId;

        IF @PredecessorStatusCode NOT IN (1, 2)
            THROW 51122, 'A successor Draft requires an active Published or Submitted predecessor.', 1;

        IF @PredecessorStatusCode = 1
            EXEC Cash.proc_CategoryVersionCanonicalise
                @VersionId = @PredecessorVersionId,
                @CanonicalSha256 = @BaseContentSha256 OUTPUT,
                @CanonicalByteLength = @CanonicalByteLength OUTPUT;

        IF @BaseContentSha256 IS NULL
            THROW 51123, 'The active predecessor does not have canonical evidence.', 1;

        EXEC Cash.proc_CategoryVersionIdNext @VersionId = @VersionId OUTPUT;

        INSERT INTO Cash.tbCategoryVersion
        (
            VersionId, VersionStatusCode, Description, Notes,
            PredecessorVersionId, BaseContentSha256, EffectiveFromOn, CreatedByUserId
        )
        VALUES
        (
            @VersionId, 0, @Description, @Notes,
            @PredecessorVersionId, @BaseContentSha256, @EffectiveFromOn, @UserId
        );

        INSERT INTO Cash.tbCategory
        (
            VersionId, CategoryCode, Category, CategoryTypeCode,
            CashPolarityCode, CashTypeCode, DisplayOrder, IsEnabled
        )
        SELECT
            @VersionId, CategoryCode, Category, CategoryTypeCode,
            CashPolarityCode, CashTypeCode, DisplayOrder, IsEnabled
        FROM Cash.tbCategory
        WHERE VersionId = @PredecessorVersionId;

        INSERT INTO Cash.tbCategoryTotal (VersionId, ParentCode, ChildCode, DisplayOrder)
        SELECT @VersionId, ParentCode, ChildCode, DisplayOrder
        FROM Cash.tbCategoryTotal
        WHERE VersionId = @PredecessorVersionId;

        INSERT INTO Cash.tbCategoryCodeMap (VersionId, CashCode, CategoryCode)
        SELECT @VersionId, CashCode, CategoryCode
        FROM Cash.tbCategoryCodeMap
        WHERE VersionId = @PredecessorVersionId;

        INSERT INTO Cash.tbCategoryRoot (VersionId, RootTypeCode, CategoryCode)
        SELECT @VersionId, RootTypeCode, CategoryCode
        FROM Cash.tbCategoryRoot
        WHERE VersionId = @PredecessorVersionId;

        EXEC Cash.proc_CategoryVersionCanonicalise
            @VersionId = @VersionId,
            @CanonicalSha256 = @BaseContentSha256 OUTPUT,
            @CanonicalByteLength = @CanonicalByteLength OUTPUT;

        INSERT INTO Cash.tbCategoryVersionEvent
        (
            VersionId, EventTypeCode, ToStatusCode,
            UserId, UserName, ChangeNote, ContentSha256
        )
        VALUES
        (
            @VersionId, 0, 0,
            @UserId, @UserName, N'Successor Draft cloned from the active version.', @BaseContentSha256
        );

        COMMIT TRAN;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRAN;
        THROW;
    END CATCH;
END;
GO

PRINT N'Creating Procedure [Cash].[proc_CategoryVersionPublish]...';


GO
CREATE PROCEDURE [Cash].[proc_CategoryVersionPublish]
(
    @VersionId NVARCHAR(10),
    @ChangeNote NVARCHAR(MAX)
)
AS
BEGIN
    SET NOCOUNT, XACT_ABORT ON;

    DECLARE
        @PredecessorVersionId NVARCHAR(10),
        @PredecessorStatusCode SMALLINT,
        @BaseContentSha256 BINARY(32),
        @PredecessorSha256 BINARY(32),
        @DraftSha256 BINARY(32),
        @CanonicalByteLength BIGINT,
        @PublicationOn DATE = CONVERT(DATE, SYSUTCDATETIME()),
        @EffectiveFromOn DATE,
        @PredecessorEffectiveFromOn DATE,
        @UserId NVARCHAR(10),
        @UserName NVARCHAR(50),
        @LockResult INT;

    SELECT TOP (1) @UserId = UserId, @UserName = UserName
    FROM Usr.vwCredentials;

    IF @UserId IS NULL
        THROW 51124, 'Category Tree publication requires an enabled application user.', 1;

    IF LEN(LTRIM(RTRIM(COALESCE(@ChangeNote, N'')))) = 0
        THROW 51125, 'Category Tree publication requires a change note.', 1;

    BEGIN TRY
        BEGIN TRAN;

        EXEC @LockResult = sys.sp_getapplock
            @Resource = N'Cash.CategoryTree.Publish',
            @LockMode = N'Exclusive',
            @LockOwner = N'Transaction',
            @LockTimeout = 15000;

        IF @LockResult < 0
            THROW 51126, 'The Category Tree lifecycle lock could not be acquired.', 1;

        SELECT @PredecessorVersionId = CategoryVersionId
        FROM App.tbOptions WITH (UPDLOCK, HOLDLOCK);

        SELECT
            @BaseContentSha256 = BaseContentSha256,
            @EffectiveFromOn = EffectiveFromOn
        FROM Cash.tbCategoryVersion WITH (UPDLOCK, HOLDLOCK)
        WHERE VersionId = @VersionId
          AND VersionStatusCode = 0
          AND PredecessorVersionId = @PredecessorVersionId;

        IF @BaseContentSha256 IS NULL
            THROW 51127, 'The Draft is not a successor of the active version.', 1;

        IF @EffectiveFromOn IS NULL
            THROW 51165, 'Category Tree publication requires a proposed effective date.', 1;

        IF @EffectiveFromOn <> @PublicationOn
            THROW 51166, 'A Category Tree Draft may be published only on its proposed effective date.', 1;

        SELECT
            @PredecessorStatusCode = VersionStatusCode,
            @PredecessorSha256 = CanonicalSha256,
            @PredecessorEffectiveFromOn = EffectiveFromOn
        FROM Cash.tbCategoryVersion WITH (UPDLOCK, HOLDLOCK)
        WHERE VersionId = @PredecessorVersionId;

        IF @PredecessorStatusCode NOT IN (1, 2)
            THROW 51128, 'The active predecessor is not eligible for successor publication.', 1;

        IF @PredecessorEffectiveFromOn IS NULL OR @EffectiveFromOn <= @PredecessorEffectiveFromOn
            THROW 51167, 'A successor Category Tree must become effective after its predecessor.', 1;

        IF @PredecessorStatusCode = 1
            EXEC Cash.proc_CategoryVersionCanonicalise
                @VersionId = @PredecessorVersionId,
                @CanonicalSha256 = @PredecessorSha256 OUTPUT,
                @CanonicalByteLength = @CanonicalByteLength OUTPUT;

        IF @PredecessorSha256 <> @BaseContentSha256
            THROW 51129, 'The active predecessor changed after this Draft was cloned.', 1;

        EXEC Cash.proc_CategoryVersionValidate
            @VersionId = @VersionId,
            @CanonicalSha256 = @DraftSha256 OUTPUT,
            @CanonicalByteLength = @CanonicalByteLength OUTPUT;

        UPDATE Cash.tbCategoryVersion
        SET VersionStatusCode = 1,
            EffectiveFromOn = @EffectiveFromOn,
            EffectiveToOn = NULL
        WHERE VersionId = @VersionId;

        UPDATE App.tbOptions
        SET CategoryVersionId = @VersionId;

        UPDATE Cash.tbCategoryVersion
        SET VersionStatusCode = 3,
            EffectiveToOn = DATEADD(DAY, -1, @EffectiveFromOn)
        WHERE VersionId = @PredecessorVersionId;

        INSERT INTO Cash.tbCategoryVersionEvent
        (
            VersionId, EventTypeCode, FromStatusCode, ToStatusCode,
            UserId, UserName, ChangeNote, ContentSha256
        )
        VALUES
        (@VersionId, 3, 0, 1, @UserId, @UserName, @ChangeNote, @DraftSha256),
        (@PredecessorVersionId, 5, @PredecessorStatusCode, 3,
         @UserId, @UserName, N'Archived by successor publication.', @PredecessorSha256);

        COMMIT TRAN;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRAN;
        THROW;
    END CATCH;
END;
GO

PRINT N'Creating Procedure [Cash].[proc_CategoryVersionSubmit]...';


GO
CREATE PROCEDURE [Cash].[proc_CategoryVersionSubmit]
(
    @VersionId NVARCHAR(10),
    @ChangeNote NVARCHAR(MAX)
)
AS
BEGIN
    SET NOCOUNT, XACT_ABORT ON;

    DECLARE
        @CanonicalSha256 BINARY(32),
        @CanonicalByteLength BIGINT,
        @UserId NVARCHAR(10),
        @UserName NVARCHAR(50),
        @LockResult INT;

    SELECT TOP (1) @UserId = UserId, @UserName = UserName
    FROM Usr.vwCredentials;

    IF @UserId IS NULL
        THROW 51130, 'Category Tree submission requires an enabled application user.', 1;

    IF LEN(LTRIM(RTRIM(COALESCE(@ChangeNote, N'')))) = 0
        THROW 51131, 'Category Tree submission requires a submission note.', 1;

    BEGIN TRY
        BEGIN TRAN;

        EXEC @LockResult = sys.sp_getapplock
            @Resource = N'Cash.CategoryTree.Publish',
            @LockMode = N'Exclusive',
            @LockOwner = N'Transaction',
            @LockTimeout = 15000;

        IF @LockResult < 0
            THROW 51132, 'The Category Tree lifecycle lock could not be acquired.', 1;

        IF NOT EXISTS
        (
            SELECT 1
            FROM App.tbOptions WITH (UPDLOCK, HOLDLOCK)
            WHERE CategoryVersionId = @VersionId
        )
            THROW 51133, 'Only the active Category Tree version can be submitted.', 1;

        IF NOT EXISTS
        (
            SELECT 1
            FROM Cash.tbCategoryVersion WITH (UPDLOCK, HOLDLOCK)
            WHERE VersionId = @VersionId AND VersionStatusCode = 1
        )
            THROW 51134, 'Only a Published Category Tree version can be submitted.', 1;

        EXEC Cash.proc_CategoryVersionValidate
            @VersionId = @VersionId,
            @CanonicalSha256 = @CanonicalSha256 OUTPUT,
            @CanonicalByteLength = @CanonicalByteLength OUTPUT;

        UPDATE Cash.tbCategoryVersion
        SET VersionStatusCode = 2
        WHERE VersionId = @VersionId;

        INSERT INTO Cash.tbCategoryVersionEvent
        (
            VersionId, EventTypeCode, FromStatusCode, ToStatusCode,
            UserId, UserName, ChangeNote, ContentSha256
        )
        VALUES
        (@VersionId, 4, 1, 2, @UserId, @UserName, @ChangeNote, @CanonicalSha256);

        COMMIT TRAN;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRAN;
        THROW;
    END CATCH;
END;
GO

