GO
ALTER PROCEDURE App.proc_Template_BASE_MIN_2026
(
    @CategoryVersionId NVARCHAR(10),
    @FinancialMonth SMALLINT = 4,
    @GovAccountName NVARCHAR(255),
    @BankName NVARCHAR(255) = NULL,
    @BankAddress NVARCHAR(MAX) = NULL,
    @DummyAccount NVARCHAR(50),
    @CurrentAccount NVARCHAR(50) = NULL,
    @CA_SortCode NVARCHAR(10) = NULL,
    @CA_AccountNumber NVARCHAR(20) = NULL,
    @ReserveAccount NVARCHAR(50) = NULL,
    @RA_SortCode NVARCHAR(10) = NULL,
    @RA_AccountNumber NVARCHAR(20) = NULL
)
AS
    SET NOCOUNT, XACT_ABORT ON;

    BEGIN TRY

        DECLARE
            @CoinTypeCode SMALLINT = (SELECT TOP (1) CoinTypeCode FROM App.tbOptions),
            @SubjectCode  NVARCHAR(50),
            @AccountCode  NVARCHAR(10),
            @Decimals     SMALLINT;

        ----------------------------------------------------------------
        -- BUCKETS
        ----------------------------------------------------------------
        INSERT INTO [App].[tbBucket] ([Period], [BucketId], [BucketDescription], [AllowForecasts])
        VALUES (0,  'Overdue',    'Overdue Orders', 0),
               (1,  'Current',    'Current Week',   0),
               (2,  'Week 2',     'Week Two',       0),
               (3,  'Week 3',     'Week Three',     0),
               (4,  'Week 4',     'Week Four',      0),
               (8,  'Next Month', 'Next Month',     0),
               (16, '2 Months',   '2 Months',       1),
               (52, 'Forward',    'Forward Orders', 1);

        ----------------------------------------------------------------
        -- UNITS OF MEASURE
        ----------------------------------------------------------------
        INSERT INTO [App].[tbUom] ([UnitOfMeasure])
        VALUES ('each'),
               ('days'),
               ('hrs'),
               ('kilo'),
               ('miles'),
               ('mins'),
               ('units');

		----------------------------------------------------------------
        -- TAX CODES (minimalist, CoinType-aware)
        ----------------------------------------------------------------
        SET @Decimals = CASE @CoinTypeCode WHEN 2 THEN 2 ELSE 3 END;

        INSERT INTO [App].[tbTaxCode]
            ([TaxCode], [TaxRate], [TaxDescription], [TaxTypeCode], [RoundingCode], [Decimals])
        VALUES ('INT', 0,      'Interest Tax',       3, 0, @Decimals),
               ('N/A', 0,      'Untaxed',            3, 0, @Decimals),
               ('T0',  0,      'Zero Rated VAT',     1, 0, @Decimals),
               ('T1',  0.2000, 'Standard VAT Rate',  1, 0, @Decimals);

        ----------------------------------------------------------------
        -- CATEGORIES (purged of MTD tags; semantic prefixes)
        --   CT-* = Total (CategoryTypeCode=1)
        --   CA-* = Nominal (CategoryTypeCode=0)
        --   CE-* = Expression (CategoryTypeCode=2)
        ----------------------------------------------------------------
        INSERT INTO Cash.tbCategory
            (VersionId, CategoryCode, Category, CategoryTypeCode, CashPolarityCode, CashTypeCode, DisplayOrder, IsEnabled)
        VALUES
            -- Totals / reporting groups
            (@CategoryVersionId, 'CT-TURNOV', 'Turnover',                 1, 2, 0,  10, 1),
            (@CategoryVersionId, 'CT-OTHRIN', 'Other Income',             1, 2, 0,  20, 1),
            (@CategoryVersionId, 'CT-CSTSAL', 'Cost of Sales',            1, 2, 0,  30, 1),
            (@CategoryVersionId, 'CT-STAFFC', 'Staff Costs',              1, 2, 0,  40, 1),

            (@CategoryVersionId, 'CT-OVERHD', 'Overheads',                1, 2, 0,  60, 1),

            -- Gross profit total (required by expressions; users expect it)
            (@CategoryVersionId, 'CT-GROSSP', 'Gross Profit',             1, 2, 0,  70, 1),

            -- Profit root (system net profit root)
            (@CategoryVersionId, 'CT-PANDL',  'Profit and Loss',          1, 2, 0,  80, 1),

            -- Internal nominal categories
            (@CategoryVersionId, 'CA-SALES',  'Sales',                       0, 1, 0, 100, 1),
            (@CategoryVersionId, 'CA-INCOME', 'Other Income (Internal)',     0, 1, 0, 110, 1),
            (@CategoryVersionId, 'CA-DIRECT', 'Direct Costs',                0, 0, 0, 120, 1),
            (@CategoryVersionId, 'CA-WAGES',  'Wages',                       0, 0, 0, 130, 1),
            (@CategoryVersionId, 'CA-ADMIN',  'Admin Expenses',              0, 0, 0, 140, 1),

            -- Minimal asset movement bucket (moved to P&L)
            (@CategoryVersionId, 'CA-ASSET',  'Asset Movements',             0, 2, 2, 150, 1),

            -- Tax categories
            (@CategoryVersionId, 'CA-TAXGD',  'Tax on Goods (VAT / General)',0, 0, 1, 170, 1),
            (@CategoryVersionId, 'CA-TAXCO',  'Tax on Company (Biz)',        0, 0, 1, 180, 1),

            -- VAT root
            (@CategoryVersionId, 'CT-VAT',    'VAT Control Root',            1, 2, 1, 900, 1),

            -- Internal Balance Sheet-ish groupings
            (@CategoryVersionId, 'CA-BANK',   'Bank Accounts',               0, 2, 2, 910, 1),
            (@CategoryVersionId, 'CA-INVEST', 'Investments / Capital',       0, 2, 2, 920, 1),
            (@CategoryVersionId, 'CA-LIAB',   'Liabilities',                 0, 0, 2, 930, 1),

			-- Interbank Transfers
			(@CategoryVersionId, 'CA-IP',	   'Intercompany Payment',	      0, 0, 2, 200, 1),
			(@CategoryVersionId, 'CA-IR',      'Intercompany Receipt',	      0, 1, 2, 210, 1),

			-- Dividend Payment
			(@CategoryVersionId, 'CA-DIVID',   'Dividends',                   0, 0, 0, 300, 1);

        ----------------------------------------------------------------
        -- CATEGORY TOTALS (roll-up structure)
        ----------------------------------------------------------------
        INSERT INTO Cash.tbCategoryTotal (VersionId, ParentCode, ChildCode)
        VALUES
            -- Profit and Loss (CT-PANDL)
            (@CategoryVersionId, 'CT-PANDL', 'CT-GROSSP'),
            (@CategoryVersionId, 'CT-PANDL', 'CT-STAFFC'),
            (@CategoryVersionId, 'CT-PANDL', 'CT-OVERHD'),
            (@CategoryVersionId, 'CT-PANDL', 'CA-ASSET'),

            -- Gross Profit
            (@CategoryVersionId, 'CT-GROSSP', 'CT-TURNOV'),
            (@CategoryVersionId, 'CT-GROSSP', 'CT-OTHRIN'),
            (@CategoryVersionId, 'CT-GROSSP', 'CT-CSTSAL'),

            -- Turnover
            (@CategoryVersionId, 'CT-TURNOV', 'CA-SALES'),

            -- Other income
            (@CategoryVersionId, 'CT-OTHRIN', 'CA-INCOME'),

            -- Cost of sales
            (@CategoryVersionId, 'CT-CSTSAL', 'CA-DIRECT'),

            -- Staff costs
            (@CategoryVersionId, 'CT-STAFFC', 'CA-WAGES'),

            -- Overheads
            (@CategoryVersionId, 'CT-OVERHD', 'CA-ADMIN'),

            -- VAT root
            (@CategoryVersionId, 'CT-VAT', 'CA-SALES'),
            (@CategoryVersionId, 'CT-VAT', 'CA-INCOME'),
            (@CategoryVersionId, 'CT-VAT', 'CA-DIRECT'),
            (@CategoryVersionId, 'CT-VAT', 'CT-OVERHD');

        ----------------------------------------------------------------
        -- CASH CODES 
        ----------------------------------------------------------------
        DECLARE @CategoryCodeMap TABLE
        (
            CashCode NVARCHAR(50) NOT NULL PRIMARY KEY,
            CategoryCode NVARCHAR(10) NOT NULL
        );

        INSERT INTO Cash.tbCode
            (CashCode, CashDescription, CategoryCode, TaxCode, IsEnabled)
        OUTPUT inserted.CashCode, inserted.CategoryCode
            INTO @CategoryCodeMap (CashCode, CategoryCode)
        VALUES
            -- Income
            ('CC-SALES', 'Sales',             'CA-SALES',  'T1',  1),
            ('CC-INCME', 'Other Income',      'CA-INCOME', 'T1',  1),

            -- Direct Costs
            ('CC-DIRCT', 'Direct Costs',      'CA-DIRECT', 'T1',  1),

            -- Wages
            ('CC-WAGES', 'Wages',             'CA-WAGES',  'N/A', 1),
			('CC-PENSN', 'Pensions',          'CA-WAGES',  'N/A', 1),

            -- Admin
            ('CC-ADMIN', 'Admin Expenses',    'CA-ADMIN',  'T1',  1),

            -- Depreciation (internal)
            ('CC-DEPRC', 'Depreciation',            'CA-ASSET', 'N/A', 1),
            ('CC-DEPRJ', 'Depreciation Adjustment', 'CA-ASSET', 'N/A', 1),

            -- Tax (aligned to TaxTypeCode 0–3)
            ('CC-VAT',   'VAT Control',       'CA-TAXGD',  'N/A', 1),
            ('CC-BIZTX', 'Business Tax',      'CA-TAXCO',  'N/A', 1),
            ('CC-GENTX', 'General Taxes',     'CA-TAXGD',  'N/A', 1),

			('CC-EMPNI', 'Employers NI',      'CA-WAGES',  'N/A', 1),

            -- Operational accounts
            ('CC-BANK',  'Bank',              'CA-BANK',   'N/A', 1),
            ('CC-SHCAP', 'Share Capital',     'CA-INVEST', 'N/A', 1),
            ('CC-LOAN',  'Loan / Liability',  'CA-LIAB',   'N/A', 1),

			-- Bank Transfers
			('CC-TRNPY', 'Transfer Payment',  'CA-IP',     'N/A', 1),
            ('CC-TRNRC', 'Transfer Receipt',  'CA-IR',     'N/A', 1),
			
			-- Dividends
			('CC-DIVID', 'Dividends',         'CA-DIVID',  'N/A', 1);

        INSERT INTO Cash.tbCategoryCodeMap (VersionId, CashCode, CategoryCode)
        SELECT @CategoryVersionId, CashCode, CategoryCode
        FROM @CategoryCodeMap;

        ----------------------------------------------------------------
        -- EXPRESSION CATEGORIES (CategoryTypeCode = 2)
        ----------------------------------------------------------------
        INSERT INTO Cash.tbCategory
            (VersionId, CategoryCode, Category, CategoryTypeCode, CashPolarityCode, CashTypeCode, DisplayOrder, IsEnabled)
        VALUES
            (@CategoryVersionId, 'CE-GP', 'Gross Margin %',              2, 2, 0,  1, 1),
            (@CategoryVersionId, 'CE-NP', 'Net Profit %',                2, 2, 0,  2, 1),
            (@CategoryVersionId, 'CE-WP', 'Wages Ratio',                 2, 2, 0,  3, 1),
            (@CategoryVersionId, 'CE-AP', 'Admin Cost Ratio',            2, 2, 0,  4, 1),
            (@CategoryVersionId, 'CE-DP', 'Direct Cost Ratio',           2, 2, 0,  5, 1),
            (@CategoryVersionId, 'CE-DE', 'Depreciation Ratio',          2, 2, 0,  6, 1),
            (@CategoryVersionId, 'CE-OC', 'Overhead Coverage Ratio',     2, 2, 0,  8, 1),
            (@CategoryVersionId, 'CE-RS', 'Revenue-to-Wages Ratio',      2, 2, 0,  9, 1);

        ----------------------------------------------------------------
        -- EXPRESSION DEFINITIONS
        ----------------------------------------------------------------
        INSERT INTO Cash.tbCategoryExp
            (CategoryCode, Expression, Format, SyntaxTypeCode, IsError, ErrorMessage)
        VALUES
            -- Gross Margin %
            ('CE-GP', 'IF([CA-SALES]=0,0,([CT-GROSSP]/[CA-SALES]))', 'Pct0', 0, 0, NULL),

            -- Net Profit % (use CT-PANDL description)
            ('CE-NP', 'IF([CA-SALES]=0,0,([CT-PANDL]/[CA-SALES]))', 'Pct0', 0, 0, NULL),

            -- Wages %
            ('CE-WP', 'IF([CA-SALES]=0,0,(ABS([CA-WAGES])/[CA-SALES]))', 'Num2', 0, 0, NULL),

            -- Admin Cost %
            ('CE-AP', 'IF([CA-SALES]=0,0,(ABS([CA-ADMIN])/[CA-SALES]))', 'Num2', 0, 0, NULL),

            -- Direct Cost %
            ('CE-DP', 'IF([CA-SALES]=0,0,(ABS([CA-DIRECT])/[CA-SALES]))', 'Num2', 0, 0, NULL),

            -- Depreciation % (Asset Movements)
            ('CE-DE', 'IF([CA-SALES]=0,0,(ABS([CA-ASSET])/[CA-SALES]))', 'Num2', 0, 0, NULL),

            -- Overhead Coverage Ratio
            ('CE-OC', 'IF([CA-ADMIN]=0,0,([CT-GROSSP]/ABS([CA-ADMIN])))', 'Num2', 0, 0, NULL),

            -- Revenue per £ Staff Cost
            ('CE-RS', 'IF([CA-WAGES]=0,0,([CA-SALES]/ABS([CA-WAGES])))', 'Num2', 0, 0, NULL);

        ----------------------------------------------------------------
        -- CRYPTO-ONLY MINER FEE CASH CODE
        ----------------------------------------------------------------
        IF @CoinTypeCode < 2
        BEGIN
            INSERT INTO [Cash].[tbCode] ([CashCode], [CashDescription], [CategoryCode], [TaxCode], [IsEnabled])
            VALUES ('CC-MINER', 'Miner Fees', 'CA-DIRECT', 'N/A', 1);

            INSERT INTO Cash.tbCategoryCodeMap (VersionId, CashCode, CategoryCode)
            VALUES (@CategoryVersionId, 'CC-MINER', 'CA-DIRECT');

            UPDATE App.tbOptions
            SET MinerFeeCode = 'CC-MINER';
        END

        ----------------------------------------------------------------
        -- NET PROFIT & VAT CATEGORY
        ----------------------------------------------------------------
        INSERT INTO Cash.tbCategoryRoot (VersionId, RootTypeCode, CategoryCode)
        VALUES
            (@CategoryVersionId, 0, 'CT-PANDL'),
            (@CategoryVersionId, 1, 'CT-VAT');

        -- Transitional compatibility until the legacy option roots are removed.
        UPDATE App.tbOptions
        SET NetProfitCode   = 'CT-PANDL',
            VatCategoryCode = 'CT-VAT';

        ----------------------------------------------------------------
        -- HOME SUBJECT TAX CODE (STANDARD VAT)
        ----------------------------------------------------------------
        UPDATE Subject.tbSubject
        SET TaxCode = 'T1'
        WHERE SubjectCode = (SELECT SubjectCode FROM App.tbOptions);

        ----------------------------------------------------------------
        -- GOV / HMRC SUBJECT
        ----------------------------------------------------------------
        EXEC Subject.proc_DefaultSubjectCode
             @SubjectName = @GovAccountName,
             @SubjectCode = @SubjectCode OUTPUT;

        INSERT INTO Subject.tbSubject
            (SubjectCode, SubjectName, SubjectStatusCode, SubjectTypeCode, TaxCode)
        VALUES
            (@SubjectCode, @GovAccountName, 1, 7, 'N/A');

        INSERT INTO Subject.tbVirtual
            (SubjectCode)
        VALUES
            (@SubjectCode);

        ----------------------------------------------------------------
        -- ASSIGN CASH CODES AND GOV TO TAX TYPES
        ----------------------------------------------------------------
        UPDATE Cash.tbTaxType
        SET SubjectCode = @SubjectCode,
            CashCode    = 'CC-BIZTX',
            MonthNumber = @FinancialMonth
        WHERE TaxTypeCode IN (0, 4, 5);  -- Business Tax

        UPDATE Cash.tbTaxType
        SET SubjectCode = @SubjectCode,
            CashCode    = 'CC-VAT',
            MonthNumber = @FinancialMonth
        WHERE TaxTypeCode = 1;  -- VAT

        UPDATE Cash.tbTaxType
        SET SubjectCode = @SubjectCode,
            CashCode    = 'CC-EMPNI',
            MonthNumber = @FinancialMonth
        WHERE TaxTypeCode = 2;  -- N.I.

        UPDATE Cash.tbTaxType
        SET SubjectCode = @SubjectCode,
            CashCode    = 'CC-GENTX',
            MonthNumber = @FinancialMonth
        WHERE TaxTypeCode = 3;  -- General

        ----------------------------------------------------------------
        -- BANK / CRYPTO SUBJECT
        ----------------------------------------------------------------
        IF @CoinTypeCode = 2
        BEGIN
            -- FIAT BANK
            EXEC Subject.proc_DefaultSubjectCode
                 @SubjectName = @BankName,
                 @SubjectCode = @SubjectCode OUTPUT;

            INSERT INTO Subject.tbSubject
                (SubjectCode, SubjectName, SubjectStatusCode, SubjectTypeCode, TaxCode)
            VALUES
                (@SubjectCode, @BankName, 1, 5, 'T0');

            INSERT INTO Subject.tbVirtual
                (SubjectCode)
            VALUES
                (@SubjectCode);

            EXEC Subject.proc_AddAddress
                 @SubjectCode = @SubjectCode,
                 @Address     = @BankAddress;
        END
        ELSE
        BEGIN
            -- CRYPTO MINER SUBJECT
            EXEC Subject.proc_DefaultSubjectCode
                 @SubjectName = 'BITCOIN MINER',
                 @SubjectCode = @SubjectCode OUTPUT;

            INSERT INTO Subject.tbSubject
                (SubjectCode, SubjectName, SubjectStatusCode, SubjectTypeCode, TaxCode)
            VALUES
                (@SubjectCode, 'BITCOIN MINER', 1, 7, 'N/A');

            INSERT INTO Subject.tbVirtual
                (SubjectCode)
            VALUES
                (@SubjectCode);

            UPDATE App.tbOptions
            SET MinerAccountCode = @SubjectCode;

            -- Reset @SubjectCode to HOME subject
            SELECT @SubjectCode = SubjectCode
            FROM App.tbOptions;
        END

        ----------------------------------------------------------------
        -- CURRENT ACCOUNT
        ----------------------------------------------------------------
        EXEC Subject.proc_DefaultSubjectCode
             @SubjectName = @CurrentAccount,
             @SubjectCode = @AccountCode OUTPUT;

        INSERT INTO Subject.tbAccount
            (AccountCode, SubjectCode, AccountName, OpeningBalance, SortCode, AccountNumber, CashCode)
        VALUES
            (@AccountCode, @SubjectCode, @CurrentAccount, 0, @CA_SortCode, @CA_AccountNumber, 'CC-BANK');

        ----------------------------------------------------------------
        -- RESERVE ACCOUNT (OPTIONAL)
        ----------------------------------------------------------------
        IF (LEN(COALESCE(@ReserveAccount, '')) > 0)
        BEGIN
            EXEC Subject.proc_DefaultSubjectCode
                 @SubjectName = @ReserveAccount,
                 @SubjectCode = @AccountCode OUTPUT;

            INSERT INTO Subject.tbAccount
                (AccountCode, SubjectCode, AccountName, OpeningBalance, SortCode, AccountNumber)
            VALUES
                (@AccountCode, @SubjectCode, @ReserveAccount, 0, @RA_SortCode, @RA_AccountNumber);
        END

        ----------------------------------------------------------------
        -- RESET SUBJECT TO HOME SUBJECT
        ----------------------------------------------------------------
        SELECT @SubjectCode = (SELECT SubjectCode FROM App.tbOptions);

        ----------------------------------------------------------------
        -- DUMMY ACCOUNT (OPTIONAL)
        ----------------------------------------------------------------
        IF (LEN(COALESCE(@DummyAccount, '')) > 0)
        BEGIN
            EXEC Subject.proc_DefaultSubjectCode
                 @SubjectName = @DummyAccount,
                 @SubjectCode = @AccountCode OUTPUT;

            INSERT INTO Subject.tbAccount
                (AccountCode, SubjectCode, AccountName, AccountTypeCode, CashCode)
            VALUES
                (@AccountCode, @SubjectCode, @DummyAccount, 1, NULL);
        END

        ----------------------------------------------------------------
        -- CAPITAL (MINIMALIST: EQUIPMENT + ADJUSTMENTS)
        ----------------------------------------------------------------
        DECLARE @CapitalAccount NVARCHAR(50);

        -- LONGTERM LIABILITIES
        SET @CapitalAccount = 'LONGTERM LIABILITIES';
        EXEC Subject.proc_DefaultAccountCode
             @AccountName = @CapitalAccount,
             @AccountCode = @AccountCode OUTPUT;

        INSERT INTO Subject.tbAccount
            (AccountCode, SubjectCode, AccountName, AccountTypeCode, BalanceConstraintCode, LiquidityLevel, CashCode, AccountClosed)
        VALUES
            (@AccountCode, @SubjectCode, @CapitalAccount, 2, 2, 50, 'CC-LOAN', 0);

        -- CALLED UP SHARE CAPITAL
        SET @CapitalAccount = 'CALLED UP SHARE CAPITAL';
        EXEC Subject.proc_DefaultAccountCode
             @AccountName = @CapitalAccount,
             @AccountCode = @AccountCode OUTPUT;

        INSERT INTO Subject.tbAccount
            (AccountCode, SubjectCode, AccountName, AccountTypeCode, BalanceConstraintCode, LiquidityLevel, CashCode, AccountClosed)
        VALUES
            (@AccountCode, @SubjectCode, @CapitalAccount, 2, 2, 60, 'CC-SHCAP', 0);

        -- EQUIPMENT (replaces P&M, Vehicles, Stock)
        SET @CapitalAccount = 'EQUIPMENT';
        EXEC Subject.proc_DefaultAccountCode
             @AccountName = @CapitalAccount,
             @AccountCode = @AccountCode OUTPUT;

        INSERT INTO Subject.tbAccount
            (AccountCode, SubjectCode, AccountName, AccountTypeCode, BalanceConstraintCode, LiquidityLevel, CashCode, AccountClosed)
        VALUES
            (@AccountCode, @SubjectCode, @CapitalAccount, 2, 1, 30, 'CC-DEPRC', 1);

        -- EQUIPMENT ADJUSTMENTS (replaces Depreciation Adjustments)
        SET @CapitalAccount = 'EQUIPMENT ADJUSTMENTS';
        EXEC Subject.proc_DefaultAccountCode
             @AccountName = @CapitalAccount,
             @AccountCode = @AccountCode OUTPUT;

        INSERT INTO Subject.tbAccount
            (AccountCode, SubjectCode, AccountName, AccountTypeCode, BalanceConstraintCode, LiquidityLevel, CashCode, AccountClosed)
        VALUES
            (@AccountCode, @SubjectCode, @CapitalAccount, 2, 0, 40, 'CC-DEPRJ', 1);


    END TRY
    BEGIN CATCH
        EXEC App.proc_ErrorLog;
    END CATCH;
GO

PRINT N'Altering Procedure [App].[proc_Template_CO_MICRO_CUR_2026]...';


GO
ALTER PROCEDURE App.proc_Template_CO_MICRO_CUR_2026
(
    @CategoryVersionId NVARCHAR(10),
    @FinancialMonth SMALLINT = 4,
    @GovAccountName NVARCHAR(255),
    @BankName NVARCHAR(255) = NULL,
    @BankAddress NVARCHAR(MAX) = NULL,
    @DummyAccount NVARCHAR(50),
    @CurrentAccount NVARCHAR(50) = NULL,
    @CA_SortCode NVARCHAR(10) = NULL,
    @CA_AccountNumber NVARCHAR(20) = NULL,
    @ReserveAccount NVARCHAR(50) = NULL,
    @RA_SortCode NVARCHAR(10) = NULL,
    @RA_AccountNumber NVARCHAR(20) = NULL
)
AS
    SET NOCOUNT, XACT_ABORT ON;

    BEGIN TRY

        ----------------------------------------------------------------
        -- 1. Base template: Minimal Micro Business (current schema)
        ----------------------------------------------------------------
        EXEC App.proc_Template_BASE_MIN_2026
             @CategoryVersionId = @CategoryVersionId,
             @FinancialMonth   = @FinancialMonth,
             @GovAccountName   = @GovAccountName,
             @BankName         = @BankName,
             @BankAddress      = @BankAddress,
             @DummyAccount     = @DummyAccount,
             @CurrentAccount   = @CurrentAccount,
             @CA_SortCode      = @CA_SortCode,
             @CA_AccountNumber = @CA_AccountNumber,
             @ReserveAccount   = @ReserveAccount,
             @RA_SortCode      = @RA_SortCode,
             @RA_AccountNumber = @RA_AccountNumber;

        ----------------------------------------------------------------
        -- 2. Registered office default
        -- Initial business setup supplies one operational address. A company
        -- starts with the same value in a distinct Registered address row so
        -- either address can subsequently change without changing its role.
        ----------------------------------------------------------------
        DECLARE
            @SubjectCode NVARCHAR(50) = (SELECT SubjectCode FROM App.tbOptions),
            @DefaultAddress NVARCHAR(MAX);

        SELECT @DefaultAddress = address.Address
        FROM Subject.tbSubject subject
        JOIN Subject.tbAddress address ON address.AddressCode = subject.AddressCode
        WHERE subject.SubjectCode = @SubjectCode;

        IF @DefaultAddress IS NOT NULL
           AND NOT EXISTS
           (
               SELECT 1
               FROM Subject.tbAddress
               WHERE SubjectCode = @SubjectCode AND AddressTypeCode = 2
           )
            EXEC Subject.proc_AddAddress
                @SubjectCode = @SubjectCode,
                @Address = @DefaultAddress,
                @AddressTypeCode = 2;

        ----------------------------------------------------------------
        -- 3. COMPANY ACCOUNTING CLASSIFICATION
        -- Statutory sources are composed by proc_Template_CO_MICRO_CUR_TAX_2026
        -- after the MIN/STD accounting profile has completed its refinements.
        ----------------------------------------------------------------
        INSERT INTO Cash.tbCategory
            (VersionId, CategoryCode, Category, CategoryTypeCode, CashPolarityCode, CashTypeCode, DisplayOrder, IsEnabled)
        VALUES
            (@CategoryVersionId, 'CA-DEPREC', 'Depreciation expense', 0, 0, 0, 145, 1);

        INSERT INTO Cash.tbCategoryTotal (VersionId, ParentCode, ChildCode)
        VALUES (@CategoryVersionId, 'CT-OVERHD', 'CA-DEPREC');

        UPDATE Cash.tbCode
        SET CategoryCode = 'CA-DEPREC'
        WHERE CashCode = 'CC-DEPRC';

        UPDATE Cash.tbCategoryCodeMap
        SET CategoryCode = 'CA-DEPREC'
        WHERE VersionId = @CategoryVersionId
          AND CashCode = 'CC-DEPRC';

        ----------------------------------------------------------------
        -- 4. Business Tax settings for Corporations
        ----------------------------------------------------------------
        UPDATE Cash.tbTaxType
        SET IsEnabled = 1
        WHERE TaxTypeCode = 0;

        UPDATE Cash.tbTaxType
        SET IsEnabled = 0
        WHERE TaxTypeCode IN (4, 5);

    END TRY
    BEGIN CATCH
        EXEC App.proc_ErrorLog;
    END CATCH;
GO

PRINT N'Altering Procedure [App].[proc_DatasetSyntheticMIS_Assets]...';


GO
ALTER PROCEDURE App.proc_DatasetSyntheticMIS_Assets
(
	@IsCompany bit,
	@IsVatRegistered bit
)
AS
	SET NOCOUNT, XACT_ABORT ON;

	IF @IsCompany = 0
		RETURN;

	IF OBJECT_ID('tempdb..#DatasetCodes') IS NULL
		THROW 51260, 'DatasetSyntheticMIS_Assets: missing temp table #DatasetCodes. Run via App.proc_DatasetSyntheticMIS.', 1;

	DECLARE @UserId nvarchar(10) = (SELECT TOP (1) UserId FROM Usr.vwCredentials);

	DECLARE @Year1 smallint = (SELECT MIN(YearNumber) FROM App.tbYear);

	IF @Year1 IS NULL
		THROW 51261, 'DatasetSyntheticMIS_Assets: App.tbYear is empty.', 1;

	DECLARE @Year1FirstStartOn date =
	(
		SELECT MIN(CAST(yp.StartOn AS date))
		FROM App.tbYearPeriod yp
		WHERE yp.YearNumber = @Year1
	);

	IF @Year1FirstStartOn IS NULL
		THROW 51262, 'DatasetSyntheticMIS_Assets: unable to resolve year 1 start period.', 1;

	DECLARE @FirstTradingOn date = @Year1FirstStartOn;

	DECLARE @Year1LatePurchaseOn date =
	(
		SELECT TOP (1) CAST(yp.StartOn AS date)
		FROM App.tbYearPeriod yp
		WHERE yp.YearNumber = @Year1
		  AND yp.CashStatusCode = 2
		ORDER BY yp.StartOn DESC
	);

	IF @Year1LatePurchaseOn IS NULL
	BEGIN
		SELECT @Year1LatePurchaseOn = MAX(CAST(yp.StartOn AS date))
		FROM App.tbYearPeriod yp
		WHERE yp.YearNumber = @Year1;
	END

	UPDATE Subject.tbAccount
	SET AccountClosed = 0
	WHERE AccountTypeCode = 2
	  AND AccountClosed = 1;

	DECLARE @SettlementAccountCode nvarchar(10) =
		(SELECT CodeValue FROM #DatasetCodes WHERE CodeType = N'LINK' AND CodeName = N'SettlementAccountCode');

	IF @SettlementAccountCode IS NULL
	BEGIN
		SELECT @SettlementAccountCode = AccountCode FROM Cash.vwCurrentAccount;
	END

	IF @SettlementAccountCode IS NULL
		THROW 51263, 'DatasetSyntheticMIS_Assets: unable to resolve SettlementAccountCode.', 1;

	DECLARE
		@BusinessRootCode nvarchar(50) = (SELECT TOP (1) SubjectCode FROM App.tbOptions),
		@SellerRootCode nvarchar(50) = (SELECT CodeValue FROM #DatasetCodes WHERE CodeType = N'SUBJECT' AND CodeName = N'SellerRoot');

	IF @BusinessRootCode IS NULL OR NOT EXISTS (SELECT 1 FROM Subject.tbSubject WHERE SubjectCode = @BusinessRootCode)
		THROW 51268, 'DatasetSyntheticMIS_Assets: unable to resolve the business root subject.', 1;

	IF @SellerRootCode IS NULL
		THROW 51267, 'DatasetSyntheticMIS_Assets: missing SUBJECT/SellerRoot in #DatasetCodes.', 1;

	IF EXISTS (SELECT 1 FROM Subject.tbAccount WHERE AccountCode = N'CALUP' AND AccountClosed = 0)
	BEGIN
		DECLARE @SharePaymentCode nvarchar(20) = NULL;
		EXEC Cash.proc_NextPaymentCode @PaymentCode = @SharePaymentCode OUTPUT;

		IF NOT EXISTS
		(
			SELECT 1
			FROM Cash.tbPayment p
			WHERE p.PaymentReference = N'Called Up Shares'
			  AND p.SubjectCode = @BusinessRootCode
			  AND p.AccountCode = N'CALUP'
			  AND CAST(p.PaidOn AS date) = @FirstTradingOn
		)
		BEGIN
			INSERT INTO Cash.tbPayment
			(
				PaymentCode,
				UserId,
				PaymentStatusCode,
				SubjectCode,
				AccountCode,
				CashCode,
				TaxCode,
				PaidOn,
				PaidInValue,
				PaidOutValue,
				PaymentReference
			)
			VALUES
			(
				@SharePaymentCode,
				@UserId,
				1,
				@BusinessRootCode,
				N'CALUP',
				N'CC-SHCAP',
				N'N/A',
				@FirstTradingOn,
				0.00000,
				1.00000,
				N'Called Up Shares'
			);
		END
	END

	DECLARE
		@SidsCode nvarchar(50) = NULL,
		@EmployeeName nvarchar(100) = N'Sid Jones';

	EXEC Subject.proc_AddNamespace
		@RootSubjectCode = @BusinessRootCode,
		@SubjectName = @EmployeeName,
		@SubjectTypeCode = 9,
		@SubjectCode = @SidsCode OUTPUT;

	UPDATE Subject.tbSubject
	SET
		SubjectStatusCode = 1,
		TaxCode = N'N/A',
		ExportTypeCode = 0,
		PaymentTerms = N'Immediate',
		ExpectedDays = 0,
		PaymentDays = 0,
		PayDaysFromMonthEnd = 0,
		PayBalance = 1
	WHERE SubjectCode = @SidsCode;

	IF NOT EXISTS
	(
		SELECT 1
		FROM Subject.tbSubject s
		JOIN Subject.tbAddress a ON a.AddressCode = s.AddressCode
		WHERE s.SubjectCode = @SidsCode
	)
	BEGIN
		DECLARE @Address nvarchar(max) = CONCAT(N'Residence of ', @EmployeeName);

		EXEC Subject.proc_AddAddress
			@SubjectCode = @SidsCode,
			@Address = @Address;
	END

	MERGE #DatasetCodes AS t
	USING (SELECT N'SUBJECT' AS CodeType, N'Director' AS CodeName, @SidsCode AS CodeValue, NULL AS RelatedName, N'Sid Jones' AS Notes) AS s
		ON t.CodeType = s.CodeType AND t.CodeName = s.CodeName
	WHEN NOT MATCHED THEN INSERT (CodeType, CodeName, CodeValue, RelatedName, Notes) VALUES (s.CodeType, s.CodeName, s.CodeValue, s.RelatedName, s.Notes)
	WHEN MATCHED THEN UPDATE SET CodeValue = s.CodeValue, Notes = s.Notes;

	IF NOT EXISTS
	(
			SELECT 1
			FROM Cash.tbPayment p
			WHERE p.SubjectCode = @SidsCode
			  AND p.AccountCode = @SettlementAccountCode
			  AND p.CashCode = N'CC-INCME'
			  AND CAST(p.PaidOn AS date) = @FirstTradingOn
			  AND p.PaymentReference = N'Share Capital Subscription'
	)
	BEGIN
		DECLARE @ShareInPaymentCode nvarchar(20) = NULL;
		EXEC Cash.proc_NextPaymentCode @PaymentCode = @ShareInPaymentCode OUTPUT;

		INSERT INTO Cash.tbPayment
		(
			PaymentCode,
			UserId,
			PaymentStatusCode,
			SubjectCode,
			AccountCode,
			CashCode,
			TaxCode,
			PaidOn,
			PaidInValue,
			PaidOutValue,
			PaymentReference
		)
		VALUES
		(
			@ShareInPaymentCode,
			@UserId,
			0,
			@SidsCode,
			@SettlementAccountCode,
			N'CC-INCME',
			N'N/A',
			@FirstTradingOn,
			1.00000,
			0.00000,
			N'Share Capital Subscription'
		);
	END

	DECLARE @LoanAmount decimal(18,5) = 5000.00000;

	IF NOT EXISTS
	(
		SELECT 1
		FROM Cash.tbPayment p
		WHERE p.SubjectCode = @SidsCode
		  AND p.AccountCode = @SettlementAccountCode
		  AND p.CashCode = N'CC-INCME'
		  AND CAST(p.PaidOn AS date) = @FirstTradingOn
		  AND p.PaymentReference = N'Director Loan Injection'
	)
	BEGIN
		DECLARE @InjectPaymentCode nvarchar(20) = NULL;
		EXEC Cash.proc_NextPaymentCode @PaymentCode = @InjectPaymentCode OUTPUT;

		INSERT INTO Cash.tbPayment
		(
			PaymentCode,
			UserId,
			PaymentStatusCode,
			SubjectCode,
			AccountCode,
			CashCode,
			TaxCode,
			PaidOn,
			PaidInValue,
			PaidOutValue,
			PaymentReference
		)
		VALUES
		(
			@InjectPaymentCode,
			@UserId,
			0,
			@SidsCode,
			@SettlementAccountCode,
			N'CC-INCME',
			N'N/A',
			DATEADD(DAY, 7, @FirstTradingOn),
			@LoanAmount,
			0.00000,
			N'Director Loan Injection'
		);
	END

	IF EXISTS (SELECT 1 FROM Subject.tbAccount WHERE AccountCode = N'LONLIA' AND AccountClosed = 0)
	BEGIN
		IF NOT EXISTS
		(
			SELECT 1
			FROM Cash.tbPayment p
			WHERE p.SubjectCode = @BusinessRootCode
			  AND p.AccountCode = N'LONLIA'
			  AND p.CashCode = N'CC-LOAN'
			  AND CAST(p.PaidOn AS date) = @FirstTradingOn
			  AND p.PaymentReference = N'Director Loan Liability'
		)
		BEGIN
			DECLARE @LiabPaymentCode nvarchar(20) = NULL;
			EXEC Cash.proc_NextPaymentCode @PaymentCode = @LiabPaymentCode OUTPUT;

			INSERT INTO Cash.tbPayment
			(
				PaymentCode,
				UserId,
				PaymentStatusCode,
				SubjectCode,
				AccountCode,
				CashCode,
				TaxCode,
				PaidOn,
				PaidInValue,
				PaidOutValue,
				PaymentReference
			)
			VALUES
			(
				@LiabPaymentCode,
				@UserId,
				1,
				@BusinessRootCode,
				N'LONLIA',
				N'CC-LOAN',
				N'N/A',
				DATEADD(DAY, 7, @FirstTradingOn),
				0.00000,
				@LoanAmount,
				N'Director Loan Liability'
			);
		END
	END

	EXEC Cash.proc_PaymentPost;

	IF NOT EXISTS (SELECT 1 FROM Cash.tbCode WHERE CashCode = N'CC-MREPA')
	BEGIN
		DECLARE @CategoryVersionId NVARCHAR(10) = (SELECT CategoryVersionId FROM App.tbOptions);

		EXEC Cash.proc_CodeAdd
			@VersionId = @CategoryVersionId,
			@CashCode = N'CC-MREPA',
			@CashDescription = N'Motors',
			@CategoryCode = N'CA-DIRECT',
			@TaxCode = N'T1',
			@IsEnabled = 1;
	END

	DECLARE @GarageCode nvarchar(50) = NULL;

	EXEC Subject.proc_AddNamespace
		@RootSubjectCode = @SellerRootCode,
		@SubjectName = N'Dataset Garage',
		@SubjectTypeCode = 0,
		@SubjectCode = @GarageCode OUTPUT;

	IF @GarageCode IS NULL
		THROW 51265, 'DatasetSyntheticMIS_Assets: failed to allocate SubjectCode for Dataset Garage.', 1;

	UPDATE Subject.tbSubject
	SET
		SubjectStatusCode = 1,
		TaxCode = N'T1',
		ExportTypeCode = 0,
		PaymentTerms = N'30 days',
		ExpectedDays = 0,
		PaymentDays = 30,
		PayDaysFromMonthEnd = 0,
		PayBalance = 1
	WHERE SubjectCode = @GarageCode;

	IF NOT EXISTS
	(
		SELECT 1
		FROM Subject.tbSubject s
		JOIN Subject.tbAddress a ON a.AddressCode = s.AddressCode
		WHERE s.SubjectCode = @GarageCode
	)
	BEGIN
		EXEC Subject.proc_AddAddress
			@SubjectCode = @GarageCode,
			@Address = N'Address of Dataset Garage';
	END

	DECLARE @VehicleCost decimal(18,5) = 5000.00000;

	IF NOT EXISTS
	(
		SELECT 1
		FROM Cash.tbPayment p
		WHERE p.SubjectCode = @GarageCode
		  AND p.CashCode = N'CC-MREPA'
		  AND p.PaymentReference = N'White Van'
		  AND CAST(p.PaidOn AS date) = @Year1LatePurchaseOn
	)
	BEGIN
		DECLARE @VehiclePayCode nvarchar(20) = NULL;
		EXEC Cash.proc_NextPaymentCode @PaymentCode = @VehiclePayCode OUTPUT;

		INSERT INTO Cash.tbPayment
		(
			PaymentCode,
			UserId,
			PaymentStatusCode,
			SubjectCode,
			AccountCode,
			CashCode,
			TaxCode,
			PaidOn,
			PaidInValue,
			PaidOutValue,
			PaymentReference
		)
		VALUES
		(
			@VehiclePayCode,
			@UserId,
			0,
			@GarageCode,
			@SettlementAccountCode,
			N'CC-MREPA',
			N'T1',
			@Year1LatePurchaseOn,
			0.00000,
			@VehicleCost,
			N'White Van'
		);
	END

	EXEC Cash.proc_PaymentPost;

	DECLARE
		@EquipAccountCode nvarchar(10),
		@EquipCashCode nvarchar(50);

	-- STD replaces the MIN EQUIPM/CC-DEPRC account with asset-specific
	-- depreciation accounts. A white van belongs to Motor Vehicles; retain the
	-- equipment account as the MIN fallback.
	SELECT TOP (1)
		@EquipAccountCode = AccountCode,
		@EquipCashCode = CashCode
	FROM Subject.tbAccount
	WHERE AccountTypeCode = 2
	  AND AccountClosed = 0
	  AND CashCode IN (N'CC-DEPMV', N'CC-DEPRC')
	ORDER BY CASE CashCode WHEN N'CC-DEPMV' THEN 0 ELSE 1 END, AccountCode;

	IF @EquipAccountCode IS NULL OR @EquipCashCode IS NULL
		THROW 51266, 'DatasetSyntheticMIS_Assets: no open motor-vehicle/equipment depreciation account exists for the selected template.', 1;

	IF NOT EXISTS
	(
		SELECT 1
		FROM Cash.tbPayment p
		WHERE p.SubjectCode = @BusinessRootCode
		  AND p.AccountCode = @EquipAccountCode
		  AND p.PaymentReference = N'White Van (Capitalised)'
		  AND CAST(p.PaidOn AS date) = @Year1LatePurchaseOn
	)
	BEGIN
		DECLARE @VehicleCapCode nvarchar(20) = NULL;
		EXEC Cash.proc_NextPaymentCode @PaymentCode = @VehicleCapCode OUTPUT;

		INSERT INTO Cash.tbPayment
		(
			PaymentCode,
			UserId,
			PaymentStatusCode,
			SubjectCode,
			AccountCode,
			CashCode,
			TaxCode,
			PaidOn,
			PaidInValue,
			PaidOutValue,
			PaymentReference
		)
		VALUES
		(
			@VehicleCapCode,
			@UserId,
			1,
			@BusinessRootCode,
			@EquipAccountCode,
			@EquipCashCode,
			N'N/A',
			@Year1LatePurchaseOn,
			@VehicleCost,
			0.00000,
			N'White Van (Capitalised)'
		);
	END

	DECLARE
		@PurchaseOn date = @Year1LatePurchaseOn,
		@Price decimal(18,5) = @VehicleCost,
		@WriteOffPercent decimal(9,6) = 0.20;

	IF @WriteOffPercent <= 0 OR @WriteOffPercent > 1
		THROW 51270, 'DatasetSyntheticMIS_Assets: invalid @WriteOffPercent.', 1;

	DECLARE @Count int = CONVERT(int, ROUND(1.0 / @WriteOffPercent, 0));

	IF @Count <= 0
		THROW 51271, 'DatasetSyntheticMIS_Assets: invalid depreciation Count.', 1;

	DECLARE @PurchaseYear smallint =
	(
		SELECT TOP (1) yp.YearNumber
		FROM App.tbYearPeriod yp
		WHERE CAST(yp.StartOn AS date) <= @PurchaseOn
		ORDER BY yp.StartOn DESC
	);

	IF @PurchaseYear IS NULL
		THROW 51272, 'DatasetSyntheticMIS_Assets: unable to resolve purchase year.', 1;

	DECLARE @WriteOffDate date =
	(
		SELECT CAST(EOMONTH(MAX(CAST(yp.StartOn AS date))) AS date)
		FROM App.tbYearPeriod yp
		WHERE yp.YearNumber = @PurchaseYear
	);

	IF @WriteOffDate IS NULL
		THROW 51273, 'DatasetSyntheticMIS_Assets: unable to resolve WriteOffDate.', 1;

	WHILE @Count > 0
	BEGIN
		DECLARE @StatusCode smallint =
		(
			SELECT TOP (1) yp.CashStatusCode
			FROM App.tbYearPeriod yp
			WHERE CAST(yp.StartOn AS date) <= @WriteOffDate
			ORDER BY yp.StartOn DESC
		);

		DECLARE @PaymentStatusCode smallint = CASE WHEN @StatusCode = 2 THEN 1 ELSE 0 END;

		IF NOT EXISTS
		(
			SELECT 1
			FROM Cash.tbPayment p
			WHERE p.SubjectCode = @BusinessRootCode
			  AND p.AccountCode = @EquipAccountCode
			  AND p.PaymentReference = N'Depreciation - White Van'
			  AND CAST(p.PaidOn AS date) = @WriteOffDate
		)
		BEGIN
			DECLARE @DepPaymentCode nvarchar(20) = NULL;
			EXEC Cash.proc_NextPaymentCode @PaymentCode = @DepPaymentCode OUTPUT;

			INSERT INTO Cash.tbPayment
			(
				PaymentCode,
				UserId,
				PaymentStatusCode,
				SubjectCode,
				AccountCode,
				CashCode,
				TaxCode,
				PaidOn,
				PaidInValue,
				PaidOutValue,
				PaymentReference
			)
			VALUES
			(
				@DepPaymentCode,
				@UserId,
				@PaymentStatusCode,
				@BusinessRootCode,
				@EquipAccountCode,
				@EquipCashCode,
				N'N/A',
				@WriteOffDate,
				0.00000,
				CAST(ROUND(@Price * @WriteOffPercent, 2) AS decimal(18,5)),
				N'Depreciation - White Van'
			);
		END

		SET @WriteOffDate = DATEADD(year, 1, @WriteOffDate);
		SET @Count -= 1;
	END
GO

PRINT N'Altering Procedure [App].[proc_Template_CO_MICRO_CUR_MIN_2026]...';


GO
ALTER PROCEDURE App.proc_Template_CO_MICRO_CUR_MIN_2026
(
    @CategoryVersionId NVARCHAR(10),
    @FinancialMonth SMALLINT = 4,
    @GovAccountName NVARCHAR(255),
    @BankName NVARCHAR(255) = NULL,
    @BankAddress NVARCHAR(MAX) = NULL,
    @DummyAccount NVARCHAR(50),
    @CurrentAccount NVARCHAR(50) = NULL,
    @CA_SortCode NVARCHAR(10) = NULL,
    @CA_AccountNumber NVARCHAR(20) = NULL,
    @ReserveAccount NVARCHAR(50) = NULL,
    @RA_SortCode NVARCHAR(10) = NULL,
    @RA_AccountNumber NVARCHAR(20) = NULL,
    @IsVATRegistered BIT = 1      -- Micro entity default to VAT Registered
)
AS
    SET NOCOUNT, XACT_ABORT ON;

    BEGIN TRY

        BEGIN TRAN MicroMinTemplate;

        EXEC [App].[proc_Template_CO_MICRO_CUR_2026]
             @CategoryVersionId = @CategoryVersionId,
             @FinancialMonth   = @FinancialMonth,
             @GovAccountName   = @GovAccountName,
             @BankName         = @BankName,
             @BankAddress      = @BankAddress,
             @DummyAccount     = @DummyAccount,
             @CurrentAccount   = @CurrentAccount,
             @CA_SortCode      = @CA_SortCode,
             @CA_AccountNumber = @CA_AccountNumber,
             @ReserveAccount   = @ReserveAccount,
             @RA_SortCode      = @RA_SortCode,
             @RA_AccountNumber = @RA_AccountNumber;

        -- MIN-specific deltas

        ----------------------------------------------------------------
        -- 1. EXPRESSION CATEGORIES (CategoryTypeCode = 2)
        ----------------------------------------------------------------
        INSERT INTO Cash.tbCategory
            (VersionId, CategoryCode, Category, CategoryTypeCode, CashPolarityCode, CashTypeCode, DisplayOrder, IsEnabled)
        VALUES
            (@CategoryVersionId, 'CE-CO', 'Cash Operating Surplus %', 2, 2, 0, 10, 1);

        INSERT INTO Cash.tbCategoryExp
            (CategoryCode, Expression, Format, SyntaxTypeCode, IsError, ErrorMessage)
        VALUES
            ('CE-CO', 'IF([CA-SALES]=0,0,(([CA-SALES]+[CT-OTHRIN]-[CA-DIRECT]-[CA-WAGES]-[CA-ADMIN])/[CA-SALES]))', 'Pct0', 0, 0, NULL);

        ----------------------------------------------------------------
        -- 2. VAT handling for non‑registered businesses
        ----------------------------------------------------------------
        IF @IsVATRegistered = 0
            EXEC App.proc_Template_DisableVAT @CategoryVersionId = @CategoryVersionId;

        ----------------------------------------------------------------
        -- 3. Enable Asset Accounts
        ----------------------------------------------------------------
        UPDATE Subject.tbAccount
        SET AccountClosed = 0
        WHERE AccountClosed = 1;

        ----------------------------------------------------------------
        -- 4. Company statutory projection (separate from accounting bootstrap)
        ----------------------------------------------------------------
        EXEC App.proc_Template_CO_MICRO_CUR_TAX_2026;

        EXEC Cash.proc_TaxTagMapValidate @TaxSourceCode = 'UK-CO-ACCTS-2026';
        EXEC Cash.proc_TaxTagMapValidate @TaxSourceCode = 'UK-CO-CT-2026';
        EXEC Cash.proc_TaxTagMapValidate @TaxSourceCode = 'UK-CO-CT600-2026';

        COMMIT TRAN MicroMinTemplate;

    END TRY
    BEGIN CATCH
        EXEC App.proc_ErrorLog;
    END CATCH;
GO

PRINT N'Altering Procedure [Project].[proc_Pay]...';


GO
ALTER PROCEDURE Project.proc_Pay (@ProjectCode NVARCHAR(20), @Post BIT = 0,	@PaymentCode nvarchar(20) NULL OUTPUT)
AS
	SET NOCOUNT, XACT_ABORT ON;

	BEGIN TRY
		
		DECLARE 
			@InvoiceTypeCode smallint
			, @InvoiceNumber NVARCHAR(20)
			, @InvoicedOn DATETIME = CURRENT_TIMESTAMP

		SELECT @InvoiceTypeCode = CASE CashPolarityCode WHEN 0 THEN 2 ELSE 0 END, @InvoicedOn = Project.tbProject.PaymentOn
		FROM  Project.tbProject INNER JOIN
				Cash.vwCodeActive ON Project.tbProject.CashCode = Cash.vwCodeActive.CashCode INNER JOIN
				Cash.vwCategoryActive ON Cash.vwCodeActive.CategoryCode = Cash.vwCategoryActive.CategoryCode AND Cash.vwCodeActive.CategoryCode = Cash.vwCategoryActive.CategoryCode AND 
				Cash.vwCodeActive.CategoryCode = Cash.vwCategoryActive.CategoryCode
		WHERE Project.tbProject.ProjectCode = @ProjectCode
		
		EXEC Invoice.proc_Raise @ProjectCode = @ProjectCode, @InvoiceTypeCode = @InvoiceTypeCode, @InvoicedOn = @InvoicedOn, @InvoiceNumber = @InvoiceNumber OUTPUT
		EXEC Invoice.proc_Accept @InvoiceNumber
		EXEC Invoice.proc_Pay @InvoiceNumber = @InvoiceNumber, @PaidOn = @InvoicedOn, @Post = @Post, @PaymentCode = @PaymentCode OUTPUT

	END TRY
	BEGIN CATCH
		EXEC App.proc_ErrorLog;
	END CATCH
GO

PRINT N'Altering Procedure [App].[proc_DatasetSyntheticMIS_Expenses]...';


GO
ALTER PROCEDURE App.proc_DatasetSyntheticMIS_Expenses
(
	@IsCompany bit,
	@IsVatRegistered bit
)
AS
	SET NOCOUNT, XACT_ABORT ON;

	IF OBJECT_ID('tempdb..#DatasetCodes') IS NULL
		THROW 51215, 'DatasetSyntheticMIS_ProjectPay: missing temp table #DatasetCodes. Ensure ProjectTran ran.', 1;

	DECLARE @LastClosedStartOn date =
		TRY_CONVERT(date, (SELECT CodeValue FROM #DatasetCodes WHERE CodeType = N'LINK' AND CodeName = N'LastClosedStartOn'));

	IF @LastClosedStartOn IS NULL
		THROW 51241, 'DatasetSyntheticMIS_Expenses: missing LINK/LastClosedStartOn.', 1;

	-----------------------------------------------------------------
	-- Ensure Category + CashCode for Employee Expenses
	-----------------------------------------------------------------

	IF NOT EXISTS (SELECT 1 FROM Cash.tbCode WHERE CashCode = N'CC-EXPENSE')
	BEGIN
		DECLARE @CategoryVersionId NVARCHAR(10) = (SELECT CategoryVersionId FROM App.tbOptions);

		EXEC Cash.proc_CodeAdd
			@VersionId = @CategoryVersionId,
			@CashCode = N'CC-EXPENSE',
			@CashDescription = N'Employee Expenses',
			@CategoryCode = N'CA-ADMIN',
			@TaxCode = N'T0',
			@IsEnabled = 1;
	END

	IF NOT EXISTS (SELECT 1 FROM Object.tbObject WHERE ObjectCode = 'EXPENSE')
	BEGIN
		INSERT INTO Object.tbObject
		(
			ObjectCode,
			ProjectStatusCode,
			UnitOfMeasure,
			CashCode,
			Printed,
			RegisterName,
			ObjectDescription,
			UnitCharge
		)
		VALUES
		(
			'EXPENSE',
			1,
			'each',
			'CC-EXPENSE',
			1,
			'Purchase Order',
			'Employee Expense Claim',
			0
		);
	END

	-----------------------------------------------------------------
	-- Resolve subjects
	-----------------------------------------------------------------
	DECLARE
		@L2_UserId nvarchar(10) = (SELECT TOP (1) UserId FROM Usr.vwCredentials),
		@L2_EmployeeSubjectCode nvarchar(50) = (SELECT CodeValue FROM #DatasetCodes WHERE CodeType = N'SUBJECT' AND CodeName = N'Employee');

	IF @L2_EmployeeSubjectCode IS NULL
		THROW 51100, 'SyntheticDataset Layer2: missing SUBJECT/Employee in #DatasetCodes.', 1;

	-----------------------------------------------------------------
	-- Employee Expenses: container project + monthly claim child projects
	-----------------------------------------------------------------
	DECLARE
		@L2_ClaimsContainerProjectCode nvarchar(20) = NULL,
		@L2_ClaimsChildProjectCode nvarchar(20) = NULL,
		@L2_ClaimPaymentCode nvarchar(20) = NULL,
		@L2_ClaimsMonthEnd date,
		@L2_ClaimsMonthIndex int,
		@ObjectCode nvarchar(50);

	-- Container
	SET @ObjectCode = 'PROJECT';
	EXEC Project.proc_NextCode @ObjectCode = @ObjectCode, @ProjectCode = @L2_ClaimsContainerProjectCode OUTPUT;

	IF @L2_ClaimsContainerProjectCode IS NULL
		THROW 51110, 'SyntheticDataset Layer2: Project.proc_NextCode returned NULL.', 1;

	IF NOT EXISTS (SELECT 1 FROM Project.tbProject WHERE ProjectCode = @L2_ClaimsContainerProjectCode)
	BEGIN
		INSERT INTO Project.tbProject
		(
			ProjectCode,
			UserId,
			SubjectCode,
			ProjectTitle,
			ObjectCode,
			ProjectStatusCode,
			ActionById,
			ActionOn,
			Quantity,
			CashCode,
			TaxCode,
			UnitCharge,
			TotalCharge
		)
		VALUES
		(
			@L2_ClaimsContainerProjectCode,
			@L2_UserId,
			@L2_EmployeeSubjectCode,
			N'John Smith''s Expense Claims',
			@ObjectCode,
			0,
			@L2_UserId,
			EOMONTH(@LastClosedStartOn),
			0,
			NULL,
			NULL,
			0,
			0
		);
	END

	-- One claim per closed month
	DECLARE curClaims CURSOR LOCAL FAST_FORWARD FOR
		SELECT MonthEndOn, MonthIndex
		FROM App.fnDatasetMonths(@LastClosedStartOn)
		ORDER BY MonthStartOn
		OPTION (MAXRECURSION 0);

	OPEN curClaims;
	FETCH NEXT FROM curClaims INTO @L2_ClaimsMonthEnd, @L2_ClaimsMonthIndex;

	WHILE @@FETCH_STATUS = 0
	BEGIN
		DECLARE @ClaimCashCode nvarchar(50) = N'CC-EXPENSE';

		-- Exercise the richer standard-company accounting classifications when
		-- they exist. MIN and non-company profiles retain the generic fallback.
		IF @IsCompany = 1
		BEGIN
			DECLARE @StdClaimCandidate nvarchar(50) =
				CASE (@L2_ClaimsMonthIndex % 4)
					WHEN 0 THEN N'CC-TRAV'
					WHEN 1 THEN N'CC-PHONE'
					WHEN 2 THEN N'CC-PROF'
					ELSE N'CC-REPA'
				END;

			IF EXISTS (SELECT 1 FROM Cash.tbCode WHERE CashCode = @StdClaimCandidate AND IsEnabled = 1)
				SET @ClaimCashCode = @StdClaimCandidate;
		END

		SET @ObjectCode = 'EXPENSE';
		EXEC Project.proc_NextCode @ObjectCode = @ObjectCode, @ProjectCode = @L2_ClaimsChildProjectCode OUTPUT;

		IF @L2_ClaimsChildProjectCode IS NULL
			THROW 51111, 'SyntheticDataset Layer2: Project.proc_NextCode returned NULL for claim child project.', 1;

		INSERT INTO Project.tbProject
		(
			ProjectCode,
			UserId,
			SubjectCode,
			ProjectTitle,
			ObjectCode,
			ProjectStatusCode,
			ActionById,
			ActionOn,
			Quantity,
			CashCode,
			TaxCode,
			UnitCharge,
			TotalCharge
		)
		VALUES
		(
			@L2_ClaimsChildProjectCode,
			@L2_UserId,
			@L2_EmployeeSubjectCode,
			CASE @ClaimCashCode
				WHEN N'CC-TRAV' THEN N'Travel and subsistence'
				WHEN N'CC-PHONE' THEN N'Telephone and internet'
				WHEN N'CC-PROF' THEN N'Professional fees'
				WHEN N'CC-REPA' THEN N'Repairs and maintenance'
				ELSE CASE WHEN (@L2_ClaimsMonthIndex % 2) = 0 THEN N'Travel Costs' ELSE N'Entertainment' END
			END,
			@ObjectCode,
			0,
			@L2_UserId,
			@L2_ClaimsMonthEnd,
			1,
			@ClaimCashCode,
			N'T0',
			CAST(25 + (ABS(CHECKSUM(CONCAT(N'DS:L2:CLAIM:', @L2_ClaimsMonthIndex))) % 175) AS decimal(18,7)),
			0
		);

		EXEC Project.proc_AssignToParent
			@ChildProjectCode = @L2_ClaimsChildProjectCode,
			@ParentProjectCode = @L2_ClaimsContainerProjectCode;

		SET @L2_ClaimPaymentCode = NULL;
		EXEC Project.proc_Pay
			@ProjectCode = @L2_ClaimsChildProjectCode,
			@Post = 1,
			@PaymentCode = @L2_ClaimPaymentCode OUTPUT;

		FETCH NEXT FROM curClaims INTO @L2_ClaimsMonthEnd, @L2_ClaimsMonthIndex;
	END

	CLOSE curClaims;
	DEALLOCATE curClaims;
GO

PRINT N'Altering Procedure [App].[proc_Template_ST_SOLE_CUR_MIN_2026]...';


GO
ALTER PROCEDURE App.proc_Template_ST_SOLE_CUR_MIN_2026
(
    @CategoryVersionId NVARCHAR(10),
    @FinancialMonth      SMALLINT      = 4,
    @GovAccountName      NVARCHAR(255),
    @BankName            NVARCHAR(255) = NULL,
    @BankAddress         NVARCHAR(MAX) = NULL,
    @DummyAccount        NVARCHAR(50),
    @CurrentAccount      NVARCHAR(50)  = NULL,
    @CA_SortCode         NVARCHAR(10)  = NULL,
    @CA_AccountNumber    NVARCHAR(20)  = NULL,
    @ReserveAccount      NVARCHAR(50)  = NULL,
    @RA_SortCode         NVARCHAR(10)  = NULL,
    @RA_AccountNumber    NVARCHAR(20)  = NULL,
    @IsVATRegistered     BIT           = 0     -- Sole traders default to non‑VAT
)
AS
    SET NOCOUNT, XACT_ABORT ON;
BEGIN TRY

    BEGIN TRAN SoleTraderTemplate;

    ----------------------------------------------------------------
    -- 1. Base template: Minimal Micro Business (current schema)
    ----------------------------------------------------------------
    EXEC App.proc_Template_BASE_MIN_2026
        @CategoryVersionId = @CategoryVersionId,
        @FinancialMonth   = @FinancialMonth,
        @GovAccountName   = @GovAccountName,
        @BankName         = @BankName,
        @BankAddress      = @BankAddress,
        @DummyAccount     = @DummyAccount,
        @CurrentAccount   = @CurrentAccount,
        @CA_SortCode      = @CA_SortCode,
        @CA_AccountNumber = @CA_AccountNumber,
        @ReserveAccount   = @ReserveAccount,
        @RA_SortCode      = @RA_SortCode,
        @RA_AccountNumber = @RA_AccountNumber;

    ----------------------------------------------------------------
    -- 2. Disable company-only categories/codes (do NOT delete)
    ----------------------------------------------------------------
    UPDATE Cash.tbCategory
    SET IsEnabled = 0
    WHERE VersionId = @CategoryVersionId
      AND CategoryCode IN ('CA-DIVID');

    UPDATE Cash.tbCode
    SET IsEnabled = 0
    WHERE CashCode IN ('CC-DEPRC', 'CC-DEPRJ', 'CC-SHCAP', 'CC-DIVID');

    UPDATE Cash.tbCode
    SET IsEnabled = 1
    WHERE CashCode = 'CC-EMPNI';

    ----------------------------------------------------------------
    -- 3. Cumulative reportable-expense accounting roll-up
    ----------------------------------------------------------------
    IF NOT EXISTS (SELECT 1 FROM Cash.tbCategory WHERE VersionId = @CategoryVersionId AND CategoryCode = 'CT-CUMEXP')
        INSERT INTO Cash.tbCategory
            (VersionId, CategoryCode, Category, CategoryTypeCode, CashPolarityCode, CashTypeCode, DisplayOrder, IsEnabled)
        VALUES
            (@CategoryVersionId, 'CT-CUMEXP', 'Cumulative Reportable Expenses', 1, 2, 0, 55, 1);

    INSERT INTO Cash.tbCategoryTotal (VersionId, ParentCode, ChildCode)
    SELECT @CategoryVersionId, 'CT-CUMEXP', v.ChildCode
    FROM (VALUES ('CT-CSTSAL'), ('CT-STAFFC'), ('CT-OVERHD')) v(ChildCode)
    WHERE NOT EXISTS
    (
        SELECT 1 FROM Cash.tbCategoryTotal ct
        WHERE ct.VersionId = @CategoryVersionId
          AND ct.ParentCode = 'CT-CUMEXP' AND ct.ChildCode = v.ChildCode
    );

    UPDATE Subject.tbAccount
    SET AccountClosed = 1
    WHERE AccountCode IN ('CALUP');

    ----------------------------------------------------------------
    -- 4. Business Tax settings for Sole Traders
    ----------------------------------------------------------------
    UPDATE Cash.tbTaxType
    SET IsEnabled = 0
    WHERE TaxTypeCode = 0;

    UPDATE Cash.tbTaxType
    SET IsEnabled = 1
    WHERE TaxTypeCode IN (4, 5);

    ----------------------------------------------------------------
    -- 5. Sole trader owner movements (single CASH CODE, polarity driven)
    ----------------------------------------------------------------

    -- Ensure the MONEY nominal category exists to hold the owner cash code.
    IF NOT EXISTS (SELECT 1 FROM Cash.tbCategory WHERE VersionId = @CategoryVersionId AND CategoryCode = 'CA-OWNER')
    BEGIN
        INSERT INTO Cash.tbCategory
            (VersionId, CategoryCode, Category, CategoryTypeCode, CashPolarityCode, CashTypeCode, DisplayOrder, IsEnabled)
        VALUES
            (@CategoryVersionId, 'CA-OWNER', 'Owner Capital Account', 0, 2, 2, 895, 1);
    END;

    -- Single owner capital asset cash code (polarity indicates introduced vs drawings).
    IF EXISTS (SELECT 1 FROM Cash.tbCode WHERE CashCode = 'CC-OWNCAP')
    BEGIN
        UPDATE Cash.tbCode
        SET CategoryCode = 'CA-OWNER',
            TaxCode = 'N/A',
            IsEnabled = 1
        WHERE CashCode = 'CC-OWNCAP';

        UPDATE Cash.tbCategoryCodeMap
        SET CategoryCode = 'CA-OWNER'
        WHERE VersionId = @CategoryVersionId
          AND CashCode = 'CC-OWNCAP';
    END
    ELSE
    BEGIN
        INSERT INTO Cash.tbCode
            (CashCode, CashDescription, CategoryCode, TaxCode, IsEnabled)
        VALUES
            ('CC-OWNCAP', 'Owner Capital', 'CA-OWNER', 'N/A', 1);

        INSERT INTO Cash.tbCategoryCodeMap (VersionId, CashCode, CategoryCode)
        VALUES (@CategoryVersionId, 'CC-OWNCAP', 'CA-OWNER');
    END;

    ----------------------------------------------------------------
    -- 6. Dedicated cash account (ASSET-type) for owner capital balance
    ----------------------------------------------------------------
    DECLARE
        @SubjectCode    NVARCHAR(50) = (SELECT SubjectCode FROM App.tbOptions),
        @OwnerAccount   NVARCHAR(50) = N'OWNER CAPITAL ACCOUNT',
        @OwnerAccountCode NVARCHAR(10);

    EXEC Subject.proc_DefaultAccountCode
         @AccountName = @OwnerAccount,
         @AccountCode = @OwnerAccountCode OUTPUT;

    IF NOT EXISTS (SELECT 1 FROM Subject.tbAccount WHERE AccountCode = @OwnerAccountCode)
    BEGIN
        INSERT INTO Subject.tbAccount
            (AccountCode, SubjectCode, AccountName, AccountTypeCode, BalanceConstraintCode, LiquidityLevel, CashCode, AccountClosed)
        VALUES
            (@OwnerAccountCode, @SubjectCode, @OwnerAccount, 2, 2, 45, 'CC-OWNCAP', 0);
    END
    ELSE
    BEGIN
        UPDATE Subject.tbAccount
        SET CashCode = 'CC-OWNCAP'
        WHERE AccountCode = @OwnerAccountCode;
    END;

    ----------------------------------------------------------------
    -- 7. VAT handling for non-registered businesses
    ----------------------------------------------------------------
    IF @IsVATRegistered = 0
        EXEC App.proc_Template_DisableVAT @CategoryVersionId = @CategoryVersionId;

    ----------------------------------------------------------------
    -- 8. Tax year alignment: financial year starts on April 6
    ----------------------------------------------------------------
    WITH year_start AS
    (
        SELECT YearNumber, MIN(StartOn) StartOn
        FROM App.tbYearPeriod
        GROUP BY YearNumber
    )
    UPDATE yp
    SET StartOn = DATEADD(DAY, 5, yp.StartOn)
    FROM year_start ys
        JOIN App.tbYearPeriod yp
            ON ys.YearNumber = yp.YearNumber
           AND ys.StartOn = yp.StartOn
           AND DATEPART(DAY, yp.StartOn) = 1;


    COMMIT TRAN SoleTraderTemplate;

END TRY
BEGIN CATCH
    EXEC App.proc_ErrorLog;
END CATCH;
GO

PRINT N'Altering Procedure [App].[proc_Template_CO_MICRO_CUR_STD_2026]...';


GO
ALTER PROCEDURE App.proc_Template_CO_MICRO_CUR_STD_2026
(
    @CategoryVersionId NVARCHAR(10),
    @FinancialMonth SMALLINT = 4,
    @GovAccountName NVARCHAR(255),
    @BankName NVARCHAR(255) = NULL,
    @BankAddress NVARCHAR(MAX) = NULL,
    @DummyAccount NVARCHAR(50),
    @CurrentAccount NVARCHAR(50) = NULL,
    @CA_SortCode NVARCHAR(10) = NULL,
    @CA_AccountNumber NVARCHAR(20) = NULL,
    @ReserveAccount NVARCHAR(50) = NULL,
    @RA_SortCode NVARCHAR(10) = NULL,
    @RA_AccountNumber NVARCHAR(20) = NULL,
    @IsVATRegistered BIT = 1      -- Micro entity default to VAT Registered
)
AS
SET NOCOUNT, XACT_ABORT ON;

BEGIN TRY

    BEGIN TRAN MicroStdTemplate;

    ----------------------------------------------------------------
    -- 1. CALL SHARED MICRO CORE
    ----------------------------------------------------------------
    EXEC [App].[proc_Template_CO_MICRO_CUR_2026]
         @CategoryVersionId = @CategoryVersionId,
         @FinancialMonth   = @FinancialMonth,
         @GovAccountName   = @GovAccountName,
         @BankName         = @BankName,
         @BankAddress      = @BankAddress,
         @DummyAccount     = @DummyAccount,
         @CurrentAccount   = @CurrentAccount,
         @CA_SortCode      = @CA_SortCode,
         @CA_AccountNumber = @CA_AccountNumber,
         @ReserveAccount   = @ReserveAccount,
         @RA_SortCode      = @RA_SortCode,
         @RA_AccountNumber = @RA_AccountNumber;

    ----------------------------------------------------------------
    -- 2. STANDARD MICRO CATEGORY TREE (ADDITIVE)
    ----------------------------------------------------------------
    INSERT INTO Cash.tbCategory
        (VersionId, CategoryCode, Category, CategoryTypeCode, CashPolarityCode, CashTypeCode, DisplayOrder, IsEnabled)
    VALUES
        (@CategoryVersionId, 'CA-BUILD', 'Building', 0, 0, 0, 411, 1);

    INSERT INTO Cash.tbCategoryTotal (VersionId, ParentCode, ChildCode)
    VALUES
        (@CategoryVersionId, 'CT-OVERHD', 'CA-BUILD');

    ----------------------------------------------------------------
    -- 3. REPLACE BASE DEPRECIATION ACCOUNTING MODEL
    --    Base creates 'EQUIPMENT' account with CashCode = 'CC-DEPRC'.
    ----------------------------------------------------------------
    DELETE a
    FROM Subject.tbAccount a
    WHERE a.AccountName = 'EQUIPMENT'
      AND a.CashCode = 'CC-DEPRC';

    ----------------------------------------------------------------
    -- 4. STANDARD MICRO CASH CODES (ADDITIVE)
    ----------------------------------------------------------------
    DECLARE @CategoryCodeMap TABLE
    (
        CashCode NVARCHAR(50) NOT NULL PRIMARY KEY,
        CategoryCode NVARCHAR(10) NOT NULL
    );

    INSERT INTO Cash.tbCode
        (CashCode, CashDescription, CategoryCode, TaxCode, IsEnabled)
    OUTPUT inserted.CashCode, inserted.CategoryCode
        INTO @CategoryCodeMap (CashCode, CategoryCode)
    VALUES
        -- Sales splits -> CA-SALES
        ('CC-SALAB', 'Sales – Labour',        'CA-SALES',  'T1', 1),
        ('CC-SAMAT', 'Sales – Materials',     'CA-SALES',  'T1', 1),

        -- Direct cost splits -> CA-DIRECT
        ('CC-MAT',   'Materials',             'CA-DIRECT', 'T1', 1),
        ('CC-SUB',   'Subcontractors',        'CA-DIRECT', 'T1', 1),
        ('CC-FUEL',  'Fuel & Oil',            'CA-DIRECT', 'T1', 1),
        ('CC-MTRAV', 'Motor Travel',          'CA-DIRECT', 'T1', 1),

        -- Staff collapse: CC-WAGE -> CC-SALRY -> CA-WAGES
        ('CC-SALRY', 'Salary',                'CA-WAGES',  'N/A', 1),

        -- Building: CC-RENT, CC-LHEAT, CC-REPA -> CA-BUILD
        ('CC-RENT',  'Rent & Rates',          'CA-BUILD',  'T1', 1),
        ('CC-LHEAT', 'Light, Heat & Power',   'CA-BUILD',  'T1', 1),
        ('CC-REPA',  'Repairs & Maintenance', 'CA-BUILD',  'T1', 1),

        -- Admin collapse -> CA-ADMIN
        ('CC-INS',   'Insurance',             'CA-ADMIN',  'T1', 1),
        ('CC-PHONE', 'Telephone & Internet',  'CA-ADMIN',  'T1', 1),
        ('CC-ADVT',  'Advertising',           'CA-ADMIN',  'T1', 1),
        ('CC-TRAV',  'Travel & Subsistence',  'CA-ADMIN',  'T1', 1),
        ('CC-PROF',  'Professional Fees',     'CA-ADMIN',  'T1', 1),
        ('CC-BANKC', 'Bank Charges',          'CA-ADMIN',  'T1', 1),

        -- Depreciation (STD replacement for CC-DEPRC)
        ('CC-DEPPL', 'Depreciation – Plant & Tools',  'CA-DEPREC', 'N/A', 1),
        ('CC-DEPMV', 'Depreciation – Motor Vehicles', 'CA-DEPREC', 'N/A', 1),
        ('CC-DEPFX', 'Depreciation – Fixtures',       'CA-DEPREC', 'N/A', 1);

    INSERT INTO Cash.tbCategoryCodeMap (VersionId, CashCode, CategoryCode)
    SELECT @CategoryVersionId, CashCode, CategoryCode
    FROM @CategoryCodeMap;

    ----------------------------------------------------------------
    -- 4b. Create capital accounts for the STD depreciation model
    ----------------------------------------------------------------
    DECLARE
    @DepAccount NVARCHAR(50)
    , @SubjectCode  NVARCHAR(50) = (SELECT TOP 1 SubjectCode FROM App.tbOptions)
    , @AccountCode  NVARCHAR(10);

    SET @DepAccount = 'PLANT & TOOLS';
    EXEC Subject.proc_DefaultAccountCode
         @AccountName = @DepAccount,
         @AccountCode = @AccountCode OUTPUT;

    INSERT INTO Subject.tbAccount
        (AccountCode, SubjectCode, AccountName, AccountTypeCode, BalanceConstraintCode, LiquidityLevel, CashCode, AccountClosed)
    VALUES
        (@AccountCode, @SubjectCode, @DepAccount, 2, 1, 30, 'CC-DEPPL', 0);

    SET @DepAccount = 'MOTOR VEHICLES';
    EXEC Subject.proc_DefaultAccountCode
         @AccountName = @DepAccount,
         @AccountCode = @AccountCode OUTPUT;

    INSERT INTO Subject.tbAccount
        (AccountCode, SubjectCode, AccountName, AccountTypeCode, BalanceConstraintCode, LiquidityLevel, CashCode, AccountClosed)
    VALUES
        (@AccountCode, @SubjectCode, @DepAccount, 2, 1, 31, 'CC-DEPMV', 0);

    SET @DepAccount = 'FIXTURES';
    EXEC Subject.proc_DefaultAccountCode
         @AccountName = @DepAccount,
         @AccountCode = @AccountCode OUTPUT;

    INSERT INTO Subject.tbAccount
        (AccountCode, SubjectCode, AccountName, AccountTypeCode, BalanceConstraintCode, LiquidityLevel, CashCode, AccountClosed)
    VALUES
        (@AccountCode, @SubjectCode, @DepAccount, 2, 1, 32, 'CC-DEPFX', 0);

    ----------------------------------------------------------------
    -- 5. DELETE CASH CODE INHERITED FROM BASE TEMPLATE (now unused)
    ----------------------------------------------------------------
    DELETE FROM Cash.tbCategoryCodeMap
    WHERE VersionId = @CategoryVersionId
      AND CashCode = 'CC-DEPRC';

    DELETE FROM Cash.tbCode
    WHERE CashCode = 'CC-DEPRC';

    -- Add STD expression suite
    EXEC App.proc_Template_CO_MICRO_CUR_STD_EXP_2026
        @CategoryVersionId = @CategoryVersionId;

    ----------------------------------------------------------------
    -- 7. VAT handling for non‑registered businesses
    ----------------------------------------------------------------
    IF @IsVATRegistered = 0
        EXEC App.proc_Template_DisableVAT @CategoryVersionId = @CategoryVersionId;

    ----------------------------------------------------------------
    -- 8. Compose and validate the company statutory projection
    ----------------------------------------------------------------
    EXEC App.proc_Template_CO_MICRO_CUR_TAX_2026;

    EXEC Cash.proc_TaxTagMapValidate @TaxSourceCode = 'UK-CO-ACCTS-2026';
    EXEC Cash.proc_TaxTagMapValidate @TaxSourceCode = 'UK-CO-CT-2026';
    EXEC Cash.proc_TaxTagMapValidate @TaxSourceCode = 'UK-CO-CT600-2026';

    COMMIT TRAN MicroStdTemplate;

END TRY
BEGIN CATCH
    EXEC App.proc_ErrorLog;
END CATCH;
GO

PRINT N'Altering Procedure [App].[proc_DatasetSyntheticMIS]...';


GO
ALTER PROCEDURE App.proc_DatasetSyntheticMIS
(
	@IsCompany bit = 1,
	@IsVatRegistered bit = NULL,

	@MisOrdersPerMonth int = 2,
	@MonthsForward int = 3,    

    -- ratios
    @PriceRatio decimal(18,7) = 1.0000000,
    @QuantityRatio decimal(18,7) = 1.0000000,
	@FloatRatio decimal(18,7) = 0.25,

	-- execution switches
	@EnableProjects bit = 1,
	@EnableInvoices bit = 1,
	@EnableProjectPayments bit = 1,
	@EnablePayables bit = 1,
	@EnableMiscPayments bit = 1,
	@EnableWages bit = 1,
	@EnableExpenses bit = 1,
    @EnableAssets bit = 1,
    @EnableTax bit = 1,
	@EnableTransfers bit = 1,
    @EnableOpeningBalance bit = 0,

	@UseStdCompanyTemplate bit = 0,
	@CompletedYearCount smallint = 2,
	@FinancialMonth smallint = NULL,

	-- Test-only temporal anchor for disposable synthetic nodes. NULL preserves ordinary behaviour.
	@AsOfDate date = NULL
)
AS
	SET NOCOUNT, XACT_ABORT ON;

	BEGIN TRY
		BEGIN TRAN;

		DECLARE @TemplateCode nvarchar(10) =
			CASE
				WHEN @IsCompany = 1 AND @UseStdCompanyTemplate <> 0
					THEN N'COSTD26'
				WHEN @IsCompany = 1
					THEN N'COMIN26'
				WHEN @UseStdCompanyTemplate <> 0
					THEN N'STSTD26'
				ELSE N'STMIN26'
			END;

		-- If caller didn't specify VAT setting, inherit from template default.
		IF @IsVatRegistered IS NULL
		BEGIN
			SELECT @IsVatRegistered = IsVatRegistered
			FROM App.tbTemplate
			WHERE TemplateCode = @TemplateCode;
		END

		---------------------------------------------------------------------
		-- Shared lookup table for the whole run (visible to nested procs)
		---------------------------------------------------------------------
		IF OBJECT_ID('tempdb..#DatasetCodes') IS NOT NULL
			DROP TABLE #DatasetCodes;

		CREATE TABLE #DatasetCodes
		(
			CodeType nvarchar(20) NOT NULL,        -- 'SUBJECT' | 'OBJECT' | 'LINK' | 'PROJECT' etc
			CodeName nvarchar(100) NOT NULL,       -- logical name (unique within CodeType)
			CodeValue nvarchar(50) NOT NULL,       -- SubjectCode (10) or ObjectCode (50) or ProjectCode (20) etc
			RelatedName nvarchar(100) NULL,
			Notes nvarchar(255) NULL,
			PRIMARY KEY (CodeType, CodeName)
		);

		---------------------------------------------------------------------
		-- 1) Bootstrap (ALWAYS resets node inside the proc)
		---------------------------------------------------------------------
        EXEC App.proc_DatasetSyntheticMIS_Bootstrap
	        @TemplateCode = @TemplateCode,
	        @IsVatRegistered = @IsVatRegistered,
            @EnableOpeningBalance = @EnableOpeningBalance,
			@CompletedYearCount = @CompletedYearCount,
			@FinancialMonth = @FinancialMonth,
			@AsOfDate = @AsOfDate;

        EXEC App.proc_DatasetSyntheticMIS_StatutoryProfile @AsOfDate = @AsOfDate;

		---------------------------------------------------------------------
		-- 2) Project side
		---------------------------------------------------------------------
		IF @EnableProjects <> 0
		BEGIN
			EXEC App.proc_DatasetSyntheticMIS_ProjectInit
				@IsCompany = @IsCompany,
				@IsVatRegistered = @IsVatRegistered,
            @EnableOpeningBalance = @EnableOpeningBalance;

			EXEC App.proc_DatasetSyntheticMIS_ProjectTemplates
				@IsCompany = @IsCompany,
				@IsVatRegistered = @IsVatRegistered,
                @PriceRatio = @PriceRatio,
                @QuantityRatio = @QuantityRatio;

			EXEC App.proc_DatasetSyntheticMIS_ProjectTran
				@IsCompany = @IsCompany,
				@IsVatRegistered = @IsVatRegistered,
				@MisOrdersPerMonth = @MisOrdersPerMonth,
				@MonthsForward = @MonthsForward;

		    IF @EnableInvoices <> 0
		    BEGIN
			    EXEC App.proc_DatasetSyntheticMIS_ProjectInvoice
				    @IsCompany = @IsCompany,
				    @IsVatRegistered = @IsVatRegistered;
		    END

		    IF @EnableProjectPayments <> 0 
		    BEGIN
			    EXEC App.proc_DatasetSyntheticMIS_ProjectPay
				    @IsCompany = @IsCompany,
				    @IsVatRegistered = @IsVatRegistered;
		    END
		END

		---------------------------------------------------------------------
		-- 3a) Payables side (Accounts mode)
		---------------------------------------------------------------------
		IF @EnablePayables <> 0
		BEGIN
			EXEC App.proc_DatasetSyntheticMIS_PayInit
				@IsCompany = @IsCompany,
				@IsVatRegistered = @IsVatRegistered;

		    IF @EnableMiscPayments <> 0
		    BEGIN
			    EXEC App.proc_DatasetSyntheticMIS_PayMisc
				    @IsCompany = @IsCompany,
				    @IsVatRegistered = @IsVatRegistered;
		    END

		    -- company-only behavior (typical): wages/NI should not run for sole trader
		    IF @EnableWages <> 0 AND @IsCompany <> 0
		    BEGIN
			    EXEC App.proc_DatasetSyntheticMIS_PayWages
				    @IsCompany = @IsCompany,
				    @IsVatRegistered = @IsVatRegistered;
		    END

		    IF @EnableExpenses <> 0
		    BEGIN
			    EXEC App.proc_DatasetSyntheticMIS_Expenses
				    @IsCompany = @IsCompany,
				    @IsVatRegistered = @IsVatRegistered;
		    END
		END

		---------------------------------------------------------------------
		-- 3b) Sole Trader owner movements
		---------------------------------------------------------------------
		IF @IsCompany = 0
		BEGIN
			EXEC App.proc_DatasetSyntheticMIS_SoleTraderCapitalIntroduced
				@IsCompany = @IsCompany;

			EXEC App.proc_DatasetSyntheticMIS_SoleTraderDrawings
				@IsCompany = @IsCompany;

			EXEC App.proc_DatasetSyntheticMIS_SoleTraderPersonalTaxRate
				@IsCompany = @IsCompany;
		END

		---------------------------------------------------------------------
		-- 3c) Company Assets
		---------------------------------------------------------------------        
        IF @IsCompany <> 0 AND @EnableAssets <> 0
        BEGIN
	        EXEC App.proc_DatasetSyntheticMIS_Assets
		        @IsCompany = @IsCompany,
		        @IsVatRegistered = @IsVatRegistered;

            EXEC App.proc_DatasetSyntheticMIS_CompanyLoanPayback
                @IsCompany = @IsCompany;
        END

		---------------------------------------------------------------------
		-- 4) Tax
		---------------------------------------------------------------------        
        IF @IsVatRegistered != 0 AND @EnableTax != 0
        BEGIN
            EXEC App.proc_DatasetSyntheticMIS_TaxVat
		        @IsCompany = @IsCompany,
		        @IsVatRegistered = @IsVatRegistered;
        END

		---------------------------------------------------------------------
		-- 5) Transfers (Current -> Reserve sweep)
		---------------------------------------------------------------------
		IF @EnableTransfers <> 0
		BEGIN
			EXEC App.proc_DatasetSyntheticMIS_Transfers
				@FloatRatio = @FloatRatio;
		END

		---------------------------------------------------------------------
		-- 6) Corporation Tax (annual; paid from Reserve via transfer to Current)
		---------------------------------------------------------------------
		IF @IsCompany <> 0 AND @EnableTax <> 0
		BEGIN
			EXEC App.proc_DatasetSyntheticMIS_TaxOnProfit
				@IsCompany = @IsCompany;
		END

        EXEC App.proc_SystemRebuild;

		DECLARE
			@CategoryVersionId NVARCHAR(10) = (SELECT CategoryVersionId FROM App.tbOptions),
			@CategoryVersionSha256 BINARY(32),
			@CategoryVersionByteLength BIGINT;

		EXEC Cash.proc_CategoryVersionCanonicalise
			@VersionId = @CategoryVersionId,
			@CanonicalSha256 = @CategoryVersionSha256 OUTPUT,
			@CanonicalByteLength = @CategoryVersionByteLength OUTPUT;

		INSERT INTO Cash.tbCategoryVersionEvent
		(
			VersionId,
			EventTypeCode,
			FromStatusCode,
			ToStatusCode,
			UserId,
			UserName,
			ChangeNote,
			ContentSha256
		)
		SELECT
			@CategoryVersionId,
			2,
			1,
			1,
			UserId,
			UserName,
			N'Synthetic dataset generation validated the commissioned Category Tree.',
			@CategoryVersionSha256
		FROM Usr.vwCredentials;

		COMMIT TRAN;
	END TRY
	BEGIN CATCH
		EXEC App.proc_ErrorLog;
	END CATCH
GO

