PRINT N'Altering Procedure [App].[proc_VatSourceEvidence]...';


GO
ALTER PROCEDURE [App].[proc_VatSourceEvidence]
    @PeriodStart DATE,
    @PeriodEnd DATE
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;

    IF @PeriodStart IS NULL OR @PeriodEnd IS NULL OR @PeriodEnd < @PeriodStart
        THROW 51030, 'A valid VAT evidence period is required.', 1;

    BEGIN TRANSACTION;

    SELECT
        CONVERT(nvarchar(36), identityRow.DatabaseInstanceId) AS DatabaseInstanceReference,
        options.SubjectCode AS ReportingSubjectReference,
        options.CategoryVersionId AS CategoryTreeVersionId,
        CONVERT(bigint, @@DBTS) AS AccountingEventId,
        CONCAT(CONVERT(varchar(10), install.SQLDataVersion), '.', install.SQLRelease, '.', install.SQLBuild) AS SqlNodeVersion
    FROM App.tbDatabaseIdentity identityRow
    CROSS JOIN App.tbOptions options
    CROSS APPLY
    (
        SELECT TOP (1) SQLDataVersion, SQLRelease, SQLBuild
        FROM App.tbInstall
        ORDER BY InstallId DESC
    ) install
    WHERE identityRow.IdentityCode = 1;

    SELECT CONVERT(date, period.StartOn) AS PeriodStart,
           period.VatAdjustment AS Amount,
           period.VatAdjustmentNote AS Explanation
    FROM App.tbYearPeriod period
    WHERE period.StartOn >= @PeriodStart
      AND period.StartOn < DATEADD(day, 1, @PeriodEnd)
      AND (period.VatAdjustment <> 0 OR NULLIF(LTRIM(RTRIM(period.VatAdjustmentNote)), N'') IS NOT NULL)
    ORDER BY period.StartOn;

    DECLARE @inventory TABLE
    (
        SourceObject sysname NOT NULL PRIMARY KEY,
        CanonicalState nvarchar(max) NULL
    );

    INSERT @inventory VALUES
    (N'App.tbOptions', (SELECT Identifier, SubjectCode, CategoryVersionId, JurisdictionCode,
        CONVERT(varchar(18), RowVer, 1) RowVer FROM App.tbOptions ORDER BY Identifier FOR JSON PATH, INCLUDE_NULL_VALUES)),
    (N'App.tbYear', (SELECT YearNumber, CashStatusCode, CONVERT(varchar(18), RowVer, 1) RowVer
        FROM App.tbYear ORDER BY YearNumber FOR JSON PATH, INCLUDE_NULL_VALUES)),
    (N'App.tbYearPeriod', (SELECT YearNumber, CONVERT(date, StartOn) StartOn, MonthNumber, CashStatusCode,
        VatAdjustment, VatAdjustmentNote, CONVERT(varchar(18), RowVer, 1) RowVer
        FROM App.tbYearPeriod WHERE StartOn <= @PeriodEnd
        ORDER BY StartOn FOR JSON PATH, INCLUDE_NULL_VALUES)),
    (N'Cash.tbTaxType', (SELECT TaxTypeCode, IsEnabled, CashCode, MonthNumber, RecurrenceCode, SubjectCode, OffsetDays,
        CONVERT(varchar(18), RowVer, 1) RowVer FROM Cash.tbTaxType WHERE TaxTypeCode = 1
        ORDER BY TaxTypeCode FOR JSON PATH, INCLUDE_NULL_VALUES)),
    (N'Cash.tbCategory', (SELECT category.VersionId, category.CategoryCode, category.CategoryTypeCode,
        category.CashPolarityCode, category.CashTypeCode, category.IsEnabled,
        CONVERT(varchar(18), category.RowVer, 1) RowVer
        FROM Cash.tbCategory category
        JOIN App.tbOptions options ON options.CategoryVersionId = category.VersionId
        ORDER BY category.CategoryCode FOR JSON PATH, INCLUDE_NULL_VALUES)),
    (N'Cash.tbCategoryTotal', (SELECT total.VersionId, total.ParentCode, total.ChildCode, total.DisplayOrder,
        CONVERT(varchar(18), total.RowVer, 1) RowVer
        FROM Cash.tbCategoryTotal total
        JOIN App.tbOptions options ON options.CategoryVersionId = total.VersionId
        ORDER BY total.ParentCode, total.ChildCode FOR JSON PATH, INCLUDE_NULL_VALUES)),
    (N'Cash.tbCategoryCodeMap', (SELECT map.VersionId, map.CashCode, map.CategoryCode
        FROM Cash.tbCategoryCodeMap map
        JOIN App.tbOptions options ON options.CategoryVersionId = map.VersionId
        ORDER BY map.CashCode FOR JSON PATH, INCLUDE_NULL_VALUES)),
    (N'Cash.tbCategoryRoot', (SELECT root.VersionId, root.RootTypeCode, root.CategoryCode
        FROM Cash.tbCategoryRoot root
        JOIN App.tbOptions options ON options.CategoryVersionId = root.VersionId
        ORDER BY root.RootTypeCode FOR JSON PATH, INCLUDE_NULL_VALUES)),
    (N'Cash.tbCode', (SELECT CashCode, TaxCode, IsEnabled,
        CONVERT(varchar(18), RowVer, 1) RowVer FROM Cash.tbCode ORDER BY CashCode FOR JSON PATH, INCLUDE_NULL_VALUES)),
    (N'App.tbTaxCode', (SELECT TaxCode, TaxTypeCode, RoundingCode, TaxRate, Decimals,
        CONVERT(varchar(18), RowVer, 1) RowVer FROM App.tbTaxCode WHERE TaxTypeCode = 1
        ORDER BY TaxCode FOR JSON PATH, INCLUDE_NULL_VALUES)),
    (N'Invoice.tbInvoice', (SELECT InvoiceNumber, SubjectCode, InvoiceTypeCode, CONVERT(date, InvoicedOn) InvoicedOn,
        CONVERT(varchar(18), RowVer, 1) RowVer FROM Invoice.tbInvoice
        WHERE InvoicedOn >= @PeriodStart AND InvoicedOn < DATEADD(day, 1, @PeriodEnd)
        ORDER BY InvoiceNumber FOR JSON PATH, INCLUDE_NULL_VALUES)),
    (N'Invoice.tbItem', (SELECT item.InvoiceNumber, item.CashCode, item.TaxCode, item.InvoiceValue, item.TaxValue,
        CONVERT(varchar(18), item.RowVer, 1) RowVer FROM Invoice.tbItem item
        JOIN Invoice.tbInvoice invoice ON invoice.InvoiceNumber = item.InvoiceNumber
        WHERE invoice.InvoicedOn >= @PeriodStart AND invoice.InvoicedOn < DATEADD(day, 1, @PeriodEnd)
        ORDER BY item.InvoiceNumber, item.CashCode FOR JSON PATH, INCLUDE_NULL_VALUES)),
    (N'Invoice.tbProject', (SELECT project.InvoiceNumber, project.ProjectCode, project.CashCode, project.TaxCode,
        project.InvoiceValue, project.TaxValue, CONVERT(varchar(18), project.RowVer, 1) RowVer
        FROM Invoice.tbProject project JOIN Invoice.tbInvoice invoice ON invoice.InvoiceNumber = project.InvoiceNumber
        WHERE invoice.InvoicedOn >= @PeriodStart AND invoice.InvoicedOn < DATEADD(day, 1, @PeriodEnd)
        ORDER BY project.InvoiceNumber, project.ProjectCode FOR JSON PATH, INCLUDE_NULL_VALUES)),
    (N'Subject.tbSubject', (SELECT subject.SubjectCode, subject.ExportTypeCode,
        CONVERT(varchar(18), subject.RowVer, 1) RowVer FROM Subject.tbSubject subject
        WHERE subject.SubjectCode IN
        (
            SELECT invoice.SubjectCode FROM Invoice.tbInvoice invoice
            WHERE invoice.InvoicedOn >= @PeriodStart AND invoice.InvoicedOn < DATEADD(day, 1, @PeriodEnd)
            UNION SELECT SubjectCode FROM App.tbOptions
        ) ORDER BY subject.SubjectCode FOR JSON PATH, INCLUDE_NULL_VALUES)),
    (N'Subject.tbRegistration', (SELECT registration.SubjectCode, registration.RegistrationCode,
        registration.RegistrationSchemeCode, registration.RegistrationValue, registration.ValidFrom,
        registration.ValidTo, registration.StatusCode, registration.ValueSourceCode, registration.IsReviewed,
        CONVERT(varchar(18), registration.RowVer, 1) RowVer FROM Subject.tbRegistration registration
        JOIN App.tbOptions options ON options.SubjectCode = registration.SubjectCode
        ORDER BY registration.SubjectCode, registration.RegistrationCode FOR JSON PATH, INCLUDE_NULL_VALUES)),
    (N'Cash.tbReportingProfile', (SELECT profile.SubjectCode, profile.ReportingProfileCode, profile.TaxSourceCode,
        profile.AuthorityCode, profile.ReportingTypeCode, profile.AuthorityReference, profile.ValidFrom,
        profile.ValidTo, profile.StatusCode, profile.ValueSourceCode, profile.IsReviewed,
        CONVERT(varchar(18), profile.RowVer, 1) RowVer FROM Cash.tbReportingProfile profile
        JOIN App.tbOptions options ON options.SubjectCode = profile.SubjectCode
        WHERE profile.ReportingTypeCode = 0
        ORDER BY profile.SubjectCode, profile.ReportingProfileCode FOR JSON PATH, INCLUDE_NULL_VALUES)),
    (N'Cash.tbReportingProfileSetting', (SELECT setting.SubjectCode, setting.ReportingProfileCode,
        setting.SettingCode, setting.EffectiveFrom, setting.EffectiveTo, setting.TextValue, setting.IntegerValue,
        setting.DecimalValue, setting.DateValue, setting.BooleanValue, setting.StatusCode, setting.ValueSourceCode,
        setting.IsReviewed, CONVERT(varchar(18), setting.RowVer, 1) RowVer
        FROM Cash.tbReportingProfileSetting setting
        JOIN Cash.tbReportingProfile profile ON profile.SubjectCode = setting.SubjectCode
            AND profile.ReportingProfileCode = setting.ReportingProfileCode
        JOIN App.tbOptions options ON options.SubjectCode = profile.SubjectCode
        WHERE profile.ReportingTypeCode = 0
        ORDER BY setting.SubjectCode, setting.ReportingProfileCode, setting.SettingCode, setting.EffectiveFrom
        FOR JSON PATH, INCLUDE_NULL_VALUES));

    SELECT SourceObject, COALESCE(CanonicalState, N'[]') CanonicalState FROM @inventory ORDER BY SourceObject;

    COMMIT TRANSACTION;
END;
GO
PRINT N'Altering Procedure [Cash].[proc_CodeAdd]...';


GO
ALTER PROCEDURE [Cash].[proc_CodeAdd]
(
    @VersionId NVARCHAR(10),
    @CashCode NVARCHAR(50),
    @CashDescription NVARCHAR(100),
    @CategoryCode NVARCHAR(10),
    @TaxCode NVARCHAR(10),
    @IsEnabled SMALLINT = 1
)
AS
BEGIN
    SET NOCOUNT, XACT_ABORT ON;

    DECLARE @UserId NVARCHAR(10), @UserName NVARCHAR(50);
    SELECT TOP (1) @UserId = UserId, @UserName = UserName FROM Usr.vwCredentials;
    IF @UserId IS NULL THROW 51174, 'Cash Code creation requires an enabled application user.', 1;

    BEGIN TRY
        BEGIN TRAN;

        IF NOT EXISTS
        (
            SELECT 1
            FROM App.tbOptions WITH (UPDLOCK, HOLDLOCK)
            WHERE CategoryVersionId = @VersionId
        )
            THROW 51106, 'A new Cash Code must be added to the active Category Tree version.', 1;

        IF NOT EXISTS
        (
            SELECT 1
            FROM Cash.tbCategoryVersion WITH (UPDLOCK, HOLDLOCK)
            WHERE VersionId = @VersionId
              AND VersionStatusCode = 1
        )
            THROW 51107, 'A new Cash Code requires an editable active Published Category Tree version.', 1;

        IF NOT EXISTS
        (
            SELECT 1
            FROM Cash.tbCategory
            WHERE VersionId = @VersionId
              AND CategoryCode = @CategoryCode
              AND CategoryTypeCode = 0
        )
            THROW 51108, 'A new Cash Code must map to a Nominal category in the active version.', 1;

        IF EXISTS (SELECT 1 FROM Cash.tbCode WHERE CashCode = @CashCode)
            OR EXISTS
               (
                   SELECT 1
                   FROM Cash.tbCategoryCodeMap
                   WHERE VersionId = @VersionId
                     AND CashCode = @CashCode
               )
            THROW 51109, 'The Cash Code or its active Category Tree mapping already exists.', 1;

        INSERT INTO Cash.tbCode
        (
            CashCode,
            CashDescription,
            TaxCode,
            IsEnabled
        )
        VALUES
        (
            @CashCode,
            @CashDescription,
            @TaxCode,
            @IsEnabled
        );

        INSERT INTO Cash.tbCategoryCodeMap
        (
            VersionId,
            CashCode,
            CategoryCode
        )
        VALUES
        (
            @VersionId,
            @CashCode,
            @CategoryCode
        );

        INSERT Cash.tbCategoryVersionEvent
            (VersionId, EventTypeCode, FromStatusCode, ToStatusCode,
             UserId, UserName, ChangeNote)
        VALUES
            (@VersionId, 1, 1, 1, @UserId, @UserName,
             N'Cash Code created with its active-version mapping.');

        COMMIT TRAN;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRAN;
        THROW;
    END CATCH
END;
GO
PRINT N'Altering Procedure [App].[proc_Template_CO_MICRO_CUR_STD_EXP_2026]...';


GO
ALTER PROCEDURE App.proc_Template_CO_MICRO_CUR_STD_EXP_2026
    @CategoryVersionId NVARCHAR(10)
AS
BEGIN

    ----------------------------------------------------------------
    -- STD-SPECIFIC EXPRESSION CATEGORIES (CategoryTypeCode = 2)
    ----------------------------------------------------------------
    INSERT INTO Cash.tbCategory
        (VersionId, CategoryCode, Category, CategoryTypeCode, CashPolarityCode, CashTypeCode, DisplayOrder, IsEnabled)
    SELECT
        @CategoryVersionId,
        CategoryCode,
        Category,
        CategoryTypeCode,
        CashPolarityCode,
        CashTypeCode,
        DisplayOrder,
        IsEnabled
    FROM
    (VALUES
        -- Enabled by default (the “big four”)
        ('CE-COS',  'Cash Operating Surplus % (Structured)', 2, 2, 0, 20, 1),
        ('CE-LM',   'Labour Margin %',                       2, 2, 0, 21, 1),
        ('CE-MM',   'Materials Margin %',                    2, 2, 0, 22, 1),
        ('CE-SDR',  'Subcontractor Dependency Ratio',        2, 2, 0, 23, 1),

        -- Effective tax rate (enabled)
        ('CE-ETR',  'Effective Tax Rate',                    2, 2, 0, 24, 1),

        -- Disabled by default (progressive disclosure)
        ('CE-VCR',  'Vehicle Cost Ratio',                    2, 2, 0, 25, 0),

        ('CE-WPR',  'Wages % of Staff Costs',                2, 2, 0, 26, 0),
        ('CE-NPR',  'Employer NI % of Staff Costs',          2, 2, 0, 27, 0),
        ('CE-PPR',  'Pension % of Staff Costs',              2, 2, 0, 28, 0),

        ('CE-RPR',  'Rent % of Admin Expenses',              2, 2, 0, 29, 0),
        ('CE-UPR',  'Utilities % of Admin Expenses',         2, 2, 0, 30, 0),
        ('CE-IPR',  'Insurance % of Admin Expenses',         2, 2, 0, 31, 0),
        ('CE-MPR',  'Repairs % of Admin Expenses',           2, 2, 0, 32, 0),
        ('CE-TPR',  'Telephone % of Admin Expenses',         2, 2, 0, 33, 0),
        ('CE-APR',  'Advertising % of Admin Expenses',       2, 2, 0, 34, 0),
        ('CE-TRR',  'Travel % of Admin Expenses',            2, 2, 0, 35, 0),
        ('CE-PFR',  'Professional Fees % of Admin Expenses', 2, 2, 0, 36, 0),
        ('CE-BCR',  'Bank Charges % of Admin Expenses',      2, 2, 0, 37, 0),

        ('CE-DPL',  'Plant Depreciation % of Depreciation',  2, 2, 0, 38, 0),
        ('CE-DMV',  'Motor Depreciation % of Depreciation',  2, 2, 0, 39, 0),
        ('CE-DFX',  'Fixtures Depreciation % of Depreciation', 2, 2, 0, 40, 0)
    ) AS category
    (
        CategoryCode,
        Category,
        CategoryTypeCode,
        CashPolarityCode,
        CashTypeCode,
        DisplayOrder,
        IsEnabled
    );

    ----------------------------------------------------------------
    -- STD-SPECIFIC EXPRESSIONS (STABLE CODE REFERENCES)
    ----------------------------------------------------------------
    INSERT INTO Cash.tbCategoryExp
        (CategoryCode, Expression, Format, SyntaxTypeCode, IsError, ErrorMessage)
    VALUES
        -- Structured Cash Operating Surplus %
        ('CE-COS', 'IF([CT-TURNOV]=0,0,([CT-TURNOV]-[CT-CSTSAL]-[CT-STAFFC]-[CA-ADMIN])/[CT-TURNOV])', 'Pct0', 0, 0, NULL),

        -- Labour Margin %
        ('CE-LM', 'IF([CC-SALAB]=0,0,([CC-SALAB]-[CC-SALRY]-[CC-EMPNI]-[CC-PENSN])/[CC-SALAB])', 'Pct0', 0, 0, NULL),

        -- Materials Margin %
        ('CE-MM', 'IF([CC-SAMAT]=0,0,([CC-SAMAT]-[CC-MAT])/[CC-SAMAT])', 'Pct0', 0, 0, NULL),

        -- Subcontractor Dependency Ratio
        ('CE-SDR', 'IF([CT-CSTSAL]=0,0,[CC-SUB]/[CT-CSTSAL])', 'Pct0', 0, 0, NULL),

        -- Effective Tax Rate
        ('CE-ETR',
            'IF(([CT-TURNOV]-[CT-CSTSAL]-[CT-STAFFC]-[CA-ADMIN])=0,0,(ABS([CA-TAXCO])/([CT-TURNOV]-[CT-CSTSAL]-[CT-STAFFC]-[CA-ADMIN])))',
            'Pct0', 0, 0, NULL),

        -- Vehicle Cost Ratio
        ('CE-VCR', 'IF([CT-TURNOV]=0,0,([CC-FUEL]+[CC-MTRAV])/[CT-TURNOV])', 'Pct0', 0, 0, NULL),

        -- Staff Cost Structure
        ('CE-WPR', 'IF([CT-STAFFC]=0,0,[CC-SALRY]/[CT-STAFFC])', 'Pct0', 0, 0, NULL),
        ('CE-NPR', 'IF([CT-STAFFC]=0,0,[CC-EMPNI]/[CT-STAFFC])', 'Pct0', 0, 0, NULL),
        ('CE-PPR', 'IF([CT-STAFFC]=0,0,[CC-PENSN]/[CT-STAFFC])', 'Pct0', 0, 0, NULL),

        -- Admin Cost Structure
        ('CE-RPR', 'IF([CA-ADMIN]=0,0,[CC-RENT]/[CA-ADMIN])', 'Pct0', 0, 0, NULL),
        ('CE-UPR', 'IF([CA-ADMIN]=0,0,[CC-LHEAT]/[CA-ADMIN])', 'Pct0', 0, 0, NULL),
        ('CE-IPR', 'IF([CA-ADMIN]=0,0,[CC-INS]/[CA-ADMIN])', 'Pct0', 0, 0, NULL),
        ('CE-MPR', 'IF([CA-ADMIN]=0,0,[CC-REPA]/[CA-ADMIN])', 'Pct0', 0, 0, NULL),
        ('CE-TPR', 'IF([CA-ADMIN]=0,0,[CC-PHONE]/[CA-ADMIN])', 'Pct0', 0, 0, NULL),
        ('CE-APR', 'IF([CA-ADMIN]=0,0,[CC-ADVT]/[CA-ADMIN])', 'Pct0', 0, 0, NULL),
        ('CE-TRR', 'IF([CA-ADMIN]=0,0,[CC-TRAV]/[CA-ADMIN])', 'Pct0', 0, 0, NULL),
        ('CE-PFR', 'IF([CA-ADMIN]=0,0,[CC-PROF]/[CA-ADMIN])', 'Pct0', 0, 0, NULL),
        ('CE-BCR', 'IF([CA-ADMIN]=0,0,[CC-BANKC]/[CA-ADMIN])', 'Pct0', 0, 0, NULL),

        -- Depreciation Structure
        ('CE-DPL', 'IF([CA-DEPREC]=0,0,[CC-DEPPL]/[CA-DEPREC])', 'Pct0', 0, 0, NULL),
        ('CE-DMV', 'IF([CA-DEPREC]=0,0,[CC-DEPMV]/[CA-DEPREC])', 'Pct0', 0, 0, NULL),
        ('CE-DFX', 'IF([CA-DEPREC]=0,0,[CC-DEPFX]/[CA-DEPREC])', 'Pct0', 0, 0, NULL);

END;
GO
PRINT N'Altering Trigger [App].[App_tbOptions_TriggerUpdate]...';


GO
ALTER TRIGGER App.App_tbOptions_TriggerUpdate 
   ON App.tbOptions
   AFTER INSERT, UPDATE
AS 
BEGIN
	SET NOCOUNT ON;
	BEGIN TRY
		IF (SELECT COUNT_BIG(*) FROM App.tbOptions WITH (TABLOCKX, HOLDLOCK)) > 1
			THROW 51089, 'App.tbOptions must contain no more than one row.', 1;

		IF EXISTS
		(
			SELECT 1
			FROM inserted AS i
			WHERE i.IsInitialised = 1
			  AND i.CategoryVersionId IS NULL
		)
			THROW 51090, 'An initialised node requires an active Category Tree version.', 1;

		IF EXISTS
		(
			SELECT 1
			FROM inserted AS i
			LEFT JOIN Cash.tbCategoryVersion AS version
			  ON version.VersionId = i.CategoryVersionId
			WHERE i.CategoryVersionId IS NOT NULL
			  AND (version.VersionId IS NULL OR version.VersionStatusCode NOT IN (1, 2))
		)
			THROW 51091, 'The active Category Tree pointer must reference a Published or Submitted version.', 1;

		UPDATE App.tbOptions
		SET UpdatedBy = Usr.fnUserName(), UpdatedOn = CURRENT_TIMESTAMP
		FROM App.tbOptions INNER JOIN inserted AS i ON tbOptions.Identifier = i.Identifier;

		IF UPDATE(CoinTypeCode)
		BEGIN
			UPDATE Subject.tbAccount
			SET CoinTypeCode = (SELECT CoinTypeCode FROM inserted)
		END
	END TRY
	BEGIN CATCH
		EXEC App.proc_ErrorLog;
	END CATCH
END
GO
PRINT N'Altering Procedure [App].[proc_NodeDataInit]...';


GO
ALTER PROCEDURE App.proc_NodeDataInit
AS
SET NOCOUNT, XACT_ABORT ON;
BEGIN TRY

	BEGIN TRAN
	DELETE FROM Cash.tbReportingProfileSetting;
	DELETE FROM Cash.tbReportingProfile;
	DELETE FROM Subject.tbRegistration;
	UPDATE Cash.tbTaxType
	SET SubjectCode = null, CashCode = null;

	DELETE FROM App.tbOptions;
	DELETE FROM dbo.AspNetUsers;
	DELETE FROM Cash.tbPayment;
	DELETE FROM Invoice.tbInvoice;
	DELETE FROM Project.tbFlow;
	DELETE FROM Project.tbProject;
	DELETE FROM Object.tbFlow;
	DELETE FROM Object.tbObject;
	DELETE FROM Subject.tbAccount;
	DELETE FROM Subject.tbVirtual;
	DELETE FROM Subject.tbSubject;
	DELETE FROM Subject.tbAddressType;
	DELETE FROM App.tbYear;
	DELETE FROM App.tbBucket;
	DELETE FROM App.tbUom;
	DELETE FROM Cash.tbCategoryRoot;
	DELETE FROM Cash.tbCategoryTotal;
	DELETE FROM Cash.tbCategoryExp;
	DELETE FROM Cash.tbCategoryCodeMap;
	DELETE FROM Cash.tbCode;
	DELETE FROM App.tbTaxCode;
	DELETE FROM Cash.tbTaxType;
	DELETE FROM Cash.tbCategory;
	DELETE FROM Cash.tbCategoryVersionEvent;
	DELETE FROM Cash.tbCategoryVersion;
	ALTER SEQUENCE Cash.seqCategoryVersion RESTART WITH 1;
	DELETE FROM Usr.tbUser;
	DELETE FROM App.tbCalendar;
	DELETE FROM App.tbTemplate;
    DELETE FROM App.tbSettingDefinition;
    DELETE FROM App.tbReportingTypeRegistrationScheme;
    DELETE FROM App.tbReportingType;
    DELETE FROM App.tbRegistrationScheme;
    DELETE FROM App.tbAuthority;
    DELETE FROM App.tbValueSource;
    DELETE FROM App.tbStatutoryStatus;
    DELETE FROM App.tbValueType;
    DELETE FROM App.tbJurisdiction;
	DELETE FROM Subject.tbExportType;

	IF NOT EXISTS (SELECT * FROM Cash.tbCategoryVersionStatus)
		INSERT INTO Cash.tbCategoryVersionStatus (VersionStatusCode, VersionStatus)
		VALUES (0, N'Draft')
		, (1, N'Published')
		, (2, N'Submitted')
		, (3, N'Archived');

	IF NOT EXISTS (SELECT * FROM Cash.tbCategoryRootType)
		INSERT INTO Cash.tbCategoryRootType (RootTypeCode, RootType)
		VALUES (0, N'NET_PROFIT')
		, (1, N'VAT');
	
	IF NOT EXISTS (SELECT * FROM [Cash].[tbChangeType])
		INSERT INTO [Cash].[tbChangeType] ([ChangeTypeCode], [ChangeType])
		VALUES (0, 'Receipt')
		, (1, 'Change')

	IF NOT EXISTS (SELECT * FROM [Cash].[tbChangeStatus])
		INSERT INTO [Cash].[tbChangeStatus] ([ChangeStatusCode], [ChangeStatus])
		VALUES (0, 'Unused')
		, (1, 'Paid')
		, (2, 'Spent')

	IF NOT EXISTS (SELECT * FROM [Cash].[tbTxStatus])
		INSERT INTO [Cash].[tbTxStatus] ([TxStatusCode], [TxStatus])
		VALUES (0, 'Received')
		, (1, 'UTXO')
		, (2, 'Spent')

	IF NOT EXISTS (SELECT * FROM [Subject].[tbTransmitStatus])
		INSERT INTO [Subject].[tbTransmitStatus] ([TransmitStatusCode], [TransmitStatus])
		VALUES (0, 'Disconnected')
		, (1, 'Deploy')
		, (2, 'Update')
		, (3, 'Processed')

	IF NOT EXISTS (SELECT * FROM [Subject].[tbExportType])
		INSERT INTO [Subject].[tbExportType] ([ExportTypeCode], [ExportType])
		VALUES (0, N'Home')
		, (1, N'Export')
		, (2, N'Northern Ireland')

	IF NOT EXISTS (SELECT * FROM [App].[tbTemplate])
        INSERT INTO [App].[tbTemplate]
            ([TemplateCode], [TemplateName], [StoredProcedure], [TemplateDescription], [IsCompany], [IsVatRegistered])
        VALUES
            ('COMIN26',
             'Minimal Micro Company Accounts 2026',
             'App.proc_Template_CO_MICRO_CUR_MIN_2026',
