ALTER DATABASE CURRENT SET RECURSIVE_TRIGGERS OFF;
GO

IF NOT EXISTS
(
    SELECT 1
    FROM App.tbInstall
    WHERE SQLDataVersion = 4
      AND SQLRelease = 1
      AND SQLBuild = 20
)
    INSERT App.tbInstall (SQLDataVersion, SQLRelease, SQLBuild)
    VALUES (4, 1, 20);
GO

SELECT
    DB_NAME() AS DatabaseName,
    N'4.1.13' AS PreviousBuild,
    N'4.1.20' AS InstalledBuild,
    version.VersionId,
    status.VersionStatus,
    version.EffectiveFromOn,
    category_rows.CategoryCount,
    total_rows.TotalCount,
    root_rows.RootCount,
    mapping_rows.MappingCount,
    code_rows.CashCodeCount,
    version.CanonicalByteLength,
    CONVERT(VARCHAR(64), version.CanonicalSha256, 2) AS CanonicalSha256
FROM Cash.tbCategoryVersion AS version
JOIN Cash.tbCategoryVersionStatus AS status
  ON status.VersionStatusCode = version.VersionStatusCode
CROSS APPLY (SELECT COUNT(*) AS CategoryCount FROM Cash.tbCategory WHERE VersionId = version.VersionId) AS category_rows
CROSS APPLY (SELECT COUNT(*) AS TotalCount FROM Cash.tbCategoryTotal WHERE VersionId = version.VersionId) AS total_rows
CROSS APPLY (SELECT COUNT(*) AS RootCount FROM Cash.tbCategoryRoot WHERE VersionId = version.VersionId) AS root_rows
CROSS APPLY (SELECT COUNT(*) AS MappingCount FROM Cash.tbCategoryCodeMap WHERE VersionId = version.VersionId) AS mapping_rows
CROSS APPLY (SELECT COUNT(*) AS CashCodeCount FROM Cash.tbCode) AS code_rows
JOIN App.tbOptions AS options
  ON options.CategoryVersionId = version.VersionId
WHERE version.VersionId = N'CV00000001';
GO
